class MaterializeStageObjectsWriterTests(MaterializeCommandFixture, unittest.TestCase):
    """`--stage objects`: SKILL.md step 9's table (`src/<Package>/module.py`,
    `tests/test_invariants.py`, `tests/test_synthetic.py`), gated on the
    step-8 object map being approved and recorded."""

    def test_refuses_before_the_object_map_is_approved(self):
        """M9: the tokens these three templates carry
        (`{{FUNCTION_NAME}}`/`{{INVARIANT_ID}}`/`{{EXPECTATION}}`) have no
        answer before step 8's declaration exists -- refuses
        OBJECT_MAP_NOT_APPROVED, and writes nothing."""
        box = self._fully_materialized("_objects_before_map")
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "scaffold stage")
        plan_path = self._approved_plan_path(box)

        payload, code, proc = self._materialize_objects(box, plan_path)

        self.assertEqual(code, 2, proc.stdout)
        self.assertEqual(payload["code"], "OBJECT_MAP_NOT_APPROVED")
        for destination in impl.object_destinations(self.NAME):
            self.assertFalse((box / destination).exists(), destination)

    def test_succeeds_once_the_object_map_is_approved(self):
        """The positive case: once step 8's declaration is recorded, the
        three destinations are written -- deliberately still carrying their
        step-9 tokens, since nothing here can answer them."""
        box = self._fully_materialized("_objects_after_map")
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "scaffold stage")
        self._declare_object_map(box)
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "object map declared")
        plan_path = self._approved_plan_path(box)

        payload, code, proc = self._materialize_objects(box, plan_path)

        self.assertEqual(code, 0, proc.stderr)
        self.assertEqual(sorted(payload["written"]),
                         sorted(impl.object_destinations(self.NAME)))
        module_path = box / "src" / self.PACKAGE / "module.py"
        self.assertTrue(module_path.exists())
        self.assertIn("{{FUNCTION_NAME}}", module_path.read_text(encoding="utf-8"),
                      "the token step 9 answers is left standing, not guessed")
        self.assertEqual(impl.object_gaps(box, self.NAME), [])
        receipt = impl.read_materialization_receipt(box)
        entry = impl.receipt_entry(receipt, "tests/test_invariants.py")
        self.assertEqual(entry["kind"], "materialized")
        self.assertEqual(entry["stage"], "objects")

    def test_without_seed_refuses(self):
        box = self._fully_materialized("_objects_no_seed")
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "scaffold stage")
        self._declare_object_map(box)
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "object map declared")
        plan_path = self._approved_plan_path(box)

        payload, code, proc = self._run_cli(
            "materialize", "--target", str(box), "--name", self.NAME,
            "--stage", "objects", "--plan", plan_path)

        self.assertEqual(code, 2, proc.stdout)
        self.assertEqual(payload["code"], "SEED_REQUIRED")


class MaterializeStageHarnessWriterTests(MaterializeCommandFixture, unittest.TestCase):
    """`--stage harness`: the harness-wiring table's three destinations
    (`benchmark.py`, `verdict.py`, `probe.ipynb`), gated only on the same
    plan/clean-worktree preflight `scaffold` uses -- no object-map
    precondition, and no `--seed`."""

    def _staged_scaffold(self, tag):
        box = self._fully_materialized(tag)
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "scaffold stage")
        return box

    def test_needs_no_seed_and_succeeds(self):
        box = self._staged_scaffold("_harness_no_seed")
        plan_path = self._approved_plan_path(box)

        payload, code, proc = self._materialize_harness(box, plan_path)

        self.assertEqual(code, 0, proc.stderr)
        self.assertEqual(sorted(payload["written"]),
                         sorted(impl.harness_destinations(self.NAME)))
        for destination in impl.harness_destinations(self.NAME):
            self.assertTrue((box / destination).exists(), destination)
        self.assertEqual(impl.harness_gaps(box, self.NAME), [])
        # benchmark.py/verdict.py carry no token at all, so they must parse
        # cleanly -- unlike the objects stage, nothing here is left standing.
        for py_destination in (f"src/{self.PACKAGE}_Benchmark/benchmark.py",
                               f"src/{self.PACKAGE}_Benchmark/verdict.py"):
            ast.parse((box / py_destination).read_text(encoding="utf-8"))

    def test_destination_conflict_refuses_the_whole_stage(self):
        """The `_write_kit_stage` seam objects/harness share: a destination
        appearing between set computation and the write refuses the whole
        stage and writes no receipt -- the same DESTINATION_CONFLICT shape
        `_stage_scaffold` already proves, exercised here through the new
        shared helper instead."""
        box = self._staged_scaffold("_harness_conflict")
        raced = f"src/{self.PACKAGE}_Benchmark/benchmark.py"
        (box / raced).write_text("already here\n", encoding="utf-8")
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "the file the race lands on")
        plan_path = self._approved_plan_path(box)
        receipt_before = impl.read_materialization_receipt(box)

        with unittest.mock.patch.object(
                impl, "_materialize_harness_destinations",
                return_value=impl.harness_destinations(self.NAME)):
            args = self._materialize_args(box, stage="harness", plan=plan_path)
            with self.assertRaises(impl.Refused) as ctx:
                impl.cmd_materialize(args)

        self.assertEqual(ctx.exception.code, "DESTINATION_CONFLICT")
        self.assertEqual(impl.read_materialization_receipt(box), receipt_before,
                         "a refused stage must write no receipt entry")
        self.assertEqual((box / raced).read_text(encoding="utf-8"), "already here\n")

    def test_mid_write_failure_aborts_and_restores_the_tree(self):
        box = self._staged_scaffold("_harness_abort")
        plan_path = self._approved_plan_path(box)
        receipt_before = impl.read_materialization_receipt(box)
        real_write_text = Path.write_text
        calls = {"n": 0}

        def flaky_write_text(self_path, *args, **kwargs):
            calls["n"] += 1
            if calls["n"] == 2:
                raise OSError("simulated disk failure")
            return real_write_text(self_path, *args, **kwargs)

        args = self._materialize_args(box, stage="harness", plan=plan_path)
        with unittest.mock.patch.object(Path, "write_text", flaky_write_text):
            with self.assertRaises(impl.Refused) as ctx:
                impl.cmd_materialize(args)

        self.assertEqual(ctx.exception.code, "APPLY_ABORTED")
        self.assertEqual(impl.read_materialization_receipt(box), receipt_before,
                         "a refused stage must write no receipt entry")
        status = self._git(box, "status", "--porcelain").stdout
        self.assertEqual(status.strip(), "", "the tree was not restored: " + status)


class MaterializeVerifyObjectsAndHarnessTests(MaterializeCommandFixture, unittest.TestCase):
    """`SCAFFOLD_DRIFT`/`UNRECORDED_SCAFFOLD`'s equivalent for the `objects`
    and `harness` stages, and `structure.status` reaching all seventeen kit
    destinations (V1/V3/V4)."""

    def _all_stages(self, tag):
        return self._fully_materialized_all_stages(tag)

    def test_object_destination_drift_is_reported(self):
        box = self._all_stages("_object_drift")
        target_file = box / "tests" / "test_invariants.py"
        stat_before = target_file.stat()
        original = target_file.read_bytes()
        mutated = original.replace(b"assert True", b"assert TRUE", 1)
        self.assertNotEqual(original, mutated)
        self.assertEqual(len(original), len(mutated))
        target_file.write_bytes(mutated)
        os.utime(target_file, (stat_before.st_atime, stat_before.st_mtime))

        structure = self._verify(box)
        self.assertIn("tests/test_invariants.py", structure["objectDrift"])
        self.assertNotEqual(structure["status"], "ok")

    def test_object_destination_unrecorded_is_reported(self):
        box = self._staged_scaffold_for_unrecorded_objects("_object_unrecorded")
        (box / "src" / self.PACKAGE / "module.py").write_text(
            "# hand-written, never materialized\n", encoding="utf-8")

        structure = self._verify(box)
        self.assertIn(f"src/{self.PACKAGE}/module.py", structure["unrecordedObjects"])
        self.assertNotEqual(structure["status"], "ok")

    def _staged_scaffold_for_unrecorded_objects(self, tag):
        box = self._fully_materialized(tag)
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "scaffold stage")
        return box

    def test_harness_destination_drift_is_reported(self):
        box = self._all_stages("_harness_drift")
        target_file = box / "src" / f"{self.PACKAGE}_Benchmark" / "verdict.py"
        stat_before = target_file.stat()
        original = target_file.read_bytes()
        mutated = original + b"\n# tampered\n"
        target_file.write_bytes(mutated)
        os.utime(target_file, (stat_before.st_atime, stat_before.st_mtime + 1))

        structure = self._verify(box)
        self.assertIn(f"src/{self.PACKAGE}_Benchmark/verdict.py",
                      structure["harnessDrift"])
        self.assertNotEqual(structure["status"], "ok")

    def test_harness_gap_does_not_block_the_scaffold_only_flow(self):
        """V4: a target that has only run `--stage scaffold` reports the six
        objects/harness destinations as gaps, never drift or unrecorded --
        and `verify` itself still succeeds and reports, rather than
        refusing, so the earlier flow stays runnable."""
        box = self._fully_materialized("_v4_scaffold_only")
        structure = self._verify(box)
        self.assertEqual(sorted(structure["objectGaps"]),
                         sorted(impl.object_destinations(self.NAME)))
        self.assertEqual(sorted(structure["harnessGaps"]),
                         sorted(impl.harness_destinations(self.NAME)))
        self.assertEqual(structure["objectDrift"], [])
        self.assertEqual(structure["unrecordedObjects"], [])
        self.assertEqual(structure["harnessDrift"], [])
        self.assertEqual(structure["unrecordedHarness"], [])
        self.assertNotEqual(structure["status"], "ok")

    def test_structure_status_ok_only_once_all_seventeen_are_materialized(self):
        """V1/V3, extended to all seventeen: the positive case, without which
        the widening across objects/harness could pass by always failing."""
        box = self._all_stages("_v1_all_seventeen")
        structure = self._verify(box)
        self.assertEqual(structure["scaffoldGaps"], [])
        self.assertEqual(structure["objectGaps"], [])
        self.assertEqual(structure["harnessGaps"], [])
        self.assertEqual(structure["scaffoldDrift"], [])
        self.assertEqual(structure["objectDrift"], [])
        self.assertEqual(structure["harnessDrift"], [])
        self.assertEqual(structure["unrecordedScaffold"], [])
        self.assertEqual(structure["unrecordedObjects"], [])
        self.assertEqual(structure["unrecordedHarness"], [])
        self.assertEqual(structure["status"], "ok")

    def test_authored_and_adopt_widened_to_objects_and_harness_destinations(self):
        """The `NOT_A_KIT_DESTINATION` domain check widened from the eleven
        scaffold destinations to all seventeen -- `--authored` on an
        objects-stage path, and `--adopt` on a harness-stage path never
        materialized, both succeed rather than refusing outside-domain."""
        box = self._all_stages("_widened_domain")
        module_path = f"src/{self.PACKAGE}/module.py"
        (box / module_path).write_text(
            (box / module_path).read_text(encoding="utf-8") + "\n# authored\n",
            encoding="utf-8")

        payload, code, proc = self._run_cli(
            "materialize", "--target", str(box), "--name", self.NAME,
            "--authored", module_path)
        self.assertEqual(code, 0, proc.stderr)
        receipt = impl.read_materialization_receipt(box)
        self.assertEqual(impl.receipt_entry(receipt, module_path)["kind"], "authored")

        probe_path = f"{self.NAME}/Notebooks/probe.ipynb"
        (box / impl.MATERIALIZATION_RECEIPT).unlink()
        # Re-seed a receipt carrying no entry for probe.ipynb so --adopt has
        # something to resolve, without disturbing the other sixteen.
        receipt = {"version": 1, "name": self.NAME, "entries": [
            e for e in receipt["entries"] if e["path"] != probe_path]}
        (box / impl.MATERIALIZATION_RECEIPT).write_text(
            json.dumps(receipt, indent=2), encoding="utf-8")

        payload, code, proc = self._run_cli(
            "materialize", "--target", str(box), "--name", self.NAME,
            "--adopt", probe_path)
        self.assertEqual(code, 0, proc.stderr)
        self.assertEqual(payload["status"], "adopted")


class MaterializeDegradedGuaranteeTests(unittest.TestCase):
    """2.3: the adoption guarantee is degraded, and that sentence has to
    appear at every surface an operator can reach it from -- the usage
    reference's refusal row, the `--adopt` argparse help, and the JSON output
    of an adopted entry (proven in `MaterializeAdoptTests` above via the
    `entry["kind"] == "adopted"` distinguishability; this class holds the
    prose)."""

    MARKER_A = "record the bytes came from the kit"
    MARKER_B = "the record names who"

    def test_usage_md_states_the_degraded_guarantee(self):
        text = USAGE_MD.read_text(encoding="utf-8")
        self.assertIn("UNRECORDED_SCAFFOLD", text)
        self.assertIn(self.MARKER_B, text)

    def test_argparse_help_states_the_degraded_guarantee(self):
        source = CLI.read_text(encoding="utf-8")
        self.assertIn("Degrades the guarantee", source)

    def test_the_adopted_json_output_states_the_degraded_guarantee(self):
        source = CLI.read_text(encoding="utf-8")
        self.assertIn(self.MARKER_B, source)


#: The vocabulary the forge legitimately owns, word to the reason it was admitted.
#:
#: Rule B derives its denylist from whatever targets are on disk and subtracts
#: this. A dict rather than a set because the reason column is the review
#: artifact: admitting a word has to cost an argument, not a comma. A meta-test
#: below asserts every reason is a sentence, and a second asserts this and
#: `FORGE_VOCABULARY_FLOOR` are disjoint — so no leak already found can be
#: silenced by adding it here.
FORGE_LEXICON: dict[str, str] = {
    "adaptation": "ordinary English in doctrine prose about an arm with its "
                  "adaptation switched off, and the name of the forge's own "
                  "worked example of an assertion that cannot fail",
    "artifacts": "ordinary English for what a run leaves behind, and the "
                 "invented module in the usage reference's worked walkthrough",
    "attention": "ordinary English about what a report spends of its reader, "
                 "used in three places that describe writing rather than code",
    "bag": "the canonical illustration of two incomparable statistical units, "
           "one predicting per instance and the other per bag, which the kit "
           "needs in order to explain when a metric is not applicable",
    "benchmark": "the central noun of this whole skill: the kit ships "
                 "benchmark.py and every target declares a benchmark package",
    "confidence": "ordinary English about how sure a reading is, used in the "
                  "usage reference's prose and in no code path at all",
    "config": "a universal name for the module that holds settings, shipped by "
              "the kit itself and used by every scaffold this forge writes",
    "digest": "the forge's own kit module report_digest.py, which reduces a "
              "report to the numbers a verification can be run against",
    "domain": "an ENVIRONMENT_HINTS entry beside dataset, task and corpus: "
              "generic vocabulary for where data comes from, named by no target",
    "figures": "one of the two module names rule A allows a worked example to "
               "draw from, because the kit's own declaration already uses it",
    "harness": "probe returns a harnessStatus key and the doctrine says the "
               "harness refuses; the kit's own scaffold default for it is "
               "benchmark.py",
    "init": "the __init__.py every Python package on earth is required to have, "
            "including the declaration this skill writes",
    "kernel": "generic compute vocabulary for the unit a device queues, needed "
              "by the kit's note on why a timer stopped too early lies",
    "kernels": "the plural of the same generic compute vocabulary, in the same "
               "note in the kit's benchmark module",
    "local": "ordinary English for a remedy or a path that stays on this "
             "machine, used throughout the doctrine and the checker",
    "models": "generic machine-learning vocabulary and the name of this "
              "repository's own checkpoint directory, which no target owns",
    "objective": "the forge's declared report vocabulary for what a run is "
                 "trying to optimize, and ordinary English besides",
    "pipeline": "ordinary English for a sequence of steps, used twice in "
                "doctrine prose about how a construction arranges itself",
    "pooling": "the statistical act of folding several measurements into one, "
               "named in the doctrine sentence that says every rule governing a "
               "measurement governs every statement derived from it. The forge "
               "wrote it on 2026-08-13, three weeks before any target had a "
               "module by that name, so the word is this skill's own and not a "
               "loan from the repository that happens to share it",
    "record": "the forge's own evidence vocabulary: `@record` is one of the "
              "four witness kinds `impl_position` recognizes, and the report "
              "contract has declared `records` since before any target did",
    "report": "the central noun of the report contract this skill exists to "
              "check, appearing in doctrine on nearly every page",
    "steps": "the forge's own declaration surface and its command: a target "
             "declares `__steps__`, `impl_steps.py` runs one, and `step` is "
             "the subcommand -- named by this skill, never by a repository",
    "shard": "the forge's own distribution vocabulary: a declaration says which "
             "fields must be identical across shards and verify reads it",
    "shards": "the plural of the same distribution vocabulary, in the same "
              "declaration and the same checker",
    "tables": "the other module name rule A allows a worked example to draw "
              "from, because the kit's own declaration already uses it",
    "term": "ordinary English for a word being defined, and for a component of "
            "a sum the report contract already names generically",
    "training": "ordinary English and generic machine-learning vocabulary: the "
                "harness owns training and measuring and nothing else",
    "verdict": "the forge's own kit module verdict.py and the noun the whole "
               "flow ends on, named by the skill long before any target",
    "wiring": "the forge's own vocabulary for how a benchmark reaches prior "
              "work, checked by this skill and shipped in its kit",
}

#: Rule A's allowlist. A worked report example may draw its module names from
#: these two and nothing else, because these two are what the kit's own
#: declaration already uses (`assets/kit/src_benchmark/__init__.py:55-57`).
EXAMPLE_MODULE_NAMES = frozenset({"tables", "figures"})


class RehearsalAuthorityTests(unittest.TestCase):
    """A rehearsal is not a campaign, and this flow only ever declined the
    campaign.

    The remote-execution roster's `submit` row says this flow "offers a campaign
    to a human and never sends one itself" — a sentence about the long run, and
    the right one for it: a campaign costs hours and real quota, so a person
    authorizes it. A rehearsal is the opposite thing. It is one arm, one seed,
    minutes, and it exists to find cheaply what the long run would find
    expensively.

    Nothing forbade the agent from running it. Nothing told it to either, so it
    stopped and asked — and asking is what made the cheap check feel as costly as
    the expensive one. The gap was a missing instruction, not a rule to relax.

    Deliberately untouched: `smokeReady` still gates nothing. It cannot, for the
    reason the doctrine already gives — the fact answers identically for a
    repository with no remote-execution CLI at all and one that has generated no
    job — and this change does not pretend otherwise. What routes the agent is
    the Decision Gates row a reader already follows, not a new rung.
    """

    def rehearsal_paragraph(self) -> str:
        text = SKILL_MD.read_text(encoding="utf-8")
        marker = "### The rehearsal is the agent's to run"
        self.assertIn(marker, text,
                      "no section says whose job the rehearsal is, so an agent "
                      "reaching a job that never rehearsed can only ask")
        return text.split(marker, 1)[1].split("\n## ", 1)[0].split("\n### ", 1)[0]

    def test_the_flow_is_told_to_run_the_rehearsal_and_names_the_command(self):
        """An instruction that never names the command is a sentence a reader
        agrees with and cannot act on.
        """
        paragraph = self.rehearsal_paragraph()
        self.assertIn("--smoke", paragraph)
        self.assertIn("smoke record", paragraph)
        self.assertIn("readiness", paragraph)

    def test_the_campaign_stays_the_human_s_to_authorise(self):
        """The distinction is the whole point: relaxing the rehearsal must not
        quietly relax the run it protects.
        """
        paragraph = self.rehearsal_paragraph()
        self.assertRegex(paragraph, r"campaign")
        text = SKILL_MD.read_text(encoding="utf-8")
        self.assertIn("never sends one itself", text,
                      "the campaign's own refusal was removed along with the "
                      "rehearsal's permission")

    def test_smoke_ready_still_gates_nothing(self):
        """Locked because this change is exactly the kind that would erode it:
        permitting the rehearsal is not the same as branching on the fact, and
        the fact still cannot tell `not ready` from `not applicable`.
        """
        text = SKILL_MD.read_text(encoding="utf-8")
        row = [line for line in text.splitlines()
               if line.startswith("| `smokeReady` |")]
        self.assertEqual(len(row), 1, "no smokeReady row to hold")
        self.assertIn("**Never**", row[0])


class ForgeVocabularyDerivedGuardTests(unittest.TestCase):
    """A guard that scans a fixed word list can only catch a leak somebody has
    already found. This derives the denylist from the targets on disk instead.

    Two rules at two units, because neither one covers the other:

    - **Rule A** reads a worked report example and demands every dotted name
      draw its module from `EXAMPLE_MODULE_NAMES`. It needs no lexicon and it is
      the only rule that can catch a leak spelled with a word the forge
      legitimately owns — `harness` is in the lexicon by necessity, so no
      word-level rule can ever object to `harness.render_panorama`.
    - **Rule B** derives every target's vocabulary from directory, package and
      module names, subtracts `FORGE_LEXICON`, and objects to what is left.

    `FORGE_VOCABULARY_FLOOR` is rule C and lives on the class next door, which
    already scans it over the same surface.
    """

    SKILL_ROOT = ReportFirstSectionProseTests.SKILL_ROOT
    CACHES = ReportFirstSectionProseTests.CACHES
    BINARY_SUFFIXES = ReportFirstSectionProseTests.BINARY_SUFFIXES

    # One definition of the guarded surface, borrowed rather than restated: a
    # second spelling of "what the forge ships" is how the two go out of step.
    guarded_documents = ReportFirstSectionProseTests.guarded_documents
    scannable_text = ReportFirstSectionProseTests.scannable_text

    TARGETS = FORGE / "implementations"

    #: Split on punctuation and on camel-case boundaries, so `FEM_TOLLA_Benchmark`
    #: and `reportDigest` both come apart into the words a reader would say.
    WORD_SPLIT_RE = re.compile(r"[^A-Za-z0-9]+|(?<=[a-z])(?=[A-Z])")

    #: Two-letter fragments match too much ordinary text to carry a verdict.
    MINIMUM_WORD = 3

    def split(self, name):
        return [part.lower() for part in self.WORD_SPLIT_RE.split(name) if part]

    def target_words(self, root=None):
        """Every word the targets on disk own, and the targets they came from.

        Names only: directory, package and module basenames. No file under
        `implementations/` is opened, which is what keeps this read-only and
        keeps the cost proportional.

        Directories beginning with `_` are skipped because that is where this
        suite builds its own throwaway targets; deriving the denylist from them
        would make the guard depend on which tests happened to run first.
        """
        base = self.TARGETS if root is None else Path(root)
        words: set[str] = set()
        targets: list[str] = []
        if not base.is_dir():
            return words, targets
        for target in sorted(base.iterdir()):
            if not target.is_dir() or target.name.startswith((".", "_")):
                continue
            targets.append(target.name)
            words.update(self.split(target.name))
            source = target / "src"
            if not source.is_dir():
                continue
            for package in sorted(source.iterdir()):
                if not package.is_dir() or package.name in self.CACHES:
                    continue
                words.update(self.split(package.name))
                for module in sorted(package.glob("*.py")):
                    words.update(self.split(module.stem))
        return {word for word in words if len(word) >= self.MINIMUM_WORD}, targets

    def derived_denylist(self, root=None):
        """Rule B's denylist, or a skip when nobody has a target.

        Silence is the right answer for a clone with no `implementations/`
        repository, but it has to be an announced silence: a guard that passes
        because it had nothing to look at reads exactly like a guard that
        looked and found nothing.
        """
        words, targets = self.target_words(root)
        if not targets:
            self.skipTest(
                "no repository under implementations/, so rule B has no "
                "vocabulary to derive and this is silence rather than a pass")
        return sorted(words - set(FORGE_LEXICON))

    def leaks(self, denylist, root=None):
        found = {}
        for document in self.guarded_documents(root):
            text = self.scannable_text(document)
            hits = [word for word in denylist
                    if re.search(rf"\b{re.escape(word)}\b", text)]
            if hits:
                base = self.SKILL_ROOT if root is None else Path(root)
                found[str(document.relative_to(base))] = hits
        return found

    def test_rule_b_finds_no_target_vocabulary_in_the_forge(self):
        """The denylist is whatever the targets on disk own, minus what the
        forge owns. Anything left that appears in a forge file is a leak, and
        it is a leak whether or not anybody wrote it on a list first.
        """
        denylist = self.derived_denylist()
        self.assertTrue(
            denylist,
            "every derived word is in the lexicon, so rule B is deriving "
            "nothing and cannot object to anything")
        self.assertEqual(
            self.leaks(denylist), {},
            "these words belong to a repository under implementations/ and "
            "are neither in FORGE_LEXICON nor repaired")

    #: The keys a worked report declaration is written with. A dotted name is
    #: subject to rule A when it stands on a line that also carries one of these,
    #: which is what separates `"figures.curves"` in an example from `"README.md"`
    #: in a list of real filenames. Measured before it was written: scoped this
    #: way the rule sees 23 dotted names across the whole forge and objects to
    #: exactly the leaked ones; unscoped it sees sixty, nearly all of them real
    #: files, and would have to grow an exemption list to say anything at all.
    REPORT_KEY_RE = re.compile(
        r"""['"](renderers|conclusions|conclusionEntry|objectiveEntry"""
        r"""|figures|record)['"]""")

    #: `module.attribute`, quoted, both halves identifiers. A path keeps its
    #: slash and so never matches, which is why `"Results/summary.json"` is not
    #: read as a module name.
    DOTTED_RE = re.compile(
        r"""(?P<quote>['"])"""
        r"""(?P<name>[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*)"""
        r"""(?P=quote)""")

    def example_names(self, root=None):
        """Every dotted name a worked report example spells, with its place."""
        base = self.SKILL_ROOT if root is None else Path(root)
        found = []
        for document in self.guarded_documents(root):
            text = document.read_text(encoding="utf-8", errors="replace")
            for number, line in enumerate(text.splitlines(), start=1):
                if not self.REPORT_KEY_RE.search(line):
                    continue
                for match in self.DOTTED_RE.finditer(line):
                    found.append((str(document.relative_to(base)), number,
                                  match.group("name")))
        return found

    def example_violations(self, root=None):
        return [place for place in self.example_names(root)
                if place[2].split(".")[0] not in EXAMPLE_MODULE_NAMES]

    def scratch_forge(self):
        """The forge's shape, built for the purpose rather than borrowed.

        A rule that passes because nothing is wrong today has not been shown to
        do anything, so this is proven the way `test_a_leak_into_a_script_is_caught`
        already proves the fixed list: build the surface, plant one leak in it,
        and read back exactly what was named.
        """
        base = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, base, ignore_errors=True)
        (base / "references").mkdir()
        (base / "assets").mkdir()
        (base / "scripts").mkdir()
        (base / "SKILL.md").write_text("Generic doctrine.\n", encoding="utf-8")
        (base / "references" / "usage.md").write_text("Generic.\n", encoding="utf-8")
        return base

    def scratch_targets(self):
        """A target root built for the purpose, owning words nothing else uses.

        Rule B derives its denylist from `implementations/` on disk, so proving
        the rule reachable means owning both ends of it. Borrowing the checkout's
        real target would not do: its vocabulary is whatever somebody happens to
        have cloned, and the forge is clean of it, which is the condition under
        which rule B says nothing at all.

        The names are invented. No repository is called `Nimbus_Benchmark` and no
        forge file says `paddock`, so a hit read back from this tree is
        attributable to the derivation and to nothing else.
        """
        base = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, base, ignore_errors=True)
        package = base / "Nimbus_Benchmark" / "src" / "nimbus_benchmark"
        package.mkdir(parents=True)
        (package / "__init__.py").write_text("", encoding="utf-8")
        (package / "config.py").write_text("VALUE = 1\n", encoding="utf-8")
        (package / "paddock.py").write_text("VALUE = 2\n", encoding="utf-8")
        return base

    def test_rule_b_names_the_file_and_the_word_a_planted_leak_is_in(self):
        """Rule B, proven the way rules A and C already are.

        Against a clean checkout rule B is green because nothing is wrong, and a
        rule that is green because nothing is wrong cannot be told apart from a
        rule that is switched off: neuter the matcher in `leaks` so it can never
        fire and the whole suite still passes. The rule was reachable the day it
        was written and nothing kept that proof, which is the same objection this
        file makes about everything else.

        So this owns both ends — a target that owns `paddock` and a forge file
        that borrows it — and reads back the exact pair the guard reports, not
        merely that something failed. `paddock` is in neither `FORGE_LEXICON` nor
        `FORGE_VOCABULARY_FLOOR`, so no fixed list could have caught it, and it
        is derived from a module basename rather than the target's own directory
        name, so a rule reading only the top level could not have either.
        """
        self.assertNotIn("paddock", FORGE_LEXICON)
        self.assertNotIn("paddock", FORGE_VOCABULARY_FLOOR)

        denylist = self.derived_denylist(self.scratch_targets())
        self.assertEqual(
            denylist, ["nimbus", "paddock"],
            "the denylist is every word the target owns minus the lexicon, so "
            "`benchmark`, `config` and `init` are subtracted and these are left")

        forge = self.scratch_forge()
        (forge / "scripts" / "leaky.py").write_text(
            "# staged in the paddock before the run\nVALUE = 1\n",
            encoding="utf-8")
        (forge / "scripts" / "clean.py").write_text(
            "VALUE = 2\n", encoding="utf-8")
        self.assertEqual(
            self.leaks(denylist, forge), {"scripts/leaky.py": ["paddock"]},
            "rule B has to name the file and the word, because a guard that "
            "reports only that something is wrong repairs nothing")

    def test_rule_a_names_the_file_a_planted_example_leak_is_in(self):
        base = self.scratch_forge()
        (base / "scripts" / "leaky.py").write_text(
            'CONTRACT = {"figures": ["figures.curves", "spectra.grid"]}\n',
            encoding="utf-8")
        (base / "scripts" / "clean.py").write_text(
            'CONTRACT = {"figures": ["figures.curves"]}\n', encoding="utf-8")
        self.assertEqual(
            self.example_violations(base),
            [("scripts/leaky.py", 1, "spectra.grid")])

    def test_rule_a_objects_to_a_module_the_forge_legitimately_owns(self):
        """The reason rule A exists at all.

        `harness` is in `FORGE_LEXICON` by necessity — `probe` returns a
        `harness` key and the doctrine says the harness refuses — so rule B can
        never object to `harness.render_panorama`, which is one of the leaks the
        derived guard was adopted to catch. An allowlist over invented example
        names is the only rule that can, and this is that claim measured rather
        than argued.
        """
        base = self.scratch_forge()
        (base / "scripts" / "borrowed.py").write_text(
            'CONTRACT = {"renderers": ["tables.render", "harness.render_panorama"]}\n',
            encoding="utf-8")
        self.assertIn("harness", FORGE_LEXICON)
        self.assertEqual(self.leaks(self.derived_denylist(), base), {})
        self.assertEqual(
            self.example_violations(base),
            [("scripts/borrowed.py", 1, "harness.render_panorama")])

    def test_rule_a_lets_a_worked_example_draw_from_two_module_names(self):
        """An allowlist, which is why it is precise where rule B is not.

        A worked example is invented prose: nothing forces it to reach outside
        the two module names the kit's own declaration already uses. So the rule
        needs no list of forbidden words, and catches a leak nobody enumerated —
        including one spelled with a word the forge legitimately owns, which no
        word-level rule can ever object to.
        """
        names = self.example_names()
        self.assertTrue(
            names,
            "no worked report example was found at all, so this rule is "
            "reading nothing and proving nothing")
        self.assertEqual(
            self.example_violations(), [],
            "a worked report example names a module outside "
            f"{sorted(EXAMPLE_MODULE_NAMES)}, which means it was copied from "
            "somebody's repository instead of invented")

    def test_a_clone_with_no_target_skips_instead_of_passing(self):
        """Rule B is the one rule in this file that reads outside the forge, and
        the price is that it says nothing at all in a clone where nobody has
        checked a repository out yet.

        Saying nothing has to be visible. A skip with a reason tells a reader the
        rule did not run; a green tick tells them it ran and found the forge
        clean, which would be a claim nobody made.
        """
        empty = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, empty, ignore_errors=True)
        with self.assertRaises(unittest.SkipTest) as raised:
            self.derived_denylist(empty)
        self.assertIn("implementations/", str(raised.exception))
        self.assertIn("silence rather than a pass", str(raised.exception))

    def test_every_lexicon_entry_costs_an_argument(self):
        """The reason column is the review artifact.

        A set would let the lexicon grow by one comma per inconvenient failure,
        which is how a derived denylist quietly becomes an empty one. A sentence
        is not proof that the word belongs to the forge, but it is a thing a
        reviewer can disagree with, and that is the whole mechanism.
        """
        thin = {word: reason for word, reason in FORGE_LEXICON.items()
                if len(reason.split()) < 4}
        self.assertEqual(
            thin, {},
            "a lexicon entry has to say why the forge owns the word")

    def test_the_lexicon_cannot_silence_a_leak_already_found(self):
        """The floor and the lexicon are disjoint, structurally.

        Without this, the cheapest way to make rule B green is to declare the
        leaking word forge vocabulary — and the words most likely to be declared
        that way are exactly the ones already proven to be somebody else's.
        """
        self.assertEqual(
            sorted(set(FORGE_LEXICON) & set(FORGE_VOCABULARY_FLOOR)), [],
            "a word on the floor is a leak somebody already found, so it can "
            "never also be vocabulary the forge owns")


class UndeclaredRecordEndToEndTests(unittest.TestCase):
    """The other half of the vocabulary repair, which is not a vocabulary
    question at all: what the checker does when a report declares no record.

    It used to substitute a filename — one particular repository's filename —
    so a target that declared nothing got somebody else's answer. Dropping the
    default is the repair, but the two sites cannot drop it the same way:
    `_is_reporting_cell` is typed `str | None` and answers `False` for anything
    falsy, while `report_state` reads the declared name as text and `p.name in
    None` raises. So one site takes `None` and the other takes `""`.

    This runs the real command over a real target that declares no record,
    because the difference between those two is invisible until something
    actually asks.
    """

    DECLARATION = (
        "__benchmark__ = {\n"
        "    'revision': 'r01.md',\n"
        "    'arms': {},\n"
        "    'report': {\n"
        "        'renderers': ['tables.render'],\n"
        "        'conclusions': ['tables.conclusion'],\n"
        "        'objectiveEntry': 'tables.objective',\n"
        "        'figures': ['figures.curves'],\n"
        "        'components': {'terms': ['fit'], 'share': None},\n"
        "        'dimensions': {'accuracy': 'higher', 'fit': None},\n"
        "    },\n"
        "}\n"
    )

    def verify(self):
        box = FORGE / "implementations" / f"_norecord_{os.getpid()}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src/Method_Benchmark").mkdir(parents=True)
        (box / "Method/Notebooks").mkdir(parents=True)
        (box / "Method/Results").mkdir(parents=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        (box / "src/Method_Benchmark/__init__.py").write_text(
            self.DECLARATION, encoding="utf-8")
        # At least one JSON under the product, or the membership test the repair
        # touches is never reached and this proves nothing.
        (box / "Method/Results/summary.json").write_text(
            json.dumps({"runs": []}), encoding="utf-8")
        cells = [_cell("markdown", "The figure shows the curves."),
                 _cell("code", "figures.curves(path)",
                       outputs=[_shown("image/png")])]
        (box / "Method/Notebooks/Report.ipynb").write_text(
            json.dumps({"cells": cells, "metadata": {}, "nbformat": 4,
                        "nbformat_minor": 5}), encoding="utf-8")
        return subprocess.run(
            [sys.executable, str(CLI), "verify", "--target", str(box),
             "--name", "Method", "--revision", "r01.md"],
            capture_output=True, text=True, cwd=FORGE)

    def test_a_target_that_declares_no_record_still_gets_an_answer(self):
        """Reachable red by making either default `None`: the membership test at
        the top of `report_state` runs before anything else in the report check,
        so `p.name in None` takes down the whole command for every target that
        declared no record — which is every target that has not got that far yet.
        """
        proc = self.verify()
        self.assertEqual(proc.stderr, "", proc.stderr)
        report = json.loads(proc.stdout or "{}")["report"]
        self.assertIn(
            report["status"], ("ok", "drift", "incomplete"),
            "the report check has to reach a verdict on a target that declared "
            "no record, rather than reaching for a filename it read in somebody "
            "else's repository or falling over on the way")

    def test_the_toy_target_left_nothing_behind(self):
        self.verify()
        # Run the registered cleanup now, so what is asserted is the state a
        # later test would find rather than the state mid-test.
        self.doCleanups()
        leftover = list((FORGE / "implementations").glob("_norecord_*"))
        self.assertEqual([str(path) for path in leftover], [])


class DeclarationBlockRosterTests(unittest.TestCase):
    """Three places say this flow asks for the declaration's `revision` and
    `premises`, and no step of it did.

    The doctrine says so where the declaration is described, `declare-first`
    blames the reader for not having done it, and the kit's own scaffold says
    the value is "asked for by the flow, never invented here". Flow A's sixteen
    steps contain no such ask: every `revision` in them is the `--revision` flag
    of `admit` and `verify`, and `premises` appears nowhere at all. So the first
    pass of every new target ends at a rung whose named remedy does not exist.

    What this holds is weaker than it looks and is stated rather than claimed
    away: Flow A is prose executed by an agent, so there is no runtime path to
    assert against and no behavioural partner for these tests. What they can do
    is hold every declaration block to a step that exists and mentions it, which
    is what makes a renumbering or a deleted step fail here instead of silently
    on somebody's first pass.
    """

    KIT_DECLARATION = KIT / "src_benchmark" / "__init__.py"
    BLOCK_TABLE_HEADER = "| Block | Filled by | When |"
    FLOW_HEADING = "## Flow A — first pass"
    STEP_RE = re.compile(r"^(\d+)\.\s")

    def declared_blocks(self):
        """The six top-level keys of `__benchmark__`, read from the kit.

        From the file the scaffold actually copies, so a block added there has
        to be given a filling step rather than appearing in a target nobody told
        how to fill it.
        """
        tree = ast.parse(self.KIT_DECLARATION.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if not isinstance(node, ast.Assign):
                continue
            names = [t.id for t in node.targets if isinstance(t, ast.Name)]
            if "__benchmark__" not in names:
                continue
            self.assertIsInstance(node.value, ast.Dict)
            return [key.value for key in node.value.keys
                    if isinstance(key, ast.Constant)]
        self.fail("the kit declares no `__benchmark__` literal")

    def flow_steps(self):
        """Flow A's numbered steps, as {number: the whole step's text}."""
        text = SKILL_MD.read_text(encoding="utf-8")
        start = text.index(self.FLOW_HEADING)
        end = text.index("\n## ", start + len(self.FLOW_HEADING))
        steps: dict[int, list[str]] = {}
        current = None
        for line in text[start:end].splitlines():
            match = self.STEP_RE.match(line)
            if match:
                current = int(match.group(1))
                steps[current] = []
            if current is not None:
                steps[current].append(line)
        return {number: "\n".join(lines) for number, lines in steps.items()}

    def block_rows(self):
        tables = markdown_table_rows(
            SKILL_MD.read_text(encoding="utf-8"), self.BLOCK_TABLE_HEADER)
        self.assertEqual(
            len(tables), 1,
            "the declaration's blocks are stated in no parseable table, so "
            "which step fills each one is prose and drifts unobserved")
        return tables[0]

    def test_every_declaration_block_has_a_row(self):
        self.assertEqual(
            sorted(row[0].strip("`") for row in self.block_rows()),
            sorted(self.declared_blocks()),
            "a block the kit scaffolds is named in no row, or a row names a "
            "block the kit does not scaffold")

    def test_every_flow_a_cell_names_a_step_that_mentions_its_block(self):
        """The clause that makes the table more than a list.

        A cell saying `step 8` is worth nothing if step 8 was renumbered, or if
        it never mentions the block the row is about. Reachable red by changing
        one cell to a step that does not exist, and by deleting the mention.
        """
        steps = self.flow_steps()
        broken = []
        for row in self.block_rows():
            block, filled_by = row[0].strip("`"), row[1]
            match = re.search(r"Flow A step (\d+)", filled_by)
            if not match:
                continue
            number = int(match.group(1))
            if number not in steps:
                broken.append((block, f"step {number} does not exist"))
            elif block not in steps[number]:
                broken.append((block, f"step {number} never mentions it"))
        self.assertEqual(broken, [])

    def test_flow_a_asks_for_the_revision_and_the_premises(self):
        """The finding itself: three assertions and no step.

        Scoped to the step behind the authorization gate, because that is where
        the answers exist — the gate's own protocol draft has already produced a
        prediction, a statistical unit, a metric and a direction — and because
        `AGREEMENTS.md`'s rule is already "append at every gate, before writing
        any code the gate authorized".
        """
        steps = self.flow_steps()
        self.assertIn(8, steps, "Flow A has no step 8 to hold this to")
        for field in ("revision", "premises"):
            self.assertIn(
                f"`{field}`", steps[8],
                f"Flow A step 8 never asks for the declaration's `{field}`, "
                "which the doctrine, `declare-first` and the kit all say it does")

    def test_the_three_assertions_still_say_the_flow_asks(self):
        """If any of the three stopped claiming it, this repair would be
        answering a question nobody asks any more — so the claims are pinned
        beside the step that now honours them."""
        skill = SKILL_MD.read_text(encoding="utf-8")
        self.assertIn(
            "**`revision` and `premises` are asked by this flow, never invented.**",
            skill)
        self.assertIn("Flow A's ask for `revision` and `premises`", skill)
        self.assertIn(
            "asked for by the flow, never invented here",
            self.KIT_DECLARATION.read_text(encoding="utf-8"))


class SeventhScaffoldBlockTests(unittest.TestCase):
    """The scaffold's `__benchmark__` literal gains a seventh block, `entry`,
    prefilled empty exactly like the other six — and the doctrine's own count
    of "six blocks" moves to seven with it, named here rather than absorbed
    silently.

    This is the one non-additive cost of Decision 10: `probe`'s harness
    resolution can only stop naming `benchmark.py` for every target once a
    target has somewhere of its own to declare a different name instead.
    """

    KIT_DECLARATION = KIT / "src_benchmark" / "__init__.py"

    def declared_blocks(self) -> dict:
        tree = ast.parse(self.KIT_DECLARATION.read_text(encoding="utf-8"))
        for node in ast.walk(tree):
            if isinstance(node, ast.Assign) and any(
                    isinstance(t, ast.Name) and t.id == "__benchmark__"
                    for t in node.targets):
                return ast.literal_eval(node.value)
        self.fail("the kit declares no `__benchmark__` literal")

    def test_the_scaffold_declares_seven_blocks_not_six(self):
        declared = self.declared_blocks()
        self.assertEqual(
            sorted(declared),
            ["arms", "distribution", "entry", "premises", "report",
             "revision", "search"],
            "the scaffold must carry exactly seven top-level blocks")

    def test_the_entry_block_is_prefilled_empty(self):
        declared = self.declared_blocks()
        self.assertEqual(declared["entry"], {"module": "", "function": ""})

    def test_the_doctrine_names_seven_blocks_not_six(self):
        """The prose that counted the blocks has to count seven now, or the
        doctrine is the one place still telling a reader the old number."""
        text = SKILL_MD.read_text(encoding="utf-8")
        self.assertIn("its seven blocks", text)
        self.assertNotIn("its six blocks", text)
        self.assertIn("all seven top-level blocks", text)

    def test_a_fresh_untouched_scaffold_still_reads_as_blank(self):
        """The seventh block's own blank value is `{"module": "", "function":
        ""}` — a non-empty dict, unlike every other block's `{}` or `""`.
        Bare truthiness would read that dict as an answer nobody gave, and a
        freshly materialized target would report `"declared"` before a
        single block had anything written into it."""
        self.assertTrue(impl._declaration_is_blank(self.declared_blocks()))


class VerifyStatusRosterTests(unittest.TestCase):
    """The Output Contract enumerated eleven statuses and `verify` reports
    thirteen.

    `coupling` and `lfs` were computed, returned and named in no doctrine at
    all — not in the contract that lists what the command reports, not in the
    usage reference a reader follows to read the output. A reader who took the
    contract at its word would find two keys in the JSON nobody had told them
    existed, and would have no way to know whether either one gates.

    The repair is not a longer sentence. A prose list cannot be held to a return
    statement, so the list becomes a table with one row per status, and the
    table is derived-against rather than proof-read: adding a status to `verify`
    now fails this suite until its row exists, which is the whole point.

    What the table cannot do: columns two and three are prose and are not
    asserted. That a row says `never gates` is a claim a human makes; the
    behavioural partner for `coupling` is the `coupling_state` tests that
    already exist.
    """

    STATUS_TABLE_HEADER = "| Status | What it reports | Gates? |"

    #: The envelope, not a status: which command answered, about what, under
    #: which name. Documenting these as statuses would be documenting the shape
    #: of the reply rather than anything the command found.
    IDENTITY_KEYS = frozenset({"command", "target", "name"})

    def reported_statuses(self):
        return sorted(set(returned_keys(CLI, "cmd_verify")) - self.IDENTITY_KEYS)

    def status_rows(self):
        tables = markdown_table_rows(
            SKILL_MD.read_text(encoding="utf-8"), self.STATUS_TABLE_HEADER)
        self.assertEqual(
            len(tables), 1,
            "`verify`'s statuses are stated in no parseable table, so the "
            "Output Contract cannot be held to what the command returns")
        return tables[0]

    def documented_statuses(self):
        return sorted(row[0].strip("`") for row in self.status_rows())

    def test_the_contract_names_every_status_verify_reports(self):
        reported = self.reported_statuses()
        documented = self.documented_statuses()
        self.assertEqual(
            sorted(set(reported) - set(documented)), [],
            "`verify` returns these and the Output Contract names them nowhere")
        self.assertEqual(
            sorted(set(documented) - set(reported)), [],
            "the Output Contract names these and `verify` returns no such key")

    def test_the_contract_counts_the_statuses_it_lists(self):
        """The sentence above the table states how many rows follow, and
        until this existed nothing read it: the count said `sixteen` while
        the roster grew past it. Same doctrine as
        `test_the_roster_states_the_counts_it_actually_holds` -- the number
        stays in the prose, because a reader deserves to be told how big the
        surface is, and re-counting is this suite's work."""
        skill = " ".join(SKILL_MD.read_text(encoding="utf-8").split())
        spelled = _english_count(len(self.status_rows())).lower()
        self.assertIn(f"There are {spelled} of them", skill)

    def test_coupling_is_documented_as_reported_and_never_gating(self):
        """The row that had to exist before the roster could be honest.

        The rejected fourth rule was "every reported fact must be branched on or
        documented", and it is false by construction: `coupling` is computed,
        reported, and deliberately gates nothing. So the bar is documentation,
        and the `Gates?` column is what carries the difference.
        """
        gating = {row[0].strip("`"): row[2] for row in self.status_rows()}
        self.assertIn("coupling", gating)
        self.assertIn("never", gating["coupling"].lower())

    def test_the_usage_reference_tells_a_reader_how_to_read_them(self):
        """The contract says what is reported; `usage.md` is where somebody
        goes to find out what to do about it. Two statuses reached the JSON
        without reaching either."""
        usage = USAGE_MD.read_text(encoding="utf-8")
        section = usage[usage.index("## Reading `verify`"):]
        section = section[:section.index("\n## ", 1)]
        for status in ("coupling", "lfs", "position"):
            self.assertIn(f"`{status}`", section)

    def test_toDiscuss_is_documented_in_reading_verify(self):
        """Design D1 / spec Domain B: the new top-level `toDiscuss` key,
        same doctrine as `test_the_usage_reference_tells_a_reader_how_to_
        read_them` above -- a status that reached the JSON is worth nothing
        to a reader who is never told it exists."""
        usage = USAGE_MD.read_text(encoding="utf-8")
        section = usage[usage.index("## Reading `verify`"):]
        section = section[:section.index("\n## ", 1)]
        self.assertIn("`toDiscuss`", section)

    def test_undeclaredOptional_is_documented_in_reading_verify(self):
        """Gap 1: the new top-level `undeclaredOptional` key, same doctrine
        as the `toDiscuss` test above -- a status that reached the JSON is
        worth nothing to a reader never told it exists."""
        usage = USAGE_MD.read_text(encoding="utf-8")
        section = usage[usage.index("## Reading `verify`"):]
        section = section[:section.index("\n## ", 1)]
        self.assertIn("`undeclaredOptional`", section)

    def test_the_non_goal_is_stated_without_softening(self):
        """Cross-Domain Requirement (spec): the non-goal sentence -- the
        gate/publication points prove a decision reached the record, never
        that the operator authored it -- must appear in `SKILL.md`,
        unsoftened."""
        skill = " ".join(SKILL_MD.read_text(encoding="utf-8").split())
        self.assertIn("never that the operator authored it", skill)
        self.assertIn("An agent can open a question and answer it itself, "
                      "and nothing downstream can tell", skill)

    def test_the_roster_names_a_renamed_key(self):
        """Reachability, measured rather than asserted.

        This test is red by construction — it was written against a contract
        naming eleven statuses and a command returning thirteen — so it needs no
        inversion of the doctrine. What it does still owe is a demonstration
        that the failure *names* the divergence rather than reporting a bare
        inequality, which is the difference between a lock somebody can act on
        and one they have to go looking behind.
        """
        scratch = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, scratch, ignore_errors=True)
        copy = scratch / "renamed_cli.py"
        copy.write_text(
            CLI.read_text(encoding="utf-8").replace(
                '        "lfs": lfs_state(target),',
                '        "largeFiles": lfs_state(target),'),
            encoding="utf-8")
        renamed = set(returned_keys(copy, "cmd_verify")) - self.IDENTITY_KEYS
        self.assertEqual(sorted(renamed - set(self.documented_statuses())),
                         ["largeFiles"])
        self.assertEqual(sorted(set(self.documented_statuses()) - renamed),
                         ["lfs"])


class ProbeReportedFactsRosterTests(unittest.TestCase):
    """`probe` computes seventeen keys and the doctrine enumerated none of
    them, so two facts a reader needs before spending machine time — whether
    a job ever rehearsed, and whether the commit it is pinned to still
    matches the repository — reached the JSON and no page.

    **Why they are documented and never gating, stated as a position rather
    than left as an omission.** `remote_execution_jobs_state()` answers
    `{"jobs": [], "services": 0, "smokeReady": {}}` when the remote-execution
    CLI is not on disk at all, which is byte-identical to what it answers for
    a repository that has the CLI and has generated no job. The fact as
    computed cannot tell "not ready" from "does not apply", and a rung needs
    exactly that difference: branching on it would suppress a legitimate
    `benchmark` answer for every repository that never sends work anywhere.
    So the ladder is left alone and the reader is handed the fact beside the
    answer.

    **The falsifier, recorded rather than implied.** If
    `remote_execution_jobs_state()` grew a per-job link to the campaign about
    to be offered — so that an unrehearsed job could be tied to the run being
    proposed rather than to the repository in general — the distinction
    becomes expressible and this position should be revisited. Until then it
    is not, and the behavioural test below is what makes that a decision
    somebody can overturn instead of a gap nobody noticed.

    What this roster cannot do is the same limit the `verify` roster carries:
    columns two and three are prose and are not asserted. That a row says a
    fact never gates is a claim a human makes; the behavioural test in this
    class is what carries it for `smokeReady`.
    """

    FACT_TABLE_HEADER = "| Fact | What it reports | Gates? |"
    JOB_FACT_TABLE_HEADER = "| Job fact | What it reports | Gates? |"
    GATES_TABLE_HEADER = "| Situation | Action |"

    #: The envelope, not a fact about the repository: `status` and `kind` are
    #: string literals in the return, identical for every target that reaches
    #: it, and `target`/`name` say which repository was asked. Documenting any
    #: of the four as a reported fact would document the shape of the reply.
    IDENTITY_KEYS = frozenset({"status", "target", "name", "kind"})

    def reported_facts(self):
        return sorted(set(returned_keys(CLI, "cmd_probe")) - self.IDENTITY_KEYS)

    def fact_rows(self):
        tables = markdown_table_rows(
            SKILL_MD.read_text(encoding="utf-8"), self.FACT_TABLE_HEADER)
        self.assertEqual(
            len(tables), 1,
            "`probe`'s reported facts are stated in no parseable table, so "
            "the doctrine cannot be held to what the command returns")
        return tables[0]

    def job_fact_rows(self):
        tables = markdown_table_rows(
            SKILL_MD.read_text(encoding="utf-8"), self.JOB_FACT_TABLE_HEADER)
        self.assertEqual(
            len(tables), 1,
            "the job-folder facts folded into `remoteExecution` are stated in "
            "no parseable sub-table, so nothing holds them to the function "
            "that computes them")
        return tables[0]

    def test_the_doctrine_names_every_fact_probe_reports(self):
        reported = self.reported_facts()
        documented = sorted(row[0].strip("`") for row in self.fact_rows())
        self.assertEqual(
            sorted(set(reported) - set(documented)), [],
            "`probe` returns these and the doctrine names them nowhere")
        self.assertEqual(
            sorted(set(documented) - set(reported)), [],
            "the doctrine names these and `probe` returns no such key")

    def test_the_remote_execution_row_carries_its_job_facts(self):
        """`remoteExecution` is two sources folded under one key: the ledger
        and the filesystem. One row cannot say what a reader is looking at,
        so the row has a sub-table, and the sub-table is derived from the
        function that computes the second half.
        """
        derived = sorted(returned_keys(CLI, "remote_execution_jobs_state"))
        documented = sorted(row[0].strip("`") for row in self.job_fact_rows())
        self.assertEqual(
            sorted(set(derived) - set(documented)), [],
            "`remote_execution_jobs_state` returns these and the sub-table "
            "names them nowhere")
        self.assertEqual(
            sorted(set(documented) - set(derived)), [],
            "the sub-table names these and no such key is computed")

    def test_smoke_ready_is_documented_as_reported_and_never_gating(self):
        gating = {row[0].strip("`"): row[2] for row in self.job_fact_rows()}
        self.assertIn("smokeReady", gating)
        self.assertIn("never", gating["smokeReady"].lower())

    def test_the_decision_gates_send_a_reader_to_both_facts(self):
        """A fact reported beside an offer to run is only read if something
        tells the reader to read it. The Decision Gates table is where this
        skill says what to do about a state, so that is where both belong.
        """
        rows = markdown_table_rows(
            SKILL_MD.read_text(encoding="utf-8"), self.GATES_TABLE_HEADER)
        self.assertEqual(len(rows), 1, "the Decision Gates table moved")
        situations = "\n".join(row[0] for row in rows[0])
        self.assertIn("smokeReady", situations,
                      "no gate row tells a reader to read a job that never "
                      "rehearsed before offering a campaign")
        self.assertIn("staleness", situations,
                      "no gate row tells a reader to read a job pinned to a "
                      "commit the repository has moved past")
        self.assertIn("position: \"stale\"", situations,
                      "no gate row tells a reader the position section is "
                      "bound to a revision that has moved on")
        self.assertIn("position.disagreements", situations,
                      "no gate row tells a reader a recorded mark contradicts "
                      "its own measured evidence")
        self.assertIn("NOT_READY", situations,
                      "no gate row tells a reader why `gate` refused a launch "
                      "with no passing rehearsal on file")

    def test_the_usage_reference_tells_a_reader_what_to_do_about_them(self):
        usage = USAGE_MD.read_text(encoding="utf-8")
        section = usage[usage.index("## Reading `probe`"):]
        section = section[:section.index("\n## ", 1)]
        for fact in ("smokeReady", "staleness"):
            self.assertIn(f"`{fact}`", section)

    #: A target the ladder actually offers a run for. Every earlier rung has
    #: to be satisfied — a baseline to compare against, a trainable backend,
    #: a declaration, a faithful arm, no submission out, no declared search,
    #: and a report that agrees with the code — because a fixture answering
    #: `report-first` would never reach the branch this class is about.
    DECLARATION = (
        "__benchmark__ = {\n"
        "    'revision': 'r01.md',\n"
        "    'arms': {'floor': {'sections': ['3']}, "
        "'full': {'sections': ['3']}},\n"
        "    'report': {'renderers': ['tables.render'],\n"
        "               'conclusions': ['tables.conclude'],\n"
        "               'conclusionEntry': 'tables.conclude',\n"
        "               'objectiveEntry': 'tables.aim',\n"
        "               'figures': [],\n"
        "               'dimensions': {'scale': 'higher'},\n"
        "               'components': {'first': 'the first term'},\n"
        "               'record': 'summary.json',\n"
        "               'records': ['Results/summary.json']},\n"
        "    'entry': {'module': 'Method_Benchmark.benchmark',\n"
        "              'function': 'run'},\n"
        "}\n")
    WIRING = ("from Method.called import called\n"
              "from Method.never_called import total\n")
    TABLES = ("def render(record):\n"
              "    return record\n\n"
              "def aim(record):\n"
              "    return {'scale': 0.5}\n\n"
              "def conclude(record):\n"
              "    return {'scale': f\"{record['cells'][0]['value']}\"}\n")

    def build_target(self, suffix):
        """A target the ladder answers `benchmark` for, built for the purpose.

        The interpreter under `.venv/` is a link to the one running this suite
        rather than a built environment: the live half of the report check only
        needs an interpreter that can import the target's own package off
        `src/`, and building a real environment per test would buy nothing and
        cost seconds.
        """
        box = FORGE / "implementations" / f"_smokebox_{suffix}_{os.getpid()}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        for directory in ("src/Method", "src/Method_Benchmark", "src/Prior",
                          "Method/Results"):
            (box / directory).mkdir(parents=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        (box / "src/Method/called.py").write_text(
            _module("r01.md", ["3"], ["11"], imports="import torch\n"),
            encoding="utf-8")
        (box / "src/Method/never_called.py").write_text(
            _module("r01.md", ["3"], ["12"], imports="import torch\n"),
            encoding="utf-8")
        (box / "src/Prior/model.py").write_text("import torch\n", encoding="utf-8")
        (box / "src/Method_Benchmark/__init__.py").write_text(
            self.DECLARATION, encoding="utf-8")
        (box / "src/Method_Benchmark/wiring.py").write_text(
            self.WIRING, encoding="utf-8")
        (box / "src/Method_Benchmark/config.py").write_text(
            "SCALES = [1, 2, 3]\n", encoding="utf-8")
        (box / "src/Method_Benchmark/tables.py").write_text(
            self.TABLES, encoding="utf-8")
        # The declared entry module `introspect` now executes as its liveness
        # check (Decision 9) — undeclared here, so it falls back to the
        # scaffold's own harness-file convention (`BENCHMARK_MODULE`). Present
        # and importable, exactly as a repository that has actually run one
        # would have it.
        (box / f"src/Method_Benchmark/{impl.BENCHMARK_MODULE}").write_text(
            "import torch\n", encoding="utf-8")
        (box / "Method/Results/summary.json").write_text(
            json.dumps({"cells": [{"value": 1.0, "first": 0.5}]}),
            encoding="utf-8")

        write_fixture_interpreter(
            box / ".venv" / ("Scripts" if os.name == "nt" else "bin"))

        git = ["git", "-c", "user.email=forge@example.invalid",
               "-c", "user.name=forge", "-C", str(box)]
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        subprocess.run(git + ["add", "-A"], check=True, capture_output=True)
        subprocess.run(git + ["commit", "-qm", "toy"], check=True,
                       capture_output=True)
        head = subprocess.run(git + ["rev-parse", "HEAD"], check=True,
                              capture_output=True, text=True).stdout.strip()
        return box, head

    def write_job_folder(self, box, commit):
        """One job folder in the shape `guard_entrypoint()` admits and
        `generate-job` writes — `<target>/tools/<service>/<job-name>/` around a
        `run-config.json`. Written to disk rather than faked, because the fact
        under test is read from disk by the same reader every other command
        uses, and a hand-shaped dict would prove nothing about what `probe`
        finds.
        """
        job_dir = box / "tools" / "service" / "job"
        job_dir.mkdir(parents=True)
        (job_dir / "run-config.json").write_text(json.dumps({
            "schemaVersion": 1,
            "product": "Method",
            "service": "service",
            "jobName": "job",
            "commit": commit,
            "repo": {"url": "https://example.invalid/toy.git", "ref": "main"},
            "clonePaths": ["src"],
            "run": {"module": "Method_Benchmark.wiring", "function": "main",
                    "kwargs": {}},
            "runnerTemplate": {},
        }), encoding="utf-8")

    def probe(self, box):
        proc = subprocess.run(
            [sys.executable, str(CLI), "probe", "--target", str(box),
             "--name", "Method", "--revision", "r01.md"],
            capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        return json.loads(proc.stdout or "{}")

    def test_the_fixture_reaches_the_run_offer_before_any_job_folder_exists(self):
        """The pole. Without it every assertion below could be passing because
        the ladder never got near the offer, and nothing would say so."""
        box, _ = self.build_target("pole")
        probe = self.probe(box)
        self.assertEqual(probe["report"]["status"], "ok")
        self.assertEqual(probe["nextStep"], "benchmark")

    def test_a_job_that_never_rehearsed_still_reaches_the_benchmark_offer(self):
        """The position, made behavioural.

        A sentence saying the ladder does not branch on `smokeReady` is a
        sentence anybody can contradict with four lines of code and nothing
        going red. This is the test such a change has to break.
        """
        box, head = self.build_target("ready")
        self.write_job_folder(box, head)
        probe = self.probe(box)
        self.assertEqual(
            probe["remoteExecution"]["smokeReady"], {"job": False},
            "the fixture stopped producing an unrehearsed job, so this test "
            "is no longer about anything")
        self.assertEqual(probe["nextStep"], "benchmark")

    def test_a_job_pinned_to_a_commit_that_is_not_in_the_history_still_offers_the_run(self):
        """The other half of the same position. A pin nothing in the history
        matches reports `unknown` — the honest verdict, and still not a rung.
        """
        box, _ = self.build_target("stale")
        self.write_job_folder(box, "0" * 40)
        probe = self.probe(box)
        self.assertEqual(
            [job["staleness"]["status"]
             for job in probe["remoteExecution"]["jobs"]],
            ["unknown"])
        self.assertEqual(probe["nextStep"], "benchmark")

    def test_a_job_with_no_accelerator_and_no_local_budget_classifies_optional(self):
        """`classify_remote_necessity` (design D3, `the-pilot-decides-the-
        remote-strategy`) is purely additive in this slice -- reported
        beside the offer, refusing nothing. This fixture's job folder
        declares neither `accelerator` nor `localBudget`, and the fixture
        never wrote a `Probe_results.json` at all, so `results.status` is
        `"absent"` -- the more fundamental gap that outranks a merely
        undeclared budget (design D3's rule 5 sub-priority).
        """
        box, head = self.build_target("optional")
        self.write_job_folder(box, head)
        probe = self.probe(box)
        necessity = probe["remoteExecution"]["necessity"]
        self.assertEqual(probe["results"]["status"], "absent")
        self.assertEqual(
            necessity["jobs"]["job"],
            {"necessity": "optional", "reason": "results.unmeasured"})
        self.assertEqual(necessity["summary"],
                         {"mustRemote": 0, "localSufficient": 0, "optional": 1})

    def test_the_toy_targets_left_nothing_behind(self):
        box, head = self.build_target("cleanup")
        self.write_job_folder(box, head)
        self.probe(box)
        self.doCleanups()
        leftover = list((FORGE / "implementations").glob("_smokebox_*"))
        self.assertEqual(leftover, [], leftover)

    # --- Phase 4: probe's `piloted` `toDiscuss` (spec "Probe's `piloted`
    # status publishes a specific, runnable discuss command"; design D1/D5).
    # Reuses `build_target` unchanged -- the identical repository that
    # already reaches `benchmark` with all seven downgrade rungs non-firing
    # (Phase 0.2's reachability proof) -- and adds only the one file
    # `probe_state` reads to tell a pilot from a finished run.

    def build_piloted_target(self, suffix, ran=1, declared=5):
        box, head = self.build_target(suffix)
        # The pilot's own results file lands beside `summary.json` under the
        # same `Results/` directory `records_state` walks -- it must be
        # declared too, or it reports as a second, unaccounted-for
        # experiment (`undeclaredRecords`) and drifts the report, which
        # downgrades `piloted` to `report-first` before the branch under
        # test is ever reached.
        declaration = self.DECLARATION.replace(
            "'records': ['Results/summary.json']",
            "'records': ['Results/summary.json', 'Results/Probe_results.json']")
        self.assertIn("Probe_results.json", declaration,
                       "the declaration's records list was not extended; "
                       "the DECLARATION fixture text moved")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            declaration, encoding="utf-8")
        (box / "Method" / "Results" / impl.PROBE_RESULTS).write_text(
            json.dumps({
                "revision": "r01.md",
                "comparison": {"scale": 1},
                "reduction": {"epochs": ran},
                "targetScale": {"epochs": declared},
            }), encoding="utf-8")
        return box, head

    def test_a_piloted_probe_publishes_a_runnable_discuss_command(self):
        box, _ = self.build_piloted_target("piloted")
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "piloted")
        to_discuss = probe["toDiscuss"]
        self.assertEqual(len(to_discuss), 1)
        entry = to_discuss[0]
        self.assertIn("Method", entry["question"])
        self.assertIn("5", entry["question"],
                       "the question must name the DECLARED scale")
        self.assertIn("implementation_cli.py discuss", entry["command"])
        self.assertIn(str(box), entry["command"])

    def test_a_non_piloted_probe_publishes_its_own_question(self):
        """This test used to assert `toDiscuss == []` here, and that assertion
        WAS the defect: the offer to run is exactly the point the standing rule
        says the flow question belongs at, and it published nothing because the
        condition was the single literal `next_step == "piloted"`.

        The pole it was serving has not been dropped -- it moved to
        `ProbePublishesEveryStepsWorkTests.test_a_terminal_step_publishes_
        nothing`, where a step the roster declares terminal really does publish
        none. That is a pole about a decision; this was a pole about an
        accident.
        """
        box, head = self.build_target("not-piloted")
        self.write_job_folder(box, head)
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "benchmark")
        self.assertEqual(len(probe["toDiscuss"]), 1)
        self.assertNotIn("ran a pilot below", probe["toDiscuss"][0]["question"],
                         "the offer to run must ask its own question, never "
                         "be handed the pilot's")

    def test_the_piloted_command_is_runnable_and_appends_the_exact_question(self):
        box, _ = self.build_piloted_target("piloted-run")
        probe = self.probe(box)
        entry = probe["toDiscuss"][0]
        tokens = shlex.split(entry["command"])
        proc = subprocess.run([sys.executable, str(CLI), *tokens[1:]],
                              capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertEqual(json.loads(proc.stdout)["asked"], entry["question"])

    def test_the_piloted_question_is_stable_across_polls_at_different_achieved_counts(self):
        """Mutation proof 7 (spec Test Obligations #7): two probes against
        the same declared scale, at two different achieved repetition
        counts, both still below it, must publish byte-identical question
        text -- the pilot-vs-declared-scale decision has not changed."""
        box, _ = self.build_piloted_target("piloted-stable", ran=1, declared=5)
        first = self.probe(box)
        before_question = first["toDiscuss"][0]["question"]
        before_command = first["toDiscuss"][0]["command"]

        (box / "Method" / "Results" / impl.PROBE_RESULTS).write_text(
            json.dumps({
                "revision": "r01.md",
                "comparison": {"scale": 1},
                "reduction": {"epochs": 3},
                "targetScale": {"epochs": 5},
            }), encoding="utf-8")
        second = self.probe(box)
        self.assertEqual(second["nextStep"], "piloted")
        self.assertEqual(before_question, second["toDiscuss"][0]["question"])
        self.assertEqual(before_command, second["toDiscuss"][0]["command"])

    def test_toDiscuss_is_documented_in_reading_probe(self):
        """Same doctrine as `VerifyStatusRosterTests.test_toDiscuss_is_
        documented_in_reading_verify` -- a key that reached the JSON is
        worth nothing to a reader never told it exists."""
        usage = USAGE_MD.read_text(encoding="utf-8")
        section = usage[usage.index("## Reading `probe`"):]
        section = section[:section.index("\n## ", 1)]
        self.assertIn("`toDiscuss`", section)


def dict_literal_keys(source: Path, name: str) -> list[str]:
    """The string keys of a module-level dict assigned to `name`.

    The same argument `returned_keys` makes, one scope out: a list of commands
    written twice — once in the code that dispatches them and once in the
    reference somebody reads — is a list that loses one. Read it from the
    dispatch table instead.
    """
    tree = ast.parse(source.read_text(encoding="utf-8"))
    for node in tree.body:
        if not isinstance(node, ast.Assign) or not isinstance(node.value, ast.Dict):
            continue
        if not any(isinstance(t, ast.Name) and t.id == name for t in node.targets):
            continue
        return sorted(key.value for key in node.value.keys
                      if isinstance(key, ast.Constant)
                      and isinstance(key.value, str))
    raise AssertionError(f"{source.name} assigns no module-level dict {name}")


class WorkedInvocationRosterTests(unittest.TestCase):
    """`usage.md` opens by promising that everything below it is a real
    invocation of the CLI, and three of the CLI's nine commands had none.

    `probe` is the one that costs something. It is the command the whole
    benchmark half of this skill turns on — it is what answers `nextStep`,
    what the Decision Gates rows are written about, and what a reader is sent
    to before every offer to run — and the worked-invocation reference never
    showed anybody how to call it. `name` and `compose` are the same absence
    with less riding on it.

    The lock is a roster rather than three assertions, so a command added to
    the dispatch table fails this suite until somebody has shown how to run
    it. What it cannot check is whether the invocation shown is *correct*:
    that the flags exist is asserted below against the parser, but that the
    output described underneath is what the command actually prints is prose,
    and the end-to-end tests elsewhere in this file are what carry it.
    """

    INVOCATION_RE = re.compile(r"implementation_cli\.py\s+([a-z][a-z-]*)")

    def worked_invocations(self):
        return sorted(set(self.INVOCATION_RE.findall(
            USAGE_MD.read_text(encoding="utf-8"))))

    def dispatched_commands(self):
        return dict_literal_keys(CLI, "COMMANDS")

    def test_every_command_the_cli_dispatches_has_a_worked_invocation(self):
        dispatched = self.dispatched_commands()
        self.assertTrue(dispatched, "the dispatch table was read as empty")
        worked = self.worked_invocations()
        self.assertEqual(
            sorted(set(dispatched) - set(worked)), [],
            "the CLI dispatches these and `usage.md` works none of them, "
            "though it opens by saying everything below it is a real "
            "invocation")
        self.assertEqual(
            sorted(set(worked) - set(dispatched)), [],
            "`usage.md` works these and the CLI dispatches no such command")

    def worked_block(self, command):
        """The fenced invocation for one command, as argv."""
        usage = USAGE_MD.read_text(encoding="utf-8")
        block = usage[usage.index(f"implementation_cli.py {command}"):]
        block = block[:block.index("```")]
        argv = [command]
        for line in block.splitlines()[1:]:
            argv.extend(line.strip().rstrip("\\").strip().split())
        return argv

    def test_the_probe_invocation_uses_flags_the_real_parser_accepts(self):
        """A worked invocation nobody can run is a worse promise than none.

        Proven against the CLI's own parser rather than against a second copy
        of its argument list: the example is handed to the real process with a
        target that does not exist, so argparse sees every flag. A guard
        refusal prints JSON and means the flags were accepted; an unrecognized
        flag never gets that far.
        """
        argv = self.worked_block("probe")
        self.assertIn("--target", argv)
        self.assertIn("--name", argv)
        proc = subprocess.run(
            [sys.executable, str(CLI), *argv], capture_output=True, text=True,
            cwd=FORGE)
        self.assertNotIn("unrecognized arguments", proc.stderr)
        self.assertEqual(json.loads(proc.stdout or "{}").get("status"),
                         "refused", proc.stderr)

    def test_the_step_invocation_uses_flags_the_real_parser_accepts(self):
        argv = self.worked_block("step")
        self.assertIn("--target", argv)
        self.assertIn("--name", argv)
        self.assertIn("--step", argv)
        proc = subprocess.run(
            [sys.executable, str(CLI), *argv], capture_output=True, text=True,
            cwd=FORGE)
        self.assertNotIn("unrecognized arguments", proc.stderr)
        self.assertEqual(json.loads(proc.stdout or "{}").get("status"),
                         "refused", proc.stderr)

    def test_the_reference_shows_what_probe_answers(self):
        """An invocation with no output beside it teaches a reader to run the
        command and nothing about how to read what comes back. `nextStep` is
        the answer, so it belongs where the invocation is."""
        usage = USAGE_MD.read_text(encoding="utf-8")
        section = usage[usage.index("## Probe — what stands between this"):]
        section = section[:section.index("\n## ", 1)]
        self.assertIn("implementation_cli.py probe", section)
        self.assertIn("`nextStep`", section)


def subcommand_surface(source: Path, function: str) -> dict[str, tuple[str, ...]]:
    """Every subcommand a parser-building function declares, with its flags.

    Nested groups are followed, so a subcommand reached only through another
    one is reported by the whole path a reader would have to type. Only the
    leaves are returned: a group parser whose subcommands are `required=True`
    names no invocation — typing it alone is refused — so documenting it as a
    command would document something nobody can run.

    Read from the parser rather than from a list beside it, for the reason
    `returned_keys` is: a roster restated by hand is a roster that loses one.
    """
    tree = ast.parse(source.read_text(encoding="utf-8"))
    definition = next(
        (node for node in ast.walk(tree)
         if isinstance(node, ast.FunctionDef) and node.name == function), None)
    if definition is None:
        raise AssertionError(f"{source.name} defines no {function}")

    groups: dict[str, str] = {}
    commands: dict[str, str] = {}
    flags: dict[str, list[str]] = {}
    owners: set[str] = set()

    def only_target(node):
        if len(node.targets) != 1 or not isinstance(node.targets[0], ast.Name):
            return None
        return node.targets[0].id

    for node in ast.walk(definition):
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Call):
            call, name = node.value, only_target(node)
            attribute = call.func.attr if isinstance(call.func, ast.Attribute) else ""
            holder = (call.func.value.id
                      if isinstance(call.func, ast.Attribute)
                      and isinstance(call.func.value, ast.Name) else "")
            if attribute == "add_subparsers":
                if name is not None:
                    groups[name] = commands.get(holder, "")
                owners.add(commands.get(holder, ""))
                continue
            if attribute == "add_parser" and holder in groups and call.args:
                literal = call.args[0]
                if not isinstance(literal, ast.Constant):
                    continue
                path = f"{groups[holder]} {literal.value}".strip()
                flags.setdefault(path, [])
                if name is not None:
                    commands[name] = path
                continue
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) \
                and node.func.attr == "add_argument" \
                and isinstance(node.func.value, ast.Name) \
                and node.func.value.id in commands and node.args \
                and isinstance(node.args[0], ast.Constant) \
                and str(node.args[0].value).startswith("--"):
            flags[commands[node.func.value.id]].append(node.args[0].value)

    return {path: tuple(sorted(set(declared)))
            for path, declared in flags.items() if path not in owners}


def required_flags(source: Path, function: str) -> dict[str, tuple[str, ...]]:
    """The subset of `subcommand_surface` each subcommand marks `required=True`.

    A standalone reading, deliberately not folded into `subcommand_surface`
    itself: that function is one of `CopiedHelperFidelityTests`' pinned
    copies (`test_skill_audit.py` holds a byte-identical one), so changing
    its body here would drift the copy out from under a suite this change
    does not own. This performs the identical `_build_parser()` walk,
    narrowed to the flags that define a row's shape -- the reason
    `readiness` (`--job-dir`/`--worker`) is not `--target`/`--entrypoint`
    shaped the way every neighbouring row in the guiding table is.
    """
    tree = ast.parse(source.read_text(encoding="utf-8"))
    definition = next(
        (node for node in ast.walk(tree)
         if isinstance(node, ast.FunctionDef) and node.name == function), None)
    if definition is None:
        raise AssertionError(f"{source.name} defines no {function}")

    groups: dict[str, str] = {}
    commands: dict[str, str] = {}
    flags: dict[str, list[str]] = {}
    owners: set[str] = set()

    def only_target(node):
        if len(node.targets) != 1 or not isinstance(node.targets[0], ast.Name):
            return None
        return node.targets[0].id

    def is_required(call: ast.Call) -> bool:
        for keyword in call.keywords:
            if keyword.arg == "required":
                return isinstance(keyword.value, ast.Constant) \
                    and keyword.value.value is True
        return False

    for node in ast.walk(definition):
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Call):
            call, name = node.value, only_target(node)
            attribute = call.func.attr if isinstance(call.func, ast.Attribute) else ""
            holder = (call.func.value.id
                      if isinstance(call.func, ast.Attribute)
                      and isinstance(call.func.value, ast.Name) else "")
            if attribute == "add_subparsers":
                if name is not None:
                    groups[name] = commands.get(holder, "")
                owners.add(commands.get(holder, ""))
                continue
            if attribute == "add_parser" and holder in groups and call.args:
                literal = call.args[0]
                if not isinstance(literal, ast.Constant):
                    continue
                path = f"{groups[holder]} {literal.value}".strip()
                flags.setdefault(path, [])
                if name is not None:
                    commands[name] = path
                continue
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) \
                and node.func.attr == "add_argument" \
                and isinstance(node.func.value, ast.Name) \
                and node.func.value.id in commands and node.args \
                and isinstance(node.args[0], ast.Constant) \
                and str(node.args[0].value).startswith("--") \
                and is_required(node):
            flags[commands[node.func.value.id]].append(node.args[0].value)

    return {path: tuple(sorted(set(declared)))
            for path, declared in flags.items() if path not in owners}


class RemoteExecutionCommandRosterTests(unittest.TestCase):
    """This flow depends on a CLI it never names.

    `probe` reports a remote-execution state, the `poll-first` rung tells a
    reader to wait for a submission's answer, the drift and unreliable states
    told them to reconcile the ledger by hand, and the argument for a `tools/`
    directory rests on a job folder somebody has to have produced. Not one of
    the eight subcommands that do any of that appeared anywhere a reader of
    this skill looks — not in `SKILL.md`, not in `references/usage.md`. The
    remedy for a drifted ledger existed only inside a Python docstring.

    Two rules, because the repair has two halves that fail differently:

    - the roster derives the subcommands from the parser and holds them to a
      table, so a subcommand added there forces a doctrine decision;
    - the flag lists are deliberately *not* duplicated. `usage.md` shows the
      shape of three invocations and points at the `remote-execution` skill
      for the rest, and a test asserts that what it shows stays a proper
      subset of what the parser declares. Two copies of a flag list is the
      drift this whole change is about.

    What the table cannot check is whether the state named in column two is
    the state that really routes there. That is prose, and `probe`'s own
    end-to-end tests are what carry it.
    """

    TABLE_HEADER = SEAM_TABLE_HEADER
    GATES_TABLE_HEADER = "| Situation | Action |"

    @classmethod
    def remote_cli(cls):
        return impl.REMOTE_EXECUTION_CLI_SCRIPT

    def declared_subcommands(self):
        surface = subcommand_surface(self.remote_cli(), "_build_parser")
        self.assertTrue(surface, "the remote-execution parser was read as empty")
        return surface

    def table_rows(self):
        tables = markdown_table_rows(
            SKILL_MD.read_text(encoding="utf-8"), self.TABLE_HEADER)
        self.assertEqual(
            len(tables), 1,
            "the remote-execution subcommands are stated in no parseable "
            "table, so nothing holds this flow to the CLI it depends on")
        return tables[0]

    def test_every_subcommand_the_parser_declares_has_a_row(self):
        declared = sorted(self.declared_subcommands())
        documented = sorted(row[0].strip("`") for row in self.table_rows())
        self.assertEqual(
            sorted(set(declared) - set(documented)), [],
            "the remote-execution CLI declares these and this skill names "
            "them nowhere")
        self.assertEqual(
            sorted(set(documented) - set(declared)), [],
            "the table names these and the parser declares no such subcommand")

    def test_the_rung_that_says_to_wait_names_the_subcommand_that_waits(self):
        """`poll-first` tells a reader a submission is out and the answer has
        not come back. It never said what to run. The row exists so the rung
        resolves to something typeable."""
        rows = {row[0].strip("`"): row[1] for row in self.table_rows()}
        self.assertIn("poll", rows)
        self.assertIn("poll-first", rows["poll"])

    def test_the_named_remedy_reaches_the_reader_at_both_ends(self):
        """A remedy reachable only from a Python docstring is not a remedy.

        `drift` and `unreliable` are the two states this flow reports and
        explicitly refuses to treat as "wait for it", and the fix for both was
        described as manual work. It is a subcommand, and it is named where
        the state is reported and again in the table a reader consults about
        what to do."""
        text = SKILL_MD.read_text(encoding="utf-8")
        section = text[text.index('### `nextStep: "poll-first"`'):]
        section = section[:section.index("\n### ", 1)]
        self.assertIn("`remote_cli reconcile`", section,
                      "the drift paragraph still describes the fix as manual "
                      "work and names no command")
        gates = markdown_table_rows(text, self.GATES_TABLE_HEADER)
        self.assertEqual(len(gates), 1, "the Decision Gates table moved")
        actions = "\n".join(row[1] for row in gates[0])
        self.assertIn("remote_cli reconcile", actions,
                      "no Decision Gates row names the command that repairs a "
                      "drifted ledger")

    def test_the_tools_argument_names_what_writes_the_directory(self):
        """The layout section argues at length that `tools/` has to exist and
        never said what puts anything in it. One command does, and it writes
        one exact shape."""
        text = SKILL_MD.read_text(encoding="utf-8")
        section = text[text.index("**And `tools/` exists for the same reason"):]
        section = section[:section.index("\n## ", 1)]
        self.assertIn("`remote_cli generate-job`", section)
        self.assertIn("tools/<service>/<job-name>/", section)

    def test_the_usage_reference_works_three_invocations_and_copies_no_flag_list(self):
        """The other half of the repair, and the one that could rot.

        A reference that reprints the flag list is a second copy of it, and
        two copies of a flag list is exactly the drift this change exists to
        remove. So what `usage.md` shows has to stay a proper subset of what
        the parser declares, measured rather than promised.
        """
        usage = USAGE_MD.read_text(encoding="utf-8")
        section = usage[usage.index("## The remote-execution seam"):]
        section = section[:section.index("\n## ", 1)]
        self.assertIn("remote-execution", section,
                      "the section points nowhere for the flags it withholds")
        declared = self.declared_subcommands()
        for command in ("poll", "reconcile", "generate-job"):
            self.assertIn(f"remote_cli.py {command}", section)
            shown = {flag for flag in re.findall(r"--[a-z][a-z-]*", section)
                     if flag in declared[command]}
            self.assertTrue(
                shown, f"the {command} invocation shows no flag at all")
            self.assertLess(
                len(shown), len(declared[command]),
                f"`usage.md` reprints every flag {command} declares, which is "
                "a second copy of a list this skill does not own")


class GuidingTableFlagsTests(unittest.TestCase):
    """The table named subcommands and never how to call them.

    Followed literally, `readiness` reads like every neighbouring row —
    `--target`/`--entrypoint` — because nothing in the table said otherwise.
    It takes `--job-dir`/`--worker` instead, and the mismatch surfaces only
    as a usage error, which reads like the reader's fault rather than the
    table's.

    And no row at all answered a job folder that *exists* and is pinned to a
    commit that has moved: `generate-job`'s row covers an absent folder,
    `reconcile`'s covers the ledger and the service disagreeing, and a
    stale pin fell between both.

    Both repairs read `_build_parser()` rather than restate it, the same way
    `RemoteExecutionCommandRosterTests` already derives column one: a flags
    column that is hand-typed is the exact drift this table exists to
    remove, so it is checked against `required_flags()` — the same walk,
    narrowed to what `required=True` marks — instead of being taken on
    faith.
    """

    TABLE_HEADER = SEAM_TABLE_HEADER

    @classmethod
    def remote_cli(cls):
        return impl.REMOTE_EXECUTION_CLI_SCRIPT

    def declared_required(self):
        surface = required_flags(self.remote_cli(), "_build_parser")
        self.assertTrue(surface, "the remote-execution parser was read as empty")
        return surface

    def table_rows(self):
        tables = markdown_table_rows(
            SKILL_MD.read_text(encoding="utf-8"), self.TABLE_HEADER)
        self.assertEqual(
            len(tables), 1,
            "the remote-execution seam table is stated in no parseable "
            "table with a flags column")
        return tables[0]

    @staticmethod
    def flags_cell(cell):
        return {flag.strip().strip("`") for flag in cell.split(",") if flag.strip()}

    def test_every_row_names_its_required_flags(self):
        """Column three has to match `_build_parser()`, not a guess made from
        the shape of the row above it."""
        required = self.declared_required()
        for row in self.table_rows():
            command = row[0].strip("`")
            self.assertIn(command, required,
                          f"{command!r} names no subcommand `_build_parser()` declares")
            self.assertEqual(
                self.flags_cell(row[2]), set(required[command]),
                f"the flags column for {command!r} does not match the "
                "required arguments `_build_parser()` declares for it")

    def test_readiness_is_not_target_entrypoint_shaped(self):
        """The exact mismatch that cost three flag-shape errors in a row."""
        rows = {row[0].strip("`"): row[2] for row in self.table_rows()}
        self.assertIn("readiness", rows)
        shown = self.flags_cell(rows["readiness"])
        self.assertEqual(shown, {"--job-dir", "--worker"})
        self.assertNotIn("--target", shown)
        self.assertNotIn("--entrypoint", shown)

    def test_a_stale_pinned_job_folder_has_its_own_row(self):
        """A job folder that exists, pinned to a commit that has moved, maps
        to no row today — the exact state that blocked a launch this week.
        `generate-job`'s existing row only covers an absent folder."""
        stale_rows = [row for row in self.table_rows()
                      if row[0].strip("`") == "generate-job"
                      and "drift" in row[1]]
        self.assertEqual(
            len(stale_rows), 1,
            "no row answers a job folder that exists with a pin that has "
            "drifted from what the clone paths hold")
        required = self.declared_required()
        self.assertEqual(
            self.flags_cell(stale_rows[0][2]), set(required["generate-job"]),
            "the stale-pin row's flags column does not match "
            "`_build_parser()`'s required generate-job arguments")


class ShardRefusalCrossJoinTests(unittest.TestCase):
    """The doctrine promised a refusal nothing could produce.

    `SKILL.md` says a merge refuses when shards disagree on what they declared
    had to agree — "Not averages — refuses" — and `distribution_state` has
    read a `merged` argument for that purpose since it was written. Nothing in
    this skill ever built one. `shardsDisagree` was empty on every target
    because the only input that could fill it had no caller, and a reader
    seeing an empty list read a refusal that had never been attempted.

    `verify --shards <dir>` is that caller. The disagreement is computed by
    `shard_io.disagreements`, which reads a stamp field at a time and names no
    grouping vocabulary, so the refusal stays as general as the doctrine
    claiming it.

    And the same key that reports the arrived shards was missing from three
    of `distribution_state`'s branches, so it vanished for exactly the targets
    that declare no distribution. That was found by the roster helper rather
    than by reading: its all-returns-agree assertion is what makes a key that
    exists on some branches and not others a failure instead of a surprise.
    """

    def test_every_distribution_branch_reports_the_same_keys(self):
        """Red by construction: the `none`, `absent` and `undeclared` branches
        return `shardsDisagree` and omit `shardsArrived`, so which keys a
        caller gets depends on which branch answered."""
        self.assertIn("shardsArrived", returned_keys(CLI, "distribution_state"))

    DECLARATION = (
        "__benchmark__ = {\n"
        "    'revision': 'r01.md',\n"
        "    'arms': {'floor': {'sections': ['3']}, "
        "'full': {'sections': ['3']}},\n"
        "    'distribution': {'axis': 'repetition',\n"
        "                     'poolable': ['score'],\n"
        "                     'perEnvironment': ['wallSeconds'],\n"
        "                     'perRun': ['seed'],\n"
        "                     'identicalAcrossShards': ['epochs', 'datasetSize']},\n"
        "}\n")

    def build_target(self, suffix):
        box = FORGE / "implementations" / f"_shardbox_{suffix}_{os.getpid()}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        for directory in ("src/Method", "src/Method_Benchmark", "Method"):
            (box / directory).mkdir(parents=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        (box / "src/Method_Benchmark/__init__.py").write_text(
            self.DECLARATION, encoding="utf-8")
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        return box

    def build_shards(self, stamps):
        """A real shard directory on disk, in the ambient shape `read_shards`
        assumes: one directory per shard, each holding a `shard.json` stamp.

        Written rather than faked, because the whole objection this repairs is
        that a number nobody read off a disk is a number nobody measured.
        """
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        for shard, stamp in stamps.items():
            folder = root / shard
            folder.mkdir()
            (folder / "shard.json").write_text(json.dumps(stamp),
                                               encoding="utf-8")
        return root

    def verify(self, box, shards=None, expect=0):
        argv = [sys.executable, str(CLI), "verify", "--target", str(box),
                "--name", "Method"]
        if shards is not None:
            argv += ["--shards", str(shards)]
        proc = subprocess.run(argv, capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, expect, proc.stderr)
        return proc

    def test_verify_accepts_a_shard_directory(self):
        """Red by construction: the flag the doctrine's refusal needs in order
        to have any input at all does not exist, so `argparse` rejects it
        before the command runs."""
        box = self.build_target("flag")
        shards = self.build_shards({"a": {"epochs": 5}})
        proc = self.verify(box, shards)
        self.assertNotIn("unrecognized arguments", proc.stderr)

    AGREE = {"a": {"epochs": 5, "datasetSize": 100, "score": 0.1},
             "b": {"epochs": 5, "datasetSize": 100, "score": 0.2},
             "c": {"epochs": 5, "datasetSize": 100, "score": 0.3}}
    DISAGREE = {"a": {"epochs": 5, "datasetSize": 100},
                "b": {"epochs": 9, "datasetSize": 100}}

    def distribution(self, box, shards=None):
        return json.loads(self.verify(box, shards).stdout)["distribution"]

    def test_shards_that_disagree_are_refused_and_named(self):
        """The refusal the doctrine promised, produced for the first time.

        Read off the command's own stdout rather than off a call to
        `distribution_state`, because the claim is about what `verify` reports
        and every layer between the flag and the report is part of it.
        """
        box = self.build_target("disagree")
        distribution = self.distribution(box, self.build_shards(self.DISAGREE))

        self.assertEqual(distribution["shardsDisagree"], ["epochs"])
        self.assertEqual(distribution["shardsArrived"], ["a", "b"])
        self.assertEqual(distribution["status"], "incomplete")

    def test_shards_that_agree_report_no_disagreement_and_still_name_what_arrived(self):
        """The pole. Without it the refusal could be firing on any shard
        directory at all and nothing here would notice."""
        box = self.build_target("agree")
        distribution = self.distribution(box, self.build_shards(self.AGREE))

        self.assertEqual(distribution["shardsDisagree"], [])
        self.assertEqual(distribution["shardsArrived"], ["a", "b", "c"])
        # And the shards changed no verdict: agreeing shards are exactly as
        # silent as no shards at all. Compared against the same target rather
        # than against a literal, because this fixture declares dimensions no
        # `config.py` names and would report `incomplete` for that reason
        # alone — which has nothing to do with what came back.
        self.assertEqual(distribution["status"],
                         self.distribution(box)["status"])

    def test_the_arrived_count_is_read_from_disk_and_not_from_a_fixture(self):
        """Behavioural variation rather than inversion.

        A number a test hands to itself proves nothing about a campaign. So one
        shard directory is deleted between two runs of the same command over
        the same target, and what the command reports has to move with it.
        """
        box = self.build_target("shrink")
        shards = self.build_shards(self.AGREE)
        self.assertEqual(self.distribution(box, shards)["shardsArrived"],
                         ["a", "b", "c"])

        shutil.rmtree(shards / "b")
        self.assertEqual(self.distribution(box, shards)["shardsArrived"],
                         ["a", "c"])

    def test_omitting_the_flag_changes_nothing_else_verify_reports(self):
        """A new optional argument is a promise that everything else is where
        it was. Measured by running the same command twice over the same
        target and diffing everything but the three keys the flag exists to
        move."""
        box = self.build_target("omitted")
        without = json.loads(self.verify(box).stdout)
        with_shards = json.loads(self.verify(box, self.build_shards(
            self.DISAGREE)).stdout)

        self.assertEqual(without["distribution"]["shardsDisagree"], [])
        self.assertEqual(without["distribution"]["shardsArrived"], [])
        moved = {"shardsDisagree", "shardsArrived", "status"}
        self.assertEqual(
            {key: value for key, value in without["distribution"].items()
             if key not in moved},
            {key: value for key, value in with_shards["distribution"].items()
             if key not in moved})
        self.assertEqual({k: v for k, v in without.items() if k != "distribution"},
                         {k: v for k, v in with_shards.items()
                          if k != "distribution"})

    def test_a_shard_directory_that_does_not_exist_is_a_smaller_campaign(self):
        """Three shards planned and none returned is a legitimate answer, not
        an error: the doctrine already says the scale is recomputed from what
        came back. So an absent directory reports nothing arrived rather than
        refusing."""
        box = self.build_target("absent")
        missing = Path(tempfile.mkdtemp()) / "never-written"
        self.addCleanup(shutil.rmtree, missing.parent, ignore_errors=True)
        distribution = self.distribution(box, missing)

        self.assertEqual(distribution["shardsArrived"], [])
        self.assertEqual(distribution["shardsDisagree"], [])

    def test_a_shard_that_cannot_be_read_is_not_treated_as_a_shard_that_never_came(self):
        """The other half of the same boundary, and the one that has to be
        loud. A `shard.json` that is not JSON is not a smaller campaign; it is
        an unreadable one, and reporting it as absent is exactly the silence
        this skill exists to break."""
        box = self.build_target("malformed")
        shards = self.build_shards({"a": {"epochs": 5}})
        (shards / "a" / "shard.json").write_text("{not json", encoding="utf-8")
        proc = self.verify(box, shards, expect=1)

        self.assertIn("JSONDecodeError", proc.stderr)
        self.assertIn("read_shards", proc.stderr)

    def test_a_target_declaring_no_distribution_still_reports_both_keys(self):
        """The symmetry half, end to end. `shardsArrived` used to vanish for
        exactly the targets that declare no distribution, so a reader could
        not tell an absent key from an absent answer."""
        box = self.build_target("undeclared")
        (box / "src/Method_Benchmark/__init__.py").write_text(
            "__benchmark__ = {'revision': 'r01.md'}\n", encoding="utf-8")
        distribution = self.distribution(box)

        self.assertEqual(distribution["status"], "none")
        self.assertEqual(distribution["shardsDisagree"], [])
        self.assertEqual(distribution["shardsArrived"], [])

    def test_the_toy_targets_left_nothing_behind(self):
        self.build_target("cleanup")
        self.doCleanups()
        leftover = list((FORGE / "implementations").glob("_shardbox_*"))
        self.assertEqual(leftover, [], leftover)

    def test_the_doctrine_names_the_flag_and_says_which_half_refuses(self):
        """A promise with no producer is what this repairs, so the doctrine has
        to name the producer — and has to say plainly that refusing is where
        this skill stops, because the alternative reading is that a forge which
        refuses will eventually average."""
        text = SKILL_MD.read_text(encoding="utf-8")
        section = text[text.index("**Shards agree on what they said had to agree"):]
        section = section[:section.index("\n- **", 1)]
        self.assertIn("`verify --shards <dir>`", section)
        self.assertIn("shardsArrived", section)
        self.assertIn("never averages, pools or merges", section)

    def test_the_usage_reference_works_the_shard_invocation(self):
        usage = USAGE_MD.read_text(encoding="utf-8")
        section = usage[usage.index("### `--shards` — the refusal"):]
        section = section[:section.index("\n### ", 1)]
        self.assertIn("--shards", section)
        self.assertIn("`shardsDisagree`", section)
        self.assertIn("`shardsArrived`", section)


class ManifestProvisioningTests(unittest.TestCase):
    """`env`'s `nextCommand` must install the target's own declared manifests,
    beside the forge's `requirements-dev.txt` — never instead of them, and
    never before them, per Decision 8.
    """

    def box(self, suffix, files=()):
        path = FORGE / "implementations" / f"_manifest_{suffix}_{os.getpid()}"
        path.mkdir(parents=True)
        self.addCleanup(shutil.rmtree, path, ignore_errors=True)
        for name, text in files:
            (path / name).write_text(text, encoding="utf-8")
        return path

    def test_no_manifest_reports_an_empty_list_and_a_stated_absence(self):
        target = self.box("bare")
        found = impl.manifest_provisioning(target)
        self.assertEqual(found["rows"], [])
        self.assertTrue(found["absentNote"],
                         "an empty list alone cannot be told apart from a check "
                         "that never ran; the absence has to be stated")

    def test_requirements_and_dev_requirements_are_honoured_in_order(self):
        target = self.box("reqs", [("requirements.txt", "numpy\n"),
                                    ("requirements-dev.txt", "pytest\n")])
        found = impl.manifest_provisioning(target)
        names = [row["name"] for row in found["rows"]]
        self.assertEqual(names, ["requirements.txt", "requirements-dev.txt"])
        self.assertTrue(all(row["status"] == "honoured" for row in found["rows"]))
        self.assertEqual(found["args"],
                          ["-r", str(target / "requirements.txt"),
                           "-r", str(target / "requirements-dev.txt")])

    def test_a_buildable_project_is_installed_editable_last(self):
        target = self.box("editable", [("requirements.txt", "numpy\n"),
                                        ("pyproject.toml", "[project]\nname='x'\n")])
        found = impl.manifest_provisioning(target)
        names = [row["name"] for row in found["rows"]]
        self.assertEqual(names, ["requirements.txt", "pyproject.toml"])
        self.assertEqual(found["args"][-2:], ["-e", str(target)])

    def test_setup_py_alone_is_also_installed_editable(self):
        target = self.box("setuppy", [("setup.py", "from setuptools import setup\n")])
        found = impl.manifest_provisioning(target)
        self.assertEqual([row["name"] for row in found["rows"]], ["setup.py"])
        self.assertEqual(found["args"], ["-e", str(target)])

    def test_environment_yml_is_named_unhonoured_with_a_reason_never_ignored(self):
        target = self.box("conda", [("environment.yml", "name: x\n")])
        found = impl.manifest_provisioning(target)
        self.assertEqual(len(found["rows"]), 1)
        row = found["rows"][0]
        self.assertEqual(row["name"], "environment.yml")
        self.assertEqual(row["status"], "unhonoured")
        self.assertTrue(row["reason"])
        # An unhonoured manifest names nothing pip is asked to install.
        self.assertEqual(found["args"], [])

    def test_cmd_env_lists_the_forge_dev_reqs_first_then_target_manifests_last(self):
        target = self.box("order", [("requirements.txt", "numpy\n"),
                                     ("environment.yml", "name: x\n")])
        subprocess.run(["git", "init", "-q", str(target)], check=True, capture_output=True)
        result = impl.cmd_env(argparse.Namespace(target=str(target), python=sys.executable))
        forge_reqs = str(impl.SKILL_ROOT / "assets" / "requirements-dev.txt")
        self.assertLess(
            result["nextCommand"].index(forge_reqs),
            result["nextCommand"].index(str(target / "requirements.txt")),
            "the forge's own dev requirements must be listed before any target "
            "manifest, per Decision 8")
        self.assertEqual([row["name"] for row in result["manifests"]["rows"]],
                          ["requirements.txt", "environment.yml"])
        self.assertEqual(result["manifests"]["rows"][1]["status"], "unhonoured")

    def test_cmd_env_construction_names_no_target_package(self):
        """The forge-vocabulary guard: `cmd_env`'s own construction and its
        `manifest_provisioning` helper must name only manifest filenames the
        forge already enumerates in `ROOT_KEEP`, never a target's package,
        device or repository name.
        """
        source = inspect.getsource(impl.cmd_env) + inspect.getsource(impl.manifest_provisioning)
        for word in FORGE_VOCABULARY_FLOOR:
            self.assertNotIn(word, source.lower())


class PythonFloorTests(unittest.TestCase):
    """`env` used to promise a floor (`--help`: "The layout templates
    assume 3.10+") and check nothing: a 3.9.6 interpreter built a venv and
    reported `status: "created"` with no warning. Two check sites, one
    shared predicate (`_python_floor`) -- a fresh-build route
    (`--python` below the floor) and a reuse route (an existing venv whose
    own interpreter is below the floor); neither can see the other's
    failure mode.
    """

    def box(self, suffix, files=()):
        path = FORGE / "implementations" / f"_pyfloor_{suffix}_{os.getpid()}"
        path.mkdir(parents=True)
        self.addCleanup(shutil.rmtree, path, ignore_errors=True)
        for name, text in files:
            (path / name).write_text(text, encoding="utf-8")
        subprocess.run(["git", "init", "-q", str(path)], check=True, capture_output=True)
        return path

    def fake_interpreter(self, target: Path, version_text: str) -> Path:
        """A stand-in `python` that answers only `--version`, never a real
        interpreter -- this test never needs one to reach far enough to
        exercise a REFUSAL, which must happen before any real `venv`
        invocation.
        """
        script = target / "fake_python"
        script.write_text(
            "#!/bin/sh\n"
            'if [ "$1" = "--version" ]; then\n'
            f'    echo "{version_text}"\n'
            "    exit 0\n"
            "fi\n"
            "exit 1\n",
            encoding="utf-8",
        )
        script.chmod(0o755)
        return script

    def test_cmd_env_refuses_under_floor_interpreter_skill_default(self):
        target = self.box("skillfloor")
        fake = self.fake_interpreter(target, "Python 3.9.6")
        with self.assertRaises(impl.Refused) as caught:
            impl.cmd_env(argparse.Namespace(target=str(target), python=str(fake)))
        self.assertEqual(caught.exception.code, "PYTHON_BELOW_FLOOR")
        self.assertIn("3.10", caught.exception.detail)
        self.assertIn("skill default", caught.exception.detail)
        self.assertFalse((target / ".venv").exists(),
                          "a refused build must leave no venv behind")

    def test_cmd_env_refuses_under_floor_interpreter_target_declaration_higher(self):
        target = self.box(
            "targetfloor",
            [("setup.cfg", "[options]\npython_requires = >=3.11\n")],
        )
        fake = self.fake_interpreter(target, "Python 3.10.4")
        with self.assertRaises(impl.Refused) as caught:
            impl.cmd_env(argparse.Namespace(target=str(target), python=str(fake)))
        self.assertEqual(caught.exception.code, "PYTHON_BELOW_FLOOR")
        self.assertIn("3.11", caught.exception.detail)
        self.assertIn("target declaration", caught.exception.detail)

    def test_cmd_env_reuse_site_refuses_existing_under_floor_venv(self):
        target = self.box("reuse")
        venv_dir = target / ".venv"
        bin_dir = venv_dir / ("Scripts" if os.name == "nt" else "bin")
        bin_dir.mkdir(parents=True)
        (venv_dir / "pyvenv.cfg").write_text("", encoding="utf-8")
        fake = self.fake_interpreter(target, "Python 3.9.6")
        interpreter_path = bin_dir / ("python.exe" if os.name == "nt" else "python")
        shutil.copy(fake, interpreter_path)
        interpreter_path.chmod(0o755)
        with self.assertRaises(impl.Refused) as caught:
            impl.cmd_env(argparse.Namespace(target=str(target), python=None))
        self.assertEqual(caught.exception.code, "PYTHON_BELOW_FLOOR")
        self.assertIn("3.10", caught.exception.detail)

    def test_at_or_above_floor_created_reporting_unchanged(self):
        target = self.box("atfloor")
        env_result = impl.cmd_env(
            argparse.Namespace(target=str(target), python=sys.executable))
        self.assertEqual(env_result["status"], "created")
        self.assertNotIn("PYTHON_BELOW_FLOOR", json.dumps(env_result))

    def test_fresh_venv_is_seeded_with_a_build_backend(self):
        """Python 3.12 dropped `setuptools` from `ensurepip`; a fresh venv's
        own `pip` alone cannot satisfy `nextCommand`'s editable install
        (`pip install -e <target>`), which needs a PEP 517 backend.
        """
        target = self.box("seeded")
        env_result = impl.cmd_env(
            argparse.Namespace(target=str(target), python=sys.executable))
        pip = Path(env_result["pip"])
        listing = subprocess.run(
            [str(pip), "list"], capture_output=True, text=True, check=True,
        ).stdout.lower()
        self.assertIn("setuptools", listing)

    def test_python_floor_prefers_the_higher_of_skill_and_target(self):
        lower = self.box("lower", [("setup.cfg", "[options]\npython_requires = >=3.8\n")])
        floor, source = impl._python_floor(lower)
        self.assertEqual(floor, impl.SKILL_PYTHON_FLOOR)
        self.assertEqual(source, "skill default")

        higher = self.box("higher", [("setup.cfg", "[options]\npython_requires = >=3.12\n")])
        floor, source = impl._python_floor(higher)
        self.assertEqual(floor, (3, 12))
        self.assertEqual(source, "target declaration")


class EntryModuleLivenessTests(unittest.TestCase):
    """`live` must come from an EXECUTED import of the target's own entry
    module, never from `config` alone — a pure-Python module imports fine on
    an empty venv and answered `ok` on a repository that could not run.
    """

    def box(self, suffix):
        path = FORGE / "implementations" / f"_liveness_{suffix}_{os.getpid()}"
        (path / "src" / "Method_Benchmark").mkdir(parents=True)
        self.addCleanup(shutil.rmtree, path, ignore_errors=True)
        (path / "src" / "Method_Benchmark" / "__init__.py").write_text(
            "__benchmark__ = {'revision': 'r01.md'}\n", encoding="utf-8")
        # Pure Python: imports fine with nothing installed. This is the exact
        # module whose successful import used to answer `live: ok` alone.
        (path / "src" / "Method_Benchmark" / "config.py").write_text(
            "SCALES = [1, 2, 3]\n", encoding="utf-8")
        write_fixture_interpreter(
            path / ".venv" / ("Scripts" if os.name == "nt" else "bin"))
        return path

    def test_a_pure_python_config_import_alone_is_not_enough_evidence(self):
        """The exact defect measured: `introspect` must not report `ok` from
        `config` importing cleanly while the declared entry module cannot be
        imported at all."""
        target = self.box("bare_entry")
        # No `benchmark.py` on disk at all: the declared entry module cannot
        # be found, let alone executed.
        result = impl.introspect(target, "Method", None,
                                  entry_module="Method_Benchmark.benchmark")
        self.assertEqual(result["status"], "unavailable")
        self.assertIn("benchmark", result["detail"])

    def test_an_entry_module_importing_an_absent_dependency_is_unavailable(self):
        target = self.box("missing_dep")
        (target / "src" / "Method_Benchmark" / "benchmark.py").write_text(
            "import _pp_entry_liveness_absent_dependency\n", encoding="utf-8")
        result = impl.introspect(target, "Method", None,
                                  entry_module="Method_Benchmark.benchmark")
        self.assertEqual(result["status"], "unavailable")
        self.assertIn("_pp_entry_liveness_absent_dependency", result["detail"])

    def test_a_present_and_importable_entry_module_reports_ok(self):
        target = self.box("present")
        (target / "src" / "Method_Benchmark" / "benchmark.py").write_text(
            "VALUE = 1\n", encoding="utf-8")
        result = impl.introspect(target, "Method", None,
                                  entry_module="Method_Benchmark.benchmark")
        self.assertEqual(result["status"], "ok")
#: Every module the kit itself ships into a target's benchmark package, plus the
#: optional `config` module the engine reads beside them. A liveness failure that
#: names one of these is the forge failing to import its own scaffold — never the
#: target's environment, and never something `env` could install.
KIT_BENCHMARK_MODULES = frozenset(
    {path.stem for path in sorted((KIT / "nb").glob("*.py"))} | {"config"})


def _unresolvable_kit_modules(text):
    """Which of the kit's own modules a `ModuleNotFoundError` blames, if any.

    Reads the message rather than the exception because the import happens in
    another interpreter and arrives here as one line of its stderr.
    """
    return sorted({name for name in re.findall(r"No module named '([^']+)'", text or "")
                   if name.rpartition(".")[2] in KIT_BENCHMARK_MODULES})


class KitBuiltTargetIntrospectionTests(MaterializeCommandFixture, unittest.TestCase):
    """A repository built exactly as the kit prescribes, introspected by the same
    engine that scaffolded it.

    Measured on 2026-09-03 against a target taken through all three
    `materialize` stages, with `entry` answered by the kit's own worked example
    (`<Package>_Benchmark.benchmark`) and nothing hand-written beyond what
    SKILL.md asks for:

        report.live        unavailable
        report.liveDetail  ModuleNotFoundError: No module named 'verdict'
        nextStep           env-first

    and, once that first import resolved:

        report.liveDetail  ModuleNotFoundError:
                           No module named '<Package>_Benchmark.config'

    Two separate defects, reached one after the other, ending at the same rung.
    `env-first` publishes `env --target <t>`, which installs the dev manifest;
    it can neither add an import to a file the kit ships nor create a module the
    kit does not. A repository built from zero looped there.

    The proof is the whole chain and not an assertion about a destination list
    on purpose. `config.py` being absent from `all_kit_destinations` is one
    reading of one of the two defects, and it says nothing whatsoever about the
    flat `from verdict import ...` inside the kit's own `benchmark.py` — which
    is the one reached first.
    """

    NAME = "Kit-Built"
    PACKAGE = "Kit_Built"

    def _object_stub(self, path):
        """The base fixture's stubs, with the implementation module computing on
        tensors. `cmd_probe` stops at `convert` for a target whose backend is not
        trainable, one rung above the ladder this class is about.
        """
        stub = super()._object_stub(path)
        if path.endswith("module.py"):
            stub = stub.replace("from __future__ import annotations\n",
                                "from __future__ import annotations\n\nimport torch\n", 1)
            assert "import torch" in stub
        return stub

    def _declare_object_map(self, box, name=None):
        """Step 8's declaration, answered the way SKILL.md's worked example
        answers it: the base fixture's `revision`/`premises`, plus `entry` — the
        block this class exists for — and `report`, without which `report_state`
        never reaches `introspect` at all.
        """
        super()._declare_object_map(box, name)
        name = name or self.NAME
        package = impl.package_name(name)
        path = box / "src" / f"{package}_Benchmark" / "__init__.py"
        text = path.read_text(encoding="utf-8")
        before = text
        text = text.replace(
            '"entry": {"module": "", "function": ""},',
            f'"entry": {{"module": "{package}_Benchmark.benchmark", '
            '"function": "run"},', 1)
        text = text.replace(
            '"report": {},',
            '"report": {"renderers": ["tables.render"], '
            '"conclusions": ["tables.conclusion"], '
            '"dimensions": {"accuracy": "higher"}},', 1)
        # A substitution that silently matched nothing would leave the
        # declaration blank and every assertion below would pass over a target
        # that never declared an entry at all.
        assert text != before and f'{package}_Benchmark.benchmark' in text
        assert '"renderers"' in text
        path.write_text(text, encoding="utf-8")

    def _kit_built_target(self, tag=""):
        """All three stages, a baseline to compare against, a tensor backend,
        and an interpreter equivalent to this one."""
        box = self._fully_materialized_all_stages(tag)
        # `cmd_probe` answers `nothing-to-compare` with no prior work under
        # `src/` and never reaches the ladder at all.
        prior = box / "src" / "Prior"
        prior.mkdir(parents=True, exist_ok=True)
        (prior / "kernel.py").write_text("import torch\n", encoding="utf-8")
        # The kit's own `conftest.py` and `sweep.py` compute with numpy, so a
        # freshly scaffolded target reads `mixed` and stops at `convert`.
        # Measured; converting them is what step 10 asks for anyway. They are
        # scaffold destinations, so the edit is declared rather than left as
        # drift.
        for rel in ("tests/conftest.py", "tests/sweep.py"):
            path = box / rel
            path.write_text("import torch  # noqa: F401\n"
                            + path.read_text(encoding="utf-8"), encoding="utf-8")
            payload, code, proc = self._run_cli(
                "materialize", "--target", str(box), "--name", self.NAME,
                "--authored", rel)
            self.assertEqual(code, 0, proc.stderr)
        self._git(box, "add", "-A")
        self._git(box, "commit", "-q", "-m", "converted")
        self.assertTrue(impl.backend_state(box, self.NAME)["trainable"])
        write_fixture_interpreter(
            box / ".venv" / ("Scripts" if os.name == "nt" else "bin"))
        return box

    def _probe(self, box):
        payload, code, proc = self._run_cli(
            "probe", "--target", str(box), "--name", self.NAME)
        self.assertEqual(code, 0, proc.stderr)
        return payload

    def test_the_kit_ships_no_module_a_kit_built_target_cannot_import(self):
        """The torch-free half of the proof: whatever else the target's
        interpreter may be missing, it is never one of the kit's own modules.

        Both defects fail exactly here — `verdict` and `<Package>_Benchmark
        .config` are both kit words — and neither one is anything `env` could
        install.
        """
        box = self._kit_built_target("kitmods")
        report = self._probe(box)["report"]
        self.assertEqual(
            _unresolvable_kit_modules(report["liveDetail"]), [],
            "a target built from the kit cannot import the kit: "
            f"{report['liveDetail']}")

    def test_a_kit_built_target_is_live_and_is_never_routed_to_env_first(self):
        """The whole chain, end to end, in the target's own interpreter."""
        if importlib.util.find_spec("torch") is None:
            self.skipTest("the kit's benchmark module imports torch; this "
                          "interpreter has none, so liveness cannot be reached")
        box = self._kit_built_target("envfirst")
        payload = self._probe(box)
        report = payload["report"]
        self.assertIsNone(report["liveDetail"], report["liveDetail"])
        self.assertEqual(report["live"], "ok")
        self.assertNotEqual(payload["nextStep"], "env-first")

    def test_the_constants_holder_introspect_actually_read_is_named(self):
        """A check that could not look must not report an absence as an answer.

        `writtenSelections` is derived from the module-level constants of one
        module; which module that was is published, so a target reading `[]`
        can tell "nothing is written out" from "there was nowhere to look".
        """
        box = self._kit_built_target("holder")
        report = self._probe(box)["report"]
        self.assertEqual(report["constants"], "read")
        self.assertEqual(report["constantsHolder"],
                         f"{self.PACKAGE}_Benchmark.benchmark")


class IntrospectConstantsHolderTests(unittest.TestCase):
    """Which module `introspect` reads its module-level constants from, and what
    it says when there is none.

    `writtenSelections` is derived from one module's uppercase collections. That
    module used to be `<Package>_Benchmark.config`, imported unconditionally —
    and the kit ships no `config.py`, so a repository built from zero raised
    `ModuleNotFoundError` inside the liveness check, was reported `unavailable`,
    and was routed to a rung whose only exit installs packages.

    The order is the one `declared_dimension_names` already uses for the same
    question: a target's own `config.py` first, the kit's `benchmark.py` second.
    """

    def box(self, suffix, files):
        path = FORGE / "implementations" / f"_constants_{suffix}_{os.getpid()}"
        package = path / "src" / "Method_Benchmark"
        package.mkdir(parents=True)
        self.addCleanup(shutil.rmtree, path, ignore_errors=True)
        (package / "__init__.py").write_text(
            "__benchmark__ = {'revision': 'r01.md'}\n", encoding="utf-8")
        for name, source in files.items():
            (package / name).write_text(source, encoding="utf-8")
        write_fixture_interpreter(
            path / ".venv" / ("Scripts" if os.name == "nt" else "bin"))
        return path

    def introspect(self, target):
        return impl.introspect(target, "Method", None,
                               entry_module="Method_Benchmark.entrypoint")

    ENTRY = "VALUE = 1\n"

    def test_a_target_own_config_module_wins_over_the_kit_template(self):
        target = self.box("both", {
            "entrypoint.py": self.ENTRY,
            "config.py": "PICKED = ['a']\nWHOLE = ['a', 'b']\n",
            "benchmark.py": "PICKED = ['z']\nWHOLE = ['z', 'y', 'x']\n"})
        result = self.introspect(target)
        self.assertEqual(result["status"], "ok")
        self.assertEqual(result["constants"], "read")
        self.assertEqual(result["constantsHolder"], "Method_Benchmark.config")
        # Read from `config.py` and not from `benchmark.py`: the two disagree
        # about how big `WHOLE` is, so the reading names which file answered.
        self.assertEqual([row["whole"] for row in result["subsets"]], [2])

    def test_the_kit_template_answers_when_the_target_has_no_config(self):
        """The kit-built state: no `config.py` anywhere, and the check still
        looks somewhere real instead of raising."""
        target = self.box("fallback", {
            "entrypoint.py": self.ENTRY,
            "benchmark.py": "PICKED = ['z']\nWHOLE = ['z', 'y', 'x']\n"})
        result = self.introspect(target)
        self.assertEqual(result["status"], "ok")
        self.assertEqual(result["constants"], "read")
        self.assertEqual(result["constantsHolder"], "Method_Benchmark.benchmark")
        self.assertEqual([row["whole"] for row in result["subsets"]], [3])

    def test_no_holder_at_all_is_named_rather_than_reported_as_an_absence(self):
        """The narrow state that reaches `"absent"`, spelled out: the declared
        entry module imports (anything else answers `unavailable` and never gets
        here), it is not the benchmark module, and neither `config.py` nor
        `benchmark.py` exists beside it. `subsets` is then empty because there
        was nowhere to look, and that is what the key says."""
        target = self.box("absent", {"entrypoint.py": self.ENTRY})
        result = self.introspect(target)
        self.assertEqual(result["status"], "ok")
        self.assertEqual(result["constants"], "absent")
        self.assertIsNone(result["constantsHolder"])
        self.assertEqual(result["subsets"], [])

    def test_a_broken_config_module_still_reads_as_unavailable(self):
        """The guard answers the file's absence and nothing else. A `config.py`
        that is present and cannot import is still the interpreter's verdict,
        exactly as before — swallowing that would trade one silent pass for
        another."""
        target = self.box("broken", {
            "entrypoint.py": self.ENTRY,
            "config.py": "import _pp_constants_holder_absent_dependency\n"})
        result = self.introspect(target)
        self.assertEqual(result["status"], "unavailable")
        self.assertIn("_pp_constants_holder_absent_dependency", result["detail"])


class KitWorkedExampleResolvesTests(unittest.TestCase):
    """The kit's own worked `entry` example, imported against the kit's own files.

    Nothing joined the two halves before this. SKILL.md and
    `assets/kit/src_benchmark/__init__.py` both give the example as a package
    import (`Example_Method_Benchmark.benchmark`), while
    `assets/kit/nb/benchmark.py` imported `verdict` flat — correct only for the
    `python benchmark.py` its own docstring names, and unresolvable under the
    dotted name the example declares. Each half was internally consistent and
    they contradicted each other, so no test of either half could see it.

    Third-party absences are deliberately tolerated here: a missing `torch` is
    the target's environment and genuinely is `env`'s business. A missing
    `verdict` is the forge's own scaffold, and is not.
    """

    #: A worked `entry` example, in either of the two shapes the skill writes
    #: one: SKILL.md's fenced JSON and the kit's own `#`-prefixed comment. Scoped
    #: to the `entry` block rather than to `"module"` alone -- the kit publishes a
    #: second worked example beside it for `__steps__`, which names a module this
    #: kit does not ship and is nothing to do with the entry point.
    ENTRY_EXAMPLE_RE = re.compile(
        r'"entry":\s*\{[\s#]*"module":\s*"([A-Za-z_][\w.]*)"')

    def worked_entry_modules(self):
        """Every worked `entry.module` example the skill publishes, by source."""
        found = {}
        for document in (SKILL_MD, KIT / "src_benchmark" / "__init__.py"):
            text = document.read_text(encoding="utf-8")
            matches = self.ENTRY_EXAMPLE_RE.findall(text)
            self.assertTrue(matches, f"{document} publishes no worked entry example")
            found[document] = matches
        return found

    def test_both_halves_of_the_kit_publish_the_same_worked_example(self):
        found = self.worked_entry_modules()
        distinct = {tuple(sorted(set(matches))) for matches in found.values()}
        self.assertEqual(len(distinct), 1,
                         f"the worked entry example differs by document: {found}")

    def test_the_worked_example_imports_against_the_kit_own_files(self):
        example = sorted(set(next(iter(self.worked_entry_modules().values()))))
        self.assertEqual(len(example), 1, example)
        dotted = example[0]
        package_dir, _, module_name = dotted.rpartition(".")
        self.assertTrue(package_dir.endswith("_Benchmark"), package_dir)

        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        package = root / "src" / package_dir
        package.mkdir(parents=True)
        # Every kit file a materialized target places inside the benchmark
        # package, copied under the example's own package name. `{{PKG}}` is
        # answered exactly as `materialize --stage scaffold` answers it.
        for source in sorted((KIT / "nb").glob("*.py")):
            (package / source.name).write_text(
                source.read_text(encoding="utf-8").replace(
                    "{{PKG}}", package_dir[:-len("_Benchmark")]),
                encoding="utf-8")
        (package / "__init__.py").write_text(
            (KIT / "src_benchmark" / "__init__.py").read_text(encoding="utf-8"),
            encoding="utf-8")
        self.assertTrue((package / f"{module_name}.py").is_file(),
                        f"the kit ships no {module_name}.py for {dotted}")

        proc = subprocess.run(
            [sys.executable, "-c", f"import {dotted}"],
            capture_output=True, text=True, cwd=root,
            env={**os.environ, "PYTHONPATH": str(root / "src")})
        # `cwd` is the tree above `src/`, never the package directory itself:
        # running from inside it would put every sibling module on `sys.path`
        # and the flat import would resolve, which is exactly the mistake.
        self.assertEqual(
            _unresolvable_kit_modules(proc.stderr), [],
            f"the worked example cannot import the kit's own files:\n{proc.stderr}")


class EntryModuleResolutionTests(unittest.TestCase):
    """Where `introspect` gets the entry module's dotted name from — the
    target's own declaration when it names one, reachable only as the
    scaffold's own harness-file convention (`BENCHMARK_MODULE`) otherwise.
    A later phase adds the declared `entry` block; until it lands, this is
    the narrowest path that names no target package of its own.
    """

    def box(self, suffix, declaration):
        path = FORGE / "implementations" / f"_entrymod_{suffix}_{os.getpid()}"
        (path / "src" / "Method_Benchmark").mkdir(parents=True)
        self.addCleanup(shutil.rmtree, path, ignore_errors=True)
        (path / "src" / "Method_Benchmark" / "__init__.py").write_text(
            declaration, encoding="utf-8")
        return path

    def test_an_undeclared_entry_resolves_to_nothing_rather_than_a_guess(self):
        """This asserted the guess, and the guess was the defect.

        Falling back to the forge's own filename convention meant an
        undeclared entry produced a module name that does not exist, whose
        failed import was then reported as the interpreter's. A target whose
        harness carries any other name got sent to repair a working
        environment. `resolve_harness_status` already refuses to guess for
        this reason; its sibling now refuses too.
        """
        target = self.box("fallback", "__benchmark__ = {'revision': 'r01.md'}\n")
        self.assertIsNone(
            impl.resolve_entry_module(target, "Method", "Method"),
            "an absent declaration is an absence, not a name to invent")

    def test_an_explicitly_declared_entry_module_wins(self):
        target = self.box(
            "declared",
            "__benchmark__ = {'revision': 'r01.md', "
            "'entry': {'module': 'Method_Benchmark.custom_entry', 'function': 'run'}}\n")
        self.assertEqual(impl.resolve_entry_module(target, "Method", "Method"),
                          "Method_Benchmark.custom_entry")


class MessagesThatAssertWhatTheyCheckTests(unittest.TestCase):
    """Two refusals stated a fact neither of them checks.

    `OBJECT_MAP_NOT_APPROVED` says the package "declares no revision/premises"
    and gates on `resolve_benchmark_declaration(...)["status"] != "declared"`.
    That status is `"undeclared"` only when `_declaration_is_blank` holds --
    when ALL SEVEN blocks still carry their scaffold value. Measured: with
    `revision: ""`, `premises: {}` and only `search` answered, the status is
    `"declared"`, the gate opens, and step 9's scaffolding is written over an
    object map nobody approved -- with the refusal's own sentence describing
    the exact state that was true and did not refuse.

    `_declare_first_publication` says the target "has a benchmark declaration
    that names nothing yet". Two branches assign `declare-first`, and only one
    of them is that: the second fires for `report.live == "undeclared"`, which
    is a blank `entry.module` and nothing else -- a declaration that may name
    six blocks fully.

    The direction of each repair is decided by which half is the intent.
    `OBJECT_MAP_NOT_APPROVED` is named for the object map and its own docstring
    cites SKILL.md step 8's requirement that `revision`/`premises` be written
    before any step-9 code, so the CHECK was wrong and is tightened. The
    publication's sentence is one of several the flow could truthfully say, so
    the SENTENCE was wrong and now reads the state that actually routed there.
    """

    def _box(self, suffix, declaration, *, comparable=False):
        """`materialize` refuses `DIRTY_WORKTREE` before any gate of its own,
        so the box is committed; and `probe` answers `convert` long before the
        declaration ladder unless there is something to compare against and a
        trainable backend -- `comparable` supplies both, exactly as
        `UnreachedMathematicsEndToEndTests.probe_with` already has to."""
        box = FORGE / "implementations" / f"_assertcheck_{suffix}_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        for directory in ("src/Method", "src/Method_Benchmark", "Method", "tests"):
            (box / directory).mkdir(parents=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        (box / "src/Method_Benchmark/__init__.py").write_text(
            declaration, encoding="utf-8")
        if comparable:
            (box / "src/Prior").mkdir(parents=True)
            (box / "src/Prior/model.py").write_text("import torch\n",
                                                    encoding="utf-8")
            (box / "src/Method/called.py").write_text(
                _module("r01.md", ["3"], ["11"], imports="import torch\n"),
                encoding="utf-8")
        for command in (["git", "add", "-A"],
                        ["git", "-c", "user.email=t@t", "-c", "user.name=t",
                         "commit", "-qm", "fixture"]):
            subprocess.run(command, check=True, capture_output=True, cwd=str(box))
        return box

    SEARCH_ONLY = (
        "__benchmark__ = {\n"
        "    'revision': '',\n"
        "    'premises': {},\n"
        "    'arms': {},\n"
        "    'search': {'what': 'a scalar', 'requiredScale': {'seeds': 3},\n"
        "               'role': 'validation', 'tieRule': 'the smaller wins'},\n"
        "    'report': {},\n"
        "    'distribution': {},\n"
        "    'entry': {'module': '', 'function': ''},\n"
        "}\n")
    APPROVED = (
        "__benchmark__ = {\n"
        "    'revision': 'r01.md',\n"
        "    'premises': {'prediction': 'a label', 'statisticalUnit': 'subject',\n"
        "                 'metric': 'accuracy', 'direction': 'higher'},\n"
        "    'arms': {},\n"
        "    'search': {},\n"
        "    'report': {},\n"
        "    'distribution': {},\n"
        "    'entry': {'module': '', 'function': ''},\n"
        "}\n")

    #: A declaration nobody would call blank: bound to a revision, its
    #: premises written, its report block answered -- and `entry.module`
    #: empty, which is the ONLY thing `report.live == "undeclared"` means.
    #: This is the second branch that assigns `declare-first`, and the one
    #: the published sentence described wrongly.
    LIVE_UNDECLARED = (
        "__benchmark__ = {\n"
        "    'revision': 'r01.md',\n"
        "    'premises': {'prediction': 'a label', 'statisticalUnit': 'subject',\n"
        "                 'metric': 'accuracy', 'direction': 'higher'},\n"
        "    'arms': {},\n"
        "    'search': {},\n"
        "    'report': {'renderers': ['tables.render']},\n"
        "    'distribution': {},\n"
        "    'entry': {'module': '', 'function': ''},\n"
        "}\n")

    def _stage_objects(self, declaration, suffix):
        """`_stage_objects` directly rather than through `materialize`: the
        refusal is raised in this top-level helper, not inside
        `cmd_materialize` (which is why `OBJECT_MAP_NOT_APPROVED` is not in
        `GATING_REFUSALS` -- `raised_refusal_codes` walks `cmd_*` bodies
        only), and reaching it through the CLI would mean satisfying
        `DIRTY_WORKTREE`, `PLAN_REQUIRED` and the mode flags first, none of
        which this gate is about."""
        box = self._box(suffix, declaration)
        try:
            return None, impl._stage_objects(box, "Method", "1")
        except impl.Refused as refused:
            return refused, None

    # --- the gate that opened on a state its own sentence describes --------

    def test_a_declaration_with_no_revision_or_premises_is_refused(self):
        """The measured hole. `_declaration_is_blank` needs all seven blocks
        empty, so answering any one of them opens this gate -- and `search` is
        exactly the block a target can answer long before step 8."""
        refused, _ = self._stage_objects(self.SEARCH_ONLY, "searchonly")
        self.assertIsNotNone(refused, "the gate opened on an unapproved map")
        self.assertEqual(refused.code, "OBJECT_MAP_NOT_APPROVED")
        self.assertIn("revision", refused.detail)
        self.assertIn("premises", refused.detail)

    def test_the_gate_opens_once_the_two_blocks_it_names_are_written(self):
        """The other pole, and the one that keeps the tightening honest: the
        gate must still open, and it must open on exactly what its sentence
        asks for -- `revision` and `premises`, nothing else. A refusal nobody
        can clear is the defect one over from a gate nobody can trip."""
        refused, result = self._stage_objects(self.APPROVED, "approved")
        self.assertIsNone(refused, refused and refused.detail)
        self.assertEqual(result["stage"], "objects")

    def test_the_detail_names_which_of_the_two_is_missing(self):
        """A refusal that says "revision/premises" over a declaration whose
        `premises` is fully written sends somebody to re-read a block that is
        already right."""
        declaration = self.APPROVED.replace("'revision': 'r01.md',", "'revision': '',")
        refused, _ = self._stage_objects(declaration, "halfway")
        self.assertIsNotNone(refused)
        self.assertIn("revision", refused.detail)
        self.assertNotIn("premises", refused.detail)

    def test_a_blank_scaffold_still_refuses_the_same_code(self):
        """The state that already refused must keep refusing under the same
        code -- a tightening that renamed the existing refusal would be a
        second change wearing this one's clothes."""
        refused, _ = self._stage_objects(
            "__benchmark__ = {'revision': '', 'premises': {}, 'arms': {}, "
            "'search': {}, 'report': {}, 'distribution': {}, "
            "'entry': {'module': '', 'function': ''}}\n", "blank")
        self.assertIsNotNone(refused)
        self.assertEqual(refused.code, "OBJECT_MAP_NOT_APPROVED")

    # --- the publication that described one of two states ------------------

    def test_declare_first_says_which_of_the_two_states_routed_there(self):
        """`report.live == "undeclared"` is a blank `entry.module` and nothing
        else. The declaration here answers six blocks and the sentence called
        it one that "names nothing yet"."""
        facts = {"declared": {}, "declarationStatus": "declared",
                 "live": "undeclared"}
        published = impl.next_step_publication(
            Path("implementations/box"), "Method", "declare-first", facts)
        self.assertIn("entry.module", published["question"])
        self.assertNotIn("names nothing yet", published["question"])

    def test_declare_first_still_says_it_for_the_state_where_it_is_true(self):
        """The other pole. A declaration every block of which is still at its
        scaffold value DOES name nothing yet, and the sentence that says so is
        the right one there."""
        facts = {"declared": {}, "declarationStatus": "undeclared",
                 "live": None}
        published = impl.next_step_publication(
            Path("implementations/box"), "Method", "declare-first", facts)
        self.assertIn("names nothing yet", published["question"])

    def test_declare_first_never_claims_a_declaration_a_target_does_not_have(self):
        """The third state: no benchmark package at all. "has a benchmark
        declaration" is false there too, and it was said anyway."""
        facts = {"declared": {}, "declarationStatus": "absent", "live": None}
        published = impl.next_step_publication(
            Path("implementations/box"), "Method", "declare-first", facts)
        self.assertNotIn("has a benchmark declaration", published["question"])

    def test_probe_hands_the_publication_the_state_that_routed_there(self):
        """The join. Both sentences above are only true if `probe` actually
        passes the state it branched on -- a fact computed and not threaded
        through is a fact the publication has to guess at again."""
        box = self._box("probefacts", self.LIVE_UNDECLARED, comparable=True)
        proc = subprocess.run(
            [sys.executable, str(CLI), "probe", "--target", str(box),
             "--name", "Method"],
            capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["nextStep"], "declare-first")
        self.assertIn("entry.module", payload["resolve"]["question"])

    # --- the declaration nothing in the forge reads -------------------------

    def test_a_declared_module_with_no_function_is_reported(self):
        """`entry.function` is read by nothing in this file -- only `.module`
        is, twice. The kit's claim about it is accurate: `generate-job`'s own
        `--run-function` is `required=True`, so the value IS needed, by the
        operator, at the one handoff SKILL.md's seam table names. What was
        missing is that a target could answer `module` and leave `function`
        blank and hear about it nowhere, then reach a required flag with
        nothing to type into it."""
        target = self.box_pkg(
            "nofunction",
            "__benchmark__ = {'revision': 'r01.md', "
            "'entry': {'module': 'Method_Benchmark.benchmark', 'function': ''}}\n")
        (target / "src/Method_Benchmark/benchmark.py").write_text(
            "VALUE = 1\n", encoding="utf-8")
        status = impl.resolve_harness_status(target, "Method", "Method")
        self.assertEqual(status["status"], "present")
        self.assertIsNone(status["declaredFunction"])
        self.assertIsNotNone(status["note"])
        self.assertIn("--run-function", status["note"])

    def test_a_declared_function_is_echoed_and_the_note_is_empty(self):
        """The other pole: a target that answered both hears nothing, and the
        value it answered is echoed so the operator can read it off the same
        output rather than re-opening the declaration."""
        target = self.box_pkg(
            "withfunction",
            "__benchmark__ = {'revision': 'r01.md', "
            "'entry': {'module': 'Method_Benchmark.benchmark', "
            "'function': 'run'}}\n")
        (target / "src/Method_Benchmark/benchmark.py").write_text(
            "VALUE = 1\n", encoding="utf-8")
        status = impl.resolve_harness_status(target, "Method", "Method")
        self.assertEqual(status["declaredFunction"], "run")
        self.assertIsNone(status["note"])

    def test_an_undeclared_module_is_not_told_about_the_function_too(self):
        """One absence, one fact. `entry.module` undeclared already has its
        own status, and naming the function beside it would turn one gap into
        two findings -- `undeclared_ladder_state`'s own restraint."""
        target = self.box_pkg(
            "neither", "__benchmark__ = {'revision': 'r01.md'}\n")
        status = impl.resolve_harness_status(target, "Method", "Method")
        self.assertEqual(status["status"], "undeclared")
        self.assertIsNone(status["declaredFunction"])
        self.assertIsNone(status["note"])

    def test_every_branch_carries_both_new_keys(self):
        """`distribution_state`'s rule again: a key on some branches only
        cannot be told from an absent answer by anything downstream."""
        for suffix, declaration in (
                ("branch_undeclared", "__benchmark__ = {'revision': 'r01.md'}\n"),
                ("branch_missing",
                 "__benchmark__ = {'revision': 'r01.md', 'entry': "
                 "{'module': 'Method_Benchmark.nowhere', 'function': 'run'}}\n")):
            with self.subTest(suffix=suffix):
                status = impl.resolve_harness_status(
                    self.box_pkg(suffix, declaration), "Method", "Method")
                self.assertIn("declaredFunction", status)
                self.assertIn("note", status)

    def box_pkg(self, suffix, declaration):
        path = FORGE / "implementations" / f"_entryfn_{suffix}_{os.getpid()}_{id(self)}"
        (path / "src" / "Method_Benchmark").mkdir(parents=True)
        self.addCleanup(shutil.rmtree, path, ignore_errors=True)
        (path / "src" / "Method_Benchmark" / "__init__.py").write_text(
            declaration, encoding="utf-8")
        return path


class HarnessStatusResolutionTests(unittest.TestCase):
    """Where `probe` gets its harness's name from — the target's own
    declaration, `entry.module`, never a second hardcoded filename beside
    `BENCHMARK_MODULE`.

    Three states, and they answer three different questions: `undeclared`
    (nothing named yet — silence about the tree says nothing), `present` (the
    declared module's file exists), and `declaredMissing` (a module is named
    and its file is not where the declaration says — named with the declared
    module and the exact path looked for, because a refusal that does not say
    where it looked cannot be acted on).
    """

    def box(self, suffix, declaration):
        path = FORGE / "implementations" / f"_harnessstatus_{suffix}_{os.getpid()}"
        (path / "src" / "Method_Benchmark").mkdir(parents=True)
        self.addCleanup(shutil.rmtree, path, ignore_errors=True)
        (path / "src" / "Method_Benchmark" / "__init__.py").write_text(
            declaration, encoding="utf-8")
        return path

    def test_an_empty_entry_module_reports_undeclared(self):
        """Nothing declared yet. This must never be read as "no harness
        file exists" — the tree may hold one under any name at all."""
        target = self.box("undeclared", "__benchmark__ = {'revision': 'r01.md'}\n")
        status = impl.resolve_harness_status(target, "Method", "Method")
        self.assertEqual(status["status"], "undeclared")
        self.assertIsNone(status["declaredModule"])
        self.assertIsNone(status["path"])
        self.assertIsNone(status["searchedPath"])

    def test_a_declared_module_present_on_disk_reports_its_path(self):
        target = self.box(
            "present",
            "__benchmark__ = {'revision': 'r01.md', "
            "'entry': {'module': 'Method_Benchmark.benchmark', 'function': 'run'}}\n")
        (target / "src" / "Method_Benchmark" / "benchmark.py").write_text(
            "VALUE = 1\n", encoding="utf-8")
        status = impl.resolve_harness_status(target, "Method", "Method")
        self.assertEqual(status["status"], "present")
        self.assertEqual(status["declaredModule"], "Method_Benchmark.benchmark")
        self.assertEqual(status["path"], "src/Method_Benchmark/benchmark.py")
        self.assertIsNone(status["searchedPath"])

    def test_a_declared_module_missing_from_disk_names_it_and_where_it_looked(self):
        """Present under a different name is not the same fact as absent, and
        this is the case that tells the two apart without a second hardcoded
        filename: the target names its harness `harness.py`, nothing at
        `benchmark.py` was ever written, and the declared name is honoured."""
        target = self.box(
            "declared_missing",
            "__benchmark__ = {'revision': 'r01.md', "
            "'entry': {'module': 'Method_Benchmark.harness', 'function': 'run'}}\n")
        status = impl.resolve_harness_status(target, "Method", "Method")
        self.assertEqual(status["status"], "declaredMissing")
        self.assertEqual(status["declaredModule"], "Method_Benchmark.harness")
        self.assertIsNone(status["path"])
        self.assertEqual(status["searchedPath"], "src/Method_Benchmark/harness.py")

    def test_absent_and_missing_are_told_apart_by_the_declaration_alone(self):
        """One target has no harness file at all; another has it under the
        declared name. Neither reads the forge's own filename convention to
        tell them apart."""
        absent = self.box("absent_pole",
                          "__benchmark__ = {'revision': 'r01.md', "
                          "'entry': {'module': 'Method_Benchmark.harness', "
                          "'function': 'run'}}\n")
        present = self.box("present_pole",
                           "__benchmark__ = {'revision': 'r01.md', "
                           "'entry': {'module': 'Method_Benchmark.harness', "
                           "'function': 'run'}}\n")
        (present / "src" / "Method_Benchmark" / "harness.py").write_text(
            "VALUE = 1\n", encoding="utf-8")

        self.assertEqual(
            impl.resolve_harness_status(absent, "Method", "Method")["status"],
            "declaredMissing")
        self.assertEqual(
            impl.resolve_harness_status(present, "Method", "Method")["status"],
            "present")

    def test_no_second_hardcoded_filename_names_the_harness(self):
        """The design's own rejected alternative, measured rather than
        argued: a second hardcoded name beside `BENCHMARK_MODULE` would be
        the same defect twice."""
        source = inspect.getsource(impl.resolve_harness_status)
        self.assertNotIn("BENCHMARK_MODULE", source,
                         "the declared entry name is the only lookup here")


class EnvFirstGateTests(unittest.TestCase):
    """`nextStep` must not advance past `env-first` while the target's own
    declared entry module cannot be imported — Decision 12's new rung,
    inserted immediately after `declare-first`. Reuses
    `ProbeReportedFactsRosterTests`'s fixture builder by composition, never by
    subclassing, so its own test methods are not rediscovered under this
    class name too.
    """

    DECLARATION = ProbeReportedFactsRosterTests.DECLARATION
    WIRING = ProbeReportedFactsRosterTests.WIRING
    TABLES = ProbeReportedFactsRosterTests.TABLES

    def build_target(self, suffix):
        return ProbeReportedFactsRosterTests.build_target(self, suffix)

    def probe(self, box):
        return ProbeReportedFactsRosterTests.probe(self, box)

    def test_an_unimportable_entry_module_reports_env_first_not_benchmark(self):
        """The exact defect this rung exists to close: an empty venv whose
        pure-Python `config` still imports fine used to clear the way to a run
        the environment could not perform."""
        box, _ = self.build_target("envfirst_broken")
        (box / "src/Method_Benchmark/benchmark.py").write_text(
            "import _pp_env_first_absent_dependency\n", encoding="utf-8")
        probe = self.probe(box)
        self.assertEqual(probe["report"]["live"], "unavailable")
        self.assertEqual(probe["nextStep"], "env-first")
        self.assertNotEqual(probe["nextStep"], "benchmark")

    def test_an_undeclared_entry_is_a_declaration_gap_not_a_broken_environment(self):
        """Measured against a real target: six of seven blocks declared, the
        seventh empty, an environment that imports everything it needs — and
        the flow answered that the interpreter could not import the entry
        module. It could. Nothing had said which module to import.

        `resolve_harness_status` already refuses to guess a filename and
        reports `undeclared` instead. Its sibling guessed the forge's own
        convention, handed the guess to liveness, and liveness reported the
        guess's failure as the environment's. Two different facts under one
        message, which is the shape this whole flow exists to remove.
        """
        box, _ = self.build_target("entry_undeclared")
        # Six blocks declared, the seventh absent — a target written before
        # `entry` existed. The environment is sound; the module simply is not
        # under the name the forge would have assumed.
        init = box / "src/Method_Benchmark/__init__.py"
        text = init.read_text(encoding="utf-8")
        start = text.index("    'entry'")
        end = text.index("\n", text.index("'function'", start)) + 1
        init.write_text(text[:start] + text[end:], encoding="utf-8")
        module = box / "src/Method_Benchmark/benchmark.py"
        module.rename(module.with_name("harness.py"))
        probe = self.probe(box)
        self.assertNotEqual(
            probe["report"]["live"], "unavailable",
            "an undeclared entry is not an environment that cannot import; "
            "reporting it as one sends the reader to repair what is working")
        self.assertEqual(probe["report"]["live"], "undeclared")
        self.assertNotEqual(
            probe["nextStep"], "env-first",
            "the missing thing is a declaration, and the rung for a missing "
            "declaration already exists")
        self.assertEqual(probe["nextStep"], "declare-first")

    def test_the_same_target_reaches_benchmark_once_the_entry_module_imports(self):
        box, _ = self.build_target("envfirst_ok")
        probe = self.probe(box)
        self.assertEqual(probe["report"]["live"], "ok")
        self.assertEqual(probe["nextStep"], "benchmark")


class ProvisionedEntryLivenessIntegrationTests(unittest.TestCase):
    """A real, freshly-built `.venv` — never a symlink to the interpreter
    running this suite — proving the whole chain end to end: `env`'s
    `nextCommand` names the target's own manifest, installing it makes the
    declared entry module importable with no `ModuleNotFoundError`, and doing
    so through the venv's own prescribed interpreter never trips the same
    "foreign interpreter" refusal every target harness under this doctrine
    carries (`sys.prefix` scoped to the repository's own virtualenv).

    Nothing is launched anywhere; this only builds a venv, installs one local,
    offline package, and imports a module — the shape Unit 5's own tasks call
    for: "no launch".
    """

    VENDOR_SETUP = (
        "from setuptools import setup\n"
        "setup(name='pptinypkg', version='0.0.1', packages=['pptinypkg'])\n"
    )
    VENDOR_INIT = "VALUE = 42\n"

    #: The identical mechanism every target harness under this doctrine
    #: carries: refuse an interpreter whose `sys.prefix` sits outside the
    #: repository, once the repository has a virtualenv of its own. Proven
    #: inline rather than by invoking a real target's own harness — that
    #: repository is a separate one, out of scope here — but the check is the
    #: forge's own generic kit convention (`environment()` in
    #: `assets/kit/nb/benchmark.py`), reproduced at the one line that matters.
    ENTRY_MODULE = (
        "import sys\n"
        "from pathlib import Path\n"
        "import pptinypkg\n"
        "repository = Path(__file__).resolve().parents[2]\n"
        "prefix = Path(sys.prefix).resolve()\n"
        "if not prefix.is_relative_to(repository):\n"
        "    raise SystemExit(f'refusing to run under {prefix}')\n"
        "VALUE = pptinypkg.VALUE\n"
    )

    def build_target(self):
        target = FORGE / "implementations" / f"_env_live_{os.getpid()}"
        self.addCleanup(shutil.rmtree, target, ignore_errors=True)
        (target / "vendor" / "pptinypkg" / "pptinypkg").mkdir(parents=True)
        (target / "vendor" / "pptinypkg" / "setup.py").write_text(
            self.VENDOR_SETUP, encoding="utf-8")
        (target / "vendor" / "pptinypkg" / "pptinypkg" / "__init__.py").write_text(
            self.VENDOR_INIT, encoding="utf-8")
        (target / "requirements.txt").write_text(
            "-e ./vendor/pptinypkg\n", encoding="utf-8")
        (target / "src" / "Method_Benchmark").mkdir(parents=True)
        (target / "src" / "Method_Benchmark" / "__init__.py").write_text(
            "__benchmark__ = {'revision': 'r01.md'}\n", encoding="utf-8")
        (target / "src" / "Method_Benchmark" / "config.py").write_text(
            "SCALES = [1, 2, 3]\n", encoding="utf-8")
        (target / "src" / "Method_Benchmark" / "benchmark.py").write_text(
            self.ENTRY_MODULE, encoding="utf-8")
        subprocess.run(["git", "init", "-q", str(target)], check=True, capture_output=True)
        return target

    def test_the_prescribed_interpreter_runs_the_declared_manifest_with_no_launch(self):
        target = self.build_target()

        # 1. `env`: a real venv, never symlinked, created fresh with nothing installed.
        env_result = impl.cmd_env(
            argparse.Namespace(target=str(target), python=sys.executable))
        self.assertEqual(env_result["status"], "created")
        interpreter = Path(env_result["interpreter"])
        self.assertTrue(interpreter.is_relative_to(target),
                         "the prescribed interpreter must live inside the target")

        # 2. Before install: the entry module cannot be imported at all — the
        #    empty-venv state `env-first` exists to catch. `config.py` is not
        #    even present here, so there is nothing pure-Python to hide behind.
        before = impl.introspect(target, "Method", None,
                                  entry_module="Method_Benchmark.benchmark")
        self.assertEqual(before["status"], "unavailable")
        self.assertIn("pptinypkg", before["detail"])

        # 3. Install exactly the target's own honoured manifest — the part of
        #    `nextCommand` this test can run offline. `--no-build-isolation`
        #    is this test's own concession to a sandbox with no network; it
        #    changes nothing about what `manifest_provisioning` reports.
        manifests = impl.manifest_provisioning(target)
        self.assertEqual([row["name"] for row in manifests["rows"]],
                          ["requirements.txt"])
        proc = subprocess.run(
            [str(env_result["pip"]), "install", "--no-build-isolation",
             "--disable-pip-version-check", "-q", *manifests["args"]],
            capture_output=True, text=True, cwd=str(target))
        self.assertEqual(proc.returncode, 0, proc.stderr)

        # 4. After install: the prescribed interpreter imports the declared
        #    entry module with no `ModuleNotFoundError`, and the same
        #    "foreign interpreter" refusal every target harness under this
        #    doctrine carries is not triggered — `sys.prefix` is genuinely
        #    inside the target now, not a symlink borrowing another one's.
        after = impl.introspect(target, "Method", None,
                                 entry_module="Method_Benchmark.benchmark")
        self.assertEqual(after["status"], "ok", after.get("detail"))

        direct = subprocess.run(
            [str(interpreter), "-c",
             "import Method_Benchmark.benchmark as m; print(m.VALUE)"],
            capture_output=True, text=True, cwd=str(target),
            env={**os.environ, "PYTHONPATH": str(target / "src")})
        self.assertEqual(direct.returncode, 0, direct.stderr)
        self.assertNotIn("refusing to run under", direct.stdout + direct.stderr)
        self.assertIn("42", direct.stdout)


class PositionModuleTests(unittest.TestCase):
    """`impl_position`'s pure grammar and splice, exercised directly against
    the module — no target, no repository, no subprocess.

    The two byte-preservation properties below are ported from the
    deliberation engine's own suite
    (`tests/proposal-deliberation-successor-byte-preservation.test.mjs:41-78`),
    not re-derived: a replacement argument that interprets its own bytes as
    escapes is the same bug class in a different language, and `AGREED.md`
    already carries the payload that would expose it — `$$`, `\\tag{}`, and
    backslashes (design lines 197-261 of a real target).
    """

    HEADER = {
        "revision": "research-concept-r17",
        "revisionSha256": "a" * 64,
        "derivedAt": "2026-08-27T00:00:00Z",
        "session": "s1",
        "target": "final",
    }

    def block_text(self, items):
        return impl_position.render(self.HEADER, items)

    # --- ported: "$$" survives, never collapsed by a replacement-pattern escape ---

    def test_a_dollar_dollar_and_backslash_payload_survives_splice_byte_for_byte(self):
        payload_text = "The identity is $$E=mc^2$$ and \\tag{39} names it."
        items = [{"ordinal": 1, "mark": " ", "text": payload_text,
                  "witness": {"kind": "record", "operand": None}}]
        new_block = self.block_text(items).encode("utf-8")
        original = "# Title\n\nSome prose already here.\n".encode("utf-8")

        spliced = impl_position.splice(original, new_block, None)

        self.assertIn(payload_text.encode("utf-8"), spliced)
        self.assertTrue(spliced.startswith(original))
        # Round-trip: locate + parse recovers the identical payload text,
        # which is only possible if the bytes were concatenated rather than
        # run through anything that treats "$$" or "\t" as an escape.
        block = impl_position.locate_block(spliced)
        parsed = impl_position.parse_items(block["body"])
        self.assertEqual(parsed[0]["text"], payload_text)

    # --- ported: only the located span changes; an identical string elsewhere stays ---

    def test_replacing_the_block_leaves_an_identical_string_elsewhere_untouched(self):
        outside = "Shared line.\n"
        placeholder = [{"ordinal": 1, "mark": " ", "text": "placeholder",
                        "witness": {"kind": "record", "operand": None}}]
        old_block = self.block_text(placeholder).encode("utf-8")
        original = ("# Doc\n\n" + outside + "\n").encode("utf-8") + old_block

        block = impl_position.locate_block(original)
        self.assertIsNotNone(block)

        new_items = [{"ordinal": 1, "mark": " ", "text": "Shared line.",
                      "witness": {"kind": "record", "operand": None}}]
        new_block = self.block_text(new_items).encode("utf-8")
        spliced = impl_position.splice(original, new_block, block)

        # The outside occurrence, at its original byte offset, is untouched.
        outside_at = original.index(outside.encode("utf-8"))
        self.assertEqual(spliced[outside_at:outside_at + len(outside)],
                          outside.encode("utf-8"))
        # It appears exactly once outside the block and once inside the
        # freshly spliced-in block -- never merged, never duplicated by the
        # splice itself.
        self.assertEqual(spliced.count(b"Shared line."), 2)

    # --- location: uniqueness required, never first-occurrence-wins ---

    def test_two_position_blocks_refuse_rather_than_pick_the_first(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "record", "operand": None}}]
        block = self.block_text(items).encode("utf-8")
        doc = block + b"\n" + block

        with self.assertRaises(impl.Refused) as ctx:
            impl_position.locate_block(doc)
        self.assertEqual(ctx.exception.code, "POSITION_BLOCK_NOT_UNIQUE")

    def test_absent_block_is_a_state_not_an_error(self):
        self.assertIsNone(impl_position.locate_block(b"# Doc\n\nNo block here.\n"))

    # --- derive(): three-valued, per witness kind, never guessing on absence ---

    def test_derive_record_ticks_on_found_and_required_scale_satisfied(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "record", "operand": None}}]
        self.assertIs(impl_position.derive(
            items, {"search": {"recordFound": False}, "requiredScale": {}}
        )[0]["derived"], False)
        self.assertIs(impl_position.derive(
            items, {"search": {"recordFound": True}, "requiredScale": {}}
        )[0]["derived"], True)
        self.assertIs(impl_position.derive(
            items, {"search": {"recordFound": True, "scaleSatisfied": False},
                    "requiredScale": {"seeds": 30}}
        )[0]["derived"], False)
        self.assertIsNone(impl_position.derive(items, {})[0]["derived"])

    def test_derive_notebook_ticks_on_executed_and_sources_match(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "notebook",
                             "operand": "Notebooks/campaign.ipynb"}}]
        evidence = {"notebooks": {"reports": [
            {"notebook": "Method/Notebooks/campaign.ipynb",
             "status": "executed", "sourcesMatch": True}]}}
        self.assertIs(impl_position.derive(items, evidence)[0]["derived"], True)
        evidence["notebooks"]["reports"][0]["sourcesMatch"] = False
        self.assertIs(impl_position.derive(items, evidence)[0]["derived"], False)
        self.assertIsNone(impl_position.derive(items, {})[0]["derived"])

    def test_derive_rehearsal_ticks_on_smoke_ready(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "rehearsal", "operand": "undercut-search"}}]
        self.assertIs(impl_position.derive(
            items, {"smokeReady": {"undercut-search": True}})[0]["derived"], True)
        self.assertIs(impl_position.derive(
            items, {"smokeReady": {"undercut-search": False}})[0]["derived"], False)
        self.assertIsNone(impl_position.derive(items, {})[0]["derived"])

    def test_derive_shard_is_unmeasured_without_shard_evidence(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "shard", "operand": "s3"}}]
        self.assertIs(impl_position.derive(
            items, {"shardsArrived": ["s3"]})[0]["derived"], True)
        self.assertIs(impl_position.derive(
            items, {"shardsArrived": ["s1"]})[0]["derived"], False)
        # `probe` never supplies `shardsArrived`; `verify` without `--shards`
        # does not either. Both leave this `None` -- never a false "did not
        # arrive" for a shard this invocation was simply not told to check.
        self.assertIsNone(impl_position.derive(items, {})[0]["derived"])

    def test_derive_flags_disagreement_between_disk_mark_and_measurement(self):
        items = [{"ordinal": 1, "mark": "x", "text": "x",
                  "witness": {"kind": "rehearsal", "operand": "job"}}]
        result = impl_position.derive(items, {"smokeReady": {"job": False}})[0]
        self.assertIs(result["derived"], False)
        self.assertTrue(result["disagrees"])

    def test_derive_unmeasured_never_disagrees(self):
        items = [{"ordinal": 1, "mark": "x", "text": "x",
                  "witness": {"kind": "shard", "operand": "s3"}}]
        result = impl_position.derive(items, {})[0]
        self.assertIsNone(result["derived"])
        self.assertFalse(result["disagrees"])

    # --- parse_items(): malformed witness is refused, never silently accepted ---

    def test_item_without_a_witness_is_refused(self):
        with self.assertRaises(impl.Refused) as ctx:
            impl_position.parse_items("- [ ] 1. No witness token at all.\n")
        self.assertEqual(ctx.exception.code, "POSITION_ITEM_WITHOUT_WITNESS")

    def test_item_naming_an_unknown_witness_kind_is_refused(self):
        with self.assertRaises(impl.Refused) as ctx:
            impl_position.parse_items("- [ ] 1. Something. `@wat`\n")
        self.assertEqual(ctx.exception.code, "POSITION_WITNESS_UNKNOWN_KIND")

    # --- ledger fold: append-only, absent file is zero events, not an error ---

    def test_ledger_round_trips_and_is_empty_when_absent(self):
        with tempfile.TemporaryDirectory() as raw:
            path = Path(raw) / "Method" / ".implementation" / "position.jsonl"
            self.assertEqual(impl_position.read_events(path), [])
            impl_position.append_event(path, {"kind": "gate", "jobName": "j1"})
            impl_position.append_event(path, {"kind": "close", "session": "s1"})
            events = impl_position.read_events(path)
            self.assertEqual([e["kind"] for e in events], ["gate", "close"])


class AbsentFileDigestTests(unittest.TestCase):
    """`impl_position.current_file_digest` / `open_defects` — the derived
    half of the `maintenance-blocks-it-does-not-mix` mechanism (design
    decisions 1-4). Phase 1 only: record and derive, inert, blocks nothing.

    Exercised directly against the module, no CLI, no repository: `forge_root`
    is an explicit argument to `open_defects` (design decision 8) precisely so
    the property can be proven here against a throwaway tree instead of the
    real forge.
    """

    def _forge(self):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / ".claude" / "skills" / "some-skill").mkdir(parents=True)
        return root

    def _write(self, forge_root, rel, data):
        path = forge_root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(data)
        return path

    # --- ABSENT_FILE_DIGEST: the sentinel itself, never a valid digest ---

    def test_absent_file_digest_never_matches_a_sha256_hex_shape(self):
        self.assertIsNone(
            re.fullmatch(r"[0-9a-f]{64}", impl_position.ABSENT_FILE_DIGEST))

    # --- current_file_digest: the one producer both declaration and check call ---

    def test_current_file_digest_hashes_a_regular_file(self):
        forge_root = self._forge()
        path = self._write(forge_root, ".claude/skills/some-skill/mod.py", b"x = 1\n")
        self.assertEqual(impl_position.current_file_digest(path),
                         impl_position.digest_bytes(b"x = 1\n"))

    def test_current_file_digest_returns_the_sentinel_for_an_absent_path(self):
        forge_root = self._forge()
        never = forge_root / ".claude" / "skills" / "some-skill" / "never.py"
        self.assertEqual(impl_position.current_file_digest(never),
                         impl_position.ABSENT_FILE_DIGEST)

    def test_current_file_digest_returns_the_sentinel_for_a_directory(self):
        forge_root = self._forge()
        directory = forge_root / ".claude" / "skills" / "some-skill"
        self.assertEqual(impl_position.current_file_digest(directory),
                         impl_position.ABSENT_FILE_DIGEST)

    # --- open_defects: one uniform comparison, latest-wins, fail-closed ---

    def test_open_defects_empty_with_no_defect_events(self):
        forge_root = self._forge()
        self.assertEqual(impl_position.open_defects([], forge_root), [])
        self.assertEqual(
            impl_position.open_defects([{"kind": "gate"}], forge_root), [])

    def test_open_defects_open_while_the_recorded_digest_still_matches(self):
        forge_root = self._forge()
        path = self._write(forge_root, ".claude/skills/some-skill/mod.py", b"x = 1\n")
        rel = str(path.relative_to(forge_root))
        digest = impl_position.digest_bytes(b"x = 1\n")
        events = [{"kind": "defect", "file": rel, "fileSha256": digest}]
        self.assertEqual(impl_position.open_defects(events, forge_root), events)

    def test_open_defects_clears_the_moment_the_bytes_change(self):
        forge_root = self._forge()
        path = self._write(forge_root, ".claude/skills/some-skill/mod.py", b"x = 1\n")
        rel = str(path.relative_to(forge_root))
        stale_digest = impl_position.digest_bytes(b"x = 1\n")
        path.write_bytes(b"x = 2\n")
        events = [{"kind": "defect", "file": rel, "fileSha256": stale_digest}]
        self.assertEqual(impl_position.open_defects(events, forge_root), [])

    def test_open_defects_missing_filesha256_key_fails_closed_open(self):
        forge_root = self._forge()
        path = self._write(forge_root, ".claude/skills/some-skill/mod.py", b"x = 1\n")
        rel = str(path.relative_to(forge_root))
        events = [{"kind": "defect", "file": rel}]  # no fileSha256 key at all
        self.assertEqual(impl_position.open_defects(events, forge_root), events)

    def test_open_defects_latest_wins_per_file(self):
        forge_root = self._forge()
        path = self._write(forge_root, ".claude/skills/some-skill/mod.py", b"x = 1\n")
        rel = str(path.relative_to(forge_root))
        current_digest = impl_position.digest_bytes(b"x = 1\n")  # matches the file's live bytes
        stale_digest = impl_position.digest_bytes(b"x = 0\n")    # never matches them
        events = [
            # Oldest: names the CURRENT digest -- would read as open alone.
            {"kind": "defect", "file": rel, "fileSha256": current_digest},
            # Newest: names a stale digest -- would read as cleared alone.
            {"kind": "defect", "file": rel, "fileSha256": stale_digest},
        ]
        # Only the newest event decides. Without latest-wins the older
        # matching event would leak through and report this open.
        self.assertEqual(impl_position.open_defects(events, forge_root), [])

    def test_open_defects_never_existing_path_deadlocks_open_under_the_uniform_comparison(self):
        """The mirror image of the reported bypass (design decision 1's own
        rationale): a `defect` event recorded with the sentinel for a path
        that stays absent compares sentinel-equals-sentinel forever.
        `cmd_defect` refuses this at declaration (`DEFECT_FILE_ABSENT`) so it
        can never be produced live, but the derivation itself must still
        exhibit the property the refusal exists to keep unreachable.
        """
        forge_root = self._forge()
        never = forge_root / ".claude" / "skills" / "some-skill" / "never.py"
        rel = str(never.relative_to(forge_root))
        events = [{"kind": "defect", "file": rel,
                  "fileSha256": impl_position.ABSENT_FILE_DIGEST}]
        self.assertEqual(impl_position.open_defects(events, forge_root), events)

    def test_open_defects_rejects_a_stored_file_that_escapes_the_skills_tree(self):
        """Design decision 4: the containment invariant is re-verified for
        free on the read side. A hand-written ledger line naming a path
        outside `.claude/skills/` cannot point the checker anywhere else."""
        forge_root = self._forge()
        events = [{"kind": "defect", "file": "../outside.txt",
                  "fileSha256": "deadbeef"}]
        self.assertEqual(impl_position.open_defects(events, forge_root), [])

    # --- the bypass's structural closure: no existence branch in the clearing path ---

    def test_open_defects_source_carries_no_existence_branch(self):
        source = inspect.getsource(impl_position.open_defects)
        pattern = re.compile(r"if\s+not\s+\S+\.(exists|is_file)\(")
        self.assertIsNone(
            pattern.search(source),
            "open_defects branches on file existence directly -- absence "
            "must enter only as current_file_digest's own return value")


class PositionLevelGrammarTests(unittest.TestCase):
    """PR10, `the-position-nobody-holds`: the boolean tick becomes an ordered
    level, without collapsing `None` ("unmeasured") into the floor rung, and
    without ever assigning a two-state item a rung it never declared.

    The two tests immediately below are the mandated first tests: written and
    confirmed RED for the stated reason before the production grammar in
    `impl_position.py` existed. Levels used throughout are deliberately
    generic (`"local"`, `"cluster"`, ...) — the ladder's own names are never
    the forge's; see `derive`'s and `level_index`'s docstrings.
    """

    LEVELS = ["local", "staging", "cluster"]

    # --- mandated test 1: a two-state item cannot be assigned a middle rung ---

    def test_a_two_state_item_is_never_assigned_a_level_string(self):
        """A `:level`-less witness stays two-state even when the evidence
        underneath it (a record, found but short of the declared scale)
        would otherwise resolve to a real middle rung for a leveled item —
        proving the two-state grammar is not just "leveled with no ladder
        declared", it actively refuses the rung.
        """
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "record", "operand": None}}]  # no twostate key: default
        evidence = {
            "search": {"recordFound": True, "scaleSatisfied": False},
            "requiredScale": {"seeds": 30},
            "levels": self.LEVELS, "targetLevel": "cluster",
        }
        result = impl_position.derive(items, evidence)[0]
        self.assertTrue(result["twostate"])
        self.assertIn(result["derived"], (True, False, None))
        self.assertNotIn(result["derived"], self.LEVELS)

    # --- mandated test 2: unreadable evidence reports unmeasured, never the floor ---

    def test_unreadable_evidence_reports_unmeasured_not_the_floor_rung(self):
        """A leveled item whose evidence dict carries nothing to read (the
        same shape `probe` or a flagless `verify` already hands a `@shard`
        witness) must derive `None`, not `self.LEVELS[0]` — "we did not
        look" and "it has not started" stay two different facts.
        """
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "shard", "operand": "s3", "twostate": False}}]
        result = impl_position.derive(items, {"levels": self.LEVELS})[0]
        self.assertIsNone(result["derived"])
        self.assertNotEqual(result["derived"], self.LEVELS[0])
        self.assertIsNone(result["satisfied"])
        self.assertFalse(result["disagrees"])

    # --- twostate default: unmarked items behave exactly as the prior revision ---

    def test_an_unmarked_witness_defaults_to_two_state_unchanged_from_before(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "rehearsal", "operand": "job"}}]
        result = impl_position.derive(items, {"smokeReady": {"job": True}})[0]
        self.assertTrue(result["twostate"])
        self.assertIs(result["derived"], True)
        self.assertIs(result["satisfied"], True)

    # --- :level grammar round-trips through render/parse/locate ---

    def test_a_level_marked_witness_round_trips_through_render_and_parse(self):
        header = {**PositionModuleTests.HEADER, "target": "staging"}
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "rehearsal", "operand": "job", "twostate": False}}]
        text = impl_position.render(header, items)
        self.assertIn("`@rehearsal:level job`", text)
        block = impl_position.locate_block(text.encode("utf-8"))
        self.assertEqual(block["target"], "staging")
        parsed = impl_position.parse_items(block["body"])
        self.assertFalse(parsed[0]["witness"]["twostate"])

    def test_an_unmarked_witness_round_trips_as_two_state_with_no_suffix(self):
        text = impl_position.render(PositionModuleTests.HEADER, [
            {"ordinal": 1, "mark": " ", "text": "x",
             "witness": {"kind": "notebook", "operand": "a.ipynb"}}])
        self.assertIn("`@notebook a.ipynb`", text)
        self.assertNotIn("`@notebook:level", text)
        block = impl_position.locate_block(text.encode("utf-8"))
        parsed = impl_position.parse_items(block["body"])
        self.assertTrue(parsed[0]["witness"]["twostate"])

    # --- header migration: a block written by the prior grammar is refused ---

    def test_a_pre_pr10_block_with_no_target_field_is_refused_not_migrated(self):
        old_style = (
            "<!-- position revision=r1 sha256=" + "b" * 64 +
            " derivedAt=2026-01-01T00:00:00Z session=s1 -->\n"
            "- [ ] 1. Something. `@record`\n"
            "<!-- /position -->\n"
        ).encode("utf-8")
        with self.assertRaises(impl.Refused) as ctx:
            impl_position.locate_block(old_style)
        self.assertEqual(ctx.exception.code, "POSITION_BLOCK_MALFORMED")

    def test_allow_legacy_reads_a_pre_pr10_block_as_migratable(self):
        """`position` is the one place a caller may opt into reading an old
        block at all (`allow_legacy=True`) -- everyone else keeps refusing,
        exercised immediately above. This is what makes migration reachable:
        without it, `cmd_position` could never even see the block it is
        supposed to rewrite.
        """
        old_style = (
            "<!-- position revision=r1 sha256=" + "b" * 64 +
            " derivedAt=2026-01-01T00:00:00Z session=s1 -->\n"
            "- [ ] 1. Something. `@record`\n"
            "<!-- /position -->\n"
        ).encode("utf-8")
        block = impl_position.locate_block(old_style, allow_legacy=True)
        self.assertIsNotNone(block)
        self.assertIsNone(block["target"])
        self.assertTrue(block["legacy"])
        # The item grammar itself needs no migration -- unaffected by the
        # header's shape.
        items = impl_position.parse_items(block["body"])
        self.assertEqual(items[0]["witness"], {"kind": "record", "operand": None,
                                                "twostate": True})

    # --- level_index(): the whole of what the forge knows about a ladder ---

    def test_level_index_reads_position_never_semantics(self):
        self.assertEqual(impl_position.level_index(self.LEVELS, "local"), 0)
        self.assertEqual(impl_position.level_index(self.LEVELS, "cluster"), 2)
        self.assertIsNone(impl_position.level_index(self.LEVELS, "nonexistent"))
        self.assertIsNone(impl_position.level_index(self.LEVELS, None))
        self.assertIsNone(impl_position.level_index([], "local"))

    # --- @record leveled: found-but-short-of-scale is a real middle rung ---

    def test_record_leveled_found_short_of_declared_scale_is_the_middle_rung(self):
        """The exact motivating defect: a record structurally present (a
        notebook reading it would report `sourcesMatch: True`) but short of
        the declared scale must resolve to the middle rung, not the top —
        visible on the item itself, not something a reader has to remember.
        """
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "record", "operand": None, "twostate": False}}]
        evidence = {"search": {"recordFound": True, "scaleSatisfied": False},
                    "requiredScale": {"seeds": 30}, "levels": self.LEVELS,
                    "targetLevel": "cluster"}
        result = impl_position.derive(items, evidence)[0]
        self.assertEqual(result["derived"], "staging")
        self.assertFalse(result["satisfied"])

    def test_record_leveled_found_and_satisfied_is_the_top_rung(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "record", "operand": None, "twostate": False}}]
        evidence = {"search": {"recordFound": True, "scaleSatisfied": True},
                    "requiredScale": {"seeds": 30}, "levels": self.LEVELS,
                    "targetLevel": "cluster"}
        result = impl_position.derive(items, evidence)[0]
        self.assertEqual(result["derived"], "cluster")
        self.assertTrue(result["satisfied"])

    def test_record_leveled_not_found_is_the_floor_rung(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "record", "operand": None, "twostate": False}}]
        evidence = {"search": {"recordFound": False}, "requiredScale": {},
                    "levels": self.LEVELS, "targetLevel": "local"}
        result = impl_position.derive(items, evidence)[0]
        self.assertEqual(result["derived"], "local")
        self.assertTrue(result["satisfied"])

    def test_record_leveled_insufficient_scale_on_a_two_rung_ladder_collapses_to_floor(self):
        """A two-rung ladder has no honest place for "something ran, but not
        enough of it" except the floor -- there is nowhere else to put it.
        """
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "record", "operand": None, "twostate": False}}]
        evidence = {"search": {"recordFound": True, "scaleSatisfied": False},
                    "requiredScale": {"seeds": 30}, "levels": ["local", "cluster"],
                    "targetLevel": "local"}
        result = impl_position.derive(items, evidence)[0]
        self.assertEqual(result["derived"], "local")

    # --- @rehearsal leveled: a two-valued fact can only reach the first rung ---

    def test_rehearsal_leveled_ready_reaches_the_second_rung_never_further(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "rehearsal", "operand": "job", "twostate": False}}]
        result = impl_position.derive(
            items, {"smokeReady": {"job": True}, "levels": self.LEVELS,
                    "targetLevel": "cluster"})[0]
        self.assertEqual(result["derived"], "staging")
        self.assertFalse(result["satisfied"])

    def test_rehearsal_leveled_not_ready_is_the_floor_rung(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "rehearsal", "operand": "job", "twostate": False}}]
        result = impl_position.derive(
            items, {"smokeReady": {"job": False}, "levels": self.LEVELS,
                    "targetLevel": "local"})[0]
        self.assertEqual(result["derived"], "local")

    # --- @shard leveled: arrival is full-scale evidence in its own right ---

    def test_shard_leveled_arrived_is_the_top_rung(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "shard", "operand": "s3", "twostate": False}}]
        result = impl_position.derive(
            items, {"shardsArrived": ["s3"], "levels": self.LEVELS,
                    "targetLevel": "cluster"})[0]
        self.assertEqual(result["derived"], "cluster")
        self.assertTrue(result["satisfied"])

    def test_shard_leveled_not_arrived_is_the_floor_rung(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "shard", "operand": "s1", "twostate": False}}]
        result = impl_position.derive(
            items, {"shardsArrived": ["s3"], "levels": self.LEVELS,
                    "targetLevel": "local"})[0]
        self.assertEqual(result["derived"], "local")

    # --- @notebook leveled: a stale report cannot attribute a rung to anything ---

    def test_notebook_leveled_stale_report_is_unmeasured_not_the_floor(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "notebook", "operand": "a.ipynb", "twostate": False}}]
        evidence = {"notebooks": {"reports": [
                        {"notebook": "a.ipynb", "status": "executed",
                         "sourcesMatch": False}]},
                    "search": {"recordFound": True, "scaleSatisfied": True},
                    "requiredScale": {"seeds": 30}, "levels": self.LEVELS}
        result = impl_position.derive(items, evidence)[0]
        self.assertIsNone(result["derived"])

    def test_notebook_leveled_current_report_reads_the_record_s_own_rung(self):
        items = [{"ordinal": 1, "mark": " ", "text": "x",
                  "witness": {"kind": "notebook", "operand": "a.ipynb", "twostate": False}}]
        evidence = {"notebooks": {"reports": [
                        {"notebook": "a.ipynb", "status": "executed",
                         "sourcesMatch": True}]},
                    "search": {"recordFound": True, "scaleSatisfied": False},
                    "requiredScale": {"seeds": 30}, "levels": self.LEVELS,
                    "targetLevel": "cluster"}
        result = impl_position.derive(items, evidence)[0]
        self.assertEqual(result["derived"], "staging")
        self.assertFalse(result["satisfied"])


class KitScaffoldLevelsDeclarationJoinTests(unittest.TestCase):
    """PR11, a defect found in PR10: the kit ships `__levels__` as an
    *annotated* assignment (`__levels__: list = [...]`, `ast.AnnAssign`), but
    `read_declaration` walked only `ast.Assign`. A target that uses the
    scaffold the skill itself ships therefore declared a ladder the skill
    could not read — the writer (`assets/kit/src_benchmark/__init__.py`) and
    the reader (`read_declaration`, and everything built on it) are in the
    same work unit and were never crossed until this test.

    Not "an annotated assignment parses" in the abstract: this reads the
    exact file the kit ships, unmodified, through the exact reader every
    caller uses.
    """

    KIT_INIT = (FORGE / ".claude/skills/proposal-implementation"
                / "assets/kit/src_benchmark/__init__.py")

    def test_the_shipped_scaffold_s_annotated_levels_literal_is_readable(self):
        """The kit's own `__levels__: list = []` -- an `ast.AnnAssign`, not
        an `ast.Assign` -- must be read as an empty list declared, not as
        nothing declared. Before the fix this fails: `read_declaration`
        returns `None` for a file that plainly declares `__levels__`.
        """
        result = impl.read_declaration(self.KIT_INIT, "__levels__")
        self.assertIsNotNone(
            result, "read_declaration saw no __levels__ in the kit's own "
            "scaffold, which declares one as `__levels__: list = []`")
        self.assertEqual(result, [])

    def test_a_filled_in_annotated_levels_literal_is_readable_end_to_end(self):
        """The realistic case: a target copies the scaffold and fills the
        ladder in, keeping the annotation exactly as shipped. Exercises the
        full join through `resolve_levels_declaration`, the function every
        caller actually uses -- not `read_declaration` in isolation.
        """
        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            bench = root / "src" / "Method_Benchmark"
            bench.mkdir(parents=True)
            source = self.KIT_INIT.read_text(encoding="utf-8").replace(
                "__levels__: list = []",
                '__levels__: list = ["local", "cluster"]')
            self.assertIn('__levels__: list = ["local", "cluster"]', source)
            (bench / "__init__.py").write_text(source, encoding="utf-8")
            levels = impl.resolve_levels_declaration(root, "Method")
        self.assertEqual(levels, ["local", "cluster"])

    def test_an_annotation_with_no_value_declares_nothing_not_a_crash(self):
        """`x: list` alone (no `=`) is a bare annotation -- `ast.AnnAssign.value`
        is `None` -- and must read as nothing declared, never raise inside
        `read_declaration` and never be mistaken for a declared empty list.
        """
        with tempfile.TemporaryDirectory() as raw:
            path = Path(raw) / "__init__.py"
            path.write_text("__levels__: list\n", encoding="utf-8")
            result = impl.read_declaration(path, "__levels__")
        self.assertIsNone(result)

    # --- sweep: every other declaration this reader (or its siblings) is
    # --- asked for, checked against what the kit actually ships ---

    def test_the_shipped_scaffold_s_benchmark_literal_is_also_readable(self):
        """Sweep result: `__benchmark__` goes through the same
        `read_declaration` reader. It is a plain `ast.Assign` in the shipped
        kit, not annotated -- unaffected by the `AnnAssign` hole, confirmed
        directly against the shipped file rather than assumed.
        """
        result = impl.read_declaration(self.KIT_INIT, "__benchmark__")
        self.assertIsNotNone(result)
        self.assertIn("revision", result)

    def test_the_shipped_scaffold_s_dimensions_literal_is_also_unaffected(self):
        """Sweep result: `DIMENSIONS` is read by a separate, bespoke AST walk
        in `declared_dimension_names` (never `read_declaration`), with the
        identical `isinstance(node, ast.Assign)` restriction -- the same hole
        class, in a different function. The kit's own template
        (`assets/kit/nb/benchmark.py`) ships it unannotated, so this reader
        is not exercised by the PR10 defect today; confirmed directly against
        the shipped file rather than assumed, not left as a guess.
        """
        kit_benchmark = (FORGE / ".claude/skills/proposal-implementation"
                          / "assets/kit/nb/benchmark.py")
        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            bench = root / "src" / "Method_Benchmark"
            bench.mkdir(parents=True)
            (bench / "benchmark.py").write_text(
                kit_benchmark.read_text(encoding="utf-8"), encoding="utf-8")
            names = impl.declared_dimension_names(root, "Method")
        self.assertEqual(names, ["accuracy", "seconds", "peakMiB", "parameters"])


class PositionKeyExitStatusTests(unittest.TestCase):
    """The `position` key is reported and never gates — the same discipline
    `coupling` (`CouplingNeverGatesTests`) and `smokeReady`
    (`ProbeReportedFactsRosterTests`) already carry. `position_state` is
    exercised directly across all four statuses; one end-to-end `verify`/
    `probe` run proves the key's mere presence never changes the process's
    own exit status, mirroring `CouplingNeverGatesTests._run` exactly.
    """

    HEADER = {
        "revision": "r01.md", "revisionSha256": "a" * 64,
        "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final",
    }

    def write_position(self, root, mark, sha256=None):
        (root / "Method").mkdir(parents=True, exist_ok=True)
        items = [{"ordinal": 1, "mark": mark, "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        header = {**self.HEADER, "revisionSha256": sha256 or self.HEADER["revisionSha256"]}
        (root / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

    def test_position_state_reports_all_four_statuses_without_raising(self):
        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            (root / "Method").mkdir(parents=True)
            absent = impl.position_state(root, "Method", {}, None, None)
            self.assertEqual(absent["status"], "absent")

        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            self.write_position(root, " ")
            open_state = impl.position_state(root, "Method", {}, None, None)
            self.assertEqual(open_state["status"], "open")

        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            self.write_position(root, "x")
            evidence = {"smokeReady": {"job1": True}}
            complete = impl.position_state(root, "Method", evidence, None, None)
            self.assertEqual(complete["status"], "complete")

        with tempfile.TemporaryDirectory() as raw:
            root = Path(raw)
            self.write_position(root, "x", sha256="b" * 64)
            evidence = {"smokeReady": {"job1": True}}
            stale = impl.position_state(root, "Method", evidence, "r01.md", "some content")
            self.assertEqual(stale["status"], "stale")

    def test_position_key_never_changes_exit_status(self):
        box = FORGE / "implementations" / f"_e2e_position_{os.getpid()}"
        try:
            (box / "src" / "Method").mkdir(parents=True)
            (box / "src" / "Method_Benchmark").mkdir(parents=True)
            (box / "tests").mkdir(parents=True)
            subprocess.run(["git", "init", "-q", str(box)], check=True,
                           capture_output=True)
            (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
            (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
                _COUPLING_DECLARATION, encoding="utf-8")
            self.write_position(box, " ")
            verify = subprocess.run(
                [sys.executable, str(CLI), "verify", "--target", str(box),
                 "--name", "Method"],
                capture_output=True, text=True, cwd=FORGE)
            probe = subprocess.run(
                [sys.executable, str(CLI), "probe", "--target", str(box),
                 "--name", "Method"],
                capture_output=True, text=True, cwd=FORGE)
        finally:
            shutil.rmtree(box, ignore_errors=True)
        self.assertEqual(verify.returncode, 0, verify.stderr)
        self.assertEqual(probe.returncode, 0, probe.stderr)
        verify_json = json.loads(verify.stdout or "{}")
        probe_json = json.loads(probe.stdout or "{}")
        self.assertIn("position", verify_json)
        self.assertIn("position", probe_json)
        self.assertEqual(verify_json["position"]["status"], "open")
        self.assertEqual(probe_json["position"]["status"], "open")


class PositionCommandTests(unittest.TestCase):
    """`position` — the only writer into `<Name>/AGREED.md`'s section.

    No flag: REFRESH — re-derive the marks of whatever block is already
    there, and touch nothing else about it. `--sequence -`: INSTALL — a
    fresh sequence from stdin JSON becomes the block, refused as
    `POSITION_BLOCK_EXISTS` unless `--replace` says otherwise (design §3.3).

    Every test supplies a real `--revision`, resolved against a throwaway
    `proposals/` root: the header this command writes is bound to a
    revision's own content hash (`impl_position.locate_block`'s
    `sha256=` field), so there is no code path here that skips resolving
    one, and a test that omitted it would exercise `REVISION_UNREADABLE`
    rather than the refusal it names.
    """

    #: Fixed so a test that needs the header's `sha256=` to actually MATCH
    #: this revision (the `unchanged`/byte-preservation tests) can compute
    #: it once, the same way `cmd_position` itself will.
    PROPOSAL_TEXT = "## 1\ntexto\n"
    PROPOSAL_SHA256 = hashlib.sha256(PROPOSAL_TEXT.encode("utf-8")).hexdigest()

    def _proposals(self, text=None):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / "r1.md").write_text(
            self.PROPOSAL_TEXT if text is None else text, encoding="utf-8")
        return root

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_position_cmd_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        return box

    def run_cli(self, *args, stdin=None, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def block_text(self, body, sha256=None, target="final"):
        return (f"<!-- position revision=r1.md sha256={sha256 or 'a' * 64} "
                f"derivedAt=2026-08-27T00:00:00Z session=s0 target={target} -->\n"
                f"{body}<!-- /position -->\n")

    # --- 3.1 refusals: a malformed artifact exits 2 with a code ---

    def test_refuses_when_the_existing_block_has_an_item_without_a_witness(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self.block_text("- [ ] 1. No witness token at all.\n"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_ITEM_WITHOUT_WITNESS")

    def test_refuses_when_the_existing_block_names_an_unknown_witness_kind(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self.block_text("- [ ] 1. Something. `@wat`\n"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_WITNESS_UNKNOWN_KIND")

    def test_refuses_installing_when_no_markdown_file_holds_anything_to_append_into(self):
        box = self._box()
        sequence = json.dumps([{"text": "Rehearse the job.",
                                "witness": {"kind": "rehearsal", "operand": "job1"}}])
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--sequence", "-", stdin=sequence, proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_HOLDER_ABSENT")

    def test_refuses_when_two_files_already_carry_a_position_block(self):
        box = self._box()
        block = self.block_text("- [ ] 1. Step. `@rehearsal job1`\n")
        (box / "Method" / "AGREED.md").write_text(block, encoding="utf-8")
        (box / "Method" / "SECOND.md").write_text(block, encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_HOLDER_AMBIGUOUS")

    # --- compare-and-swap: the holder moving under a write (design decision 2) ---

    def test_refuses_when_the_holder_moves_between_location_and_write(self):
        """Mutation B (design decision 2, "stale offsets"): the holder file
        changes AFTER the read that located `existing_block`'s own offsets
        but BEFORE the write reaches it. Proxied by patching
        `impl_position.render` -- the last hook `cmd_position` calls before
        `write_spliced`'s own re-check -- to write concurrently as a side
        effect, then delegate to the real `render`. In-process (not
        `run_cli`'s subprocess) so the patch reaches the exact module
        object `cmd_position` itself imports.

        Distinct from `WriteSplicedCasTests` in `test_implementation_core.py`
        (which drives `write_spliced` directly with a hand-built mismatched
        digest): this proves the WIRING -- that `cmd_position` really does
        carry the location read's own digest all the way to the write call,
        never a digest of the second, later read `before_bytes` itself is.
        """
        box = self._box()
        holder = box / "Method" / "AGREED.md"
        holder.write_text(
            self.block_text("- [ ] 1. Something. `@record`\n",
                            sha256=self.PROPOSAL_SHA256, target="final"),
            encoding="utf-8")
        concurrent_bytes = b"# Rewritten by something else entirely\n"
        original_render = impl_position.render

        def _rewrite_holder_then_render(header, items):
            holder.write_bytes(concurrent_bytes)
            return original_render(header, items)

        proposals = self._proposals()
        (proposals / "r2.md").write_text("## 2\notro texto\n", encoding="utf-8")
        os.environ["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        self.addCleanup(os.environ.pop, "IMPLEMENTATION_PROPOSALS", None)

        args = argparse.Namespace(
            target=str(box), name="Method", sequence=None, reconcile=False,
            # A different revision than the block's own recorded one, so
            # this call is never `unchanged` and the write path -- and this
            # seam -- is actually reached.
            revision="r2.md", session="s1", replace=False)

        with unittest.mock.patch.object(impl_position, "render",
                                        side_effect=_rewrite_holder_then_render):
            with self.assertRaises(impl.Refused) as ctx:
                impl.cmd_position(args)
        self.assertEqual(ctx.exception.code, "POSITION_HOLDER_MOVED")
        # The offsets `existing_block` located are never applied to
        # `concurrent_bytes` -- the file holds exactly what the concurrent
        # write put there, untouched by the refused splice.
        self.assertEqual(holder.read_bytes(), concurrent_bytes)

    # --- migration: a pre-PR10 block is refused for reading, migratable for writing ---

    def test_a_legacy_block_refuses_verify_but_position_migrates_it(self):
        box = self._box()
        legacy = (
            "<!-- position revision=r1.md sha256=" + "a" * 64 +
            " derivedAt=2026-01-01T00:00:00Z session=s0 -->\n"
            "- [ ] 1. Old-grammar step. `@rehearsal job1`\n"
            "<!-- /position -->\n"
        )
        (box / "Method" / "AGREED.md").write_text(legacy, encoding="utf-8")

        verify_proc = self.run_cli("verify", "--target", str(box), "--name", "Method",
                                   "--revision", "r1.md", proposals=self._proposals())
        self.assertEqual(verify_proc.returncode, 2, verify_proc.stdout)
        self.assertEqual(json.loads(verify_proc.stdout)["code"], "POSITION_BLOCK_MALFORMED")

        migrate = self.run_cli("position", "--target", str(box), "--name", "Method",
                               "--revision", "r1.md", "--session", "s1",
                               "--target-level", "final",
                               proposals=self._proposals())
        self.assertEqual(migrate.returncode, 0, migrate.stdout)
        result = json.loads(migrate.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["targetLevel"], "final")
        self.assertEqual([item["text"] for item in result["sequence"]],
                         ["Old-grammar step."])

        on_disk = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("target=final", on_disk)

        verify_again = self.run_cli("verify", "--target", str(box), "--name", "Method",
                                    "--revision", "r1.md", proposals=self._proposals())
        self.assertEqual(verify_again.returncode, 0, verify_again.stdout)
        self.assertEqual(
            json.loads(verify_again.stdout)["position"]["targetLevel"], "final")

    # --- 3.2 refresh: item text and order survive byte-for-byte ---

    def test_refresh_leaves_item_text_and_order_untouched(self):
        box = self._box()
        payload = "The identity is $$E=mc^2$$ and \\tag{39} names it."
        body = (f"- [ ] 1. {payload} `@notebook Notebooks/nope.ipynb`\n"
                "- [ ] 2. Second step. `@rehearsal job-none`\n")
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, sha256=self.PROPOSAL_SHA256), encoding="utf-8")
        before = (box / "Method" / "AGREED.md").read_bytes()

        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())

        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "unchanged")
        self.assertEqual([item["ordinal"] for item in result["sequence"]], [1, 2])
        self.assertEqual(result["sequence"][0]["text"], payload)
        self.assertEqual(result["sequence"][1]["text"], "Second step.")
        # Neither witness is measurable in this box (no such notebook, no
        # such job), so nothing could have flipped a mark -- and a refresh
        # that found nothing to flip never rewrites the file at all.
        after = (box / "Method" / "AGREED.md").read_bytes()
        self.assertEqual(before, after)

    # --- 3.3 install: writes the section and derives its marks immediately ---

    def test_install_writes_a_fresh_sequence_and_derives_marks_immediately(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n- [x] 1. Something already settled.\n", encoding="utf-8")
        sequence = json.dumps([
            {"text": "Undercut search.", "witness": {"kind": "record"}},
            {"text": "Rehearse the job.",
             "witness": {"kind": "rehearsal", "operand": "job1"}},
        ])
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "final",
                            "--sequence", "-", stdin=sequence, proposals=self._proposals())

        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["holder"], "Method/AGREED.md")
        self.assertEqual([item["witness"]["kind"] for item in result["sequence"]],
                         ["record", "rehearsal"])
        # Neither witness is measurable in this box (no search declared, no
        # job ever rehearsed), so install DERIVES rather than assuming every
        # fresh item starts ticked.
        self.assertEqual(result["unmeasured"], [1, 2])
        on_disk = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("Something already settled.", on_disk)
        self.assertIn("<!-- position", on_disk)

    def test_refuses_installing_over_an_existing_block_without_replace(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self.block_text("- [ ] 1. Old step. `@rehearsal job1`\n"), encoding="utf-8")
        sequence = json.dumps([{"text": "New step.",
                                "witness": {"kind": "rehearsal", "operand": "job2"}}])
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--sequence", "-", stdin=sequence, proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_BLOCK_EXISTS")

    def test_replace_overwrites_the_existing_block(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self.block_text("- [ ] 1. Old step. `@rehearsal job1`\n"), encoding="utf-8")
        sequence = json.dumps([{"text": "New step.",
                                "witness": {"kind": "rehearsal", "operand": "job2"}}])
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--sequence", "-", "--replace", stdin=sequence,
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual([item["text"] for item in result["sequence"]], ["New step."])
        on_disk = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertNotIn("Old step.", on_disk)
        self.assertIn("New step.", on_disk)

    # --- 3.4 the ledger: appended on a real write, never on a no-op ---

    def test_refresh_flips_a_measurable_mark_and_appends_one_ledger_event(self):
        box = self._box()
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            "__benchmark__ = {'search': {'record': 'Results/record.json'}}\n",
            encoding="utf-8")
        (box / "Method" / "Results").mkdir(parents=True)
        (box / "Method" / "Results" / "record.json").write_text("{}", encoding="utf-8")
        (box / "Method" / "AGREED.md").write_text(
            self.block_text("- [ ] 1. Undercut search. `@record`\n"), encoding="utf-8")

        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())

        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["wrote"], [1])
        on_disk = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("- [x] 1. Undercut search.", on_disk)
        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        self.assertEqual(len(events), 1)
        self.assertEqual(events[0]["kind"], "position")

    def test_refresh_reports_unchanged_and_appends_no_event_when_nothing_moves(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self.block_text("- [ ] 1. Step. `@rehearsal job-none`\n",
                            sha256=self.PROPOSAL_SHA256), encoding="utf-8")

        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())

        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "unchanged")
        self.assertFalse((box / "Method" / ".implementation" / "position.jsonl").exists())


class StepOperandRefusalTests(unittest.TestCase):
    """`POSITION_STEP_UNKNOWN` -- spec "Unknown Step Operand Is A
    Classified, Roster-Visible Refusal"; design "The new refusal is a work
    state, raised in `cmd_position`", a measured correction to the
    proposal's `INVOCATION_DEFECT`: `--step <name>` is invocation because
    a caller typed it; no argument `position` accepts names a position
    ITEM's operand -- it lives in AGREED.md, so clearing this means editing
    the document or declaring the step.

    `parse_items` (`impl_position.py`) validates only the witness KIND --
    that `"step"` is a member of `WITNESS_KINDS` -- never the operand
    string, so an `@step nosuch` item reaches `cmd_position` unblocked
    without this check and would otherwise silently derive `unmeasured`
    forever.
    """

    PROPOSAL_TEXT = PositionCommandTests.PROPOSAL_TEXT
    PROPOSAL_SHA256 = PositionCommandTests.PROPOSAL_SHA256

    def _proposals(self):
        return PositionCommandTests._proposals(self)

    def _box(self, declare_steps=None):
        box = FORGE / "implementations" / f"_e2e_step_operand_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            f"__steps__ = {declare_steps!r}\n" if declare_steps is not None else "",
            encoding="utf-8")
        return box

    def run_cli(self, *args, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def block_text(self, body, sha256=None, target="final"):
        return (f"<!-- position revision=r1.md sha256={sha256 or 'a' * 64} "
                f"derivedAt=2026-08-27T00:00:00Z session=s0 target={target} -->\n"
                f"{body}<!-- /position -->\n")

    def test_an_undeclared_step_operand_refuses_position_step_unknown(self):
        """Two `@step` items, the FIRST one valid and the SECOND one not --
        so a check that only inspects the first `@step` item in the
        sequence (a plausible off-by-scope bug) would silently miss the
        second one and this test would catch it."""
        box = self._box(declare_steps={"run_suite": {"module": "Method_Benchmark.steps",
                                                     "function": "run_ok"}})
        body = ("- [ ] 1. Run the suite. `@step run_suite`\n"
                "- [ ] 2. Run something else. `@step nosuch`\n")
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, sha256=self.PROPOSAL_SHA256), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "POSITION_STEP_UNKNOWN")
        self.assertIn("nosuch", result["detail"])
        self.assertIn("run_suite", result["detail"])
        # Classified and published: a WORK_STATE code carries a runnable
        # resolution, never a bare code with nothing attached (the roster's
        # own reason for existing).
        self.assertEqual(result["resolve"]["kind"], "question")
        self.assertTrue(result["resolve"]["command"].strip())

    def test_steps_completely_undeclared_reuses_steps_undeclared_verbatim(self):
        """The second arm: no new code. A target with no `__steps__` at
        all is the identical fact `cmd_step` itself already raises
        `STEPS_UNDECLARED` for -- reused here verbatim, not reclassified."""
        box = self._box(declare_steps=None)
        body = "- [ ] 1. Run the suite. `@step run_suite`\n"
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, sha256=self.PROPOSAL_SHA256), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "STEPS_UNDECLARED")
        self.assertIn("declares no __steps__ at all", result["detail"])

    def test_a_declared_step_operand_is_not_refused(self):
        box = self._box(declare_steps={"run_suite": {"module": "Method_Benchmark.steps",
                                                     "function": "run_ok"}})
        body = "- [ ] 1. Run the suite. `@step run_suite`\n"
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, sha256=self.PROPOSAL_SHA256), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "unchanged")


class PositionRecordMalformedTests(unittest.TestCase):
    """`__steps__` has a shape refusal; `__records__` had none.

    `cmd_step` raises `STEP_MALFORMED` the moment an entry lacks `module` or
    `function`. `POSITION_RECORD_UNKNOWN` checks only membership in the raw
    dict, so a declared entry of any shape at all passes it. Measured:

    - `{"main": {"file": ..., "requiredScale": ...}}` (a typo'd `path`):
      `POSITION_RECORD_UNKNOWN` passes, `named_records_state` keeps the entry
      with `recordFound: None`, and the item derives no rung ever.
    - `{"main": "Results/r.json"}` (not a mapping at all):
      `POSITION_RECORD_UNKNOWN` passes because `main` IS a key, and
      `named_records_state` drops the entry entirely -- so the refusal says
      `main` is declared and the reader says it does not exist, and the two
      never meet.

    Either way a ticked witness becomes `POSITION_UNBACKED` and a leveled one
    sinks `attained_level` forever, with nothing naming the declaration as the
    cause. `STEP_MALFORMED`'s own answer, one literal over.

    **Which input reaches it, given every check that already runs first.** The
    refusal sits immediately after `POSITION_RECORD_UNKNOWN` and therefore
    still ahead of `_skipped_rung_detail` -- the same trap-1 placement D5
    established, and for the same reason: a malformed entry derives `None`
    too, which sinks `attained_level`, so a check placed after the rung guard
    would be unreachable for any `--target-level` above the floor. It is
    reached by a leveled `@record:level <name>` witness whose name IS a key of
    `__records__` (or `POSITION_RECORD_UNKNOWN` would have fired) and whose
    entry `named_records_state` cannot read.
    """

    PROPOSAL_TEXT = PositionCommandTests.PROPOSAL_TEXT
    PROPOSAL_SHA256 = PositionCommandTests.PROPOSAL_SHA256
    LADDER = ["floor", "middle", "top"]

    def _proposals(self):
        return PositionCommandTests._proposals(self)

    def _box(self, records):
        box = FORGE / "implementations" / f"_e2e_record_shape_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        for directory in ("src/Method", "src/Method_Benchmark", "tests", "Method"):
            (box / directory).mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        (box / "src/Method_Benchmark/__init__.py").write_text(
            f"__levels__ = {self.LADDER!r}\n__records__ = {records!r}\n",
            encoding="utf-8")
        (box / "Method/AGREED.md").write_text(
            f"<!-- position revision=r1.md sha256={self.PROPOSAL_SHA256} "
            "derivedAt=2026-08-27T00:00:00Z session=s0 target=floor -->\n"
            "- [ ] 1. Reach the record. `@record:level main`\n"
            "<!-- /position -->\n", encoding="utf-8")
        return box

    def _position(self, records, target_level="floor"):
        box = self._box(records)
        env = dict(os.environ)
        env["IMPLEMENTATION_PROPOSALS"] = str(self._proposals())
        proc = subprocess.run(
            [sys.executable, str(CLI), "position", "--target", str(box),
             "--name", "Method", "--revision", "r1.md", "--session", "s1",
             "--target-level", target_level],
            capture_output=True, text=True, cwd=FORGE, env=env)
        return proc

    GOOD = {"main": {"path": "Results/r.json", "requiredScale": {}}}
    TYPO = {"main": {"file": "Results/r.json", "requiredScale": {}}}
    NOT_A_MAPPING = {"main": "Results/r.json"}

    def test_an_entry_that_is_not_a_mapping_refuses(self):
        """The sharp one. `named_records_state` skips a non-dict entry
        entirely, so `evidence["records"]` has no `main` at all while
        `POSITION_RECORD_UNKNOWN` says `main` is declared -- the refusal and
        the reader disagreeing about the same name, with nothing crossing
        them."""
        proc = self._position(self.NOT_A_MAPPING)
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "POSITION_RECORD_MALFORMED")
        self.assertIn("main", result["detail"])

    def test_an_entry_with_no_usable_path_refuses(self):
        """The quiet one. A dict entry survives every existing check, keeps
        its place in `evidence["records"]`, and derives `recordFound: None`
        forever -- so a ticked witness reads `POSITION_UNBACKED` and a leveled
        one sinks `attainedLevel`, neither of them naming the typo."""
        proc = self._position(self.TYPO)
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "POSITION_RECORD_MALFORMED")
        self.assertIn("path", result["detail"])

    def test_a_well_formed_entry_is_never_refused(self):
        """The other pole, and the one a weaker lock survives: a refusal that
        fired on every declared record would close the door this declaration
        exists to open."""
        proc = self._position(self.GOOD)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)

    def test_it_refuses_above_the_floor_too(self):
        """The trap-1 ordering claim, measured the way
        `PositionRecordUnknownTests` measures its own: a malformed entry
        derives `None` and sinks `attained_level`, so a check placed after
        `_skipped_rung_detail` would answer `POSITION_RUNG_SKIPPED` here and
        never be reachable above the floor at all."""
        proc = self._position(self.NOT_A_MAPPING, target_level="middle")
        self.assertEqual(proc.returncode, 2, proc.stdout + proc.stderr)
        self.assertEqual(json.loads(proc.stdout)["code"],
                         "POSITION_RECORD_MALFORMED")

    def test_a_name_no_witness_addresses_is_not_this_command_s_business(self):
        """The narrowing `STEP_MALFORMED` already keeps: it refuses the step
        it was asked to run, never every entry of `__steps__`. A repository
        may legitimately carry a half-written entry it has not wired a witness
        to yet, and refusing every position write until every entry is perfect
        would be the forge deciding when a declaration is finished."""
        box = self._box({"main": {"path": "Results/r.json", "requiredScale": {}},
                         "spare": "not-a-mapping"})
        env = dict(os.environ)
        env["IMPLEMENTATION_PROPOSALS"] = str(self._proposals())
        proc = subprocess.run(
            [sys.executable, str(CLI), "position", "--target", str(box),
             "--name", "Method", "--revision", "r1.md", "--session", "s1",
             "--target-level", "floor"],
            capture_output=True, text=True, cwd=FORGE, env=env)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)

    def test_the_code_is_classified_and_publishes_something_runnable(self):
        """`GatingRefusalRosterTests`' own rule, asserted here too so the
        classification travels with the refusal rather than being noticed by
        a roster count moving."""
        self.assertEqual(impl.GATING_REFUSALS["POSITION_RECORD_MALFORMED"],
                         impl.WORK_STATE)
        resolution = impl.refusal_resolution(
            "POSITION_RECORD_MALFORMED",
            argparse.Namespace(command="position", target="implementations/box",
                               name="Method", session="s1", revision="r1.md",
                               about=None, text=None))
        self.assertEqual(resolution["kind"], "question")
        self.assertIn("__records__", resolution["question"])


class PositionRecordUnknownTests(unittest.TestCase):
    """`POSITION_RECORD_UNKNOWN` -- design D5/D6; spec "`@record:level
    <name>` grammar" is unaffected, this is the operand-validity refusal
    that mirrors `POSITION_STEP_UNKNOWN`'s own shape and reasoning.

    **Trap 1, the whole reason this class carries an above-the-floor
    fixture rather than only a floor one.** `_record_operand_detail`'s
    raise sits BEFORE `_skipped_rung_detail` is ever called (design D5): an
    unknown record name derives `None`
    (`impl_position._derive_record_level`), which sinks `attained_level`
    -- so a check placed AFTER `_skipped_rung_detail` instead (mirroring
    `@step`'s own position) would let `POSITION_RUNG_SKIPPED` fire first
    for any `--target-level` above the floor, and `POSITION_RECORD_UNKNOWN`
    would become unreachable there. A fixture sealing at the floor
    (`levels[0]`) cannot tell the two placements apart -- `_skipped_rung_
    detail` never intervenes at the floor regardless of order -- so
    `test_an_unknown_record_above_the_floor_refuses_position_record_unknown`
    is the one that actually proves the ordering claim; the floor-only
    sibling beside it is the weaker lock the brief names, kept here so the
    contrast is measured rather than merely asserted.
    """

    PROPOSAL_TEXT = PositionCommandTests.PROPOSAL_TEXT
    PROPOSAL_SHA256 = PositionCommandTests.PROPOSAL_SHA256
    LADDER = ["floor", "middle", "top"]

    def _proposals(self):
        return PositionCommandTests._proposals(self)

    def _box(self, declare_records=None, ladder=LADDER):
        box = FORGE / "implementations" / f"_e2e_record_operand_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        declaration = f"__levels__ = {ladder!r}\n" if ladder is not None else ""
        if declare_records is not None:
            declaration += f"__records__ = {declare_records!r}\n"
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            declaration, encoding="utf-8")
        return box

    def run_cli(self, *args, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def block_text(self, body, target, sha256=None):
        return (f"<!-- position revision=r1.md sha256={sha256 or 'a' * 64} "
                f"derivedAt=2026-08-27T00:00:00Z session=s0 target={target} -->\n"
                f"{body}<!-- /position -->\n")

    def test_an_unknown_record_above_the_floor_refuses_position_record_unknown(self):
        """**The strong lock (trap 1).** A fixture already satisfied at the
        floor (`item 1`, an unrelated bare rehearsal witness that is
        two-state and always satisfied) and a target-level of `middle`
        (above the floor): with the placement this task requires, this
        refuses `POSITION_RECORD_UNKNOWN`, never `POSITION_RUNG_SKIPPED` --
        proving the check runs BEFORE `_skipped_rung_detail`."""
        box = self._box(declare_records={"main": {"path": "r.json",
                                                    "requiredScale": {}}})
        body = "- [ ] 1. Reach the record. `@record:level nosuch`\n"
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, "floor", sha256=self.PROPOSAL_SHA256),
            encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "middle",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "POSITION_RECORD_UNKNOWN")
        self.assertIn("nosuch", result["detail"])
        self.assertIn("main", result["detail"])

    def test_an_unknown_record_at_the_floor_also_refuses(self):
        """**The weaker lock.** At the floor, `_skipped_rung_detail` never
        intervenes regardless of placement, so this fixture alone cannot
        distinguish a correct placement from the trap; it only proves the
        code exists and fires somewhere reachable."""
        box = self._box(declare_records={"main": {"path": "r.json",
                                                    "requiredScale": {}}})
        body = "- [ ] 1. Reach the record. `@record:level nosuch`\n"
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, "floor", sha256=self.PROPOSAL_SHA256),
            encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "floor",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_RECORD_UNKNOWN")

    def test_records_declaring_nothing_at_all_is_the_same_code_a_different_detail(self):
        """Design D6: one code covers both facts. No `__records__` entries
        at all -- the detail says so, distinctly from the "declares others"
        case above."""
        box = self._box(declare_records={})
        body = "- [ ] 1. Reach the record. `@record:level main`\n"
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, "floor", sha256=self.PROPOSAL_SHA256),
            encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "floor",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "POSITION_RECORD_UNKNOWN")
        self.assertIn("declares none at all", result["detail"])

    def test_a_declared_record_operand_is_not_refused(self):
        box = self._box(declare_records={"main": {"path": "r.json",
                                                    "requiredScale": {}}})
        body = "- [ ] 1. Reach the record. `@record:level main`\n"
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, "floor", sha256=self.PROPOSAL_SHA256),
            encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "floor",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)

    def test_a_bare_operand_less_leveled_record_is_never_checked_here(self):
        """A leveled `@record:level` with no operand at all -- the grammar
        that predates `__records__` entirely -- is unaffected: it derives
        against the `search` block, and `_record_operand_detail` has
        nothing to say about it (there is no name to look up)."""
        box = self._box(declare_records={})
        body = "- [ ] 1. Reach the record. `@record:level`\n"
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, "floor", sha256=self.PROPOSAL_SHA256),
            encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "floor",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)

    def test_the_roster_classifies_it_as_a_work_state_with_a_runnable_resolution(self):
        box = self._box(declare_records={"main": {"path": "r.json",
                                                    "requiredScale": {}}})
        body = "- [ ] 1. Reach the record. `@record:level nosuch`\n"
        (box / "Method" / "AGREED.md").write_text(
            self.block_text(body, "floor", sha256=self.PROPOSAL_SHA256),
            encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "floor",
                            proposals=self._proposals())
        result = json.loads(proc.stdout)
        self.assertEqual(result["resolve"]["kind"], "question")
        self.assertTrue(result["resolve"]["command"].strip())


class PositionRungLadderTests(unittest.TestCase):
    """A position may never skip a rung going forward.

    `__levels__` names an ordered ladder and `--target-level` names the rung a
    pass aims at. Three checks already guarded that flag -- a rung must be
    named, it must be one the target declared, and a leveled witness needs a
    ladder to exist -- and not one of them asks whether the rung *below* the
    named one was ever reached. `--target-level <third rung>` was accepted on a
    repository whose evidence had not left the floor.

    **Derived from state, never from history.** The rule could have been
    written against the position ledger -- "was there a prior pass at the rung
    below" -- and it is deliberately not: a target that has never run this
    command has no ledger at all, so a history check would pass vacuously on
    exactly the repositories it exists to stop. The predicate asks the evidence
    instead: *to seal at rung N, every leveled item in the sequence must
    already grade as satisfied at rung N-1*, graded by `impl_position.derive`
    itself at that previous rung rather than by a second, parallel arithmetic.

    The ladder names below (`floor`/`middle`/`top`) are this test's own
    invention. The forge holds no rung vocabulary -- it knows only the ordered
    list a target declared -- so a fixture that borrowed a real target's rung
    names would be teaching the suite a word the engine must never learn.
    """

    PROPOSAL_TEXT = PositionCommandTests.PROPOSAL_TEXT
    PROPOSAL_SHA256 = PositionCommandTests.PROPOSAL_SHA256
    LADDER = ["floor", "middle", "top"]

    def _proposals(self):
        return PositionCommandTests._proposals(self)

    def _box(self, ladder=LADDER):
        box = FORGE / "implementations" / f"_e2e_position_rung_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            "" if ladder is None else f"__levels__ = {ladder!r}\n", encoding="utf-8")
        return box

    def _shards(self, box):
        """An empty directory of returned shards -- present, so `shardsArrived`
        is `[]` (a definite "asked, and nothing came back") rather than `None`
        ("nobody asked"). That is what puts a `@shard:level` witness on the
        floor rung instead of leaving it unmeasured, and the two cases below
        need to be told apart by exactly that difference."""
        root = box / "shards"
        root.mkdir(parents=True, exist_ok=True)
        return str(root)

    def run_cli(self, *args, stdin=None, proposals=None):
        return PositionCommandTests.run_cli(self, *args, stdin=stdin,
                                            proposals=proposals)

    def _block(self, body, target, sha256=None):
        return (f"<!-- position revision=r1.md sha256={sha256 or 'a' * 64} "
                f"derivedAt=2026-08-27T00:00:00Z session=s0 target={target} -->\n"
                f"{body}<!-- /position -->\n")

    LEVELED = "- [ ] 1. Distribute the campaign. `@shard:level s1`\n"

    # --- the rule itself -----------------------------------------------------

    def test_a_pass_that_skips_a_rung_is_refused(self):
        """The headline. The block sits at the floor, the evidence reaches the
        floor, and the caller asks for the top -- the rung between them was
        never attained, so the seal is refused rather than recorded."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "floor"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "top", "--shards", self._shards(box),
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["code"], "POSITION_RUNG_SKIPPED")
        # The refusal names the rung that was skipped, not just the one asked
        # for: a reader who is told only "top is refused" still does not know
        # what to do next.
        self.assertIn("middle", payload["detail"])
        # And nothing was written: the header on disk still records the floor.
        self.assertIn("target=floor",
                      (box / "Method" / "AGREED.md").read_text(encoding="utf-8"))

    def test_a_legitimate_one_rung_advance_is_still_allowed(self):
        """The other pole, and the one that keeps the guard from being a wall.
        Identical repository, identical evidence -- only the rung asked for
        differs, and the one directly above the attained rung goes through."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "floor"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "middle", "--shards", self._shards(box),
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["targetLevel"], "middle")

    def test_one_rung_forward_is_refused_when_the_rung_below_is_unmeasured(self):
        """State, not ordinals. A guard that only counted positions on the
        ladder would wave this through -- it is a single step. The rung below
        is not *attained*, though: without a shards directory nothing measured
        the one leveled witness at all, and 'we did not look' is not 'it has
        been reached'. This is the case that separates the predicate this
        change builds from the cheaper one it is not."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "floor"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "middle",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_RUNG_SKIPPED")

    def test_a_fresh_header_may_seal_above_the_floor_when_the_evidence_is_there(self):
        """History, not consulted. Nothing has ever been sealed here -- no
        block, no ledger, nothing to read a prior pass out of -- and the second
        rung is still reachable, because the evidence on disk currently grades
        the sequence as satisfied at the first. A rule written against the
        ledger would refuse this repository forever."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n- [x] 1. Something already settled.\n", encoding="utf-8")
        sequence = json.dumps([
            {"text": "Distribute the campaign.",
             "witness": {"kind": "shard", "operand": "s1", "twostate": False}}])
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "middle", "--shards", self._shards(box),
                            "--sequence", "-", stdin=sequence,
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["targetLevel"], "middle")

    # --- the five boundaries the rule is defined against ---------------------

    def test_the_first_rung_needs_no_predecessor_on_an_empty_repository(self):
        """Index zero has nothing below it, and a repository where nothing has
        run yet must still be able to start. No shards directory, so the one
        leveled witness measures to nothing at all -- and the floor is still
        sealable, because the check never runs there."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n- [x] 1. Something already settled.\n", encoding="utf-8")
        sequence = json.dumps([
            {"text": "Distribute the campaign.",
             "witness": {"kind": "shard", "operand": "s1", "twostate": False}}])
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "floor",
                            "--sequence", "-", stdin=sequence,
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["targetLevel"], "floor")

    def test_a_recorded_rung_the_evidence_no_longer_attains_is_no_exemption(self):
        """The headline of this change, and the reversal of an earlier one.

        `target=` in the header states what a pass AIMS at, and an aim is
        legitimately one rung above what is attained -- that is how a fresh
        header at a higher rung is possible at all. The exemption here used to
        read that same field as what had already been REACHED and use it as a
        floor, so a rung that outlived its evidence did not merely go stale: it
        switched the guard off for itself, permanently, and a switched-off
        guard is indistinguishable from a green one.

        The block records the middle rung and the shards it was sealed against
        are gone, so nothing on this ladder is attained. A bare refresh is
        still a seal at `middle`, and it still asserts that the floor is
        reached. It is not, so it is refused -- by name, item by item.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "middle", sha256=self.PROPOSAL_SHA256),
            encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["code"], "POSITION_RUNG_SKIPPED")
        # The regression is reported, not hidden: the detail names the rung
        # that is short and the item that leaves it short.
        self.assertIn("floor", payload["detail"])
        self.assertIn("item 1", payload["detail"])
        # And nothing was written: the header on disk is untouched.
        self.assertIn("target=middle",
                      (box / "Method" / "AGREED.md").read_text(encoding="utf-8"))

    def test_moving_down_is_refused_when_the_lower_rung_is_not_attained_either(self):
        """A retreat is exempt from the FORWARD rule and is still a seal.

        Landing on the middle rung asserts that the floor is reached, exactly
        as arriving there from below would -- where the pass came from changes
        nothing about what the seal claims. The floor is not reached here, so
        the retreat is refused too, and the operator is pointed at the one rung
        that is honest (`..._never_cornered`, below, proves it exists).
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "top"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "middle",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_RUNG_SKIPPED")

    def test_retreating_all_the_way_to_the_floor_is_allowed_too(self):
        """The other retreat, kept because it is the one an operator actually
        types after a remote rung failed: back to the bottom of the ladder,
        with nothing measurable anywhere."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "top"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "floor",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["targetLevel"], "floor")

    def test_an_operator_whose_evidence_collapsed_is_never_cornered(self):
        """Decision 2 of `a position never skips a rung going forward`, kept
        alive under a rule that no longer reads the header: **`position` is the
        instrument that measures, and an instrument that refuses to take a
        reading because the reading is bad hides the regression it exists to
        report.** What changed is the mechanism, not the guarantee. The old
        exemption bought "never cornered" by letting the recorded rung re-seal
        itself forever, which is what switched the guard off; the guarantee is
        now carried by the floor, which has no predecessor and so is exempt on
        its own terms.

        Proven by exhaustion rather than asserted in a comment: the evidence
        attains nothing, every rung on the declared ladder is tried, and the
        set that goes through is neither empty (the operator always has a move)
        nor larger than the floor (the guard is not off). Every refusal names
        the same one legal move.
        """
        box = self._box()
        allowed, refused = [], {}
        for rung in self.LADDER:
            # Rewritten each time rather than a fresh repository each time:
            # the block on disk is the whole of the input, and the ledger this
            # leaves behind is deliberately not, since the rule reads the
            # evidence and never a prior pass.
            (box / "Method" / "AGREED.md").write_text(
                self._block(self.LEVELED, "top"), encoding="utf-8")
            proc = self.run_cli(
                "position", "--target", str(box), "--name", "Method",
                "--revision", "r1.md", "--session", "s1",
                "--target-level", rung, proposals=self._proposals())
            if proc.returncode == 0:
                allowed.append(rung)
            else:
                payload = json.loads(proc.stdout)
                self.assertEqual(payload["code"], "POSITION_RUNG_SKIPPED",
                                 proc.stdout)
                refused[rung] = payload["resolve"]["command"]
        self.assertEqual(
            allowed, ["floor"],
            "the floor is the one rung nothing has to be attained for, so it "
            "is exactly what an operator with collapsed evidence has left")
        self.assertEqual(sorted(refused), ["middle", "top"])
        for rung, command in refused.items():
            self.assertIn(
                "--target-level floor", command,
                f"the refusal at {rung!r} has to hand back the move that "
                "works, or 'never cornered' is true and unreachable")

    def test_the_published_next_rung_is_read_from_attainment_not_the_header(self):
        """The resolution carries the same separation the guard does.

        Read from the header, the rung published would be the one above
        whatever was last AIMED at -- `top` here, which is refused for the
        identical reason the call being answered was, so the resolution would
        refuse on its own advice. Read from attainment, it publishes the floor.

        Proven by running the `position` invocation the question embeds, not
        the `discuss` command beside it: `discuss` opens the decision and would
        exit 0 whatever rung the question named, so it can witness that the
        published text parses and nothing more.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "middle"), encoding="utf-8")
        proposals = self._proposals()
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "top", proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        question = json.loads(proc.stdout)["resolve"]["question"]
        self.assertIn("--target-level floor", question)
        self.assertNotIn("--target-level top", question)
        embedded = re.search(r"`([^`]*\bposition\b[^`]*)`", question)
        self.assertIsNotNone(embedded, question)
        rerun = self.run_cli(*shlex.split(embedded.group(1))[1:],
                             proposals=proposals)
        self.assertEqual(rerun.returncode, 0, rerun.stdout + rerun.stderr)
        self.assertEqual(json.loads(rerun.stdout)["targetLevel"], "floor")

    def test_the_attained_rung_is_reported_and_not_only_enforced(self):
        """A fact nobody can see is a fact nobody acts on. `position_state`
        already publishes `targetLevel` -- the aim -- and until now published
        nothing about what the evidence reaches, so the only way to learn that
        a recorded rung had outlived its evidence was to trip a refusal. The
        two now stand side by side on the same payload.

        Both poles in one reading: with the shard answer present the floor is
        attained and reported, and with it gone the same repository reports
        `None` while the header goes on naming the same aim. Read in-process
        off `position_state` itself, because that is the one function every
        publisher of this payload (`probe`, `verify`, `gate`, `close`) goes
        through -- asserting it at one command would prove it for one command.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "floor", sha256=self.PROPOSAL_SHA256),
            encoding="utf-8")

        def read(shards_arrived):
            return impl.position_state(
                box, "Method",
                {"levels": list(self.LADDER), "shardsArrived": shards_arrived,
                 "shardsCurrent": None},
                None, None)

        reached = read([])
        self.assertEqual(reached["targetLevel"], "floor")
        self.assertEqual(reached["attainedLevel"], "floor")

        gone = read(None)
        self.assertEqual(gone["targetLevel"], "floor")
        self.assertIsNone(
            gone["attainedLevel"],
            "nothing measured the one leveled witness, and 'we did not look' "
            "is not 'the floor has been reached'")

        # The uniform key set every branch owes its readers: a caller must not
        # have to know whether a block was found before it may read this.
        absent = impl.position_state(
            box, "Nothing", {"levels": list(self.LADDER)}, None, None)
        self.assertEqual(absent["status"], "absent")
        self.assertIsNone(absent["attainedLevel"])

    def test_a_target_that_declares_no_ladder_is_untouched(self):
        """No `__levels__`, no rungs, no progression to enforce. The header may
        name whatever it names, exactly as it did before this rule existed --
        the same silence `POSITION_TARGET_LEVEL_UNKNOWN` already keeps for an
        undeclared ladder."""
        box = self._box(ladder=None)
        (box / "Method" / "AGREED.md").write_text(
            self._block("- [ ] 1. Rehearse. `@rehearsal job-none`\n", "final"),
            encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "whatever-it-likes",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["targetLevel"], "whatever-it-likes")

    def test_a_two_state_item_never_holds_the_ladder_back(self):
        """Two-state items do not participate. Their verdict is computed
        without the ladder and is identical at every rung, so folding them in
        would make this refuse a legitimate advance for a reason that has
        nothing to do with rungs -- whole-sequence completeness wearing this
        rule's name. Here the leveled witness is on the floor and an open
        two-state one sits beside it; the advance goes through."""
        box = self._box()
        body = (self.LEVELED
                + "- [ ] 2. Rehearse. `@rehearsal job-none`\n")
        (box / "Method" / "AGREED.md").write_text(
            self._block(body, "floor"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "middle", "--shards", self._shards(box),
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["targetLevel"], "middle")

    # --- the refusal obeys the roster ----------------------------------------

    def test_the_refusal_publishes_the_next_rung_this_target_can_seal(self):
        """A work state publishes what unblocks it. Nothing about the
        invocation clears a skipped rung -- the work below it has to actually
        happen -- so the payload carries the rung this target can seal next,
        read from the evidence, and the `discuss` command that opens the
        decision.

        The rung published is the floor even though this call passed
        `--shards` and its evidence therefore attains the floor, which would
        make `middle` reachable. The `position` command the question embeds
        carries no `--shards` of its own (`_refusal_position_command`), so a
        rebuild that read this call's flag would publish a rung together with a
        command that cannot reach it -- a resolution refusing on its own
        advice, which is the one thing this builder exists not to be. A target
        that DECLARES `distribution.shardsRoot` is read either way, since the
        rebuild resolves the declaration exactly as every other reader does.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "floor"), encoding="utf-8")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "top", "--shards", self._shards(box),
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["resolve"]["kind"], "question")
        self.assertIn("--target-level floor", payload["resolve"]["question"])
        self.assertIn("implementation_cli.py discuss",
                      payload["resolve"]["command"])
        # The detail is where the operator learns they are not actually on the
        # floor: this call DID measure the shards, so the rung attained is
        # named there even though the safe published move is the floor.
        self.assertIn("attains 'floor'", payload["detail"])

    def test_the_published_discuss_command_is_directly_runnable(self):
        """A published command that does not parse is prose in a monospace
        font. This runs the one the engine published, unedited."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            self._block(self.LEVELED, "floor"), encoding="utf-8")
        proposals = self._proposals()
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1",
                            "--target-level", "top", "--shards", self._shards(box),
                            proposals=proposals)
        published = json.loads(proc.stdout)["resolve"]["command"]
        rerun = self.run_cli(*shlex.split(published)[1:], proposals=proposals)
        self.assertEqual(rerun.returncode, 0, rerun.stdout + rerun.stderr)

    def test_position_is_a_gating_command_and_the_code_is_a_work_state(self):
        """The roster is where the decision lives. `position` refuses on the
        repository's own state and can stop a session dead -- the criterion
        `GATING_COMMANDS` states for itself -- so its refusals are classified
        there, and this one is a work state."""
        self.assertIn("position", impl.GATING_COMMANDS)
        self.assertEqual(impl.GATING_REFUSALS["POSITION_RUNG_SKIPPED"],
                         impl.WORK_STATE)


class DefectCommandTests(unittest.TestCase):
    """`defect` — declares a forge file broken (design decisions 1-4,
    `maintenance-blocks-it-does-not-mix`). These tests prove only the
    ledger side (declaring, refusing on a bad `--file`, appending on a
    repeat declaration) — `OpenDefectLadderTests` below proves the
    refusal `_require_no_open_defect` wires into `step`/`gate`/`offer`/
    `close`/`settle`/`apply`/`admit`, and `DiagnosticsAnsweringWhileDefect
    OpenTests` proves the seven diagnostic commands stay unaffected.
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_defect_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        return box

    def _forge_file(self, data=b"placeholder = True\n"):
        path = (FORGE / ".claude" / "skills" / "proposal-implementation" / "scripts"
               / f"_defect_fixture_{os.getpid()}_{id(self)}.py")
        path.write_bytes(data)
        self.addCleanup(path.unlink, missing_ok=True)
        return path

    def run_cli(self, *args):
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE)

    def ledger_path(self, box):
        return box / "Method" / ".implementation" / "position.jsonl"

    def test_declares_against_a_real_forge_file_and_appends_the_computed_digest(self):
        box = self._box()
        fixture = self._forge_file(b"x = 1\n")
        proc = self.run_cli("defect", "--target", str(box), "--name", "Method",
                            "--session", "s1", "--file", str(fixture),
                            "--detail", "smoke does not import")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        result = json.loads(proc.stdout)
        expected_digest = hashlib.sha256(b"x = 1\n").hexdigest()
        self.assertEqual(result["fileSha256"], expected_digest)
        self.assertEqual(result["detail"], "smoke does not import")
        events = impl_position.read_events(self.ledger_path(box))
        self.assertEqual(len(events), 1)
        self.assertEqual(events[0]["kind"], "defect")
        self.assertEqual(events[0]["fileSha256"], expected_digest)
        self.assertEqual(events[0]["session"], "s1")
        self.assertEqual(events[0]["detail"], "smoke does not import")
        self.assertTrue(events[0]["file"].startswith(".claude/skills/"))

    def test_repeat_declaration_with_no_detail_omits_the_key_rather_than_writing_null(self):
        box = self._box()
        fixture = self._forge_file(b"x = 1\n")
        proc = self.run_cli("defect", "--target", str(box), "--name", "Method",
                            "--session", "s1", "--file", str(fixture))
        self.assertEqual(proc.returncode, 0, proc.stdout)
        events = impl_position.read_events(self.ledger_path(box))
        self.assertNotIn("detail", events[0])

    def test_refuses_a_file_outside_the_forge_skills_tree_and_writes_nothing(self):
        box = self._box()
        outside_root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, outside_root, ignore_errors=True)
        outside = outside_root / "somewhere.py"
        outside.write_text("x = 1\n", encoding="utf-8")
        proc = self.run_cli("defect", "--target", str(box), "--name", "Method",
                            "--session", "s1", "--file", str(outside))
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "DEFECT_FILE_NOT_FORGE_OWNED")
        self.assertFalse(self.ledger_path(box).exists())

    def test_refuses_a_path_that_never_existed_inside_the_forge_tree(self):
        """The bypass, closed (design decision 1): a declaration against an
        already-absent path is refused, never recorded with the sentinel."""
        box = self._box()
        never = (FORGE / ".claude" / "skills" / "proposal-implementation" / "scripts"
                / f"_defect_never_{os.getpid()}_{id(self)}.py")
        self.assertFalse(never.exists())
        proc = self.run_cli("defect", "--target", str(box), "--name", "Method",
                            "--session", "s1", "--file", str(never))
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "DEFECT_FILE_ABSENT")
        self.assertFalse(self.ledger_path(box).exists())

    def test_outside_tree_and_nonexistent_refuses_not_forge_owned_first(self):
        box = self._box()
        outside_root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, outside_root, ignore_errors=True)
        never = outside_root / "never.py"
        self.assertFalse(never.exists())
        proc = self.run_cli("defect", "--target", str(box), "--name", "Method",
                            "--session", "s1", "--file", str(never))
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "DEFECT_FILE_NOT_FORGE_OWNED")

    def test_repeat_declaration_on_an_unchanged_digest_appends_rather_than_refuses(self):
        box = self._box()
        fixture = self._forge_file(b"x = 1\n")
        for _ in range(2):
            proc = self.run_cli("defect", "--target", str(box), "--name", "Method",
                                "--session", "s1", "--file", str(fixture))
            self.assertEqual(proc.returncode, 0, proc.stdout)
        events = impl_position.read_events(self.ledger_path(box))
        self.assertEqual(len(events), 2)


class OpenDefectLadderTests(unittest.TestCase):
    """`_require_no_open_defect` wired into `step`/`gate`/`offer`/`close`/
    `settle`/`apply`/`admit` (Phase 2, `maintenance-blocks-it-does-not-mix`
    design decision 5): an open forge defect refuses `FORGE_DEFECT_OPEN` as
    the first check after `resolve_target`/`validate_name`, ahead of every
    other rung in each of the seven commands.

    **Position is proven by which refusal wins**, never merely that
    `FORGE_DEFECT_OPEN` can fire somewhere. Every scenario below arranges a
    second, independent, KNOWN refusal that would win instead if the
    insertion were missing or placed one line too low — the discipline the
    design's own per-command table states.

    **The reachability instrument is arm/disarm on a real ledger fixture,
    never source mutation** (design "The reachability instrument: arm/
    disarm, not source mutation"): ARMED appends a real `defect` event,
    through the real `defect` subcommand, against a real forge file at its
    real current digest — the identical call `_require_no_open_defect`
    itself re-derives against. DISARMED edits that same file's bytes
    (changing its size, so a same-size edit can never reuse a stale
    `.pyc` and mask a change) so the identical call must stop refusing
    `FORGE_DEFECT_OPEN`.
    """

    PROPOSAL_REVISION = "r1.md"
    PROPOSAL_TEXT = "## 1\ntexto\n"

    def setUp(self):
        self._fixtures = []

    def _proposals(self):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / self.PROPOSAL_REVISION).write_text(self.PROPOSAL_TEXT, encoding="utf-8")
        return root

    def _box(self, committed=True):
        self._box_count = getattr(self, "_box_count", 0) + 1
        box = (FORGE / "implementations"
              / f"_e2e_open_defect_ladder_{os.getpid()}_{id(self)}_{self._box_count}")
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        (box / "Method").mkdir(parents=True, exist_ok=True)
        # A tracked placeholder, not an empty directory: git never reports an
        # untracked FILE inside an untracked directory on its own porcelain
        # line -- an empty `Method/` collapses to one line, `?? Method/`,
        # which `_is_own_bookkeeping` (parts-based) does not recognize as
        # `.implementation/`. Committing one real file here is what lets a
        # LATER `.implementation/position.jsonl` append show up on its own
        # descended porcelain line instead.
        (box / "Method" / ".gitkeep").write_text("", encoding="utf-8")
        (box / "tests").mkdir(parents=True, exist_ok=True)
        env = dict(os.environ)
        env["GIT_AUTHOR_NAME"] = env["GIT_COMMITTER_NAME"] = "open-defect-ladder-tests"
        env["GIT_AUTHOR_EMAIL"] = env["GIT_COMMITTER_EMAIL"] = \
            "open-defect-ladder-tests@example.invalid"
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        if committed:
            subprocess.run(["git", "add", "-A"], cwd=box, env=env, check=True,
                           capture_output=True)
            subprocess.run(["git", "commit", "-q", "-m", "initial"], cwd=box, env=env,
                           check=True, capture_output=True)
        return box

    def _forge_file(self, data=b"placeholder = True\n"):
        path = (FORGE / ".claude" / "skills" / "proposal-implementation" / "scripts"
               / f"_open_defect_ladder_fixture_{os.getpid()}_{id(self)}_{len(self._fixtures)}.py")
        path.write_bytes(data)
        self.addCleanup(path.unlink, missing_ok=True)
        self._fixtures.append(path)
        return path

    def run_cli(self, *args, proposals=None, stdin=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def _arm(self, box, *, name="Method", session="s1", fixture=None, detail="broken"):
        """Declares a real open defect through the real `defect` subcommand
        -- never a hand-written ledger line."""
        fixture = fixture if fixture is not None else self._forge_file()
        proc = self.run_cli("defect", "--target", str(box), "--name", name,
                            "--session", session, "--file", str(fixture),
                            "--detail", detail)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        return fixture

    def _disarm(self, fixture):
        """Edits the declared file's bytes (a different size) so the newest
        `defect` event's recorded digest no longer matches -- clears
        without touching the ledger or source-mutating any tested code."""
        fixture.write_bytes(b"placeholder = True  # edited, a different size now\n")

    def _step(self, box, name="Method", session="s1", step="anything"):
        return self.run_cli("step", "--target", str(box), "--name", name,
                            "--session", session, "--step", step)

    # --- step: DIRTY_WORKTREE is the known refusal that would win ---

    def test_step_refuses_forge_defect_open_ahead_of_dirty_worktree(self):
        box = self._box()
        fixture = self._arm(box)
        (box / "dirty.txt").write_text("uncommitted\n", encoding="utf-8")

        proc = self._step(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

        self._disarm(fixture)
        proc = self._step(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "DIRTY_WORKTREE")

    # --- gate: GATE_AUTHORIZATION_REQUIRED, the sharpest row (design) ---
    # Pure-argv, at the very top of `cmd_gate`'s own ladder -- an insertion
    # placed one line too low fails this scenario loudly.

    def test_gate_refuses_forge_defect_open_ahead_of_authorization_required(self):
        box = self._box()
        fixture = self._arm(box)
        args = ["gate", "--target", str(box), "--name", "Method", "--session", "s1",
                "--job", "job1", "--worker", "w1",
                "--justification", "Because it is time."]

        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

        self._disarm(fixture)
        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_AUTHORIZATION_REQUIRED")

    # --- offer: REVISION_UNREADABLE, not OFFER_UNANSWERED ---
    #
    # `OFFER_UNANSWERED` cannot serve this scenario: `cmd_offer` checks
    # `--answer` BEFORE `resolve_target`/`validate_name` even run (see its
    # own docstring, "Both checks sit above resolve_target/revision_
    # source"), so omitting `--answer` would refuse identically whether the
    # insertion is present, missing, or misplaced -- it can never
    # distinguish the three, which is exactly the "specified refusal no
    # input could ever trigger" trap the design warns the implementer to
    # watch for at every one of the seven insertion points. A valid
    # `--answer` with an unreadable `--revision` is the nearest reachable
    # marker: still checked immediately after the insertion point, in the
    # same position `close`'s own `REVISION_UNREADABLE` occupies.

    def test_offer_refuses_forge_defect_open_ahead_of_revision_unreadable(self):
        box = self._box()
        fixture = self._arm(box)
        args = ["offer", "--target", str(box), "--name", "Method", "--session", "s1",
                "--answer", "yes", "--revision", "does-not-exist.md"]

        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

        self._disarm(fixture)
        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "REVISION_UNREADABLE")

    # --- close: REVISION_UNREADABLE ---

    def test_close_refuses_forge_defect_open_ahead_of_revision_unreadable(self):
        box = self._box()
        fixture = self._arm(box)
        args = ["close", "--target", str(box), "--name", "Method", "--session", "s1",
                "--revision", "does-not-exist.md"]

        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

        self._disarm(fixture)
        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "REVISION_UNREADABLE")

    # --- settle: SETTLE_HEADING_ABSENT ---

    def test_settle_refuses_forge_defect_open_ahead_of_heading_absent(self):
        box = self._box(committed=False)
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        discuss = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                               "--about", "record", "--question", "Settled?",
                               "--answer", "Yes.")
        self.assertEqual(discuss.returncode, 0, discuss.stdout)
        fixture = self._arm(box)
        args = ["settle", "--target", str(box), "--name", "Method", "--session", "s1",
                "--about", "record", "--text", "New text", "--under", "## Nowhere"]

        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

        self._disarm(fixture)
        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HEADING_ABSENT")

    # --- apply: PLAN_MISMATCH ---
    #
    # The design's own table names "--plan path unreadable/stale"; a
    # literally unreadable (nonexistent) `--plan` path is not a coded
    # `Refused` at all today -- `Path(args.plan).read_text()` raises
    # `FileNotFoundError` uncaught (Phase 3's crash capture is a separate,
    # later change), so it cannot serve as "a different KNOWN refusal
    # wins". `PLAN_MISMATCH` is the nearest reachable, deterministic, coded
    # refusal past `require_clean_worktree` -- a plan JSON that exists,
    # parses, and simply names a different target/name.

    def test_apply_refuses_forge_defect_open_ahead_of_plan_mismatch(self):
        box = self._box()
        fixture = self._arm(box)
        plan_path = Path(tempfile.mktemp(suffix=".json"))
        self.addCleanup(plan_path.unlink, missing_ok=True)
        plan_path.write_text(json.dumps({"target": "bogus", "name": "Bogus"}),
                             encoding="utf-8")
        args = ["apply", "--target", str(box), "--name", "Method", "--plan", str(plan_path)]

        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

        self._disarm(fixture)
        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "PLAN_MISMATCH")

    # --- admit: REVISION_UNREADABLE, admit's own actual first-ladder
    # refusal (task 2.1's re-location -- `cmd_admit` never called
    # `validate_name` before this change; `--name` was already required and
    # collected by argparse, so adding the call uses a value the parser
    # already accepted, not a new flag) ---

    def test_admit_refuses_forge_defect_open_ahead_of_revision_unreadable(self):
        box = self._box()
        fixture = self._arm(box)
        args = ["admit", "--target", str(box), "--name", "Method"]

        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

        self._disarm(fixture)
        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "REVISION_UNREADABLE")

    # --- the guard order the mechanism must never invert ---

    def test_non_repository_target_refuses_not_a_git_repo_not_forge_defect_open(self):
        """`resolve_target`'s own `NOT_A_GIT_REPO` precedes the defect check
        by construction: there is no ledger path to consult before a target
        even resolves. A defect armed elsewhere must never leak into this
        refusal."""
        elsewhere = self._box()
        self._arm(elsewhere)

        not_a_repo = (FORGE / "implementations"
                     / f"_e2e_not_a_repo_{os.getpid()}_{id(self)}")
        self.addCleanup(shutil.rmtree, not_a_repo, ignore_errors=True)
        (not_a_repo / "Method").mkdir(parents=True)

        proc = self._step(not_a_repo)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "NOT_A_GIT_REPO")

    def test_a_defect_open_under_one_target_does_not_block_a_different_target(self):
        """Per-target scope (spec, design's Two Limits): every `defect`
        event is scoped to the exact `<target>/<name>/.implementation/` it
        was appended to."""
        box_a = self._box()
        self._arm(box_a)
        box_b = self._box()

        proc = self._step(box_b)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        # Reaches its own (unrelated) refusal, never the other target's
        # defect -- proof the check consulted box_b's own ledger, not box_a's.
        self.assertEqual(json.loads(proc.stdout)["code"], "STEPS_UNDECLARED")

    def test_declaring_then_stepping_in_the_same_target_never_self_trips_dirty_worktree(self):
        """Task 2.7: the defect's own ledger append must not be mistaken
        for uncommitted work by `require_clean_worktree`
        (`impl_guards._is_own_bookkeeping` already excuses `.implementation/`
        for every command that checks it) -- proven here composed with the
        NEW `FORGE_DEFECT_OPEN` check: declare, then clear (so `step` can
        reach `require_clean_worktree` at all), and the ledger line the
        declaration left behind must still not trip it. A genuinely
        separate, non-ledger dirty file must still refuse."""
        box = self._box()
        fixture = self._arm(box)
        self._disarm(fixture)

        proc = self._step(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "STEPS_UNDECLARED")

        (box / "dirty.txt").write_text("genuinely uncommitted\n", encoding="utf-8")
        proc = self._step(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "DIRTY_WORKTREE")

    # --- materialize: MATERIALIZE_MODE_REQUIRED, a pure-argv check ---
    # `materialize` arrived from a sibling change AFTER the seven insertions
    # were written, so it was the one spend command the merge left unguarded.
    # It writes kit destinations over the target -- squarely a command that
    # spends -- and its mode check is pure argv, so an insertion placed one
    # line too low fails this scenario loudly.

    def test_materialize_refuses_forge_defect_open_ahead_of_mode_required(self):
        box = self._box()
        fixture = self._arm(box)
        args = ["materialize", "--target", str(box), "--name", "Method"]

        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

        self._disarm(fixture)
        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"],
                         "MATERIALIZE_MODE_REQUIRED")



class DiagnosticsAnsweringWhileDefectOpenTests(unittest.TestCase):
    """`probe`, `verify`, `position`, `plan`, `compose`, `handoff` and
    `discuss` carry no `FORGE_DEFECT_OPEN` check (spec "Diagnostic Commands
    Stay Reachable"; design decision 5's own scope). Every scenario below
    pairs its diagnostic call with a companion assertion, on the identical
    fixture, that a spend command (`step`) IS refused `FORGE_DEFECT_OPEN`
    there -- without that pairing all seven would pass on a fixture whose
    arm never armed (design "Diagnostics: seven scenarios, each with a
    non-vacuity companion").
    """

    def setUp(self):
        self._fixtures = []

    def _proposals(self, revision="r1.md", text="## 1\ntexto\n"):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / revision).write_text(text, encoding="utf-8")
        return root

    def _box(self, committed=True):
        self._box_count = getattr(self, "_box_count", 0) + 1
        box = (FORGE / "implementations"
              / f"_e2e_open_defect_diag_{os.getpid()}_{id(self)}_{self._box_count}")
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        (box / "Method").mkdir(parents=True, exist_ok=True)
        # See `OpenDefectLadderTests._box`'s identical comment: a tracked
        # placeholder, not an empty directory, so a later `.implementation/`
        # append shows up on its own porcelain line rather than collapsing
        # `Method/` itself into one untracked-directory line.
        (box / "Method" / ".gitkeep").write_text("", encoding="utf-8")
        (box / "tests").mkdir(parents=True, exist_ok=True)
        env = dict(os.environ)
        env["GIT_AUTHOR_NAME"] = env["GIT_COMMITTER_NAME"] = "open-defect-diag-tests"
        env["GIT_AUTHOR_EMAIL"] = env["GIT_COMMITTER_EMAIL"] = \
            "open-defect-diag-tests@example.invalid"
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        if committed:
            subprocess.run(["git", "add", "-A"], cwd=box, env=env, check=True,
                           capture_output=True)
            subprocess.run(["git", "commit", "-q", "-m", "initial"], cwd=box, env=env,
                           check=True, capture_output=True)
        return box

    def _forge_file(self, data=b"placeholder = True\n"):
        path = (FORGE / ".claude" / "skills" / "proposal-implementation" / "scripts"
               / f"_open_defect_diag_fixture_{os.getpid()}_{id(self)}_{len(self._fixtures)}.py")
        path.write_bytes(data)
        self.addCleanup(path.unlink, missing_ok=True)
        self._fixtures.append(path)
        return path

    def run_cli(self, *args, proposals=None, stdin=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def _arm(self, box, *, name="Method", session="s1"):
        fixture = self._forge_file()
        proc = self.run_cli("defect", "--target", str(box), "--name", name,
                            "--session", session, "--file", str(fixture),
                            "--detail", "broken, for a diagnostic fixture")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        return fixture

    def _assert_spend_command_is_refused_here(self, box, name="Method"):
        """The non-vacuity companion: proves this exact fixture is really
        armed, by showing a spend command refuses FORGE_DEFECT_OPEN on it."""
        proc = self.run_cli("step", "--target", str(box), "--name", name,
                            "--session", "s1", "--step", "anything")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "FORGE_DEFECT_OPEN")

    def test_probe_answers_while_a_defect_is_open(self):
        box = self._box()
        self._arm(box)
        proc = self.run_cli("probe", "--target", str(box), "--name", "Method")
        self.assertNotEqual(json.loads(proc.stdout).get("code"), "FORGE_DEFECT_OPEN",
                            proc.stdout)
        self._assert_spend_command_is_refused_here(box)

    def test_verify_answers_while_a_defect_is_open(self):
        box = self._box()
        self._arm(box)
        proc = self.run_cli("verify", "--target", str(box), "--name", "Method")
        self.assertNotEqual(json.loads(proc.stdout).get("code"), "FORGE_DEFECT_OPEN",
                            proc.stdout)
        self._assert_spend_command_is_refused_here(box)

    def test_position_answers_while_a_defect_is_open(self):
        box = self._box()
        self._arm(box)
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--session", "s1")
        self.assertNotEqual(json.loads(proc.stdout).get("code"), "FORGE_DEFECT_OPEN",
                            proc.stdout)
        self._assert_spend_command_is_refused_here(box)

    def test_plan_answers_while_a_defect_is_open(self):
        box = self._box()
        self._arm(box)
        proc = self.run_cli("plan", "--target", str(box), "--name", "Method")
        self.assertNotEqual(json.loads(proc.stdout).get("code"), "FORGE_DEFECT_OPEN",
                            proc.stdout)
        self._assert_spend_command_is_refused_here(box)

    def test_compose_answers_while_a_defect_is_open(self):
        box = self._box()
        self._arm(box)
        proc = self.run_cli("compose", "--target", str(box), "--finding", "nonexistent",
                            "--entry-text", "text")
        self.assertNotEqual(json.loads(proc.stdout).get("code"), "FORGE_DEFECT_OPEN",
                            proc.stdout)
        self._assert_spend_command_is_refused_here(box)

    def test_handoff_answers_while_a_defect_is_open(self):
        box = self._box()
        proposals = self._proposals()
        self._arm(box)
        proc = self.run_cli("handoff", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", proposals=proposals)
        self.assertNotEqual(json.loads(proc.stdout).get("code"), "FORGE_DEFECT_OPEN",
                            proc.stdout)
        self._assert_spend_command_is_refused_here(box)

    def test_discuss_answers_while_a_defect_is_open(self):
        box = self._box()
        self._arm(box)
        proc = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                            "--about", "record", "--question", "Still open?")
        self.assertNotEqual(json.loads(proc.stdout).get("code"), "FORGE_DEFECT_OPEN",
                            proc.stdout)
        self._assert_spend_command_is_refused_here(box)


class HandoffSurfacesOpenDefectsTests(unittest.TestCase):
    """`handoff` gains `openDefects` (design decision 7): a new report key,
    additive, never folding forge health into `status`, which keeps meaning
    exactly what it means today -- findings routing."""

    def _proposals(self, revision="r1.md", text="## 1\ntexto\n"):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / revision).write_text(text, encoding="utf-8")
        return root

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_handoff_defects_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        (box / "Method").mkdir(parents=True, exist_ok=True)
        (box / "tests").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        return box

    def _forge_file(self, data=b"placeholder = True\n"):
        path = (FORGE / ".claude" / "skills" / "proposal-implementation" / "scripts"
               / f"_handoff_defects_fixture_{os.getpid()}_{id(self)}.py")
        path.write_bytes(data)
        self.addCleanup(path.unlink, missing_ok=True)
        return path

    def run_cli(self, *args, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def test_handoff_reports_no_open_defects_when_none_are_declared(self):
        box = self._box()
        proc = self.run_cli("handoff", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["openDefects"], [])

    def test_handoff_surfaces_an_open_defect_by_file_session_and_detail(self):
        box = self._box()
        fixture = self._forge_file(b"x = 1\n")
        declare = self.run_cli("defect", "--target", str(box), "--name", "Method",
                               "--session", "s7", "--file", str(fixture),
                               "--detail", "smoke does not import")
        self.assertEqual(declare.returncode, 0, declare.stdout)

        proc = self.run_cli("handoff", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        open_defects = json.loads(proc.stdout)["openDefects"]
        self.assertEqual(len(open_defects), 1)
        self.assertTrue(open_defects[0]["file"].startswith(".claude/skills/"))
        self.assertEqual(open_defects[0]["session"], "s7")
        self.assertEqual(open_defects[0]["detail"], "smoke does not import")

    def test_handoff_stops_surfacing_a_defect_once_the_file_changes(self):
        box = self._box()
        fixture = self._forge_file(b"x = 1\n")
        declare = self.run_cli("defect", "--target", str(box), "--name", "Method",
                               "--session", "s7", "--file", str(fixture))
        self.assertEqual(declare.returncode, 0, declare.stdout)
        fixture.write_bytes(b"x = 1  # fixed, a different size now\n")

        proc = self.run_cli("handoff", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["openDefects"], [])


class _CustomForgeBug(Exception):
    """A crash type this suite owns, so "the same exception type survives"
    means something beyond every test happening to raise `RuntimeError`."""


class CrashCaptureTests(unittest.TestCase):
    """`main()`'s guarded `except Exception` arm (design decision 6,
    `maintenance-blocks-it-does-not-mix`): any exception reaching `main()`'s
    dispatch that is not `Refused` is, by definition, a forge-side bug, and
    is auto-recorded as a `kind: "defect"` event before it re-raises -- the
    half of this mechanism that needs no agent cooperation.

    Every scenario calls `impl.main(...)` IN-PROCESS (never through
    `run_cli`'s subprocess) so `COMMANDS` can be monkeypatched: a reachable
    non-`Refused` crash has to be constructed, not merely asserted possible
    -- ordinary argv-shaped calls into the real, unpatched command surface
    only ever reach coded `Refused` paths.
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_crash_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "Method").mkdir(parents=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        return box

    def ledger_path(self, box):
        return box / "Method" / ".implementation" / "position.jsonl"

    def _call_main(self, argv):
        buf = io.StringIO()
        with contextlib.redirect_stdout(buf):
            code = impl.main(argv)
        return code, buf.getvalue()

    def test_a_non_refused_crash_records_the_raising_forge_module_and_its_current_digest(self):
        """Reachability, constructed: `COMMANDS["step"]` is monkeypatched to
        raise a plain `RuntimeError` -- an exception `except Refused` never
        catches. The raise itself happens inside a stdlib `unittest.mock`
        frame, never inside `implementation_cli.py`, which is exactly the
        "deepest frame is stdlib" hazard the design names: the recorded
        file must be `main()`'s own frame (the LAST forge frame still on
        the traceback), and its digest must be the file's CURRENT bytes,
        computed through the identical `current_file_digest` the ladder
        check re-derives against.
        """
        box = self._box()
        boom = unittest.mock.Mock(side_effect=RuntimeError("boom"))
        with unittest.mock.patch.dict(impl.COMMANDS, {"step": boom}):
            with self.assertRaises(RuntimeError):
                impl.main(["step", "--target", str(box), "--name", "Method",
                          "--session", "s1", "--step", "whatever"])

        events = impl_position.read_events(self.ledger_path(box))
        defects = [e for e in events if e.get("kind") == "defect"]
        self.assertEqual(len(defects), 1)
        self.assertEqual(defects[0]["command"], "step")
        self.assertEqual(defects[0]["session"], "s1")
        self.assertTrue(defects[0]["file"].endswith("implementation_cli.py"),
                        defects[0]["file"])
        self.assertEqual(defects[0]["fileSha256"],
                         impl_position.current_file_digest(CLI))

    def test_the_original_exception_type_and_message_propagate_unchanged(self):
        box = self._box()
        boom = unittest.mock.Mock(
            side_effect=_CustomForgeBug("cmd_step forgot to check something"))
        with unittest.mock.patch.dict(impl.COMMANDS, {"step": boom}):
            with self.assertRaises(_CustomForgeBug) as ctx:
                impl.main(["step", "--target", str(box), "--name", "Method",
                          "--session", "s1", "--step", "whatever"])
        self.assertEqual(str(ctx.exception), "cmd_step forgot to check something")

    def test_a_failing_recorder_never_replaces_the_original_exception(self):
        """`append_event` itself raising must stay invisible: the ORIGINAL
        exception still propagates, unwrapped and unreplaced, and no
        second error is ever reported."""
        box = self._box()
        boom = unittest.mock.Mock(side_effect=RuntimeError("boom"))
        with unittest.mock.patch.dict(impl.COMMANDS, {"step": boom}), \
             unittest.mock.patch.object(impl_position, "append_event",
                                        side_effect=OSError("ledger disk full")):
            with self.assertRaises(RuntimeError) as ctx:
                impl.main(["step", "--target", str(box), "--name", "Method",
                          "--session", "s1", "--step", "whatever"])
        self.assertEqual(str(ctx.exception), "boom")

    def test_refused_records_nothing_the_ordinary_refusal_path_is_unchanged(self):
        """Highest-consequence scenario in the design's own table: a
        `Refused` leaking into the recorder would permanently block the
        flow on its own refusals. `except Refused` sits ABOVE `except
        Exception`, and this is the real, unpatched `cmd_step` refusing
        for real (`NOT_A_GIT_REPO`, no `git init` here) -- not a
        monkeypatch standing in for one."""
        box = FORGE / "implementations" / f"_e2e_crash_refused_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "Method").mkdir(parents=True)
        code, out = self._call_main(
            ["step", "--target", str(box), "--name", "Method",
             "--session", "s1", "--step", "whatever"])
        self.assertEqual(code, 2)
        self.assertEqual(json.loads(out)["code"], "NOT_A_GIT_REPO")
        self.assertFalse(self.ledger_path(box).exists())

    def test_keyboard_interrupt_and_system_exit_record_nothing(self):
        box = self._box()
        for exc_type in (KeyboardInterrupt, SystemExit):
            with self.subTest(exc_type=exc_type.__name__):
                raiser = unittest.mock.Mock(side_effect=exc_type())
                with unittest.mock.patch.dict(impl.COMMANDS, {"step": raiser}):
                    with self.assertRaises(exc_type):
                        impl.main(["step", "--target", str(box), "--name", "Method",
                                  "--session", "s1", "--step", "whatever"])
                self.assertFalse(self.ledger_path(box).exists())

    def test_a_crash_in_env_appends_nothing_and_re_raises_the_stated_limit(self):
        """`env` never gets a `--name`, so it has no `<target>/<name>/
        .implementation/` ledger path to write into at all -- the stated
        limit `_record_engine_defect`'s own docstring names, never a gap
        this closes."""
        box = self._box()
        boom = unittest.mock.Mock(side_effect=RuntimeError("env boom"))
        with unittest.mock.patch.dict(impl.COMMANDS, {"env": boom}):
            with self.assertRaises(RuntimeError) as ctx:
                impl.main(["env", "--target", str(box)])
        self.assertEqual(str(ctx.exception), "env boom")
        self.assertFalse(self.ledger_path(box).exists())


class CommandRosterTests(unittest.TestCase):
    """`COMMANDS` binds every subcommand `main()` accepts; a table in
    `SKILL.md` is the human-facing roster of what each of the four
    write-verbs this change adds writes and refuses on — the same
    table-vs-code mechanism the `verify`/`probe` rosters already apply,
    one level up (design §7.1), narrowed to the commands that write.

    Full coverage over every key of `COMMANDS` (nine to thirteen, design
    §7.1) is `test_every_command_dispatched_is_accounted_for`'s assertion:
    the four write-verbs are held to a row here, and the remaining nine are
    named explicitly as read-only or otherwise out of this table's own
    scope — `env`/`name`/`plan`/`apply`/`admit`/`handoff`/`compose` predate
    this change, and `probe`/`verify` already carry their own status/fact
    rosters (`ProbeReportedFactsRosterTests`/`VerifyStatusRosterTests`), so
    documenting their statuses a second time here would be the second
    definition of one rule this file's own doctrine keeps rejecting.
    """

    COMMAND_TABLE_HEADER = "| Command | What it writes | Refuses on |"

    #: Predates this change, or already carries its own roster elsewhere —
    #: named explicitly rather than left as a silent gap in this table.
    DOCUMENTED_ELSEWHERE = frozenset(
        {"env", "name", "plan", "apply", "admit", "handoff", "compose",
         "probe", "verify"})

    def command_rows(self):
        tables = markdown_table_rows(
            SKILL_MD.read_text(encoding="utf-8"), self.COMMAND_TABLE_HEADER)
        self.assertEqual(
            len(tables), 1,
            "the command roster is stated in no parseable table, so nothing "
            "holds a new command to a documented row")
        return tables[0]

    def test_position_is_registered_and_documented(self):
        self.assertIn("position", impl.COMMANDS)
        rows = {row[0].strip("`"): row for row in self.command_rows()}
        self.assertIn("position", rows)
        writes, refuses = rows["position"][1], rows["position"][2]
        self.assertTrue(writes.strip(), "the `position` row names nothing it writes")
        self.assertTrue(refuses.strip(), "the `position` row names nothing it refuses on")

    def test_every_command_dispatched_is_accounted_for(self):
        write_verbs = {"position", "discuss", "propose", "gate", "offer",
                       "close", "step", "settle", "defect",
                       "materialize"}
        dispatched = set(impl.COMMANDS)
        self.assertEqual(
            dispatched, self.DOCUMENTED_ELSEWHERE | write_verbs,
            "`COMMANDS` dispatches a command this roster neither documents "
            "nor names as out of scope")

        rows = {row[0].strip("`"): row for row in self.command_rows()}
        for command in sorted(write_verbs):
            self.assertIn(command, rows,
                          f"`{command}` writes and has no row in the command roster")
            writes, refuses = rows[command][1], rows[command][2]
            self.assertTrue(writes.strip(), f"the `{command}` row names nothing it writes")
            self.assertTrue(refuses.strip(), f"the `{command}` row names nothing it refuses on")


class CommandRosterClosureTests(unittest.TestCase):
    """Lock: `SKILL.md`'s `## Command Roster` states the dispatch surface as a
    CLOSED set, and the set is read out of the document rather than trusted.

    The defect this closes was written into the file as a confession and then
    left to rot: a limitation paragraph said the CLI "accepts nine and refuses
    everything else by naming them, so the running code holds a roster; this
    document does not". By the time anybody measured it, `COMMANDS` bound
    nineteen. Nothing derived the nine, so nothing went red as the surface
    doubled underneath the sentence -- prose that outlived its mechanism, the
    same class this file's refusal and `nextStep` rosters already close.

    `CommandRosterTests` above holds the write-verbs to a documented row and
    names the remaining commands as out of scope, but it names them *in this
    file*: the closed set lived in a Python frozenset a reader of `SKILL.md`
    never sees. This class moves the statement into the document and holds the
    document to `COMMANDS`, in both directions -- a command added to the
    dispatch table fails until it has a row, and a row no command backs fails
    too.

    `test_the_roster_derivation_finds_the_measured_nineteen` is the guard on
    the scraper rather than on the roster, for the reason
    `GatingRefusalRosterTests` states about its own count: a walk that silently
    matches nothing makes the second direction pass over an empty set, and a
    lock that passes because nothing happened is indistinguishable from one
    that holds.
    """

    #: The two tables that together are the roster. Read by their own header
    #: lines, so renaming a column is a red test rather than a silent halving.
    WRITE_TABLE_HEADER = "| Command | What it writes | Refuses on |"
    REST_TABLE_HEADER = "| Command | What it does | Where its detail lives |"

    def _table(self, header):
        skill = SKILL_MD.read_text(encoding="utf-8")
        tables = markdown_table_rows(skill, header)
        self.assertEqual(
            len(tables), 1,
            f"exactly one table is expected under {header!r} and "
            f"{len(tables)} were found; the roster is half-read, and a "
            "half-read roster is what this class exists to refuse")
        rows = tables[0]
        self.assertTrue(
            rows, f"the table under {header!r} was read as empty")
        for row in rows:
            # At least three, never exactly three: `markdown_table_rows` splits
            # on every `|`, and a cell carrying an escaped `\\|` (the
            # `materialize` row's `<scaffold\\|objects\\|harness>`) reports
            # extra cells. The guard that matters is that a row is not a stub.
            self.assertGreaterEqual(
                len(row), 3,
                f"a row under {header!r} has fewer than three cells: {row!r}")
        return rows

    def rostered_commands(self):
        """Column one of both tables, in document order, ungrouped."""
        return [row[0].strip().strip("`")
                for header in (self.WRITE_TABLE_HEADER, self.REST_TABLE_HEADER)
                for row in self._table(header)]

    def test_the_roster_derivation_finds_the_measured_nineteen(self):
        """Sanity on the walk, not on the roster. A command added to or removed
        from the CLI should move this number; a broken header, a renamed column
        or a table that stopped parsing should not be able to leave it green."""
        rostered = self.rostered_commands()
        self.assertEqual(len(rostered), 19)
        self.assertEqual(
            sorted(rostered), sorted(set(rostered)),
            "a command is rostered twice; two rows for one command is two "
            "places to keep in agreement, which is the drift this closes")

    def test_every_dispatched_command_has_a_roster_row(self):
        rostered = set(self.rostered_commands())
        self.assertEqual(
            sorted(set(impl.COMMANDS) - rostered), [],
            "`COMMANDS` dispatches these and the command roster states none "
            "of them, so the document's closed set is not the CLI's")

    def test_every_rostered_command_is_dispatched(self):
        """The other direction, and the one an empty scrape would pass. A row
        for a command that no longer exists teaches a reader an invocation the
        CLI answers `invalid choice` to."""
        rostered = set(self.rostered_commands())
        self.assertEqual(
            sorted(rostered - set(impl.COMMANDS)), [],
            "the command roster states these and the CLI dispatches no such "
            "command")

    def test_the_roster_states_the_counts_it_actually_holds(self):
        """The `nine` that rotted was a spelled number in prose with nothing
        reading it. The counts stay in the prose -- a reader deserves to be
        told how big the surface is -- and every one of them is derived here,
        so re-counting is this suite's work rather than a reviewer's."""
        skill = " ".join(SKILL_MD.read_text(encoding="utf-8").split())
        write_rows = len(self._table(self.WRITE_TABLE_HEADER))
        rest_rows = len(self._table(self.REST_TABLE_HEADER))
        self.assertEqual(write_rows + rest_rows, len(impl.COMMANDS))
        total = _english_count(len(impl.COMMANDS)).lower()
        self.assertIn(f"`COMMANDS` binds {total} subcommands", skill)
        self.assertIn(
            f"The {_english_count(write_rows).lower()} above and the "
            f"{_english_count(rest_rows).lower()} below", skill)

    def test_every_rest_row_says_where_the_detail_lives(self):
        """The third column is the whole point of the second table: these
        commands are rostered here and documented at length elsewhere, and a
        roster row that names no elsewhere sends the reader nowhere."""
        for row in self._table(self.REST_TABLE_HEADER):
            command = row[0].strip().strip("`")
            with self.subTest(command=command):
                self.assertTrue(
                    row[1].strip(), f"the `{command}` row says nothing it does")
                self.assertIn(
                    "usage.md", row[2],
                    f"the `{command}` row points at no worked reference")


class PositionReconcileTests(unittest.TestCase):
    """`--reconcile` — reconstruction from a target that already has
    notebooks, job folders and a declared search, but no position section
    yet (design §3.3, spec "Reconstruction From an Existing Target").

    The fixture (`tests/fixtures/agreed_shape_reconcile.md`) mirrors the
    *shape* a real target's `AGREED.md` reaches — ~90 checklist items
    across sixteen `##` sections, plus a trailing no-bullet `Reversed`
    section — because `implementations/` is gitignored and reconciliation
    has to be proven against a realistically dense, hand-curated document,
    not a two-line toy nobody would mistake for a stress test.
    """

    FIXTURE = Path(__file__).resolve().parent / "fixtures" / "agreed_shape_reconcile.md"

    def _proposals(self):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / "r1.md").write_text("## 1\ntexto\n", encoding="utf-8")
        return root

    def _box(self, agreed_text=None):
        box = FORGE / "implementations" / f"_e2e_position_reconcile_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        if agreed_text is not None:
            (box / "Method" / "AGREED.md").write_text(agreed_text, encoding="utf-8")
        return box

    def run_cli(self, *args, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def _shards(self, stamps):
        """A real shard directory on disk, one subdirectory per shard, each
        holding a `shard.json` stamp -- the exact shape `shard_io.read_shards`
        assumes, and the same shape `ShardRefusalCrossJoinTests.build_shards`
        builds elsewhere in this file for `verify`. Duplicated here rather
        than shared across classes because a stray cross-class dependency
        would make this class's own fixtures harder to read in isolation.
        """
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        for shard, stamp in stamps.items():
            folder = root / shard
            folder.mkdir()
            (folder / "shard.json").write_text(json.dumps(stamp), encoding="utf-8")
        return root

    # --- 4.2: the fixture's 90 items and its Reversed section survive ---

    def test_reconcile_appends_without_disturbing_existing_items_or_reversed_section(self):
        fixture_text = self.FIXTURE.read_text(encoding="utf-8")
        box = self._box(agreed_text=fixture_text)
        (box / "Method" / "Notebooks").mkdir(parents=True)
        (box / "Method" / "Notebooks" / "pilot.ipynb").write_text("{}", encoding="utf-8")

        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1", "--target-level", "final",
                            "--reconcile", proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["holder"], "Method/AGREED.md")
        self.assertGreaterEqual(len(result["sequence"]), 1)

        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertTrue(after.startswith(fixture_text))
        # Every one of the fixture's 90 items, verbatim, still present --
        # not merely a prefix check, which a splice that silently truncated
        # mid-file could still pass.
        for line in fixture_text.splitlines():
            if line.strip().startswith("- ["):
                self.assertIn(line, after)
        self.assertIn("## Reversed", after)
        self.assertIn(
            "This reversal was made without reading this file", after)
        self.assertIn("<!-- position", after)

    # --- 4.3: witness identity across reruns ---

    def test_reconcile_preserves_witness_identity_across_reruns(self):
        box = self._box(agreed_text="# Agreed\n\n- [x] Something already settled.\n")
        (box / "Method" / "Notebooks").mkdir(parents=True)
        (box / "Method" / "Notebooks" / "a.ipynb").write_text("{}", encoding="utf-8")
        proposals = self._proposals()

        first = self.run_cli("position", "--target", str(box), "--name", "Method",
                             "--revision", "r1.md", "--session", "s1", "--target-level", "final",
                             "--reconcile", proposals=proposals)
        self.assertEqual(first.returncode, 0, first.stdout)
        first_result = json.loads(first.stdout)
        self.assertEqual(len(first_result["sequence"]), 1)
        self.assertEqual(first_result["sequence"][0]["witness"],
                         {"kind": "notebook", "operand": "Notebooks/a.ipynb", "twostate": True})

        # A human writes the real sentence over the placeholder.
        agreed_path = box / "Method" / "AGREED.md"
        agreed_path.write_text(
            agreed_path.read_text(encoding="utf-8").replace(
                impl.POSITION_PLACEHOLDER_TEXT,
                "Read the pilot notebook into the report."),
            encoding="utf-8")

        # A second notebook appears before the second reconcile.
        (box / "Method" / "Notebooks" / "b.ipynb").write_text("{}", encoding="utf-8")
        second = self.run_cli("position", "--target", str(box), "--name", "Method",
                              "--revision", "r1.md", "--session", "s2",
                              "--reconcile", proposals=proposals)
        self.assertEqual(second.returncode, 0, second.stdout)
        second_result = json.loads(second.stdout)
        self.assertEqual(len(second_result["sequence"]), 2)
        self.assertEqual(second_result["sequence"][0]["ordinal"], 1)
        self.assertEqual(second_result["sequence"][0]["text"],
                         "Read the pilot notebook into the report.")
        self.assertEqual(second_result["sequence"][0]["witness"],
                         {"kind": "notebook", "operand": "Notebooks/a.ipynb", "twostate": True})
        self.assertEqual(second_result["sequence"][1]["ordinal"], 2)
        self.assertEqual(second_result["sequence"][1]["witness"],
                         {"kind": "notebook", "operand": "Notebooks/b.ipynb", "twostate": True})

    # --- 4.4: `--reconcile --shards` measures what it just discovered ---

    def test_reconcile_measures_an_arrived_shard_it_discovers(self):
        """RED before the fix, for the exact reason design §11 names:
        `--reconcile --shards <dir>` discovers a `@shard` witness for every
        arrived shard, but `position`'s own evidence
        (`_position_write_evidence`) hardcoded `shardsArrived: None`
        regardless of `--shards`, so the very witness this call just
        discovered from `<dir>` read `unmeasured` instead of `True` -- the
        arrival evidence was a function argument away and never read.
        """
        box = self._box(agreed_text="# Agreed\n\n- [x] Something already settled.\n")
        shards = self._shards({"a": {"epochs": 5}})

        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", "r1.md", "--session", "s1", "--target-level", "final",
                            "--reconcile", "--shards", str(shards),
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        shard_item = next(item for item in result["sequence"]
                          if item["witness"] == {"kind": "shard", "operand": "a", "twostate": True})
        self.assertTrue(
            shard_item["derived"],
            f"a shard just discovered from --shards's own directory reads "
            f"derived={shard_item['derived']!r} instead of True; --reconcile "
            "found it but position's own evidence never learns --shards was "
            "given at all.")

    # --- 4.5: the falsifier, an assertion that runs (design §11) ---

    def test_unmeasured_never_outnumbers_measured_on_reconciled_target(self):
        """If this fails, the fix is design §11's own escalation — move
        `@shard` off the no-flag default — never loosening this assertion.

        Ten shard directories against six other witnesses (one `@record`,
        five `@notebook`) is not an arbitrary ratio: it is the real shape
        measured against a target that had already run split (ten shards
        under `Results/Benchmark/shards`, five notebooks, one declared
        record), reproduced with `position --reconcile --shards <dir>` --
        the exact invocation that surfaced `_position_write_evidence`'s hardcoded
        `shardsArrived: None`. RED before that function threads `--shards`
        through (6 measured vs 10 unmeasured); GREEN once it does.
        """
        box = self._box(agreed_text=self.FIXTURE.read_text(encoding="utf-8"))
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            "__benchmark__ = {'search': {'record': 'Results/record.json'}}\n",
            encoding="utf-8")
        (box / "Method" / "Results").mkdir(parents=True)
        (box / "Method" / "Results" / "record.json").write_text("{}", encoding="utf-8")
        (box / "Method" / "Notebooks").mkdir(parents=True)
        for notebook in ("a", "b", "c", "d", "e"):
            (box / "Method" / "Notebooks" / f"{notebook}.ipynb").write_text(
                "{}", encoding="utf-8")
        shards = self._shards({f"s{i:02d}": {"epochs": 5} for i in range(10)})
        proposals = self._proposals()

        reconcile = self.run_cli("position", "--target", str(box), "--name", "Method",
                                 "--revision", "r1.md", "--session", "s1", "--target-level", "final",
                                 "--reconcile", "--shards", str(shards),
                                 proposals=proposals)
        self.assertEqual(reconcile.returncode, 0, reconcile.stdout)
        position = json.loads(reconcile.stdout)

        measured = sum(1 for item in position["sequence"] if item["derived"] is not None)
        unmeasured = sum(1 for item in position["sequence"] if item["derived"] is None)
        self.assertGreaterEqual(
            measured, unmeasured,
            f"`unmeasured` ({unmeasured}) outnumbers `measured` ({measured}) on "
            "a reconciled target shaped like a real one (10 shards, 6 other "
            "witnesses), given the exact `--shards` directory that discovered "
            "them -- the mechanism is decaying into the prose it replaced "
            "(design §11's own falsifier).")


class DiscussCommandBuilderTests(unittest.TestCase):
    """`_discuss_command` -- the one command-string builder every
    publication point in this change routes through (design D2): every
    embedded value escaped with `shlex.quote`, never a naive interpolation
    or single-quote wrapping.
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_discuss_command_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        return box

    def test_apostrophe_bearing_question_is_quoted_and_runnable(self):
        """Mutation proof 5 (spec Test Obligations #5): remove `shlex.quote`
        and this fails against an apostrophe-bearing text -- the same
        discipline `OfferCommandTests.test_expand_contract_command_string_
        is_runnable_and_writes_nothing` already applies to `expand-contract`.
        """
        box = self._box()
        question = "does render's docstring still hold?"
        command = impl._discuss_command(
            box, "Method", about="record", question=question,
            answer="yes, it still holds")

        tokens = shlex.split(command)
        self.assertTrue(tokens[0].endswith("implementation_cli.py"), command)
        self.assertEqual(tokens[1], "discuss", command)

        # Executed as a subprocess, not merely read as text -- inspection
        # alone cannot see a quoting defect an apostrophe would trigger.
        proc = subprocess.run([sys.executable, str(CLI), *tokens[1:]],
                              capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        result = json.loads(proc.stdout)
        self.assertEqual(result["asked"], question)
        self.assertEqual(result["status"], "answered")

    def test_omitted_answer_leaves_the_flag_out_and_the_call_stays_open(self):
        box = self._box()
        command = impl._discuss_command(
            box, "Method", about="record", question="what next?")
        tokens = shlex.split(command)
        self.assertNotIn("--answer", tokens, command)

        proc = subprocess.run([sys.executable, str(CLI), *tokens[1:]],
                              capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertEqual(json.loads(proc.stdout)["status"], "open")

    def test_operand_bearing_about_round_trips(self):
        box = self._box()
        command = impl._discuss_command(
            box, "Method", about="notebook Notebooks/pilot.ipynb",
            question="does an agreement already name this notebook?")
        tokens = shlex.split(command)
        self.assertIn("--about", tokens)
        self.assertEqual(tokens[tokens.index("--about") + 1],
                         "notebook Notebooks/pilot.ipynb")


class OpenDiscussionsTests(unittest.TestCase):
    """`_open_discussions` -- the pure reader `cmd_close`'s new third axis
    is built on (spec Domain A, "Bucketing is by exact trimmed question
    text, never by witness identity"; "A bucket's state is the LAST event
    in ledger order").
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_open_discussions_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "Method").mkdir(parents=True)
        return box

    def _ledger(self, box):
        return box / "Method" / ".implementation" / "position.jsonl"

    def _append(self, box, *, asked, answered=None):
        impl_position.append_event(self._ledger(box), {
            "kind": "discuss",
            "about": {"kind": "record", "operand": None, "twostate": True},
            "asked": asked, "answered": answered,
            "status": "answered" if answered else "open",
            "at": impl._now_iso8601(),
        })

    def test_zero_events_is_zero_open(self):
        box = self._box()
        self.assertEqual(impl._open_discussions(box, "Method"), [])

    def test_exact_text_grouping_not_identity(self):
        """Mutation proof 1 (spec Test Obligations #1): every event below
        shares the identical witness identity `(kind="record",
        operand=None)` -- the measured live shape (all 27 reference-target
        `discuss` events). Swapping to identity grouping would report every
        text answered once any one of them is.
        """
        box = self._box()
        texts = [f"question {n}?" for n in range(4)]
        for text in texts:
            self._append(box, asked=text)
        self._append(box, asked=texts[0], answered="yes")

        open_texts = {item["asked"] for item in impl._open_discussions(box, "Method")}
        self.assertEqual(open_texts, set(texts[1:]))

    def test_last_word_in_ledger_order_five_open_two_answered(self):
        """Spec 'Five open, two answered, evaluates to zero open': the
        measured recurring-text shape, 7 events for one exact question --
        open, open, open, open, answered, open, answered.
        """
        box = self._box()
        text = "what should the experiment contract still add?"
        for _ in range(4):
            self._append(box, asked=text)
        self._append(box, asked=text, answered="first answer")
        self._append(box, asked=text)
        self._append(box, asked=text, answered="second answer")

        self.assertEqual(impl._open_discussions(box, "Method"), [])

    def test_ask_answer_ask_reports_open_not_answered_once(self):
        """Mutation proof 3 (spec Test Obligations #3): a fresh, unanswered
        re-ask of byte-identical text after an answer must still read open
        -- 'answered-once' would silently accept the stale answer sitting
        behind it."""
        box = self._box()
        text = "should this job rehearse before the campaign?"
        self._append(box, asked=text, answered="yes")
        self._append(box, asked=text)

        open_texts = [item["asked"] for item in impl._open_discussions(box, "Method")]
        self.assertEqual(open_texts, [text])

    def test_a_clarifying_question_never_reopens_the_original(self):
        """Doctrine preservation (spec 'A later, differently-worded question
        never reopens an earlier answered one'): `settle`'s own 'ANY
        answered event satisfies this, never newest-wins' protects a
        clarification under IDENTITY grouping; under exact-text grouping the
        clarification simply forms its own, independent bucket -- the same
        guarantee, delivered by construction rather than a second rule.
        """
        box = self._box()
        original = "should TAPER_UNDERCUT stay at 1.0?"
        clarification = "does 'stay at 1.0' mean for every family, or per family?"
        self._append(box, asked=original, answered="yes, for every family")
        self._append(box, asked=clarification)

        open_texts = [item["asked"] for item in impl._open_discussions(box, "Method")]
        self.assertEqual(open_texts, [clarification])


class DiscussCommandTests(unittest.TestCase):
    """`discuss` -- discussion as an operation with a return value (design §3.3).

    Replaces the prose at `SKILL.md`'s AGREEMENTS doctrine telling the agent to
    name a collision with an existing agreement and wait for the user: prose
    cannot be held to a return statement, so this makes "I asked" a fact with
    a ledger line instead. It never gates -- there is no refusal here for an
    unanswered question, only a reported `status`.
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_discuss_cmd_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        return box

    def run_cli(self, *args, stdin=None):
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE)

    # --- 5.1: collides is computed fresh each call, never remembered ---

    def test_discuss_computes_collides_not_remembers(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n"
            "- [x] Read the pilot notebook, Notebooks/pilot.ipynb, into the report.\n",
            encoding="utf-8")

        first = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                             "--about", "notebook Notebooks/pilot.ipynb",
                             "--question", "Does an agreement already name this notebook?")
        self.assertEqual(first.returncode, 0, first.stdout)
        first_result = json.loads(first.stdout)
        self.assertEqual(len(first_result["collides"]), 1)
        self.assertIn("Notebooks/pilot.ipynb", first_result["collides"][0])

        # The identical call, after the collision is edited out of the file --
        # if `collides` were remembered from the first call rather than
        # computed fresh, it would still report one here.
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n- [x] Something unrelated.\n", encoding="utf-8")
        second = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                              "--about", "notebook Notebooks/pilot.ipynb",
                              "--question", "Does an agreement already name this notebook?")
        self.assertEqual(second.returncode, 0, second.stdout)
        self.assertEqual(json.loads(second.stdout)["collides"], [])

    # --- 5.2: open, then answered -- a real status transition ---

    def test_discuss_open_then_answered_status_transition(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text("# Agreed\n", encoding="utf-8")

        opened = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                              "--about", "rehearsal governing-search",
                              "--question", "Should this job rehearse before the campaign?")
        self.assertEqual(opened.returncode, 0, opened.stdout)
        opened_result = json.loads(opened.stdout)
        self.assertEqual(opened_result["status"], "open")
        self.assertIsNone(opened_result["answered"])

        answered = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                                "--about", "rehearsal governing-search",
                                "--question", "Should this job rehearse before the campaign?",
                                "--answer", "Yes, rehearse it first.")
        self.assertEqual(answered.returncode, 0, answered.stdout)
        answered_result = json.loads(answered.stdout)
        self.assertEqual(answered_result["status"], "answered")
        self.assertEqual(answered_result["answered"], "Yes, rehearse it first.")

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        self.assertEqual([e["kind"] for e in events], ["discuss", "discuss"])
        self.assertEqual([e["status"] for e in events], ["open", "answered"])

    def test_discuss_about_accepts_an_ordinal_into_the_position_sequence(self):
        """The other half of `--about <ordinal|witness>` (design §3.3): a
        caller may name a step by its number instead of repeating its witness.
        """
        box = self._box()
        header = {"revision": "r1.md", "revisionSha256": "a" * 64,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        proc = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                            "--about", "1", "--question", "Is job1 the right job?")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["about"], {"ordinal": 1, "kind": "rehearsal",
                                           "operand": "job1", "twostate": True})

    def test_discuss_refuses_an_ordinal_not_in_the_sequence(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text("# Agreed\n", encoding="utf-8")
        proc = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                            "--about", "9", "--question", "What is step 9?")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "DISCUSS_ABOUT_NOT_FOUND")

    # --- the cause fix: self-collision, operand-less witnesses, the bare-kind refusal ---

    def test_discuss_about_an_ordinal_never_collides_with_its_own_line(self):
        """Measured: the item's own witness operand ("job1") is a substring
        of its own rendered line -- the witness token itself, backticks
        included -- so a collision search that scanned the whole file,
        block included, always reported the item colliding with itself.
        """
        box = self._box()
        header = {"revision": "r1.md", "revisionSha256": "a" * 64,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        proc = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                            "--about", "1", "--question", "Is job1 the right job?")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["collides"], [])

    def test_about_record_reports_the_collision_search_as_unperformed(self):
        """`record` is the one operand-less `WITNESS_KINDS` member (design's
        own decision): a falsy operand means the search literally could not
        run, and `[]` alone would read exactly like "ran and found nothing".
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text("# Agreed\n", encoding="utf-8")
        proc = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                            "--about", "record",
                            "--question", "Does the record satisfy the contract?")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["collides"], [])
        self.assertEqual(result["collisionSearch"], "unperformed")

    def test_about_notebook_with_no_operand_is_refused(self):
        """The third defect, measured with a fixture built to discriminate.
        The holder's agreement text names the exact operand a correct call
        would search for -- a fixture that omits it cannot tell "the search
        ran and found nothing" apart from "nothing ran", which is exactly
        why the discriminating half below is required alongside this one.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n"
            "- [ ] Notebooks/verification.ipynb runs against this tree\n",
            encoding="utf-8")
        proc = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                            "--about", "notebook",
                            "--question", "Does this discuss the right notebook?")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"],
                         "DISCUSS_ABOUT_OPERAND_REQUIRED")

    def test_about_notebook_with_an_operand_performs_the_search(self):
        """The discriminating half of the same fixture: with the operand
        present, the search runs and finds the collision it was built to
        find -- proof the refusal above fires before any search ever runs,
        not merely on an empty result.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n"
            "- [ ] Notebooks/verification.ipynb runs against this tree\n",
            encoding="utf-8")
        proc = self.run_cli("discuss", "--target", str(box), "--name", "Method",
                            "--about", "notebook Notebooks/verification.ipynb",
                            "--question", "Does this discuss the right notebook?")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(len(result["collides"]), 1)
        self.assertEqual(result["collisionSearch"], "performed")


class SettleCommandTests(unittest.TestCase):
    """`settle` -- the placer (design "the placer", spec domain
    `agreement-placement`). The agent drafts a discussion and a proposed
    sentence; `settle` validates, refuses, and performs the one write --
    exactly one unticked `- [ ] <text>` line, verbatim, under a
    caller-named heading, gated on an answered `discuss` event it cannot
    mint from its own argv.
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_settle_cmd_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        return box

    def run_cli(self, *args, stdin=None):
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE)

    def _discuss(self, box, about, question="Should this be settled?", answer=None):
        args = ["discuss", "--target", str(box), "--name", "Method",
                "--about", about, "--question", question]
        if answer is not None:
            args += ["--answer", answer]
        proc = self.run_cli(*args)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        return json.loads(proc.stdout)

    def _settle(self, box, **overrides):
        args = {"target": str(box), "name": "Method", "session": "s1",
                "about": "record", "text": "New text", "under": "## Ladder"}
        args.update(overrides)
        argv = ["settle"]
        for flag, value in args.items():
            if value is None or value is False:
                continue
            if value is True:
                argv += [f"--{flag}"]
                continue
            argv += [f"--{flag}", value]
        return self.run_cli(*argv)

    # --- pure-argv refusals, checked before anything is read from disk ---

    def test_settle_refuses_stdin_conflict(self):
        proc = self._settle(self._box(), text="-", supersedes="-")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_STDIN_CONFLICT")

    def test_settle_refuses_empty_text(self):
        proc = self._settle(self._box(), text="   ")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_EMPTY_TEXT")

    def test_settle_refuses_paragraph_without_reverse(self):
        """--paragraph only ever feeds a NEW ## Reversed entry; only
        --reverse writes one, so the create path refuses it rather than
        silently ignoring a flag the caller bothered to type -- the
        identical discipline SETTLE_STDIN_CONFLICT already keeps one
        level up."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box, paragraph="unused prose")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REVERSE_CONFLICT")

    # --- the discussion gate ---

    def test_settle_refuses_not_discussed(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_NOT_DISCUSSED")

    def test_settle_refuses_discussion_unanswered(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_DISCUSSION_UNANSWERED")

    def test_settle_succeeds_when_the_answered_event_is_not_the_newest_one(self):
        """Design decision "Discussion match": ANY answered event
        satisfies, never newest-wins. A later clarifying question left
        open must not retroactively erase an earlier answer -- if it did,
        this would teach a caller not to ask one.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record", question="First question?", answer="Yes.")
        self._discuss(box, "record", question="A later clarifying question?")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["status"], "written")

    def test_settle_refuses_not_discussed_when_only_the_operand_differs(self):
        """The witness identity is `(kind, operand)`, both fields -- a
        discussion about one notebook must never authorize a placement
        about a different one just because the kind matches.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "notebook Notebooks/a.ipynb", answer="Yes.")
        proc = self._settle(box, about="notebook Notebooks/b.ipynb")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_NOT_DISCUSSED")

    # --- where the placement would even go ---

    def test_settle_refuses_holder_absent(self):
        box = self._box()
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HOLDER_ABSENT")

    def test_settle_refuses_heading_absent(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box, under="## Nowhere")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HEADING_ABSENT")

    def test_settle_refuses_heading_ambiguous(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a\n\n## Ladder\n\n- [ ] b\n",
            encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HEADING_AMBIGUOUS")

    def test_settle_refuses_a_heading_inside_a_fenced_code_block(self):
        """Design decision "Fenced regions": a heading-shaped line that
        exists only inside a fenced block must read as absent, not as the
        one hit that would land a placement inside the fence.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n```\n## Ladder\n```\n\n- [ ] placeholder\n",
            encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HEADING_ABSENT")

    # --- a collision must be named, not silently overwritten ---

    def test_settle_refuses_collides_unnamed(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n"
            "- [x] existing item mentioning Notebooks/verification.ipynb\n",
            encoding="utf-8")
        self._discuss(box, "notebook Notebooks/verification.ipynb", answer="Yes.")
        proc = self._settle(box, about="notebook Notebooks/verification.ipynb")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_COLLIDES_UNNAMED")

    def test_settle_collides_unnamed_names_every_colliding_text(self):
        """Spec Domain B, 'A settle collision publishes a specific, runnable
        discuss command': the refusal enumerates every colliding text, not
        `len(collides)` (design D5 -- excluded source)."""
        box = self._box()
        first = "first item mentioning Notebooks/verification.ipynb"
        second = "second item also mentioning Notebooks/verification.ipynb"
        (box / "Method" / "AGREED.md").write_text(
            f"# Agreed\n\n## Ladder\n\n- [x] {first}\n- [ ] {second}\n",
            encoding="utf-8")
        self._discuss(box, "notebook Notebooks/verification.ipynb", answer="Yes.")
        proc = self._settle(box, about="notebook Notebooks/verification.ipynb")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        body = json.loads(proc.stdout)
        self.assertEqual(body["code"], "SETTLE_COLLIDES_UNNAMED")
        self.assertIn(first, body["detail"])
        self.assertIn(second, body["detail"])
        self.assertNotIn("2 existing agreement(s)", body["detail"])

    def test_settle_collides_unnamed_publishes_a_runnable_discuss_command(self):
        """Mutation proof groundwork (spec Test Obligations #6): the
        collision refusal also prints a directly runnable `discuss` command
        naming the operand and both colliding texts, executed as a
        subprocess -- not merely read as text -- the same discipline
        `test_close_discussion_refusal_prints_a_runnable_apostrophe_
        bearing_retirement` already applies to Half 1's retirement command.
        """
        box = self._box()
        first = "first item mentioning Notebooks/verification.ipynb"
        second = "second item also mentioning Notebooks/verification.ipynb"
        (box / "Method" / "AGREED.md").write_text(
            f"# Agreed\n\n## Ladder\n\n- [x] {first}\n- [ ] {second}\n",
            encoding="utf-8")
        self._discuss(box, "notebook Notebooks/verification.ipynb", answer="Yes.")
        proc = self._settle(box, about="notebook Notebooks/verification.ipynb")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        body = json.loads(proc.stdout)

        line = next(l for l in body["detail"].splitlines()
                    if "implementation_cli.py discuss" in l)
        tokens = shlex.split(line)
        self.assertEqual(tokens[tokens.index("--target") + 1], str(box))
        self.assertEqual(tokens[tokens.index("--name") + 1], "Method")
        question = tokens[tokens.index("--question") + 1]
        self.assertIn(first, question)
        self.assertIn(second, question)

        run = self.run_cli(*tokens[1:])
        self.assertEqual(run.returncode, 0, run.stdout + run.stderr)
        self.assertEqual(json.loads(run.stdout)["asked"], question)

    def test_settle_collides_command_is_runnable_for_an_apostrophe_bearing_text(self):
        """Mutation proof 6 (spec Test Obligations #6, apostrophe form): a
        colliding text containing an ASCII apostrophe must still produce a
        runnable command -- executed as a subprocess, the same discipline
        `mutation proof 5` already applies to Half 1."""
        box = self._box()
        first = "the target's own item mentioning Notebooks/verification.ipynb"
        (box / "Method" / "AGREED.md").write_text(
            f"# Agreed\n\n## Ladder\n\n- [x] {first}\n", encoding="utf-8")
        self._discuss(box, "notebook Notebooks/verification.ipynb", answer="Yes.")
        proc = self._settle(box, about="notebook Notebooks/verification.ipynb")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        body = json.loads(proc.stdout)
        self.assertIn(first, body["detail"])

        line = next(l for l in body["detail"].splitlines()
                    if "implementation_cli.py discuss" in l)
        tokens = shlex.split(line)
        run = self.run_cli(*tokens[1:])
        self.assertEqual(run.returncode, 0, run.stdout + run.stderr)
        self.assertIn(first, json.loads(run.stdout)["asked"])

    def test_settle_collision_question_is_stable_across_calls_with_unrelated_state_changes(self):
        """Spec 'Published question text MUST be reproducible from stable
        identity alone': derived from operand + sorted colliding texts only
        (design D5). An unrelated, later `discuss` event landing on the
        SAME ledger between the two calls must not change one byte of the
        collision question."""
        box = self._box()
        first = "first item mentioning Notebooks/verification.ipynb"
        (box / "Method" / "AGREED.md").write_text(
            f"# Agreed\n\n## Ladder\n\n- [x] {first}\n", encoding="utf-8")
        self._discuss(box, "notebook Notebooks/verification.ipynb", answer="Yes.")
        first_proc = self._settle(box, about="notebook Notebooks/verification.ipynb")
        self.assertEqual(first_proc.returncode, 2, first_proc.stdout)
        before = json.loads(first_proc.stdout)["detail"]

        # Unrelated ledger growth between the two calls -- a fresh, distinct
        # discuss bucket about a different witness identity entirely.
        self._discuss(box, "record", question="an unrelated question?")

        second_proc = self._settle(box, about="notebook Notebooks/verification.ipynb")
        self.assertEqual(second_proc.returncode, 2, second_proc.stdout)
        after = json.loads(second_proc.stdout)["detail"]
        self.assertEqual(before, after)

    def test_settle_collision_question_changes_when_a_new_colliding_agreement_is_added(self):
        """The one legitimate exception (spec, design D5): a genuinely NEW
        colliding agreement changes the collision question's text, and that
        is correct -- it is a different decision, not the same one restated.
        """
        box = self._box()
        first = "first item mentioning Notebooks/verification.ipynb"
        (box / "Method" / "AGREED.md").write_text(
            f"# Agreed\n\n## Ladder\n\n- [x] {first}\n", encoding="utf-8")
        self._discuss(box, "notebook Notebooks/verification.ipynb", answer="Yes.")
        first_proc = self._settle(box, about="notebook Notebooks/verification.ipynb")
        self.assertEqual(first_proc.returncode, 2, first_proc.stdout)
        before = json.loads(first_proc.stdout)["detail"]

        second = "second item also mentioning Notebooks/verification.ipynb"
        text = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        (box / "Method" / "AGREED.md").write_text(
            text + f"- [ ] {second}\n", encoding="utf-8")

        second_proc = self._settle(box, about="notebook Notebooks/verification.ipynb")
        self.assertEqual(second_proc.returncode, 2, second_proc.stdout)
        after = json.loads(second_proc.stdout)["detail"]
        self.assertNotEqual(before, after)
        self.assertIn(second, after)

    def test_settle_refuses_supersedes_unknown(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n"
            "- [x] existing item mentioning Notebooks/verification.ipynb\n",
            encoding="utf-8")
        self._discuss(box, "notebook Notebooks/verification.ipynb", answer="Yes.")
        proc = self._settle(box, about="notebook Notebooks/verification.ipynb",
                            supersedes="text nobody wrote")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_SUPERSEDES_UNKNOWN")

    def test_settle_accepts_an_exact_matching_supersedes_and_writes(self):
        box = self._box()
        colliding = "existing item mentioning Notebooks/verification.ipynb"
        (box / "Method" / "AGREED.md").write_text(
            f"# Agreed\n\n## Ladder\n\n- [x] {colliding}\n", encoding="utf-8")
        self._discuss(box, "notebook Notebooks/verification.ipynb", answer="Yes.")
        proc = self._settle(box, about="notebook Notebooks/verification.ipynb",
                            supersedes=colliding)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["supersedes"], colliding)
        self.assertEqual(result["collides"], [colliding])

    # --- the happy path: byte-identical except one inserted unticked line ---

    def test_settle_writes_exactly_one_unticked_line_byte_identical_otherwise(self):
        box = self._box()
        before = ("# Agreed\n\nSome prose above the section.\n\n"
                  "## Ladder\n\n- [x] an unrelated settled item\n\n"
                  "## Reversed\n\nA hand-written paragraph.\n")
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box, text="the free scalar stays at its neutral")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")

        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        expected = before.replace(
            "## Ladder\n\n",
            "## Ladder\n\n- [ ] the free scalar stays at its neutral\n")
        self.assertEqual(after, expected)

    def test_settle_never_writes_a_ticked_mark(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box, text="arbitrary caller text, [x] included in prose")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("- [ ] arbitrary caller text, [x] included in prose", after)
        self.assertNotIn("- [x] arbitrary caller text", after)

    def test_settle_appends_one_settle_event_with_no_id_key(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        settle_events = [e for e in events if e["kind"] == "settle"]
        self.assertEqual(len(settle_events), 1)
        self.assertNotIn("id", settle_events[0])

    # --- the witness token (design D5, spec Groups 3 & 5) ---

    def test_settle_omitting_witness_writes_the_byte_identical_bare_line(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box, text="a bare agreement")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("- [ ] a bare agreement\n", after)
        self.assertNotIn("`", after)
        self.assertIsNone(json.loads(proc.stdout)["witness"])

    def test_settle_with_witness_persists_it_into_the_written_line(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box, text="a witnessed agreement",
                            witness="test_the_thing")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["witness"], "test_the_thing")
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn(
            "- [ ] a witnessed agreement `test_the_thing`\n", after)

        # Read back without consulting the ledger (spec "the binding
        # survives the write").
        state = impl.agreements_state(box, "Method")
        self.assertEqual(state["witness"]["unmeasured"],
                         ["a witnessed agreement"])

    def test_settle_refuses_a_malformed_witness(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self._discuss(box, "record", answer="Yes.")
        proc = self._settle(box, witness="not-a-valid-token")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_WITNESS_MALFORMED")
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertNotIn("not-a-valid-token", after)

    # --- the reused compare-and-swap ---

    def test_settle_refuses_position_holder_moved_on_a_concurrent_write(self):
        """`POSITION_HOLDER_MOVED` is reused, not minted fresh
        (design "POSITION_HOLDER_MOVED reused"): `write_spliced`'s own
        compare-and-swap fires unchanged when the holder changes between
        the read `settle` located its heading against and the write --
        the identical mechanism `WriteSplicedCasTests` proves at the
        primitive level, exercised here through the whole `cmd_settle`
        path so the wiring itself is checked too.
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n", encoding="utf-8")
        self.run_cli("discuss", "--target", str(box), "--name", "Method",
                    "--about", "record", "--question", "q?", "--answer", "a")

        real_locate = impl_position.locate_headings

        def racing_locate(data, heading):
            (box / "Method" / "AGREED.md").write_text(
                "# Agreed\n\n## Ladder\n\n- [ ] placeholder\n"
                "- [ ] a concurrent edit nobody told settle about\n",
                encoding="utf-8")
            return real_locate(data, heading)

        args = argparse.Namespace(
            target=str(box), name="Method", session="s1", about="record",
            text="New text", under="## Ladder", supersedes=None)
        with unittest.mock.patch.object(
                impl_position, "locate_headings", side_effect=racing_locate):
            with self.assertRaises(impl.Refused) as ctx:
                impl.cmd_settle(args)
        self.assertEqual(ctx.exception.code, "POSITION_HOLDER_MOVED")
        # Refused before any write -- the concurrent edit above is the only
        # change on disk, byte-identical to what the racing write itself wrote.
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("a concurrent edit nobody told settle about", after)
        self.assertNotIn("New text", after)


class VerifyToDiscussTests(unittest.TestCase):
    """`verify`'s new top-level `toDiscuss` key (spec Domain B, 'Verify
    publishes one discuss command per unwritten local remedy finding';
    design D1's new top-level publication surface). One command per
    `audit.localRemediesNotWritten` finding id, and no command at all for
    `prose.staleRevisions`/`unresolvedSymbols` or
    `agreements.witness.unwitnessed` -- both explicitly excluded (spec).
    """

    def _box(self, findings_src: str, extra_files: dict | None = None) -> Path:
        box = FORGE / "implementations" / f"_verify_todiscuss_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            "", encoding="utf-8")
        (box / "tests" / "findings.py").write_text(findings_src, encoding="utf-8")
        for relative, content in (extra_files or {}).items():
            path = box / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
        return box

    def _verify(self, box: Path) -> dict:
        return impl.cmd_verify(
            argparse.Namespace(target=str(box), name="Method", revision=None))

    def test_each_unwritten_local_remedy_gets_its_own_discuss_command(self):
        """Spec scenario 'Each unwritten local remedy gets its own
        command': `audit.localRemediesNotWritten: ["finding_7",
        "finding_12"]` -> two distinct commands, neither a generic
        question, each naming its own finding id."""
        findings = (
            "FINDINGS = [\n"
            "    {'id': 'finding_7'},\n"
            "    {'id': 'finding_12'},\n"
            "]\n"
        )
        box = self._box(findings)
        result = self._verify(box)
        self.assertEqual(result["audit"]["localRemediesNotWritten"],
                         ["finding_7", "finding_12"])
        to_discuss = result["toDiscuss"]
        self.assertEqual(len(to_discuss), 2)
        questions = {entry["about"]["operand"]: entry["question"] for entry in to_discuss}
        self.assertEqual(set(questions), {"finding_7", "finding_12"})
        self.assertIn("finding_7", questions["finding_7"])
        self.assertIn("finding_12", questions["finding_12"])
        self.assertNotEqual(questions["finding_7"], questions["finding_12"])
        for entry in to_discuss:
            self.assertIn("implementation_cli.py discuss", entry["command"])
            self.assertIn(str(box), entry["command"])

    def test_toDiscuss_commands_are_runnable_and_append_the_exact_question(self):
        findings = "FINDINGS = [\n    {'id': 'finding_alone'},\n]\n"
        box = self._box(findings)
        result = self._verify(box)
        entry = result["toDiscuss"][0]
        tokens = shlex.split(entry["command"])
        proc = subprocess.run([sys.executable, str(CLI), *tokens[1:]],
                              capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertEqual(json.loads(proc.stdout)["asked"], entry["question"])

    def test_a_finding_id_with_an_apostrophe_still_publishes_a_runnable_command(self):
        """Reuses Half 1's `shlex.quote` discipline (spec 'Every command
        published under this domain reuses the identical shlex.quote
        discipline as Half 1')."""
        findings = "FINDINGS = [\n    {'id': \"the target's finding\"},\n]\n"
        box = self._box(findings)
        result = self._verify(box)
        entry = result["toDiscuss"][0]
        tokens = shlex.split(entry["command"])
        proc = subprocess.run([sys.executable, str(CLI), *tokens[1:]],
                              capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertIn("the target's finding", json.loads(proc.stdout)["asked"])

    def test_prose_and_unwitnessed_findings_publish_no_discuss_command(self):
        """Spec 'prose.staleRevisions and prose.unresolvedSymbols MUST NOT
        publish a discuss action' and 'agreements.witness.unwitnessed MUST
        NOT publish a discuss action' -- both present and non-empty
        alongside one genuine local-remedy finding, and `toDiscuss` still
        holds exactly one entry, addressed to that finding alone."""
        findings = "FINDINGS = [\n    {'id': 'only_local_finding'},\n]\n"
        box = self._box(findings, extra_files={
            "Method/notes.md": "See `not_a_real_symbol` for details.\n",
            "Method/AGREED.md": "# Agreed\n\n## Ladder\n\n"
                               "- [ ] an unwitnessed agreement item\n",
        })
        result = self._verify(box)
        self.assertTrue(result["prose"]["unresolvedSymbols"],
                        "fixture must actually trigger unresolvedSymbols")
        self.assertTrue(result["agreements"]["witness"]["unwitnessed"],
                        "fixture must actually trigger unwitnessed")
        to_discuss = result["toDiscuss"]
        self.assertEqual(len(to_discuss), 1)
        self.assertEqual(to_discuss[0]["about"]["operand"], "only_local_finding")
        for entry in to_discuss:
            self.assertNotIn("not_a_real_symbol", entry["question"])
            self.assertNotIn("unwitnessed", entry["question"])

    def test_toDiscuss_question_is_stable_across_calls_with_changed_surrounding_state(self):
        """Spec 'Published question text MUST be reproducible from stable
        identity alone': derived from the finding id alone (design D5).
        Adding an unrelated, already-adopted second finding between the two
        `verify` calls must not change one byte of the first finding's own
        question."""
        findings_one = "FINDINGS = [\n    {'id': 'only_local_finding'},\n]\n"
        box = self._box(findings_one)
        first = self._verify(box)
        before = first["toDiscuss"][0]["question"]
        before_command = first["toDiscuss"][0]["command"]

        findings_two = (
            "FINDINGS = [\n"
            "    {'id': 'only_local_finding'},\n"
            "    {'id': 'a_second_finding', 'equations': ['1.1'],\n"
            "     'remedy_equations': ['1.1'], 'introduces': ['x'],\n"
            "     'remedy_block': 'written'},\n"
            "]\n"
        )
        (box / "tests" / "findings.py").write_text(findings_two, encoding="utf-8")
        second = self._verify(box)
        entries = [e for e in second["toDiscuss"]
                  if e["about"]["operand"] == "only_local_finding"]
        self.assertEqual(len(entries), 1)
        self.assertEqual(before, entries[0]["question"])
        self.assertEqual(before_command, entries[0]["command"])


class SettleAttachCommandTests(unittest.TestCase):
    """`settle --attach` -- binds a witness onto a line ALREADY settled,
    matched by its exact `--text`, instead of placing a new one (design
    "attach, not place"). This is the missing half of the programme this
    change closes: `settle --text` only ever creates; nothing before this
    could attach a witness to what a target already had settled by hand
    or by a prior `settle` call made before `--witness` existed.
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_settle_attach_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        return box

    def run_cli(self, *args, stdin=None):
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE)

    def _settle(self, box, **overrides):
        args = {"target": str(box), "name": "Method", "session": "s1",
                "attach": True, "text": "an already-settled item",
                "witness": "test_the_thing"}
        args.update(overrides)
        argv = ["settle"]
        for flag, value in args.items():
            if value is None or value is False:
                continue
            if value is True:
                argv += [f"--{flag}"]
                continue
            argv += [f"--{flag}", value]
        return self.run_cli(*argv)

    # --- the search: matched by exact text, same discipline as headings ---

    def test_attach_refuses_when_text_matches_zero_lines(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [x] a different item\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_ABSENT")

    def test_attach_refuses_when_text_matches_more_than_one_line(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item\n\n"
            "## Reversed\n\n- [x] an already-settled item\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_AMBIGUOUS")

    def test_attach_refuses_when_the_line_already_carries_a_witness(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n"
            "- [x] an already-settled item `test_prior_witness`\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_ALREADY_WITNESSED")
        # Refused before any write.
        after = (box / "Method" / "AGREED.md").read_bytes()
        before = (b"# Agreed\n\n## Ladder\n\n"
                  b"- [x] an already-settled item `test_prior_witness`\n")
        self.assertEqual(after, before)

    def test_attach_refuses_holder_absent(self):
        box = self._box()
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HOLDER_ABSENT")

    # --- pure-argv shape ---

    def test_attach_refuses_without_witness(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item\n",
            encoding="utf-8")
        proc = self._settle(box, witness=None)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_WITNESS_REQUIRED")

    def test_attach_refuses_a_malformed_witness(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item\n",
            encoding="utf-8")
        proc = self._settle(box, witness="not-a-valid-token")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_WITNESS_MALFORMED")

    def test_attach_refuses_combined_with_under(self):
        box = self._box()
        proc = self._settle(box, under="## Ladder")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_ATTACH_CONFLICT")

    def test_attach_refuses_combined_with_supersedes(self):
        box = self._box()
        proc = self._settle(box, supersedes="some other text")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_ATTACH_CONFLICT")

    # --- the design decision: no discussion precondition for --attach ---

    def test_attach_succeeds_with_zero_discuss_events_ever_recorded(self):
        """The whole point: a line already settled was already discussed
        and already placed at the time `settle` first wrote it. Attaching
        a witness to it now must never require a fresh `discuss` call --
        proven here by an empty ledger (no position.jsonl at all).
        """
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item\n",
            encoding="utf-8")
        ledger = box / "Method" / ".implementation" / "position.jsonl"
        self.assertFalse(ledger.exists())
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["status"], "written")

    # --- the happy path: byte-identical except the appended witness ---

    def test_attach_preserves_an_open_mark_byte_identical_otherwise(self):
        box = self._box()
        before = ("# Agreed\n\nSome prose above the section.\n\n"
                  "## Ladder\n\n- [ ] an already-settled item\n\n"
                  "## Reversed\n\nA hand-written paragraph.\n")
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["attach"], True)
        self.assertEqual(result["witness"], "test_the_thing")

        after = (box / "Method" / "AGREED.md").read_bytes()
        expected = before.replace(
            "- [ ] an already-settled item\n",
            "- [ ] an already-settled item `test_the_thing`\n").encode("utf-8")
        self.assertEqual(after, expected)

    def test_attach_preserves_a_ticked_mark_byte_identical_otherwise(self):
        """A ticked item stays ticked -- `--attach` never authors or
        removes a tick, only the create path's own `[ ]` restriction is
        about NEW items; this line was already `[x]` before this call.
        """
        box = self._box()
        before = ("# Agreed\n\n## Ladder\n\n"
                  "- [x] an already-settled item\n\n"
                  "## Reversed\n\nA hand-written paragraph.\n")
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        after = (box / "Method" / "AGREED.md").read_bytes()
        expected = before.replace(
            "- [x] an already-settled item\n",
            "- [x] an already-settled item `test_the_thing`\n").encode("utf-8")
        self.assertEqual(after, expected)

    def test_attach_appends_one_settle_event_flagged_attach_true(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        settle_events = [e for e in events if e["kind"] == "settle"]
        self.assertEqual(len(settle_events), 1)
        self.assertEqual(settle_events[0]["attach"], True)
        self.assertIsNone(settle_events[0]["about"])
        self.assertIsNone(settle_events[0]["under"])

    def test_attach_read_back_by_agreements_state_without_the_ledger(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        state = impl.agreements_state(box, "Method")
        self.assertEqual(state["witness"]["unmeasured"],
                         ["an already-settled item"])


class SettleReversedQuoteMatchingTests(unittest.TestCase):
    """The pure predicate `settle --remove`'s own guard evaluates:
    whether `--text` is quoted, bold, inside the document's own
    `## Reversed` section -- possibly truncated with a trailing
    ellipsis (design "the guard removal must pass", see `cmd_settle`'s
    own docstring). Tested directly against `impl._reversed_quote_matches_text`,
    without a CLI round-trip: the `SettleRemoveCommandTests` class below
    proves the WIRING (the guard is actually consulted, in the right
    order, against the right file); these prove the RULE itself, cheaply,
    over inputs a full CLI fixture would make tedious to vary.
    """

    def test_exact_bold_quote_matches(self):
        data = b'## Reversed\n\n**"the exact text"** replaced by something else.\n'
        self.assertTrue(impl._reversed_quote_matches_text(data, "the exact text"))

    def test_unrelated_bold_quote_does_not_match(self):
        data = b'## Reversed\n\n**"something else entirely"** replaced.\n'
        self.assertFalse(impl._reversed_quote_matches_text(data, "the exact text"))

    def test_no_reversed_section_at_all_does_not_match(self):
        data = b"## Ladder\n\n- [ ] the exact text\n"
        self.assertFalse(impl._reversed_quote_matches_text(data, "the exact text"))

    def test_bold_quote_under_a_differently_named_heading_does_not_match(self):
        """Exact heading equality, the same discipline
        `impl_position.locate_headings` already states for `--under`: a
        section merely named something else must never authorize
        removal, even if it quotes the identical text."""
        data = b'## Retired\n\n**"the exact text"** replaced.\n'
        self.assertFalse(impl._reversed_quote_matches_text(data, "the exact text"))

    def test_truncated_quote_matches_by_exact_prefix(self):
        data = b'## Reversed\n\n**"the exact..."** replaced by something shorter.\n'
        self.assertTrue(impl._reversed_quote_matches_text(data, "the exact text"))

    def test_truncated_quote_with_a_wrong_prefix_does_not_match(self):
        """The trailing ellipsis alone proves nothing -- what precedes it
        must be an actual prefix of `--text`, or an unrelated truncated
        quote that merely happens to end in "..." would authorize
        removing an agreement it never actually named."""
        data = b'## Reversed\n\n**"nothing alike at all..."** replaced.\n'
        self.assertFalse(impl._reversed_quote_matches_text(data, "the exact text"))

    def test_truncated_quote_matches_by_unicode_ellipsis_too(self):
        data = '## Reversed\n\n**"the exact…"** replaced.\n'.encode("utf-8")
        self.assertTrue(impl._reversed_quote_matches_text(data, "the exact text"))


class SettleRemoveCommandTests(unittest.TestCase):
    """`settle --remove` -- deletes a line ALREADY settled, matched by its
    exact `--text` (design "the eraser", the destructive counterpart to
    "attach, not place"). The one write path this CLI has never had until
    now: every other `settle` mode only ever adds bytes. Guarded on
    purpose -- refused `SETTLE_NOT_REVERSED` unless the document's own
    `## Reversed` section already quotes the exact text being removed
    (see `cmd_settle`'s own docstring for the full argument).
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_settle_remove_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        return box

    def run_cli(self, *args, stdin=None):
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE)

    def _settle(self, box, **overrides):
        args = {"target": str(box), "name": "Method", "session": "s1",
                "remove": True, "text": "a retired agreement"}
        args.update(overrides)
        argv = ["settle"]
        for flag, value in args.items():
            if value is None or value is False:
                continue
            if value is True:
                argv += [f"--{flag}"]
                continue
            argv += [f"--{flag}", value]
        return self.run_cli(*argv)

    REVERSED_QUOTE = ('\n\n## Reversed\n\n'
                      '**"a retired agreement"** replaced by something better.\n')

    # --- pure-argv shape: --remove needs nothing else, and refuses ---
    # --- whatever the create/attach paths need but this one doesn't ---

    def test_remove_refuses_combined_with_attach(self):
        box = self._box()
        proc = self._settle(box, attach=True, witness="test_x")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REMOVE_CONFLICT")

    def test_remove_refuses_combined_with_under(self):
        box = self._box()
        proc = self._settle(box, under="## Ladder")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REMOVE_CONFLICT")

    def test_remove_refuses_combined_with_supersedes(self):
        box = self._box()
        proc = self._settle(box, supersedes="some other text")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REMOVE_CONFLICT")

    def test_remove_refuses_combined_with_witness(self):
        box = self._box()
        proc = self._settle(box, witness="test_x")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REMOVE_CONFLICT")

    # --- where the removal would even happen ---

    def test_remove_refuses_holder_absent(self):
        box = self._box()
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HOLDER_ABSENT")

    # --- the search: matched by exact text, same discipline as --attach ---

    def test_remove_refuses_when_text_matches_zero_lines(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a different item\n" + self.REVERSED_QUOTE,
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_ABSENT")

    def test_remove_refuses_when_text_matches_more_than_one_line(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
            "## Elsewhere\n\n- [x] a retired agreement\n" + self.REVERSED_QUOTE,
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_AMBIGUOUS")

    def test_remove_never_matches_a_position_block_item(self):
        """`_agreement_scan_text`'s own exclusion, reused unchanged via
        `_locate_settled_text` -- the identical function `--attach`
        already searches with. A position sequence item has exactly
        `AGREEMENT_LINE`'s shape, and must never read as a removable
        agreement even when the `## Reversed` section quotes its text."""
        box = self._box()
        block = ("<!-- position revision=r1.md sha256=" + "a" * 64 +
                "  derivedAt=2026-08-27T00:00:00Z session=s0 target=final -->\n"
                "- [ ] 1. a position sequence item. `@notebook Notebooks/x.ipynb`\n"
                "<!-- /position -->\n")
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [x] an unrelated real agreement\n\n" +
            block +
            "\n## Reversed\n\n"
            "**\"1. a position sequence item. `@notebook Notebooks/x.ipynb`\"** "
            "never agreed, never removable.\n",
            encoding="utf-8")
        proc = self._settle(
            box, text="1. a position sequence item. `@notebook Notebooks/x.ipynb`")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_ABSENT")

    # --- the guard: refused unless the document already reversed it ---

    def test_remove_refuses_when_not_quoted_in_reversed_section_at_all(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_NOT_REVERSED")
        # Refused before any write.
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("- [ ] a retired agreement", after)

    def test_remove_refuses_when_reversed_section_quotes_different_text(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
            "## Reversed\n\n**\"a completely different agreement\"** replaced.\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_NOT_REVERSED")

    def test_remove_accepts_a_truncated_quote_ending_in_ellipsis(self):
        box = self._box()
        long_text = ("a very long retired agreement whose reversal paragraph "
                    "elides the tail")
        before = ("# Agreed\n\n## Ladder\n\n"
                  f"- [ ] {long_text}\n\n"
                  "## Reversed\n\n"
                  '**"a very long retired agreement whose reversal..."** '
                  "replaced by something shorter.\n")
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box, text=long_text)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertNotIn(long_text, after)

    # --- the happy path: byte-identical except the one deleted line ---

    def test_remove_deletes_exactly_one_line_byte_identical_otherwise(self):
        box = self._box()
        before = ("# Agreed\n\nSome prose above the section.\n\n"
                  "## Ladder\n\n- [x] an unrelated settled item\n\n"
                  "- [ ] a retired agreement\n\n"
                  "## Reversed\n\n"
                  '**"a retired agreement"** replaced by something better.\n')
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["remove"], True)
        self.assertEqual(result["text"], "a retired agreement")

        after = (box / "Method" / "AGREED.md").read_bytes()
        expected = before.replace("- [ ] a retired agreement\n", "").encode("utf-8")
        self.assertEqual(after, expected)

    def test_remove_preserves_a_ticked_neighbor_and_the_position_block(self):
        """No reflow: an unrelated item above AND a position block below
        the deleted line both come out byte-identical."""
        box = self._box()
        block = ("<!-- position revision=r1.md sha256=" + "a" * 64 +
                "  derivedAt=2026-08-27T00:00:00Z session=s0 target=final -->\n"
                "- [ ] 1. an unrelated position item. `@notebook Notebooks/x.ipynb`\n"
                "<!-- /position -->\n")
        before = ("# Agreed\n\n## Ladder\n\n- [x] an unrelated settled item\n\n"
                  "- [ ] a retired agreement\n\n" + block +
                  "\n## Reversed\n\n"
                  '**"a retired agreement"** replaced by something better.\n')
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        after = (box / "Method" / "AGREED.md").read_bytes()
        expected = before.replace("- [ ] a retired agreement\n", "").encode("utf-8")
        self.assertEqual(after, expected)
        self.assertIn(block.encode("utf-8"), after)

    def test_remove_appends_one_settle_event_flagged_remove_true(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n" +
            self.REVERSED_QUOTE, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        settle_events = [e for e in events if e["kind"] == "settle"]
        self.assertEqual(len(settle_events), 1)
        self.assertEqual(settle_events[0]["remove"], True)
        self.assertIsNone(settle_events[0]["about"])
        self.assertIsNone(settle_events[0]["under"])
        self.assertIsNone(settle_events[0]["witness"])

    def test_remove_read_back_by_agreements_state_reports_it_gone(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n" +
            self.REVERSED_QUOTE, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        state = impl.agreements_state(box, "Method")
        self.assertEqual(state["status"], "absent")
        self.assertEqual(state["open"], [])


class SettleReverseCommandTests(unittest.TestCase):
    """`settle --reverse` -- one transaction that writes the `## Reversed`
    entry AND deletes the settled line, instead of requiring a hand edit
    to satisfy `SETTLE_NOT_REVERSED` before `--remove` can run at all
    (design "a reversal is one write"). Reuses `_locate_settled_text`,
    `SETTLE_TEXT_ABSENT`/`SETTLE_TEXT_AMBIGUOUS`, `_reversed_quote_matches_text`
    and `impl_position.splice` unchanged -- the same search and the same
    guard predicate `--remove` already has, never a second implementation
    of either.
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_settle_reverse_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        return box

    def run_cli(self, *args, stdin=None):
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE)

    def _settle(self, box, **overrides):
        args = {"target": str(box), "name": "Method", "session": "s1",
                "reverse": True, "text": "a retired agreement",
                "paragraph": "Reversed because the underlying measurement changed."}
        args.update(overrides)
        argv = ["settle"]
        for flag, value in args.items():
            if value is None or value is False:
                continue
            if value is True:
                argv += [f"--{flag}"]
                continue
            argv += [f"--{flag}", value]
        return self.run_cli(*argv)

    # --- pure-argv shape: --reverse is a fourth, mutually exclusive mode ---

    def test_reverse_refuses_combined_with_attach(self):
        box = self._box()
        proc = self._settle(box, attach=True, witness="test_x")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REVERSE_CONFLICT")

    def test_reverse_refuses_combined_with_remove(self):
        box = self._box()
        proc = self._settle(box, remove=True)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REVERSE_CONFLICT")

    def test_reverse_refuses_combined_with_under(self):
        box = self._box()
        proc = self._settle(box, under="## Ladder")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REVERSE_CONFLICT")

    def test_reverse_refuses_combined_with_supersedes(self):
        box = self._box()
        proc = self._settle(box, supersedes="some other text")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REVERSE_CONFLICT")

    def test_reverse_refuses_combined_with_witness(self):
        box = self._box()
        proc = self._settle(box, witness="test_x")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_REVERSE_CONFLICT")

    def test_reverse_refuses_without_paragraph(self):
        """The engine never authors the reasoning -- refused before
        anything is read from disk, the identical shape
        `SETTLE_WITNESS_REQUIRED` already has for `--attach`."""
        box = self._box()
        proc = self._settle(box, paragraph=None)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_PARAGRAPH_REQUIRED")

    def test_reverse_refuses_blank_paragraph(self):
        box = self._box()
        proc = self._settle(box, paragraph="   ")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_PARAGRAPH_REQUIRED")

    # --- where the removal would even happen ---

    def test_reverse_refuses_holder_absent(self):
        box = self._box()
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HOLDER_ABSENT")

    # --- the search: matched by exact text, the identical helper --remove uses ---

    def test_reverse_refuses_when_text_matches_zero_lines(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a different item\n\n## Reversed\n\n"
            "prose only, no quote yet.\n", encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_ABSENT")

    def test_reverse_refuses_when_text_matches_more_than_one_line(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
            "## Elsewhere\n\n- [x] a retired agreement\n\n"
            "## Reversed\n\nprose only, no quote yet.\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_AMBIGUOUS")

    # --- the new guard: refuses a duplicate explanation ---

    def test_reverse_refuses_when_the_text_is_already_quoted(self):
        """Measured on a real adopting target (2026-08-31): a `## Reversed`
        entry can already quote a line's exact text while the line itself
        is still present, because the entry was hand-written before this
        mode existed. `--reverse` must not author a SECOND explanation for
        an agreement that already has one; plain `--remove` is the
        reachable command for that state (see
        `SettleRemoveCommandTests.test_remove_deletes_exactly_one_line_byte_identical_otherwise`,
        which proves it still is)."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
            "## Reversed\n\n"
            '**"a retired agreement"** replaced by something better.\n',
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_ALREADY_REVERSED")
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("- [ ] a retired agreement", after)

    # --- where the entry would even go ---

    def test_reverse_refuses_heading_absent(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HEADING_ABSENT")
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn("- [ ] a retired agreement", after)

    def test_reverse_refuses_heading_ambiguous(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
            "## Reversed\n\nprose only.\n\n"
            "## Reversed\n\nmore prose, a second heading.\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HEADING_AMBIGUOUS")

    # --- the happy path: one transaction, byte-exact everywhere else ---

    def test_reverse_writes_the_entry_and_deletes_the_line_in_one_call(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\nSome prose above the section.\n\n"
            "## Ladder\n\n- [x] an unrelated settled item\n\n"
            "- [ ] a retired agreement\n\n"
            "## Reversed\n\n"
            'Every reversal, written rather than deleted.\n',
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["reverse"], True)
        self.assertEqual(result["text"], "a retired agreement")
        self.assertEqual(
            result["paragraph"],
            "Reversed because the underlying measurement changed.")

        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertNotIn("- [ ] a retired agreement\n", after)
        self.assertIn(
            '**"a retired agreement"** '
            "Reversed because the underlying measurement changed.",
            after)
        # The quote lands after the section's existing prose, not before it.
        self.assertLess(
            after.index("Every reversal, written rather than deleted."),
            after.index('**"a retired agreement"**'))

    def test_reverse_derives_the_quote_from_the_located_line_excluding_a_witness(self):
        """`_render_reversed_entry` reads the bold quote off
        `AGREEMENT_LINE`'s own `text` group on the located line -- never
        `--text` itself -- so a witness token already bound to the line is
        excluded from the quote the same way `--attach`'s own read of
        `located.group("text")` already excludes it."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [x] a retired agreement `test_x`\n\n"
            "## Reversed\n\nprose only, no quote yet.\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn('**"a retired agreement"**', after)
        self.assertNotIn("test_x", after)

    def test_reverse_inserts_immediately_before_the_position_block(self):
        box = self._box()
        block = ("<!-- position revision=r1.md sha256=" + "a" * 64 +
                "  derivedAt=2026-08-27T00:00:00Z session=s0 target=final -->\n"
                "- [ ] 1. an unrelated position item. `@notebook Notebooks/x.ipynb`\n"
                "<!-- /position -->\n")
        before = ("# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
                  "## Reversed\n\nprose only, no quote yet.\n\n" + block)
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertIn(block, after)
        self.assertLess(
            after.index('**"a retired agreement"**'),
            after.index("<!-- position"))
        self.assertNotIn("- [ ] a retired agreement\n\n## Reversed", after)

    def test_reverse_appends_at_the_end_of_section_with_no_position_block(self):
        box = self._box()
        before = ("# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
                  "## Reversed\n\nprose only, no quote yet.\n")
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertTrue(after.rstrip("\n").endswith(
            "Reversed because the underlying measurement changed."))

    def test_reverse_appends_before_a_later_heading_with_no_position_block(self):
        box = self._box()
        before = ("# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
                  "## Reversed\n\nprose only, no quote yet.\n\n"
                  "## Later section\n\n- [ ] untouched\n")
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        after = (box / "Method" / "AGREED.md").read_text(encoding="utf-8")
        self.assertLess(
            after.index('**"a retired agreement"**'),
            after.index("## Later section"))
        self.assertIn("## Later section\n\n- [ ] untouched\n", after)

    def test_reverse_appends_one_settle_event_flagged_reverse_true(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
            "## Reversed\n\nprose only, no quote yet.\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        settle_events = [e for e in events if e["kind"] == "settle"]
        self.assertEqual(len(settle_events), 1)
        self.assertEqual(settle_events[0]["reverse"], True)
        self.assertEqual(settle_events[0]["remove"], False)
        self.assertEqual(
            settle_events[0]["paragraph"],
            "Reversed because the underlying measurement changed.")
        self.assertIsNone(settle_events[0]["about"])
        self.assertIsNone(settle_events[0]["under"])
        self.assertIsNone(settle_events[0]["witness"])

    def test_reverse_read_back_by_agreements_state_reports_it_gone(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a retired agreement\n\n"
            "## Reversed\n\nprose only, no quote yet.\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        state = impl.agreements_state(box, "Method")
        self.assertEqual(state["status"], "absent")
        self.assertEqual(state["open"], [])


class SettleDoneCommandTests(unittest.TestCase):
    """`settle --done` -- flips an already-settled line's own mark from
    `[ ]` to `[x]`, matched by its exact `--text` (design "the tick this
    class closes"). This is the last member of the class `--attach`,
    `--remove` and `--reverse` already close: editing an agreement's text
    is `--reverse` then place, moving one between sections is `--remove`
    then place elsewhere -- both compositions of verbs that already
    existed. There was no composition that ticked one; every one of a real
    target's 90 ticked agreements was typed by hand before this landed.

    Guarded on purpose -- refused `SETTLE_NOT_WITNESSED` unless the located
    line already carries a `` `test_<id>` `` token (see `cmd_settle`'s own
    docstring, "Why marking done requires a witness", for the full
    argument): a tick asserts the work is done, and a line nobody can point
    a test at cannot assert that through this command. `settle --attach`
    is the one way to put a witness there first.
    """

    def _box(self):
        box = FORGE / "implementations" / f"_e2e_settle_done_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method_Benchmark").mkdir(parents=True)
        (box / "tests").mkdir(parents=True)
        (box / "Method").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text("", encoding="utf-8")
        return box

    def run_cli(self, *args, stdin=None):
        return subprocess.run([sys.executable, str(CLI), *args], input=stdin,
                              capture_output=True, text=True, cwd=FORGE)

    def _settle(self, box, **overrides):
        args = {"target": str(box), "name": "Method", "session": "s1",
                "done": True, "text": "an already-settled item"}
        args.update(overrides)
        argv = ["settle"]
        for flag, value in args.items():
            if value is None or value is False:
                continue
            if value is True:
                argv += [f"--{flag}"]
                continue
            argv += [f"--{flag}", value]
        return self.run_cli(*argv)

    # --- the search: matched by exact text, same discipline as --attach ---

    def test_done_refuses_when_text_matches_zero_lines(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] a different item `test_x`\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_ABSENT")

    def test_done_refuses_when_text_matches_more_than_one_line(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item `test_a`\n\n"
            "## Reversed\n\n- [ ] an already-settled item `test_b`\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_TEXT_AMBIGUOUS")

    def test_done_refuses_holder_absent(self):
        box = self._box()
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_HOLDER_ABSENT")

    # --- pure-argv shape: --done is a fourth, mutually exclusive mode ---

    def test_done_refuses_combined_with_attach(self):
        box = self._box()
        proc = self._settle(box, attach=True, witness="test_the_thing")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_DONE_CONFLICT")

    def test_done_refuses_combined_with_remove(self):
        box = self._box()
        proc = self._settle(box, remove=True)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_DONE_CONFLICT")

    def test_done_refuses_combined_with_reverse(self):
        box = self._box()
        proc = self._settle(box, reverse=True, paragraph="because")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_DONE_CONFLICT")

    def test_done_refuses_combined_with_under(self):
        box = self._box()
        proc = self._settle(box, under="## Ladder")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_DONE_CONFLICT")

    def test_done_refuses_combined_with_supersedes(self):
        box = self._box()
        proc = self._settle(box, supersedes="some other text")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_DONE_CONFLICT")

    def test_done_refuses_combined_with_witness(self):
        box = self._box()
        proc = self._settle(box, witness="test_the_thing")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_DONE_CONFLICT")

    def test_done_refuses_combined_with_paragraph(self):
        box = self._box()
        proc = self._settle(box, paragraph="because")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_DONE_CONFLICT")

    # --- the guard: a tick must rest on a witness ---

    def test_done_refuses_a_line_with_no_witness_at_all(self):
        box = self._box()
        before = "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item\n"
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_NOT_WITNESSED")
        # Refused before any write.
        after = (box / "Method" / "AGREED.md").read_bytes()
        self.assertEqual(after, before.encode("utf-8"))

    def test_done_refuses_a_line_already_ticked(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [x] an already-settled item `test_the_thing`\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_ALREADY_DONE")

    def test_done_refuses_a_line_already_ticked_uppercase_mark(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [X] an already-settled item `test_the_thing`\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SETTLE_ALREADY_DONE")

    # --- the happy path: byte-identical except the flipped mark ---

    def test_done_flips_the_mark_byte_identical_otherwise(self):
        box = self._box()
        before = ("# Agreed\n\nSome prose above the section.\n\n"
                  "## Ladder\n\n- [ ] an already-settled item `test_the_thing`\n\n"
                  "## Reversed\n\nA hand-written paragraph.\n")
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "written")
        self.assertEqual(result["done"], True)

        after = (box / "Method" / "AGREED.md").read_bytes()
        expected = before.replace(
            "- [ ] an already-settled item `test_the_thing`\n",
            "- [x] an already-settled item `test_the_thing`\n").encode("utf-8")
        self.assertEqual(after, expected)

    def test_done_on_a_star_bullet_is_byte_identical_otherwise(self):
        box = self._box()
        before = "# Agreed\n\n## Ladder\n\n* [ ] an already-settled item `test_the_thing`\n"
        (box / "Method" / "AGREED.md").write_text(before, encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        after = (box / "Method" / "AGREED.md").read_bytes()
        expected = before.replace(
            "* [ ] an already-settled item `test_the_thing`\n",
            "* [x] an already-settled item `test_the_thing`\n").encode("utf-8")
        self.assertEqual(after, expected)

    # --- the design decision: no discussion precondition for --done ---

    def test_done_succeeds_with_zero_discuss_events_ever_recorded(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item `test_the_thing`\n",
            encoding="utf-8")
        ledger = box / "Method" / ".implementation" / "position.jsonl"
        self.assertFalse(ledger.exists())
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["status"], "written")

    def test_done_appends_one_settle_event_flagged_done_true(self):
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item `test_the_thing`\n",
            encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        settle_events = [e for e in events if e["kind"] == "settle"]
        self.assertEqual(len(settle_events), 1)
        self.assertEqual(settle_events[0]["done"], True)
        self.assertEqual(settle_events[0]["attach"], False)
        self.assertEqual(settle_events[0]["remove"], False)
        self.assertEqual(settle_events[0]["reverse"], False)
        self.assertIsNone(settle_events[0]["about"])
        self.assertIsNone(settle_events[0]["under"])

    def test_done_read_back_by_agreements_state_when_the_witness_exists(self):
        """The witness function genuinely exists in `tests/`, so the tick
        reads as `unmeasured` (present, never executed by this CLI) rather
        than `disagrees` (present as a token, absent from `tests/`)."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item `test_the_thing`\n",
            encoding="utf-8")
        (box / "tests" / "test_it.py").write_text(
            "def test_the_thing():\n    pass\n", encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        state = impl.agreements_state(box, "Method")
        self.assertEqual(state["open"], [])
        self.assertEqual(state["settled"], 1)
        self.assertEqual(state["witness"]["unmeasured"],
                         ["an already-settled item"])
        self.assertEqual(state["witness"]["disagrees"], [])

    def test_done_read_back_by_agreements_state_disagrees_when_the_witness_does_not_exist(self):
        """The mirror case: the located line's witness token names no real
        function under `tests/`. `agreements_state` -- not this command --
        is the instrument that catches it, immediately after the tick, the
        same as it would for any hand-ticked line."""
        box = self._box()
        (box / "Method" / "AGREED.md").write_text(
            "# Agreed\n\n## Ladder\n\n- [ ] an already-settled item `test_the_thing`\n",
            encoding="utf-8")
        (box / "tests" / "test_it.py").write_text(
            "def test_something_else():\n    pass\n", encoding="utf-8")
        proc = self._settle(box)
        self.assertEqual(proc.returncode, 0, proc.stdout)

        state = impl.agreements_state(box, "Method")
        self.assertEqual(state["witness"]["disagrees"],
                         ["an already-settled item"])


class SettleRemoveReverseUsageDocumentedTests(unittest.TestCase):
    """Gap 2: `--remove` and `--reverse` shipped with three passing
    mentions each in `usage.md` (inside the `--done` section) and no
    worked section of their own -- unlike `--attach` and `--done`, which
    each carry a `### ` heading, a runnable example and the fact that
    makes the mode safe. This locks the two missing sections to that same
    depth.
    """

    def usage_text(self):
        return USAGE_MD.read_text(encoding="utf-8")

    def section(self, heading):
        text = self.usage_text()
        self.assertIn(heading, text, f"{heading!r} has no worked section")
        body = text[text.index(heading):]
        return body[:body.index("\n#", 1)]

    def test_remove_has_its_own_worked_section(self):
        body = self.section("### `--remove`")
        self.assertIn("```bash", body)
        self.assertIn("--remove", body)
        # The guard that makes `--remove` safe: nothing is deleted before
        # the document's own `## Reversed` section already explains why.
        self.assertIn("SETTLE_NOT_REVERSED", body)

    def test_reverse_has_its_own_worked_section(self):
        body = self.section("### `--reverse`")
        self.assertIn("```bash", body)
        self.assertIn("--reverse", body)
        # The guard that makes `--reverse` safe: the engine never authors
        # the reasoning, so it refuses without `--paragraph`.
        self.assertIn("--paragraph", body)
        self.assertIn("SETTLE_PARAGRAPH_REQUIRED", body)
        # The atomicity claim: the `## Reversed` entry and the deletion
        # land in the SAME call, or neither does.
        self.assertIn("one", body.lower())
        self.assertIn("SETTLE_ALREADY_REVERSED", body)


class SettleFiveModesClassStatedOnceTests(unittest.TestCase):
    """Gap 3: `cmd_settle` now has five modes -- place, `--attach`,
    `--remove`, `--reverse`, `--done` -- and their relationship (two of
    them are compositions of the other three, not new gaps) is worth
    stating once in `SKILL.md`, rather than re-derived by measurement
    every time somebody trips over the missing member.
    """

    def skill_text(self):
        return SKILL_MD.read_text(encoding="utf-8")

    def test_the_five_modes_are_named_together(self):
        text = " ".join(self.skill_text().split())
        for token in ("`--attach`", "`--remove`", "`--reverse`", "`--done`"):
            self.assertIn(token, text)

    def test_the_two_compositions_are_named_as_such(self):
        """Editing an agreement's text is `--reverse` then a fresh
        placement; moving one between sections is `--remove` then a
        placement under the new heading -- both compositions, never
        gaps."""
        text = " ".join(self.skill_text().split())
        self.assertIn("editing an agreement's text is `--reverse`", text)
        self.assertIn("moving one between sections is `--remove`", text)

    def test_the_settle_row_documents_remove_and_reverse(self):
        rows = markdown_table_rows(
            self.skill_text(), "| Command | What it writes | Refuses on |")
        self.assertEqual(len(rows), 1)
        row = next(r for r in rows[0] if r[0].strip("`") == "settle")
        writes, refuses = row[1], row[2]
        self.assertIn("`--remove`", writes)
        self.assertIn("`--reverse`", writes)
        self.assertIn("SETTLE_NOT_REVERSED", refuses)
        self.assertIn("SETTLE_ALREADY_REVERSED", refuses)
        self.assertIn("SETTLE_PARAGRAPH_REQUIRED", refuses)
        self.assertIn("SETTLE_REMOVE_CONFLICT", refuses)
        self.assertIn("SETTLE_REVERSE_CONFLICT", refuses)


