class AgreementWitnessSingleWritePathTests(unittest.TestCase):
    """Spec Group 5: `settle` is the ONLY command that ever writes a
    witness token. Held the same way D3 holds `impl_availability`'s
    call-site sets -- by an `ast` walk of the whole CLI, not by reading
    every command's docstring and trusting it.

    `_render_settled_line` is the one construction of a witness segment
    (design D5); if a future command ever called it too, this test would
    fail the moment that call landed, before any hand-editing doctrine had
    to be relied on.
    """

    def call_site_functions(self, name: str) -> set[str]:
        tree = ast.parse(CLI.read_text(encoding="utf-8"))
        enclosing: dict[int, str] = {}
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                for child in ast.walk(node):
                    if child is not node:
                        enclosing[id(child)] = node.name
        sites = set()
        for node in ast.walk(tree):
            if (isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Name)
                    and node.func.id == name):
                caller = enclosing.get(id(node))
                if caller:
                    sites.add(caller)
        return sites

    def test_render_settled_line_is_called_only_from_cmd_settle(self):
        self.assertEqual(
            self.call_site_functions("_render_settled_line"), {"cmd_settle"})

    def test_render_reversed_entry_is_called_only_from_cmd_settle(self):
        self.assertEqual(
            self.call_site_functions("_render_reversed_entry"), {"cmd_settle"})

    def test_render_done_line_is_called_only_from_cmd_settle(self):
        self.assertEqual(
            self.call_site_functions("_render_done_line"), {"cmd_settle"})

    def test_a_second_caller_would_be_caught(self):
        """Reachable-red by construction, over a scratch copy rather than
        the real CLI: a second call site is added, the assertion fails
        naming both callers, and the scratch copy is discarded -- the real
        file is never touched by this test.
        """
        scratch = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, scratch, ignore_errors=True)
        mutated = scratch / "mutated_cli.py"
        source = CLI.read_text(encoding="utf-8")
        injected = source.replace(
            "def cmd_discuss(args: argparse.Namespace) -> dict:",
            "def cmd_discuss(args: argparse.Namespace) -> dict:\n"
            "    _render_settled_line('x', None)  # injected second caller",
            1)
        self.assertNotEqual(injected, source, "the anchor text moved")
        mutated.write_text(injected, encoding="utf-8")

        tree = ast.parse(mutated.read_text(encoding="utf-8"))
        enclosing: dict[int, str] = {}
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                for child in ast.walk(node):
                    if child is not node:
                        enclosing[id(child)] = node.name
        sites = set()
        for node in ast.walk(tree):
            if (isinstance(node, ast.Call)
                    and isinstance(node.func, ast.Name)
                    and node.func.id == "_render_settled_line"):
                caller = enclosing.get(id(node))
                if caller:
                    sites.add(caller)
        self.assertEqual(sites, {"cmd_settle", "cmd_discuss"})


class GateCommandTests(unittest.TestCase):
    """`gate` -- the launch authorization record (design §4, domain
    launch-authorization). Checked in refusing-costs-nothing order: the
    justification first (pure argv), then whether a position section exists
    to reach a rung in, then the un-forgeable readiness measurement itself,
    then whether the rung this job's witness names has actually been
    reached.
    """

    PROPOSAL_REVISION = "r1.md"
    PROPOSAL_TEXT = "## 1\ntexto\n"
    PROPOSAL_SHA256 = hashlib.sha256(PROPOSAL_TEXT.encode("utf-8")).hexdigest()

    def _proposals(self):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / self.PROPOSAL_REVISION).write_text(self.PROPOSAL_TEXT, encoding="utf-8")
        (root / "r2.md").write_text("## 2\notro\n", encoding="utf-8")
        return root

    def _box(self, packages=("Method",)):
        self._box_count = getattr(self, "_box_count", 0) + 1
        box = FORGE / "implementations" / f"_e2e_gate_cmd_{os.getpid()}_{id(self)}_{self._box_count}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        box.mkdir(parents=True)
        env = dict(os.environ)
        env["GIT_AUTHOR_NAME"] = env["GIT_COMMITTER_NAME"] = "gate-tests"
        env["GIT_AUTHOR_EMAIL"] = env["GIT_COMMITTER_EMAIL"] = "gate-tests@example.invalid"
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        for package in packages:
            (box / "src" / package).mkdir(parents=True, exist_ok=True)
            (box / "src" / package / "__init__.py").write_text("", encoding="utf-8")
            (box / "src" / f"{package}_Benchmark").mkdir(parents=True, exist_ok=True)
            (box / "src" / f"{package}_Benchmark" / "__init__.py").write_text(
                "", encoding="utf-8")
            (box / package).mkdir(parents=True, exist_ok=True)
        (box / "tests").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "add", "-A"], cwd=box, env=env, check=True,
                       capture_output=True)
        subprocess.run(["git", "commit", "-q", "-m", "initial"], cwd=box, env=env,
                       check=True, capture_output=True)
        commit = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=box, env=env, check=True,
            capture_output=True, text=True).stdout.strip()
        return box, commit

    def _write_job_folder(self, box, commit, *, service="svc", job_name="job1",
                          product="Method", clone_paths=("src/Method",)):
        job_dir = box / "tools" / service / job_name
        job_dir.mkdir(parents=True, exist_ok=True)
        run_config = {
            "schemaVersion": 1, "product": product, "service": service,
            "jobName": job_name, "commit": commit,
            "repo": {"url": "https://example.invalid/repo.git", "ref": "main"},
            "clonePaths": list(clone_paths),
            "run": {"module": f"{product}.module", "function": "run", "kwargs": {}},
            "runnerTemplate": [
                {"path": "assets/runner_bootstrap.py", "sha256": "0" * 64},
                {"path": "assets/runner_invoke.py", "sha256": "0" * 64},
            ],
        }
        (job_dir / "run-config.json").write_text(json.dumps(run_config), encoding="utf-8")
        return job_dir

    def _write_smoke_pass(self, box, *, product="Method", job_name="job1",
                          commit, worker="w1"):
        smoke_path = box / product / ".remote-execution" / "smoke.jsonl"
        smoke_path.parent.mkdir(parents=True, exist_ok=True)
        event = {"kind": "smokeResult", "ts": "2026-08-27T00:00:00Z",
                  "jobName": job_name, "result": "pass", "commit": commit,
                  "worker": worker, "missing": []}
        with smoke_path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(event) + "\n")

    def run_cli(self, *args, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def _mint_authorization(self, box, proposals, *, job="job1", units=None,
                            session="s1"):
        """A REAL token, minted through the actual `cmd_offer` mint path
        in-process (never hand-computed) -- the same mechanism `offer`
        itself uses, so this stays correct even if the binding shape ever
        changes, and `gate`'s own independent re-derivation is genuinely
        being checked against something the engine minted, not a fixture's
        guess at what it would mint. `--unit`'s service is fixed at
        `"svc"` because every job folder `_write_job_folder` writes in
        this class declares that service; a capacity reporter is
        registered for it so `_offer_launch_action` does not omit the
        launch for want of one.
        """
        rcli = impl._load_remote_execution_cli()
        rcli.ADAPTER.register_declared_capacity("svc", lambda: (1, 1))
        args = argparse.Namespace(
            target=str(box), name="Method", revision=self.PROPOSAL_REVISION,
            session=session, answer="yes", units=units)
        with unittest.mock.patch.dict(
                os.environ, {"IMPLEMENTATION_PROPOSALS": str(proposals)}):
            result = impl.cmd_offer(args)
        launch = next(
            a for a in result["actions"]
            if a["id"] == "launch" and a["binding"].get("job") == job)
        return launch["binding"]["authorization"]

    def _propose(self, box, *, jobs=("job1",), workers=("w1",), session="s1"):
        """A REAL `proposal` event, appended through the actual
        `cmd_propose` path in-process (never hand-written) -- called
        BEFORE `_mint_authorization` in every fixture that needs a token
        `gate` will accept: a token minted while no proposal covers its
        job still mints (`proposalDigest: null`) and still passes
        `_verify_gate_authorization`, but `gate` then refuses
        `GATE_PROPOSAL_UNKNOWN` on the separate proposal precondition.
        """
        args = argparse.Namespace(
            target=str(box), name="Method", session=session,
            jobs=list(jobs), workers=list(workers), depends_on=None,
            rationale="Campaign proposal for the test fixture.")
        return impl.cmd_propose(args)

    # --- 6.1: no passing rehearsal on file -- refused, never asserted ---

    def test_gate_refuses_not_ready_when_smoke_ready_false(self):
        box, commit = self._box()
        self._write_job_folder(box, commit)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        # A well-formed but unminted token: the presence check (pure argv,
        # checked first) is satisfied, so this call reaches the readiness
        # check it exists to prove -- the full authorization VERIFICATION
        # runs only once every earlier ladder rung stands, which this
        # invocation never reaches.
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", "unminted-placeholder",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "NOT_READY")

    # --- 6.2: the rest of the refusals ---

    def test_gate_refuses_empty_justification(self):
        box, _ = self._box()
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "   ",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "EMPTY_JUSTIFICATION")

    def test_gate_refuses_on_absent_or_stale_position(self):
        proposals = self._proposals()

        with self.subTest("absent"):
            box, _ = self._box()
            proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                                "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                                "--job", "job1", "--worker", "w1",
                                "--justification", "Because it is time.",
                                "--authorization", "unminted-placeholder",
                                proposals=proposals)
            self.assertEqual(proc.returncode, 2, proc.stdout)
            self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_ABSENT")

        with self.subTest("stale"):
            box, _ = self._box()
            header = {"revision": self.PROPOSAL_REVISION, "revisionSha256": "a" * 64,
                      "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
            items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                      "witness": {"kind": "rehearsal", "operand": "job1"}}]
            (box / "Method" / "AGREED.md").write_text(
                impl_position.render(header, items), encoding="utf-8")
            # Bound to r1.md's name, but "a"*64 never matches r2.md's real
            # content -- gating against r2.md finds the header stale.
            proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                                "--revision", "r2.md", "--session", "s1",
                                "--job", "job1", "--worker", "w1",
                                "--justification", "Because it is time.",
                                "--authorization", "unminted-placeholder",
                                proposals=proposals)
            self.assertEqual(proc.returncode, 2, proc.stdout)
            self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_STALE")

    def test_gate_refuses_sequence_not_reached(self):
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [
            {"ordinal": 1, "mark": " ", "text": "Read the pilot notebook.",
             "witness": {"kind": "notebook", "operand": "Notebooks/pilot.ipynb"}},
            {"ordinal": 2, "mark": " ", "text": "Rehearse the job.",
             "witness": {"kind": "rehearsal", "operand": "job1"}},
        ]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", "unminted-placeholder",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "SEQUENCE_NOT_REACHED")

    # --- 6.3: the record itself, once every precondition is real ---

    def test_gate_records_the_authorization_after_a_passing_rehearsal(self):
        """The runtime harness this task is scored against: a rehearsal
        actually recorded via `readiness`'s own three-fact bind (through
        `remote_execution_jobs_state`'s `smokeReady`) on a scratch job
        folder, then `gate` reads it back rather than trusting an assertion.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        proposals = self._proposals()
        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Rehearsal passed at the pinned commit.",
                            "--authorization", token, "--elect", "job1",
                            proposals=proposals)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "recorded")
        self.assertEqual(result["job"], "job1")
        self.assertEqual(result["commit"], commit)
        # No MINTED token in the reply: the whole point (design §4.1) is
        # that this record cannot be minted by computing a digest over the
        # caller's own argv -- `token` itself never appears as a KEY here
        # (the presented `--authorization` value is consumed, never echoed
        # back as if `gate` had just invented it).
        self.assertNotIn("token", "".join(result.keys()).lower())

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        gate_event = next(e for e in events if e["kind"] == "gate")
        self.assertEqual(gate_event["jobName"], "job1")
        self.assertEqual(gate_event["justification"], "Rehearsal passed at the pinned commit.")
        # Single-use: consumption is a SEPARATE appended event, never a
        # mutation of the `authorization` event it spends.
        self.assertEqual(events[-1]["kind"], "authorization-consumed")
        self.assertEqual(events[-1]["token"], token)

    # --- 6.4: the campaign form (PR8, design revision) ------------------
    #
    # PR7 shipped `gate` with no way to authorize a campaign at all --
    # `remote_cli._verify_launch_authorization()` exempted `units` truthy
    # entirely, which left the single send authorized and the campaign
    # (the full-scale, multi-worker launch this mechanism exists to gate)
    # not. `--unit`, repeatable, closes that: it binds the exact ordered
    # unit list a later `submit --unit ...` will carry, the same
    # derivation `campaign_consent_token()` already uses for consent.

    def test_gate_refuses_worker_and_unit_together(self):
        box, _ = self._box()
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--unit", "u0", "--unit", "u1",
                            "--justification", "Because it is time.",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_WORKER_UNIT_CONFLICT")

    def test_gate_refuses_when_neither_worker_nor_unit_given(self):
        box, _ = self._box()
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1",
                            "--justification", "Because it is time.",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_WORKER_REQUIRED")

    def test_gate_records_a_campaign_authorization_with_ordered_units_and_no_worker(
        self,
    ):
        """The runtime harness for the campaign form, mirroring `test_gate_
        records_the_authorization_after_a_passing_rehearsal` above: a real
        rehearsal recorded through `readiness`'s own three-fact bind, then
        `--unit` authorizes the launch with `worker: None` recorded --
        never a named account, matching what a campaign `submit`
        invocation's own binding always is.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        proposals = self._proposals()
        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals, units=["u0", "u1"])
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--unit", "u0", "--unit", "u1",
                            "--justification", "Rehearsal passed; launching the campaign.",
                            "--authorization", token, "--elect", "job1",
                            proposals=proposals)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "recorded")
        self.assertIsNone(result["worker"])
        self.assertEqual(result["units"], ["u0", "u1"])

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        gate_event = next(e for e in events if e["kind"] == "gate")
        self.assertIsNone(gate_event["worker"])
        # Order preserved, never sorted -- the same rule `campaign_consent_
        # token()` documents for consent (Decision 5).
        self.assertEqual(gate_event["units"], ["u0", "u1"])
        self.assertEqual(events[-1]["kind"], "authorization-consumed")
        self.assertEqual(events[-1]["token"], token)

    # --- 6.5: `--authorization` and its five refusal codes (Slice 2B) ---

    def test_gate_refuses_authorization_required_when_omitted(self):
        """Pure argv, checked before any I/O -- there is no default and no
        way to reach a later refusal code without it.
        """
        box, _ = self._box()
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_AUTHORIZATION_REQUIRED")

    def test_gate_refuses_authorization_unknown_when_no_record_vouches_for_it(self):
        """A syntactically fine token that names no ledger event at all --
        the honest answer to a caller who typed a value rather than copying
        one `offer` actually minted.
        """
        proposals = self._proposals()
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", "f" * 64,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_AUTHORIZATION_UNKNOWN")

    def test_gate_refuses_authorization_mismatch_on_a_different_unit_list(self):
        """A genuine, unconsumed record exists -- but it was minted for a
        DIFFERENT operator-declared unit list than this invocation's own,
        so it is refused for naming the wrong launch, not for being absent.
        """
        proposals = self._proposals()
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        token = self._mint_authorization(box, proposals, units=["u0"])
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--unit", "u1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_AUTHORIZATION_MISMATCH")

    def test_gate_refuses_authorization_stale_when_the_pin_moves(self):
        """The exact spec scenario ("moved binding goes stale"): a token
        minted while the job's pin is P1 is refused once the job folder's
        own declared commit becomes P2 -- a fact this launch depends on
        moved, and this is never about elapsed time (`session`/`at` are
        digest discriminators, not a clock this check reads).
        """
        proposals = self._proposals()
        box, commit = self._box()
        job_dir = self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        token = self._mint_authorization(box, proposals)

        # The pin moves: a NEW commit is declared in the job folder's own
        # run-config.json, and a fresh rehearsal is recorded against it, so
        # this call reaches the staleness check rather than being turned
        # back earlier by NOT_READY.
        new_commit = "b" * 40
        run_config = json.loads((job_dir / "run-config.json").read_text(encoding="utf-8"))
        run_config["commit"] = new_commit
        (job_dir / "run-config.json").write_text(json.dumps(run_config), encoding="utf-8")
        self._write_smoke_pass(box, commit=new_commit)

        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_AUTHORIZATION_STALE")

    def test_gate_refuses_authorization_consumed_on_reuse(self):
        """Single-use: a token that already authorized one successful
        `gate` call is refused on a second presentation, and the ledger
        shows an APPENDED `authorization-consumed` record, never a deleted
        `authorization` event (`append_event`'s own append-only rationale).
        """
        proposals = self._proposals()
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)
        first = self.run_cli("gate", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             "--job", "job1", "--worker", "w1",
                             "--justification", "Rehearsal passed at the pinned commit.",
                             "--authorization", token, "--elect", "job1",
                             proposals=proposals)
        self.assertEqual(first.returncode, 0, first.stdout)

        second = self.run_cli("gate", "--target", str(box), "--name", "Method",
                              "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                              "--job", "job1", "--worker", "w1",
                              "--justification", "Rehearsal passed at the pinned commit.",
                              "--authorization", token,
                              proposals=proposals)
        self.assertEqual(second.returncode, 2, second.stdout)
        self.assertEqual(json.loads(second.stdout)["code"], "GATE_AUTHORIZATION_CONSUMED")

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        consumed = [e for e in events if e.get("kind") == "authorization-consumed"]
        gate_events = [e for e in events if e.get("kind") == "gate"]
        self.assertEqual(len(consumed), 1, "one refusal must never mint a second consumption")
        self.assertEqual(len(gate_events), 1, "the refused second call appends no `gate` event")

    # --- 6.6: backward compatibility -- a pre-change record, never migrated ---

    def test_a_pre_change_gate_record_is_neither_migrated_nor_the_reason_for_refusal(self):
        """Spec "old event, new gate call": a target whose ledger already
        carries a tokenless `gate` event (written before this mechanism
        existed) refuses the NEW `gate` command for lack of --authorization
        -- the command's own new precondition -- never because the old
        event is somehow invalid. The old event is untouched: no migration,
        no rewrite, and this refusal appends nothing at all.

        The design's own measurement found ZERO `gate` events in either
        real ledger in this repository, so this fixture builds its own --
        there is no local instance to discover.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        ledger = box / "Method" / ".implementation" / "position.jsonl"
        pre_change_event = {
            "kind": "gate", "jobName": "job1", "worker": "w1", "commit": commit,
            "revision": self.PROPOSAL_REVISION, "revisionSha256": self.PROPOSAL_SHA256,
            "entrypoint": "tools/svc/job1/run.py", "units": [],
            "justification": "prior work, before --authorization existed",
            "session": "s0", "at": "2026-08-27T00:00:00Z",
        }
        impl_position.append_event(ledger, pre_change_event)
        before = ledger.read_text(encoding="utf-8")

        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_AUTHORIZATION_REQUIRED")
        # Untouched: the refusal appended nothing, migrated nothing, and
        # rewrote nothing -- the pre-change event is byte-identical.
        self.assertEqual(ledger.read_text(encoding="utf-8"), before)


class AuthorizationBindingKeysStructuralTests(unittest.TestCase):
    """Task 3.1 (`the-pilot-decides-the-remote-strategy`): three literals
    spell `_AUTHORIZATION_BINDING_KEYS`' own key set --
    `_AUTHORIZATION_BINDING_KEYS` itself, `_authorization_binding`'s own
    return, and `cmd_gate`'s inline `gate_binding` dict -- and nothing
    enforced their agreement before this test. Read from source with
    `ast`, never by calling the functions: `_authorization_binding` needs
    a real `action`/`events` this test has no reason to construct, and
    `gate_binding` is a local variable, never returned at all.

    Mutation-proven: adding a key to only `_authorization_binding` (not
    the other two) must turn this red -- verified by hand (temporarily
    adding `"bogus": None` to `_authorization_binding`'s own return dict
    literal in `implementation_cli.py`), confirmed red, then reverted.
    """

    def test_all_three_binding_key_spellings_agree(self):
        tuple_keys = set(impl._AUTHORIZATION_BINDING_KEYS)

        binding_return_keys = set(returned_keys(CLI, "_authorization_binding"))
        self.assertEqual(
            tuple_keys, binding_return_keys,
            "_authorization_binding's own return must name exactly the "
            "keys _AUTHORIZATION_BINDING_KEYS declares")

        tree = ast.parse(CLI.read_text(encoding="utf-8"))
        cmd_gate = next(
            node for node in ast.walk(tree)
            if isinstance(node, ast.FunctionDef) and node.name == "cmd_gate")
        assign = next(
            node for node in ast.walk(cmd_gate)
            if isinstance(node, ast.Assign)
            and any(isinstance(target, ast.Name) and target.id == "gate_binding"
                    for target in node.targets))
        self.assertIsInstance(assign.value, ast.Dict,
                              "cmd_gate's gate_binding must be a dict literal")
        gate_binding_keys = {
            key.value for key in assign.value.keys
            if isinstance(key, ast.Constant) and isinstance(key.value, str)}
        self.assertEqual(
            tuple_keys, gate_binding_keys,
            "cmd_gate's inline gate_binding dict must name exactly the "
            "keys _AUTHORIZATION_BINDING_KEYS declares")


class ProposeCommandTests(unittest.TestCase):
    """`propose` -- the campaign proposal (design D4, spec domain
    `submission-proposal`). One `proposal` event per call, multi-use,
    never consumed.
    """

    def _box(self, packages=("Method",)):
        self._box_count = getattr(self, "_box_count", 0) + 1
        box = FORGE / "implementations" / f"_e2e_propose_cmd_{os.getpid()}_{id(self)}_{self._box_count}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        box.mkdir(parents=True)
        env = dict(os.environ)
        env["GIT_AUTHOR_NAME"] = env["GIT_COMMITTER_NAME"] = "propose-tests"
        env["GIT_AUTHOR_EMAIL"] = env["GIT_COMMITTER_EMAIL"] = "propose-tests@example.invalid"
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        for package in packages:
            (box / "src" / package).mkdir(parents=True, exist_ok=True)
            (box / "src" / package / "__init__.py").write_text("", encoding="utf-8")
            (box / "src" / f"{package}_Benchmark").mkdir(parents=True, exist_ok=True)
            (box / "src" / f"{package}_Benchmark" / "__init__.py").write_text(
                "", encoding="utf-8")
            (box / package).mkdir(parents=True, exist_ok=True)
        (box / "tests").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "add", "-A"], cwd=box, env=env, check=True,
                       capture_output=True)
        subprocess.run(["git", "commit", "-q", "-m", "initial"], cwd=box, env=env,
                       check=True, capture_output=True)
        return box

    def _write_job_folder(self, box, commit, *, service="svc", job_name="job1"):
        job_dir = box / "tools" / service / job_name
        job_dir.mkdir(parents=True, exist_ok=True)
        run_config = {
            "schemaVersion": 1, "product": "Method", "service": service,
            "jobName": job_name, "commit": commit,
            "repo": {"url": "https://example.invalid/repo.git", "ref": "main"},
            "clonePaths": ["src/Method"],
            "run": {"module": "Method.module", "function": "run", "kwargs": {}},
            "runnerTemplate": [
                {"path": "assets/runner_bootstrap.py", "sha256": "0" * 64},
                {"path": "assets/runner_invoke.py", "sha256": "0" * 64},
            ],
        }
        (job_dir / "run-config.json").write_text(json.dumps(run_config), encoding="utf-8")
        return job_dir

    def run_cli(self, *args):
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=os.environ.copy())

    def test_propose_writes_one_event_naming_every_field(self):
        """RED-then-GREEN target for task 3.4: one proposal event naming
        both jobs, dependency edges and rationale -- scoped "one event,
        all fields present", never the retry scenario (task 3.9 owns
        that).
        """
        box = self._box()
        commit = "a" * 40
        self._write_job_folder(box, commit, job_name="job1")
        self._write_job_folder(box, commit, job_name="job2")

        proc = self.run_cli(
            "propose", "--target", str(box), "--name", "Method", "--session", "s1",
            "--job", "job1", "--job", "job2",
            "--worker", "w1", "--worker", "w2",
            "--depends-on", "job2:job1",
            "--rationale", "Full-scale campaign for the accepted concept.")
        self.assertEqual(proc.returncode, 0, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["status"], "recorded")
        self.assertEqual(sorted(result["jobs"]), ["job1", "job2"])
        self.assertEqual(sorted(result["workers"]), ["w1", "w2"])
        self.assertEqual(result["dependsOn"], [{"job": "job2", "on": "job1"}])
        self.assertEqual(result["rationale"],
                         "Full-scale campaign for the accepted concept.")
        self.assertEqual(result["campaign"]["jobSet"], ["job1", "job2"])

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        proposals = [e for e in events if e.get("kind") == "proposal"]
        self.assertEqual(len(proposals), 1)
        self.assertEqual(set(proposals[0]) - {"kind"},
                         {"digest", "jobs", "workers", "dependsOn", "rationale",
                          "campaign", "session", "at", "proposeOrdinal"})
        self.assertEqual(sorted(proposals[0]["jobs"]), ["job1", "job2"])
        self.assertEqual(proposals[0]["proposeOrdinal"], 0)

    def test_propose_refuses_empty_rationale(self):
        box = self._box()
        proc = self.run_cli(
            "propose", "--target", str(box), "--name", "Method", "--session", "s1",
            "--job", "job1", "--worker", "w1", "--rationale", "   ")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "EMPTY_RATIONALE")

    def test_propose_is_multi_use_and_appends_rather_than_replaces(self):
        """Design D4: no `GATE_PROPOSAL_CONSUMED`, deliberately. Calling
        `propose` a second time appends a SECOND event; the first is
        never edited or removed.
        """
        box = self._box()
        commit = "a" * 40
        self._write_job_folder(box, commit, job_name="job1")
        first = self.run_cli(
            "propose", "--target", str(box), "--name", "Method", "--session", "s1",
            "--job", "job1", "--worker", "w1", "--rationale", "First campaign pass.")
        self.assertEqual(first.returncode, 0, first.stdout)
        second = self.run_cli(
            "propose", "--target", str(box), "--name", "Method", "--session", "s1",
            "--job", "job1", "--worker", "w1", "--rationale", "Second campaign pass.")
        self.assertEqual(second.returncode, 0, second.stdout)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        proposals = [e for e in events if e.get("kind") == "proposal"]
        self.assertEqual(len(proposals), 2)
        self.assertEqual(proposals[0]["proposeOrdinal"], 0)
        self.assertEqual(proposals[1]["proposeOrdinal"], 1)
        self.assertEqual(proposals[0]["rationale"], "First campaign pass.")
        self.assertEqual(proposals[1]["rationale"], "Second campaign pass.")


class RungNotAttainedGateTests(unittest.TestCase):
    """`RUNG_NOT_ATTAINED` -- spec "launch-rung-gate". Reuses
    `GateCommandTests`'s own fixture machinery (`_box`, `_write_job_folder`,
    `_write_smoke_pass`, `_mint_authorization`, `_propose`, `run_cli`)
    rather than rebuilding it: this class exercises the identical launch
    mechanism, only with a declared `__levels__`/`__records__` pair added.
    """

    PROPOSAL_REVISION = GateCommandTests.PROPOSAL_REVISION
    PROPOSAL_TEXT = GateCommandTests.PROPOSAL_TEXT
    PROPOSAL_SHA256 = GateCommandTests.PROPOSAL_SHA256

    def _proposals(self):
        return GateCommandTests._proposals(self)

    def _box(self, packages=("Method",)):
        return GateCommandTests._box(self, packages)

    def _write_job_folder(self, box, commit, **kwargs):
        return GateCommandTests._write_job_folder(self, box, commit, **kwargs)

    def _write_smoke_pass(self, box, **kwargs):
        return GateCommandTests._write_smoke_pass(self, box, **kwargs)

    def _mint_authorization(self, box, proposals, **kwargs):
        return GateCommandTests._mint_authorization(self, box, proposals, **kwargs)

    def _propose(self, box, **kwargs):
        return GateCommandTests._propose(self, box, **kwargs)

    def run_cli(self, *args, proposals=None):
        return GateCommandTests.run_cli(self, *args, proposals=proposals)

    def _declare_ladder_and_record(self, box):
        """`__levels__` and `__records__` -- neither exists in
        `GateCommandTests._box`'s own scaffold, so this fixture declares
        both explicitly. A blank `mark` on both sequence items throughout
        this class (never `x`): `_launch_disagreements` filters
        `disagrees` to ticked items only, so a blank leveled item can move
        between rungs across a fixture's two calls (mint, then gate)
        without ever tripping `POSITION_DISAGREES` or `POSITION_UNBACKED`
        along the way -- the identical restraint that keeps this fixture
        from needing a `position --reconcile` pass between the two."""
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            "__levels__ = ['floor', 'pilot', 'full']\n"
            "__records__ = {'main': {'path': 'r.json', "
            "'requiredScale': {'seeds': 3}}}\n",
            encoding="utf-8")

    def _write_block(self, box):
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1",
                  "target": "full"}
        items = [
            {"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
             "witness": {"kind": "rehearsal", "operand": "job1"}},
            {"ordinal": 2, "mark": " ", "text": "Reach the record.",
             "witness": {"kind": "record", "operand": "main", "twostate": False}},
        ]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

    def test_below_floor_attainment_refuses_rung_not_attained(self):
        """The reachability nuance, using the SIMPLE (placeholder-token)
        entry point rather than the deliberately-constructed one below: a
        non-empty `--authorization` reaches this check regardless of
        whether it would ever verify, because `launch_available` runs
        strictly before token verification."""
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._declare_ladder_and_record(box)
        # No `r.json` at all -- the record derives `False`/the floor rung,
        # below `levels[-2]` ("pilot").
        self._write_block(box)
        proc = self.run_cli(
            "gate", "--target", str(box), "--name", "Method",
            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
            "--job", "job1", "--worker", "w1",
            "--justification", "Because it is time.",
            "--authorization", "unminted-placeholder",
            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "RUNG_NOT_ATTAINED")
        self.assertIn("pilot", result["detail"])
        self.assertEqual(result["resolve"]["kind"], "question")

    def test_the_deliberately_constructed_regressed_evidence_path(self):
        """**A3's reachability nuance, constructed rather than assumed.**
        `GATE_AUTHORIZATION_REQUIRED` (token PRESENCE) sits before
        `launch_available` runs; `_verify_gate_authorization` (token
        VALIDITY) runs last, immediately before the record is appended. So
        in production `RUNG_NOT_ATTAINED` is reachable only on the
        regressed-evidence path: `offer` minted a token when attainment was
        SUFFICIENT, and attainment then fell before `gate` ran. This
        constructs exactly that sequence -- mint first, regress second,
        gate third -- with the REAL minted token, proving the token's own
        VALIDITY still holds (nothing about its binding depended on
        attainment) while the newly-added check refuses anyway."""
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._declare_ladder_and_record(box)
        # Attainment sufficient at mint time: the record exists, at the
        # declared scale -- the top rung.
        (box / "Method" / "r.json").write_text(
            json.dumps({"seeds": 3}), encoding="utf-8")
        self._write_block(box)

        proposals = self._proposals()
        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)

        # Regress: the record this launch's rung depended on is gone. The
        # minted token's own binding (job, commit, entrypoint, units, rung,
        # revisionSha256, positionStatus, proposalDigest) names none of
        # this, so the token itself stays exactly as valid as it was minted.
        (box / "Method" / "r.json").unlink()

        proc = self.run_cli(
            "gate", "--target", str(box), "--name", "Method",
            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
            "--job", "job1", "--worker", "w1",
            "--justification", "Because it is time.",
            "--authorization", token, "--elect", "job1",
            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        result = json.loads(proc.stdout)
        # Never a GATE_AUTHORIZATION_* code: the token itself is genuine
        # and current. The refusal is the rung, not the token.
        self.assertEqual(result["code"], "RUNG_NOT_ATTAINED")

        # And nothing about the token was consumed by this refusal -- the
        # SAME token remains presentable once the rung is actually reached
        # (unlike a `GATE_AUTHORIZATION_CONSUMED` token, which would not).
        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        self.assertFalse(
            any(e["kind"] == "authorization-consumed" for e in events),
            "a refused gate call must never consume the token it was handed")

    def test_offer_silently_omits_the_launch_action_on_identical_facts(self):
        """**A2 -- one shared fixture, both callers, on identical facts.**
        `_offer_launch_action` needs no logic change: its own `if not
        verdict["available"]: return None` already covers this new code
        generically. The SAME below-floor fixture `gate` refuses loudly
        for is here handed to `cmd_offer` instead, and the `launch` action
        for `job1` is simply absent from the published action set -- never
        a disabled-with-a-reason entry, matching every other silent
        omission this function already keeps."""
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._declare_ladder_and_record(box)
        self._write_block(box)
        proposals = self._proposals()

        rcli = impl._load_remote_execution_cli()
        rcli.ADAPTER.register_declared_capacity("svc", lambda: (1, 1))
        args = argparse.Namespace(
            target=str(box), name="Method", revision=self.PROPOSAL_REVISION,
            session="s1", answer="yes", units=None)
        with unittest.mock.patch.dict(
                os.environ, {"IMPLEMENTATION_PROPOSALS": str(proposals)}):
            result = impl.cmd_offer(args)
        launches = [a for a in result["actions"] if a["id"] == "launch"]
        self.assertEqual(launches, [],
                         "a below-floor rung must omit the launch action "
                         "entirely, the identical silent-omission shape "
                         "every other unavailable cause already keeps")


class ProposalAndElectionGateTests(unittest.TestCase):
    """`gate`'s two Phase-3 preconditions (design D4/D5): the campaign
    proposal precondition (`_verify_gate_proposal`) and the optional-job
    election precondition (`_verify_optional_election`), plus D6's
    `GATE_AUTHORIZATION_SUPERSEDED` discriminator. Fixtures mirror
    `GateCommandTests`' own helpers (duplicated per that class's own
    existing convention in this file, not imported).
    """

    PROPOSAL_REVISION = "r1.md"
    PROPOSAL_TEXT = "## 1\ntexto\n"
    PROPOSAL_SHA256 = hashlib.sha256(PROPOSAL_TEXT.encode("utf-8")).hexdigest()

    def _proposals(self):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / self.PROPOSAL_REVISION).write_text(self.PROPOSAL_TEXT, encoding="utf-8")
        return root

    def _box(self):
        self._box_count = getattr(self, "_box_count", 0) + 1
        box = FORGE / "implementations" / f"_e2e_proposal_election_{os.getpid()}_{id(self)}_{self._box_count}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        box.mkdir(parents=True)
        env = dict(os.environ)
        env["GIT_AUTHOR_NAME"] = env["GIT_COMMITTER_NAME"] = "proposal-election-tests"
        env["GIT_AUTHOR_EMAIL"] = env["GIT_COMMITTER_EMAIL"] = "proposal-election-tests@example.invalid"
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        for package in ("Method",):
            (box / "src" / package).mkdir(parents=True, exist_ok=True)
            (box / "src" / package / "__init__.py").write_text("", encoding="utf-8")
            (box / "src" / f"{package}_Benchmark").mkdir(parents=True, exist_ok=True)
            (box / "src" / f"{package}_Benchmark" / "__init__.py").write_text(
                "", encoding="utf-8")
            (box / package).mkdir(parents=True, exist_ok=True)
        (box / "tests").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "add", "-A"], cwd=box, env=env, check=True,
                       capture_output=True)
        subprocess.run(["git", "commit", "-q", "-m", "initial"], cwd=box, env=env,
                       check=True, capture_output=True)
        commit = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=box, env=env, check=True,
            capture_output=True, text=True).stdout.strip()
        return box, commit

    def _write_job_folder(self, box, commit, *, service="svc", job_name="job1"):
        job_dir = box / "tools" / service / job_name
        job_dir.mkdir(parents=True, exist_ok=True)
        run_config = {
            "schemaVersion": 1, "product": "Method", "service": service,
            "jobName": job_name, "commit": commit,
            "repo": {"url": "https://example.invalid/repo.git", "ref": "main"},
            "clonePaths": ["src/Method"],
            "run": {"module": "Method.module", "function": "run", "kwargs": {}},
            "runnerTemplate": [
                {"path": "assets/runner_bootstrap.py", "sha256": "0" * 64},
                {"path": "assets/runner_invoke.py", "sha256": "0" * 64},
            ],
        }
        (job_dir / "run-config.json").write_text(json.dumps(run_config), encoding="utf-8")
        return job_dir

    def _write_smoke_pass(self, box, *, job_name="job1", commit, worker="w1"):
        smoke_path = box / "Method" / ".remote-execution" / "smoke.jsonl"
        smoke_path.parent.mkdir(parents=True, exist_ok=True)
        event = {"kind": "smokeResult", "ts": "2026-08-27T00:00:00Z",
                  "jobName": job_name, "result": "pass", "commit": commit,
                  "worker": worker, "missing": []}
        with smoke_path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(event) + "\n")

    def _write_agreed(self, box, jobs):
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        items = [{"ordinal": i + 1, "mark": " ", "text": f"Rehearse {job}.",
                  "witness": {"kind": "rehearsal", "operand": job}}
                 for i, job in enumerate(jobs)]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

    def run_cli(self, *args, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def _propose(self, box, *, jobs=("job1",), workers=("w1",), session="s1"):
        args = argparse.Namespace(
            target=str(box), name="Method", session=session,
            jobs=list(jobs), workers=list(workers), depends_on=None,
            rationale="Campaign proposal for the test fixture.")
        return impl.cmd_propose(args)

    def _mint_authorization(self, box, proposals, *, job="job1", session="s1"):
        rcli = impl._load_remote_execution_cli()
        rcli.ADAPTER.register_declared_capacity("svc", lambda: (1, 1))
        args = argparse.Namespace(
            target=str(box), name="Method", revision=self.PROPOSAL_REVISION,
            session=session, answer="yes", units=None)
        with unittest.mock.patch.dict(
                os.environ, {"IMPLEMENTATION_PROPOSALS": str(proposals)}):
            result = impl.cmd_offer(args)
        launch = next(
            a for a in result["actions"]
            if a["id"] == "launch" and a["binding"].get("job") == job)
        return launch["binding"]["authorization"]

    # --- GATE_PROPOSAL_* (task 3.9) --------------------------------------

    def test_gate_refuses_proposal_unknown_when_no_proposal_covers_the_job(self):
        """Mutation-proven: treating a `null` `proposalDigest` as "match
        any proposal event" (instead of refusing outright) must turn this
        red -- verified by hand (temporarily changing `_verify_gate_
        proposal`'s lookup predicate to `proposal_digest is None or
        e.get("digest") == proposal_digest`), confirmed red with a
        DIFFERENT code (`GATE_ELECTION_REQUIRED`, since the wrongly
        accepted proposal let the call fall through to the next rung of
        the ladder), then reverted.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        # No `propose` call before minting: the token's own
        # `proposalDigest` is frozen `null`. A campaign IS proposed
        # afterward, covering the same job -- a REAL `proposal` event
        # exists on the ledger by the time `gate` runs, so the mutation
        # below (treating `null` as "match any proposal") has a genuine
        # candidate to wrongly accept.
        token = self._mint_authorization(box, proposals)
        self._propose(box, jobs=["job1"])
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_PROPOSAL_UNKNOWN")

    def test_gate_refuses_proposal_mismatch_when_the_bound_proposal_omits_the_job(self):
        """A genuine, CURRENT proposal exists (its `campaign` matches live
        disk), and the token names it -- but it names only `job1`, and
        THIS gate call is for `job2`. Mutation-proven: widening the
        job-membership test to `any(...)` over every proposal event (not
        only the one the token's own `proposalDigest` names) must turn
        this red -- verified by hand, then reverted.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit, job_name="job1")
        self._write_job_folder(box, commit, job_name="job2")
        self._write_smoke_pass(box, job_name="job2", commit=commit)
        self._write_agreed(box, ["job2"])
        proposals = self._proposals()

        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals, job="job2")
        # A SECOND proposal, naming job2, published AFTER the token above
        # was already minted -- it never becomes what THIS token is bound
        # to (the token's own `proposalDigest` was frozen at mint time,
        # pointing at the first, job1-only proposal). Its only purpose is
        # to give a widened `any(...)` mutation something to wrongly
        # accept; without it, "the only proposal on the ledger" and "the
        # one this token is bound to" would be the same event, and the
        # mutation below would not actually change this test's outcome.
        self._propose(box, jobs=["job2"], session="s2")
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job2", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_PROPOSAL_MISMATCH")

    def test_gate_refuses_proposal_stale_when_a_job_folder_is_added(self):
        """The bound proposal names `job1` and re-digests correctly, but
        its OWN frozen `campaign.jobSet` (`["job1"]`) no longer equals
        what THIS gate call just re-derived from live disk (`["job1",
        "job2"]`, once `job2`'s folder is added after minting).
        Mutation-proven: removing `jobSet` from the proposal's campaign
        identity comparison must turn this red -- verified by hand, then
        reverted.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit, job_name="job1")
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)

        # A job folder is added to the target AFTER the proposal (and the
        # token) were minted -- the second half of design D4's own
        # stated STALE trigger.
        self._write_job_folder(box, commit, job_name="job2")

        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_PROPOSAL_STALE")

    # --- proposal survives a same-campaign retry (task 3.11) -------------

    def test_proposal_survives_a_same_campaign_retry_with_no_re_propose(self):
        """Spec "proposal survives a same-campaign retry": one `propose`
        call, then TWO successful `gate` calls for the same job (the
        second standing in for a retry after the first launch's own
        remote submission failed elsewhere -- the authorization token
        itself is single-use and was already consumed by the first
        `gate`, so the retry mints a FRESH token via `offer` again, never
        a fresh `propose`). Both `gate` calls re-verify against the
        IDENTICAL proposal event.

        Mutation-proven: adding `positionStatus` to the campaign identity
        comparison (temporarily, in `_verify_gate_proposal`, comparing
        `{**campaign, "positionStatus": record.get("positionStatus")}`
        against the proposal's own two-key `campaign`) must turn this red
        -- any extra key the stored proposal event never carried breaks
        the match unconditionally, proving retry-survival currently
        depends on exactly `{commit, jobSet}` and nothing else. Verified
        by hand, then reverted.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        self._propose(box, jobs=["job1"])
        token1 = self._mint_authorization(box, proposals)
        first = self.run_cli("gate", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             "--job", "job1", "--worker", "w1",
                             "--justification", "First attempt.",
                             "--authorization", token1, "--elect", "job1",
                             proposals=proposals)
        self.assertEqual(first.returncode, 0, first.stdout)

        # The retry: a FRESH token (single-use, the first was consumed),
        # no second `propose` call.
        token2 = self._mint_authorization(box, proposals, session="s2")
        second = self.run_cli("gate", "--target", str(box), "--name", "Method",
                              "--revision", self.PROPOSAL_REVISION, "--session", "s2",
                              "--job", "job1", "--worker", "w1",
                              "--justification", "Retry after a transient failure.",
                              "--authorization", token2, "--elect", "job1",
                              proposals=proposals)
        self.assertEqual(second.returncode, 0, second.stdout)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        self.assertEqual(len([e for e in events if e.get("kind") == "proposal"]), 1,
                         "no second propose call should have been needed")

    # --- GATE_ELECTION_* (task 3.14) --------------------------------------

    def test_gate_refuses_election_required_for_an_undecided_job(self):
        """`job1` declares no `accelerator` and no `localBudget`, and no
        results are on file -- `classify_remote_necessity` verdicts
        `optional`. Mutation-proven: defaulting `--elect` to "every
        optional job in the unit" (instead of requiring it named
        explicitly) must turn this red -- verified by hand, then
        reverted.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_ELECTION_REQUIRED")

    def test_gate_refuses_election_mismatch_naming_a_different_job(self):
        """`--elect job1` satisfies the REQUIRED check (job1 IS named),
        but a SECOND `--elect job2` also names a job outside this gate
        call's own scope -- refused, not silently accepted alongside the
        valid one. `job1` alone (without the stray `job2`) is exactly
        `test_gate_records_the_authorization_after_a_passing_rehearsal`'s
        own passing shape in `GateCommandTests`, so this isolates the
        extra name as the only difference. Mutation-proven: dropping the
        not-in-unit / not-optional check (accepting any `--elect` value
        unconditionally once the REQUIRED check is satisfied) must turn
        this red -- verified by hand, then reverted.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            "--elect", "job1", "--elect", "job2",
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_ELECTION_MISMATCH")

    def test_gate_refuses_election_mismatch_for_a_job_that_already_decides(self):
        """`--elect job1` while `job1`'s own facts already decide it
        (`accelerator` declared -> `must-remote`) -- electing something
        that was never in question is refused, not silently accepted.
        """
        box, commit = self._box()
        job_dir = self._write_job_folder(box, commit)
        run_config = json.loads((job_dir / "run-config.json").read_text(encoding="utf-8"))
        run_config["accelerator"] = {"kind": "gpu", "architectures": ["t4"]}
        (job_dir / "run-config.json").write_text(json.dumps(run_config), encoding="utf-8")
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token, "--elect", "job1",
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_ELECTION_MISMATCH")

    def test_gate_accepts_a_declared_accelerator_job_with_no_election(self):
        """The mirror of the case above: `job1` classifies `must-remote`
        (accelerator declared) and `gate` succeeds with NO `--elect` at
        all -- an election is only ever required for `optional`.
        """
        box, commit = self._box()
        job_dir = self._write_job_folder(box, commit)
        run_config = json.loads((job_dir / "run-config.json").read_text(encoding="utf-8"))
        run_config["accelerator"] = {"kind": "gpu", "architectures": ["t4"]}
        (job_dir / "run-config.json").write_text(json.dumps(run_config), encoding="utf-8")
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["elected"], [])

    # --- GATE_AUTHORIZATION_SUPERSEDED vs _UNKNOWN (task 3.17) -----------

    def test_a_pre_change_seven_key_token_is_superseded_not_unknown(self):
        """A legitimate token minted before `proposalDigest` joined the
        binding -- hand-constructed to the EXACT 7-key digest shape this
        forge used before this change, over the SAME `hashlib.sha256(
        json.dumps(..., sort_keys=True))` form `_find_or_mint_
        authorization` still uses. Distinguished from a genuinely unknown
        or tampered token (a literal 64-hex string nothing minted, or an
        edited record) by re-digesting correctly under the 7-key shape.

        Mutation-proven: deleting the 7-key fallback recompute in
        `_verify_gate_authorization` must collapse this back to
        `GATE_AUTHORIZATION_UNKNOWN` -- verified by hand, then reverted.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        entrypoint = "tools/svc/job1/run.py"
        seven_key_binding = {
            "jobName": "job1", "commit": commit, "entrypoint": entrypoint,
            "units": [], "rung": 1, "revisionSha256": self.PROPOSAL_SHA256,
            "positionStatus": "current",
        }
        session, at, mint_ordinal = "s0", "2026-08-27T00:00:00Z", 0
        payload = {**seven_key_binding, "session": session, "at": at,
                  "mintOrdinal": mint_ordinal}
        token = hashlib.sha256(
            json.dumps(payload, sort_keys=True).encode("utf-8")).hexdigest()
        ledger = box / "Method" / ".implementation" / "position.jsonl"
        impl_position.append_event(ledger, {
            "kind": "authorization", "token": token, **payload})

        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_AUTHORIZATION_SUPERSEDED")

    def test_an_edited_post_change_token_stays_unknown_not_superseded(self):
        """The distinction is a measurement, not a guess (D6): an editor
        who merely deleted `proposalDigest` from a genuine POST-change
        event still fails the 7-key recompute too, because that event's
        token was digested WITH the key present. This must stay
        `GATE_AUTHORIZATION_UNKNOWN`, never collapse to `SUPERSEDED`.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, ["job1"])
        proposals = self._proposals()

        self._propose(box, jobs=["job1"])
        token = self._mint_authorization(box, proposals)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        events = [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]
        for event in events:
            if event.get("kind") == "authorization" and event.get("token") == token:
                del event["proposalDigest"]
        ledger.write_text(
            "\n".join(json.dumps(e) for e in events) + "\n", encoding="utf-8")

        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", token,
                            proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "GATE_AUTHORIZATION_UNKNOWN")


class OfferCommandTests(unittest.TestCase):
    """`offer` -- the state-derived action menu. Refuses to publish unless
    `--answer` is supplied on THIS exact call -- never read back from a
    prior `offer` event -- then publishes a closed action set derived
    entirely from the identical facts `gate` itself reads (spec "One shared
    availability rule for the publisher and `cmd_gate`").
    """

    PROPOSAL_REVISION = "r1.md"
    PROPOSAL_TEXT = "## 1\ntexto\n"
    PROPOSAL_SHA256 = hashlib.sha256(PROPOSAL_TEXT.encode("utf-8")).hexdigest()

    def _proposals(self):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / self.PROPOSAL_REVISION).write_text(self.PROPOSAL_TEXT, encoding="utf-8")
        (root / "r2.md").write_text("## 2\notro\n", encoding="utf-8")
        return root

    def setUp(self):
        """Every in-process `impl.cmd_offer(...)` call in this class reads
        `revision_source()` straight off `os.environ`, in THIS process --
        unlike `run_cli`'s own subprocess calls, which pass `proposals=`
        as a child environment variable, an in-process call has no such
        seam, so this class-wide fixture is set once here and every
        `_offer_args(...)` call below relies on it being present.
        """
        proposals = self._proposals()
        patcher = unittest.mock.patch.dict(
            os.environ, {"IMPLEMENTATION_PROPOSALS": str(proposals)})
        patcher.start()
        self.addCleanup(patcher.stop)

    def _box(self, packages=("Method",)):
        self._box_count = getattr(self, "_box_count", 0) + 1
        box = FORGE / "implementations" / f"_e2e_offer_cmd_{os.getpid()}_{id(self)}_{self._box_count}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        box.mkdir(parents=True)
        env = dict(os.environ)
        env["GIT_AUTHOR_NAME"] = env["GIT_COMMITTER_NAME"] = "offer-tests"
        env["GIT_AUTHOR_EMAIL"] = env["GIT_COMMITTER_EMAIL"] = "offer-tests@example.invalid"
        subprocess.run(["git", "init", "-q", str(box)], check=True, capture_output=True)
        for package in packages:
            (box / "src" / package).mkdir(parents=True, exist_ok=True)
            (box / "src" / package / "__init__.py").write_text("", encoding="utf-8")
            (box / "src" / f"{package}_Benchmark").mkdir(parents=True, exist_ok=True)
            (box / "src" / f"{package}_Benchmark" / "__init__.py").write_text(
                "", encoding="utf-8")
            (box / package).mkdir(parents=True, exist_ok=True)
        (box / "tests").mkdir(parents=True, exist_ok=True)
        subprocess.run(["git", "add", "-A"], cwd=box, env=env, check=True,
                       capture_output=True)
        subprocess.run(["git", "commit", "-q", "-m", "initial"], cwd=box, env=env,
                       check=True, capture_output=True)
        commit = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=box, env=env, check=True,
            capture_output=True, text=True).stdout.strip()
        return box, commit

    def _write_job_folder(self, box, commit, *, service="offer-fixture-svc",
                          job_name="job1", product="Method",
                          clone_paths=("src/Method",)):
        job_dir = box / "tools" / service / job_name
        job_dir.mkdir(parents=True, exist_ok=True)
        run_config = {
            "schemaVersion": 1, "product": product, "service": service,
            "jobName": job_name, "commit": commit,
            "repo": {"url": "https://example.invalid/repo.git", "ref": "main"},
            "clonePaths": list(clone_paths),
            "run": {"module": f"{product}.module", "function": "run", "kwargs": {}},
            "runnerTemplate": [
                {"path": "assets/runner_bootstrap.py", "sha256": "0" * 64},
                {"path": "assets/runner_invoke.py", "sha256": "0" * 64},
            ],
        }
        (job_dir / "run-config.json").write_text(json.dumps(run_config), encoding="utf-8")
        return job_dir

    def _write_smoke_pass(self, box, *, product="Method", job_name="job1",
                          commit, worker="w1"):
        smoke_path = box / product / ".remote-execution" / "smoke.jsonl"
        smoke_path.parent.mkdir(parents=True, exist_ok=True)
        event = {"kind": "smokeResult", "ts": "2026-08-27T00:00:00Z",
                  "jobName": job_name, "result": "pass", "commit": commit,
                  "worker": worker, "missing": []}
        with smoke_path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(event) + "\n")

    def _write_smoke_fail(self, box, *, product="Method", job_name="job1",
                          commit, worker="w1"):
        """A recorded, matching-commit smoke result whose own `result` is
        `"fail"` -- so `smokeReady`/`derive()` measure `False`, not
        `None`. Distinct from never running one at all: an unmeasured
        witness is `unbacked`, a measured-and-failing one that is ticked
        anyway is `disagrees`, and only the latter is this helper's job.
        """
        smoke_path = box / product / ".remote-execution" / "smoke.jsonl"
        smoke_path.parent.mkdir(parents=True, exist_ok=True)
        event = {"kind": "smokeResult", "ts": "2026-08-27T00:00:00Z",
                  "jobName": job_name, "result": "fail", "commit": commit,
                  "worker": worker, "missing": []}
        with smoke_path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(event) + "\n")

    def _write_agreed(self, box, items):
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1", "target": "final"}
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

    def run_cli(self, *args, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def _register_fixture_reporter(self, box, service, capacity=(3, 2)):
        """Registers a capacity reporter directly, bypassing the file-based
        `_load_backend_module` mechanism -- this test runs `cmd_offer`
        IN-PROCESS (never as a subprocess) specifically so this
        registration, made through the exact `ADAPTER` module object
        `cmd_offer` itself reads, is visible to it.
        """
        rcli = impl._load_remote_execution_cli()
        rcli.ADAPTER.register_declared_capacity(service, lambda: capacity)
        return rcli

    def _offer_args(self, box, *, answer=None, session="s1",
                    revision=None, units=None):
        return argparse.Namespace(
            target=str(box), name="Method",
            revision=revision or self.PROPOSAL_REVISION, session=session,
            answer=answer, units=units)

    def _authorization_events(self, box):
        ledger = box / "Method" / ".implementation" / "position.jsonl"
        return [e for e in impl_position.read_events(ledger)
                if e.get("kind") == "authorization"]

    def _propose(self, box, *, jobs=("job1",), workers=("w1",), session="s1"):
        """A REAL `proposal` event, appended through the actual
        `cmd_propose` path in-process, mirroring `GateCommandTests`' own
        helper of the same name -- called BEFORE `cmd_offer` mints in any
        fixture that later expects `gate` to accept the minted token.
        """
        args = argparse.Namespace(
            target=str(box), name="Method", session=session,
            jobs=list(jobs), workers=list(workers), depends_on=None,
            rationale="Campaign proposal for the test fixture.")
        return impl.cmd_propose(args)

    # --- refusal shape and pre-answer behavior ----------------------------

    def test_offer_refuses_a_non_token_answer_with_the_same_json_refusal_shape(self):
        box, _ = self._box()
        proc = self.run_cli("offer", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--answer", "maybe", proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "OFFER_ANSWER_NOT_A_TOKEN")
        # The identical key shape every other refusal prints -- proves this
        # went through the coded `Refused` path, never argparse `choices`,
        # which would have printed usage text on stderr and nothing
        # JSON-shaped on stdout at all.
        self.assertEqual(set(result), {"status", "code", "detail"})

    def test_offer_refuses_before_any_answer_and_publishes_no_actions_key(self):
        box, commit = self._box()
        self._write_job_folder(box, commit)
        proc = self.run_cli("offer", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        result = json.loads(proc.stdout)
        self.assertEqual(result["code"], "OFFER_UNANSWERED")
        self.assertNotIn("actions", result)

    def test_no_answer_always_refuses_regardless_of_ledger_history(self):
        """Renamed from `..._with_no_offer_event_reads_as_unanswered`
        (spec "A test name MUST NOT assert a dead premise"): that name
        singled out "pre-existing ledger" as a distinct case, but every
        ledger state with no `--answer` reads as unanswered identically
        now -- there is no read-back left to make one history special.
        Exercises both shapes the old name conflated (spec "Renamed test
        still exercises both ledger shapes"): an empty ledger, and one
        holding only a `gate` event -- the exact shape a `position.jsonl`
        written before `offer` existed would carry.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        proposals = self._proposals()

        empty = self.run_cli("offer", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             proposals=proposals)
        self.assertEqual(empty.returncode, 2, empty.stdout)
        self.assertEqual(json.loads(empty.stdout)["code"], "OFFER_UNANSWERED")

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        impl_position.append_event(ledger, {
            "kind": "gate", "jobName": "job1", "worker": "w1", "commit": commit,
            "revision": self.PROPOSAL_REVISION, "revisionSha256": self.PROPOSAL_SHA256,
            "entrypoint": "tools/offer-fixture-svc/job1/run.py", "units": [],
            "justification": "prior work", "session": "s0", "at": "2026-08-27T00:00:00Z",
        })
        gate_only = self.run_cli("offer", "--target", str(box), "--name", "Method",
                                 "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                                 proposals=proposals)
        self.assertEqual(gate_only.returncode, 2, gate_only.stdout)
        self.assertEqual(json.loads(gate_only.stdout)["code"], "OFFER_UNANSWERED")

    def test_two_consecutive_unanswered_calls_both_refuse(self):
        """Spec "Two consecutive unattended calls both ask": no read-back
        exists for `offer` to fall back on, so a second unanswered call
        refuses identically to the first -- never softened by the fact
        that a call already happened, and neither call appends an event.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        proposals = self._proposals()

        first = self.run_cli("offer", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             proposals=proposals)
        self.assertEqual(first.returncode, 2, first.stdout)
        self.assertEqual(json.loads(first.stdout)["code"], "OFFER_UNANSWERED")
        self.assertNotIn("actions", json.loads(first.stdout))

        second = self.run_cli("offer", "--target", str(box), "--name", "Method",
                              "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                              proposals=proposals)
        self.assertEqual(second.returncode, 2, second.stdout)
        self.assertEqual(json.loads(second.stdout)["code"], "OFFER_UNANSWERED")
        self.assertNotIn("actions", json.loads(second.stdout))

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        self.assertFalse(ledger.exists(),
                         "neither refused call may create the ledger")

    def test_a_recorded_answer_does_not_excuse_a_later_unanswered_call(self):
        """Spec "A recorded answer does not excuse a later unanswered
        call": a ledger already holding an answered `offer` event refuses
        identically to one with none -- `OFFER_UNANSWERED` never consults
        history to decide whether it applies.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        proposals = self._proposals()

        first = self.run_cli("offer", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             "--answer", "yes", proposals=proposals)
        self.assertEqual(first.returncode, 0, first.stdout)

        second = self.run_cli("offer", "--target", str(box), "--name", "Method",
                              "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                              proposals=proposals)
        self.assertEqual(second.returncode, 2, second.stdout)
        self.assertEqual(json.loads(second.stdout)["code"], "OFFER_UNANSWERED")

    def test_offer_requires_the_answer_again_on_every_later_call(self):
        """Renamed subject: from "records once, reuses after" to "always
        requires" -- the second call's ledger-count assertion inverts from
        expecting no growth on an unanswered repeat to expecting that
        repeat refused outright, appending nothing.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        proposals = self._proposals()

        first = self.run_cli("offer", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             "--answer", "no", proposals=proposals)
        self.assertEqual(first.returncode, 0, first.stdout)
        self.assertEqual(json.loads(first.stdout)["status"], "recorded")

        second = self.run_cli("offer", "--target", str(box), "--name", "Method",
                              "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                              proposals=proposals)
        self.assertEqual(second.returncode, 2, second.stdout)
        self.assertEqual(json.loads(second.stdout)["code"], "OFFER_UNANSWERED")

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        offer_events = [json.loads(line) for line
                        in ledger.read_text(encoding="utf-8").splitlines()
                        if json.loads(line).get("kind") == "offer"]
        self.assertEqual(len(offer_events), 1,
                         "a refused unanswered repeat must not append a "
                         "second offer event")

    def test_a_supplied_answer_is_always_honored_never_compared_to_history(self):
        """Spec "A supplied answer is always honored, never compared to
        history": a ledger holding a "no" answer does not stop a later
        "yes" from succeeding, and both events land on the ledger -- the
        prior event is never consulted to accept, reject, or dedup the
        later one.
        """
        box, commit = self._box()
        self._write_job_folder(box, commit)
        proposals = self._proposals()

        first = self.run_cli("offer", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             "--answer", "no", proposals=proposals)
        self.assertEqual(first.returncode, 0, first.stdout)

        second = self.run_cli("offer", "--target", str(box), "--name", "Method",
                              "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                              "--answer", "yes", proposals=proposals)
        self.assertEqual(second.returncode, 0, second.stdout)
        result = json.loads(second.stdout)
        self.assertEqual(result["answer"], "yes")
        self.assertEqual(result["status"], "recorded")

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        offer_events = [json.loads(line) for line
                        in ledger.read_text(encoding="utf-8").splitlines()
                        if json.loads(line).get("kind") == "offer"]
        self.assertEqual(len(offer_events), 2,
                         "both calls append -- offer never dedups against "
                         "a prior answer")
        self.assertEqual(offer_events[0]["answer"], "no")
        self.assertEqual(offer_events[1]["answer"], "yes")

    def test_a_stored_actions_snapshot_never_changes_a_later_calls_output(self):
        """Spec "A stored `actions` snapshot never changes a later call's
        output": the `actions` field on a recorded event is a record of
        what was offered at that moment, never a cache a later call reads
        back to decide what to publish -- proven by a newly discoverable,
        available job's `launch` action appearing only on the second call.
        In-process (like the authorization tests above), since a `launch`
        action needs the fixture capacity reporter registered directly
        through `_load_remote_execution_cli`'s module object, which a
        subprocess call cannot see.
        """
        box, commit = self._box()
        self._register_fixture_reporter(box, "offer-fixture-svc")
        proposals = self._proposals()

        with unittest.mock.patch.dict(
                os.environ, {"IMPLEMENTATION_PROPOSALS": str(proposals)}):
            first = impl.cmd_offer(self._offer_args(box, answer="yes"))
        self.assertNotIn(
            "launch", {a["id"] for a in first["actions"]},
            "no job folder exists yet on the first call")

        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                                  "witness": {"kind": "rehearsal", "operand": "job1"}}])

        with unittest.mock.patch.dict(
                os.environ, {"IMPLEMENTATION_PROPOSALS": str(proposals)}):
            second = impl.cmd_offer(self._offer_args(box, answer="yes"))

        self.assertIn(
            "launch", {a["id"] for a in second["actions"]},
            "a newly discoverable, available job must appear on the "
            "second call -- the first call's stored actions snapshot "
            "must never be read back to decide this one's output")

    # --- read-back removed: structural and documentary guards -----------

    def test_cmd_offer_never_reads_a_prior_answer_back(self):
        """Structural guard, INVERTED from
        `test_cmd_offer_dedup_reads_standing_never_existing` rather than
        deleted with the mechanism it guarded (spec "The read-back guard
        is inverted, not deleted"; design "Write-only history: stated in
        place AND held by a test"). Same `ast`-over-`inspect.getsource`
        idiom `reportable_fidelity_states` already uses on `cmd_verify`.

        Two independent structural facts over `cmd_offer`'s own source:

        1. No `ast.Compare` anywhere in `cmd_offer` compares the string
           literal `"offer"` against a `kind` subscript or `.get` call --
           the shape a reintroduced `e.get("kind") == "offer"` lookup
           would take.
        2. No subscript or `.get` read of the string `"answer"` targets
           anything other than `args` -- the shape a reintroduced
           `existing["answer"]` / `existing.get("answer")` read would
           take. The append dict's `"answer"` key is an `ast.Dict` key,
           never a subscript or `.get` call, so it does not trip this.

        Reachable red, confirmed by hand against the unmodified function on
        `35922f3`: `existing = next((e for e in reversed(events) if
        e.get("kind") == "offer"), None)` trips fact 1, and
        `existing["answer"]` / `existing.get("answer")` at that revision
        trip fact 2 -- both assertions below fail against that source,
        proving this guard reaches the exact code it targets.
        """
        tree = ast.parse(textwrap.dedent(inspect.getsource(impl.cmd_offer)))

        def is_kind_offer_compare(node):
            if not isinstance(node, ast.Compare):
                return False
            operands = [node.left, *node.comparators]
            has_offer_literal = any(
                isinstance(o, ast.Constant) and o.value == "offer" for o in operands)
            has_kind_read = any(
                (isinstance(o, ast.Subscript)
                 and isinstance(o.slice, ast.Constant) and o.slice.value == "kind")
                or (isinstance(o, ast.Call) and isinstance(o.func, ast.Attribute)
                    and o.func.attr == "get"
                    and o.args and isinstance(o.args[0], ast.Constant)
                    and o.args[0].value == "kind")
                for o in operands)
            return has_offer_literal and has_kind_read

        kind_offer_compares = [n for n in ast.walk(tree) if is_kind_offer_compare(n)]
        self.assertEqual(
            kind_offer_compares, [],
            "cmd_offer must never compare an event's kind against the "
            "literal 'offer' -- that is exactly the shape of the deleted "
            "read-back lookup reappearing")

        def is_answer_read(node):
            if isinstance(node, ast.Subscript):
                return (isinstance(node.slice, ast.Constant)
                        and node.slice.value == "answer"
                        and not (isinstance(node.value, ast.Name)
                                 and node.value.id == "args"))
            if isinstance(node, ast.Call):
                return (isinstance(node.func, ast.Attribute)
                        and node.func.attr == "get"
                        and node.args and isinstance(node.args[0], ast.Constant)
                        and node.args[0].value == "answer"
                        and not (isinstance(node.func.value, ast.Name)
                                 and node.func.value.id == "args"))
            return False

        answer_reads = [n for n in ast.walk(tree) if is_answer_read(n)]
        self.assertEqual(
            answer_reads, [],
            "cmd_offer must never read an 'answer' key/attr off anything "
            "but args -- a read off a prior ledger event is exactly the "
            "shape of the deleted read-back reappearing")

    def test_offer_unanswered_and_token_checks_are_the_first_two_statements(self):
        """Structural proof for design decision 1 ("Position above
        resolve_target/revision_source is the structural proof nothing was
        read back"): the `OFFER_UNANSWERED` and answer-token checks are the
        FIRST TWO statements in `cmd_offer`'s body, both preceding any call
        to `resolve_target`/`revision_source`. This is the STRUCTURAL half
        and is the stronger proof (task 1.14); the phrase-only test on the
        write-only-history documentation (below) is weaker by construction
        and does not substitute for this one.

        Reachable red, confirmed by hand: moving either `if` below the
        `resolve_target(...)` call, or swapping their order, flips this
        red -- verified, then reverted.
        """
        tree = ast.parse(textwrap.dedent(inspect.getsource(impl.cmd_offer)))
        func = tree.body[0]
        self.assertIsInstance(func, ast.FunctionDef)
        statements = [
            s for s in func.body
            if not (isinstance(s, ast.Expr) and isinstance(s.value, ast.Constant)
                    and isinstance(s.value.value, str))]
        self.assertGreaterEqual(len(statements), 2, "nothing was scanned")

        first, second = statements[0], statements[1]

        def is_refused_if(stmt, code):
            if not isinstance(stmt, ast.If):
                return False
            return any(
                isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
                and n.func.id == "Refused" and n.args
                and isinstance(n.args[0], ast.Constant) and n.args[0].value == code
                for n in ast.walk(stmt))

        self.assertTrue(
            is_refused_if(first, "OFFER_UNANSWERED"),
            "the first statement in cmd_offer's body must be the "
            "OFFER_UNANSWERED check")
        self.assertTrue(
            is_refused_if(second, "OFFER_ANSWER_NOT_A_TOKEN"),
            "the second statement in cmd_offer's body must be the "
            "answer-token check")

        for stmt in (first, second):
            for n in ast.walk(stmt):
                if isinstance(n, ast.Call) and isinstance(n.func, ast.Name):
                    self.assertNotIn(
                        n.func.id, {"resolve_target", "revision_source"},
                        "the first two statements must be pure-argv "
                        "checks, never calling resolve_target/"
                        "revision_source")

    def test_the_append_site_documents_the_offer_event_as_write_only_history(self):
        """Documentary proof (spec "The `offer` event is documented
        write-only history" / "The append site is self-documenting"),
        weaker by construction than the two structural guards above: a
        substring match on comment text can be satisfied by prose that
        lies, so this test alone would never have caught the original
        read-back defect. It exists only so a later dead-code audit does
        not delete the `offer` event's append call as unreachable history
        the way an earlier audit deleted a rule nothing called.
        """
        # Strip each line's leading `#` before normalizing whitespace --
        # otherwise the comment marker on every continuation line becomes
        # its own token and splits the phrase this test looks for.
        cleaned_lines = []
        for line in inspect.getsource(impl.cmd_offer).splitlines():
            stripped = line.strip()
            if stripped.startswith("#"):
                stripped = stripped[1:].strip()
            cleaned_lines.append(stripped)
        normalized = " ".join(" ".join(cleaned_lines).split())

        self.assertIn("write-only history", normalized)
        self.assertIn(
            'no code path under `.claude/skills/**/*.py` ever reads a '
            '`kind: "offer"` event\'s fields back into any later decision',
            normalized)

    def test_a_second_answer_appends_never_rewrites(self):
        """Renamed from `..._reopen_and_re_answer_appends_never_rewrites`,
        `__steps__` mutation dropped: the assertion this test holds --
        append-only, byte-identical on disk -- was never actually about a
        reopen; it is true of ANY second `offer` call, since every call
        now requires and appends a fresh answer.
        """
        box, commit = self._box()
        proposals = self._proposals()

        first = self.run_cli("offer", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             "--answer", "yes", proposals=proposals)
        self.assertEqual(first.returncode, 0, first.stdout)

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        original_lines = ledger.read_text(encoding="utf-8").splitlines()
        self.assertEqual(len(original_lines), 1)
        original_first_line = original_lines[0]

        second = self.run_cli("offer", "--target", str(box), "--name", "Method",
                              "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                              "--answer", "no", proposals=proposals)
        self.assertEqual(second.returncode, 0, second.stdout)

        new_lines = ledger.read_text(encoding="utf-8").splitlines()
        self.assertEqual(
            new_lines[0], original_first_line,
            "the original event's bytes must be unchanged on disk after a "
            "second answer")
        offer_lines = [line for line in new_lines
                       if json.loads(line).get("kind") == "offer"]
        self.assertEqual(len(offer_lines), 2)
        self.assertEqual(offer_lines[0], original_first_line)

    def test_an_authorization_minted_before_a_later_contract_change_still_gates(self):
        """Renamed from
        `..._pre_reopen_authorization_still_gates_after_the_contract_reopens`:
        `_AUTHORIZATION_BINDING_KEYS` is out of scope for this change and
        still names no contract fact, so a token minted before a later
        change to `__steps__` keeps gating exactly as before -- this was
        never about a reopen, only about what the authorization binding
        does and does not cover. `proposalDigest` (the 8th key, added by
        `the-pilot-decides-the-remote-strategy`) does not disturb this
        claim either: it is a LEDGER fact (the digest of a `proposal`
        event on this same target's ledger), never a `__steps__` contract
        fact -- read, not assumed (task 3.22).
        """
        box, commit = self._box()
        self._register_fixture_reporter(box, "offer-fixture-svc")
        self._write_job_folder(box, commit)
        self._write_smoke_pass(box, commit=commit)
        self._write_agreed(box, [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                                  "witness": {"kind": "rehearsal", "operand": "job1"}}])
        proposals = self._proposals()
        self._propose(box, jobs=["job1"])

        with unittest.mock.patch.dict(
                os.environ, {"IMPLEMENTATION_PROPOSALS": str(proposals)}):
            result = impl.cmd_offer(self._offer_args(box, answer="yes"))
        launch = next(a for a in result["actions"] if a["id"] == "launch")
        token = launch["binding"]["authorization"]

        # An ordinary contract change: __steps__ moves from undeclared to
        # naming one step. The token stays unconsumed; nothing about the
        # launch binding it carries (job/commit/entrypoint/units/rung/
        # revisionSha256/positionStatus/proposalDigest) is affected by this.
        bench_init = box / "src" / "Method_Benchmark" / "__init__.py"
        bench_init.write_text(
            "__steps__ = {'pilot': {'module': 'Method.pilot', 'function': 'run'}}\n",
            encoding="utf-8")

        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Rehearsal passed at the pinned commit.",
                            "--authorization", token, "--elect", "job1",
                            proposals=proposals)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["status"], "recorded")

