class UnbackedPositionSurfaceTests(unittest.TestCase):
    """A ticked box nobody measured, wherever the position is already reported.

    `disagrees` is surfaced by `position_state`, by `verify`, by `probe` and by
    `position` itself, and `unbacked` is the same kind of fact about the same
    item: a reader who is told which marks contradict their evidence, and not
    which marks have none, has been told the honest half.

    And `gate` refuses on one. A record whose whole purpose is that the
    recorded sequence is honest cannot be minted over a step asserted by a
    hand-typed `x` whose witness nothing ever looked at -- here, `@shard`
    with no `distribution.shardsRoot` declared and no `--shards` override,
    so the refusal is the honest `POSITION_SHARDS_UNDECLARED`, not the
    general `POSITION_UNBACKED` (see `LaunchAvailableTests` in
    `tests/test_implementation_core.py` for the two read apart at the unit
    that decides between them).
    """

    PROPOSAL_REVISION = "r1.md"
    PROPOSAL_TEXT = "## 1\nprose\n"
    PROPOSAL_SHA256 = hashlib.sha256(PROPOSAL_TEXT.encode("utf-8")).hexdigest()

    def _proposals(self):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        (root / self.PROPOSAL_REVISION).write_text(self.PROPOSAL_TEXT,
                                                   encoding="utf-8")
        return root

    def _box(self, suffix, *, mark):
        """A target whose one sequence item names a `@shard` witness -- the
        witness no invocation here supplies evidence for, so `satisfied` is
        `None` and only the mark decides whether that is honest."""
        box = FORGE / "implementations" / f"_unbacked_{suffix}_{os.getpid()}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        for directory in ("src/Method", "src/Method_Benchmark", "Method", "tests"):
            (box / directory).mkdir(parents=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        (box / "src/Method_Benchmark/__init__.py").write_text(
            "__benchmark__ = {'revision': 'r1.md'}\n", encoding="utf-8")
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        header = {"revision": self.PROPOSAL_REVISION,
                  "revisionSha256": self.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1",
                  "target": "final"}
        items = [{"ordinal": 1, "mark": mark, "text": "Collect the shard.",
                  "witness": {"kind": "shard", "operand": "s0"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")
        return box

    def run_cli(self, *args, proposals=None):
        env = dict(os.environ)
        if proposals is not None:
            env["IMPLEMENTATION_PROPOSALS"] = str(proposals)
        return subprocess.run([sys.executable, str(CLI), *args],
                              capture_output=True, text=True, cwd=FORGE, env=env)

    def position_block(self, command, box, *extra, proposals=None):
        proc = self.run_cli(command, "--target", str(box), "--name", "Method",
                            *extra, proposals=proposals)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        return json.loads(proc.stdout)["position"]

    def test_verify_names_the_unbacked_tick_and_leaves_the_blank_box_alone(self):
        """Both halves in one test, because the claim is a distinction: a
        reporter that named every unmeasured item would be as useless as one
        that named none."""
        ticked = self.position_block("verify", self._box("verify_x", mark="x"))
        blank = self.position_block("verify", self._box("verify_blank", mark=" "))

        self.assertEqual([e["ordinal"] for e in ticked["unbacked"]], [1])
        self.assertEqual(blank["unbacked"], [])
        # Both are unmeasured -- that was never the question.
        self.assertEqual([e["ordinal"] for e in ticked["unmeasured"]], [1])
        self.assertEqual([e["ordinal"] for e in blank["unmeasured"]], [1])
        # And neither is a disagreement: there is no measurement to contradict.
        self.assertEqual(ticked["disagreements"], [])
        self.assertTrue(ticked["sequence"][0]["unbacked"])
        self.assertFalse(blank["sequence"][0]["unbacked"])

    def test_probe_reports_it_too(self):
        """`probe` reads the same position through the same function; a key
        surfaced in one reader and not the other is a key a reader cannot
        rely on."""
        block = self.position_block("probe", self._box("probe", mark="x"))
        self.assertEqual([e["ordinal"] for e in block["unbacked"]], [1])

    def test_position_reports_the_tick_its_own_refresh_cannot_correct(self):
        """The sharpest of the three. A refresh rewrites a contradicted mark
        on the spot -- but an unmeasured item is skipped and its mark survives
        untouched, so `position` is exactly the command whose silence left the
        assertion standing."""
        box = self._box("position", mark="x")
        proc = self.run_cli("position", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION,
                            "--session", "s1", proposals=self._proposals())
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        result = json.loads(proc.stdout)

        self.assertEqual(result["unbacked"], [1])
        self.assertEqual(result["unmeasured"], [1])
        self.assertTrue(result["sequence"][0]["unbacked"])
        # And the mark really did survive: this is not a report about a
        # correction that happened.
        self.assertEqual(result["sequence"][0]["mark"], "x")

    def test_an_absent_position_reports_the_key_rather_than_omitting_it(self):
        """The uniform-key-set rule `position_state` already documents: a key
        that appears on some branches and not others vanishes for exactly the
        callers that took the early ones."""
        box = FORGE / "implementations" / f"_unbacked_absent_{os.getpid()}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src/Method").mkdir(parents=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)

        block = self.position_block("verify", box)
        self.assertEqual(block["status"], "absent")
        self.assertEqual(block["unbacked"], [])

    def test_gate_refuses_a_launch_authorized_over_an_undeclared_shard_tick(self):
        box = self._box("gate", mark="x")
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", "unminted-placeholder",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "POSITION_SHARDS_UNDECLARED")

    def test_the_same_gate_over_a_blank_box_reaches_the_readiness_check(self):
        """The pole, and the ordering proof in one: with the mark blanked and
        nothing else changed, the refusal moves on to `NOT_READY` -- so this
        check sits before that one and fires on the tick, not on the target."""
        box = self._box("gate_blank", mark=" ")
        proc = self.run_cli("gate", "--target", str(box), "--name", "Method",
                            "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                            "--job", "job1", "--worker", "w1",
                            "--justification", "Because it is time.",
                            "--authorization", "unminted-placeholder",
                            proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        self.assertEqual(json.loads(proc.stdout)["code"], "NOT_READY")

    def test_absent_and_stale_still_refuse_first(self):
        """Ordered AFTER the two checks about whether there is a position to
        read at all: an unbacked list computed from a section bound to a
        revision that has moved on would be naming ticks against the wrong
        evidence entirely."""
        box = FORGE / "implementations" / f"_unbacked_order_{os.getpid()}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src/Method").mkdir(parents=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        (box / "Method").mkdir(parents=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        proposals = self._proposals()

        absent = self.run_cli("gate", "--target", str(box), "--name", "Method",
                              "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                              "--job", "job1", "--worker", "w1",
                              "--justification", "Because it is time.",
                              "--authorization", "unminted-placeholder",
                              proposals=proposals)
        self.assertEqual(json.loads(absent.stdout)["code"], "POSITION_ABSENT")

        header = {"revision": self.PROPOSAL_REVISION, "revisionSha256": "b" * 64,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1",
                  "target": "final"}
        items = [{"ordinal": 1, "mark": "x", "text": "Collect the shard.",
                  "witness": {"kind": "shard", "operand": "s0"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")
        stale = self.run_cli("gate", "--target", str(box), "--name", "Method",
                             "--revision", self.PROPOSAL_REVISION, "--session", "s1",
                             "--job", "job1", "--worker", "w1",
                             "--justification", "Because it is time.",
                             "--authorization", "unminted-placeholder",
                             proposals=proposals)
        self.assertEqual(json.loads(stale.stdout)["code"], "POSITION_STALE")

    def test_the_doctrine_names_the_refusal(self):
        """A refusal a reader meets for the first time in a terminal is a
        refusal nobody designed for -- both codes now that the two are
        told apart."""
        skill_text = SKILL_MD.read_text(encoding="utf-8")
        usage_text = USAGE_MD.read_text(encoding="utf-8")
        self.assertIn("POSITION_UNBACKED", skill_text)
        self.assertIn("POSITION_UNBACKED", usage_text)
        self.assertIn("POSITION_SHARDS_UNDECLARED", skill_text)
        self.assertIn("POSITION_SHARDS_UNDECLARED", usage_text)

    def test_the_toy_targets_left_nothing_behind(self):
        self._box("cleanup", mark=" ")
        self.doCleanups()
        leftover = list((FORGE / "implementations").glob("_unbacked_*"))
        self.assertEqual(leftover, [], leftover)


class NotebookInterpreterTests(unittest.TestCase):
    """The isolation rule was the one rule nothing could check.

    The skill's own first section says target code runs under the target
    repository's `.venv` and never under system Python. A notebook obeys no
    such thing on its own: it names a KERNELSPEC, and the ordinary `python3`
    kernelspec's `argv` starts with a bare `"python"` resolved off `PATH` when
    the kernel starts. So `<target>/.venv/bin/python -m jupyter nbconvert
    --execute` -- the obvious invocation, and the one that reads as isolated --
    runs the cells under whatever `python` was already first on `PATH`.

    Measured on a real target: a suite passing 297/297 standalone produced
    fifteen failures inside the notebook, and no line of the failure text named
    an interpreter.

    The signal was measured before anything was built on it. One notebook was
    executed twice through the identical `.venv/bin/python -m jupyter nbconvert
    --to notebook --execute --inplace`, varying only which directory came first
    on `PATH`; `metadata.language_info.version` came back `3.12.13` and `3.9.6`
    respectively, overwriting a value seeded into the file beforehand. It tracks
    the process that ran the cells, not the kernelspec the file names, and that
    is what these fixtures reproduce.
    """

    def _target(self, suffix, *, venv_version=None):
        box = FORGE / "implementations" / f"_nbinterp_{suffix}_{os.getpid()}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        (box / "src" / "Method").mkdir(parents=True)
        (box / "src" / "Method" / "__init__.py").write_text("", encoding="utf-8")
        (box / "Method" / "Notebooks").mkdir(parents=True)
        if venv_version is not None:
            (box / ".venv").mkdir()
            (box / ".venv" / "pyvenv.cfg").write_text(
                "home = /somewhere/bin\n"
                "include-system-site-packages = false\n"
                f"version = {venv_version}\n", encoding="utf-8")
        return box

    def _notebook(self, box, name, *, version, executed=True):
        """A notebook in the exact shape `nbconvert` leaves behind: a
        kernelspec naming `python3` -- the label that resolves off `PATH` and
        says nothing -- and a `language_info.version` written by whichever
        kernel actually ran."""
        metadata = {"kernelspec": {"display_name": "Python 3",
                                    "language": "python", "name": "python3"}}
        if version is not None:
            metadata["language_info"] = {"name": "python", "version": version}
        notebook = {
            "cells": [{"cell_type": "code",
                       "execution_count": 1 if executed else None,
                       "metadata": {}, "outputs": [],
                       "source": "print('measured')\n"}],
            "metadata": metadata, "nbformat": 4, "nbformat_minor": 5,
        }
        path = box / "Method" / "Notebooks" / name
        path.write_text(json.dumps(notebook), encoding="utf-8")
        return path

    # --- what the venv says it is, read and never run ---------------------

    def test_the_target_version_is_read_from_the_venv_config(self):
        box = self._target("version", venv_version="3.12.13")
        self.assertEqual(impl.target_python_version(box), "3.12.13")

    def test_a_four_component_version_info_reads_as_three(self):
        """Newer CPythons write `version_info = 3.12.13.final.0`. Two
        spellings of one fact have to compare as one, or the check would
        report every notebook foreign on exactly those machines."""
        box = self._target("info")
        (box / ".venv").mkdir()
        (box / ".venv" / "pyvenv.cfg").write_text(
            "version_info = 3.12.13.final.0\n", encoding="utf-8")
        self.assertEqual(impl.target_python_version(box), "3.12.13")

    def test_no_venv_is_unmeasured_and_never_a_default(self):
        """A comparison against a version nobody could read is not a
        comparison, and answering one would be inventing the baseline."""
        self.assertIsNone(impl.target_python_version(self._target("novenv")))

    def test_one_spelling_of_the_target_interpreter_path(self):
        """`introspect` runs it, `env` builds it, this reads it. Three
        spellings of one path is how one of them eventually differs."""
        box = self._target("path")
        self.assertEqual(impl.target_interpreter(box).parent.parent,
                         box / ".venv")
        source = inspect.getsource(impl)
        self.assertEqual(
            source.count('target / ".venv" / bin_dir'), 1,
            "the venv interpreter path is spelled more than once")

    # --- what the notebook says ran it ------------------------------------

    def test_the_notebook_reports_the_version_that_executed_it(self):
        box = self._target("executedby", venv_version="3.12.13")
        state = impl.notebook_execution(
            self._notebook(box, "one.ipynb", version="3.9.6"))
        self.assertEqual(state["executedBy"], "3.9.6")

    def test_a_notebook_with_no_language_info_reports_nothing_rather_than_a_guess(self):
        box = self._target("nolang", venv_version="3.12.13")
        state = impl.notebook_execution(
            self._notebook(box, "one.ipynb", version=None))
        self.assertIsNone(state["executedBy"])

    # --- the join: the two questions, asked separately ---------------------

    def test_a_foreign_interpreter_is_named_and_a_matching_one_is_not(self):
        """Both halves in one test, because the claim is a distinction. The
        kernelspec is identical in both files -- it is the label that lies --
        and only the version the kernel wrote differs."""
        box = self._target("join", venv_version="3.12.13")
        self._notebook(box, "own.ipynb", version="3.12.13")
        self._notebook(box, "foreign.ipynb", version="3.9.6")

        state = impl.notebooks_state(box, "Method", "Method")
        by_name = {r["notebook"]: r for r in state["reports"]}

        self.assertEqual(state["interpreterVersion"], "3.12.13")
        self.assertIs(by_name["Method/Notebooks/own.ipynb"]["interpreterMatch"], True)
        self.assertIs(by_name["Method/Notebooks/foreign.ipynb"]["interpreterMatch"], False)
        self.assertEqual(state["foreignInterpreter"],
                         ["Method/Notebooks/foreign.ipynb"])

    def test_an_unmeasurable_interpreter_is_none_and_never_a_pass(self):
        """Two ways to be unmeasured -- the notebook records no version, or
        there is no venv to compare against -- and neither reads as agreement.
        Silence is not a pass here for the same reason an unstamped notebook
        is not current."""
        silent = self._target("silent", venv_version="3.12.13")
        self._notebook(silent, "one.ipynb", version=None)
        self.assertIsNone(impl.notebooks_state(silent, "Method", "Method")
                          ["reports"][0]["interpreterMatch"])

        nobaseline = self._target("nobaseline")
        self._notebook(nobaseline, "one.ipynb", version="3.9.6")
        state = impl.notebooks_state(nobaseline, "Method", "Method")
        self.assertIsNone(state["interpreterVersion"])
        self.assertIsNone(state["reports"][0]["interpreterMatch"])
        self.assertEqual(state["foreignInterpreter"], [],
                         "unmeasured must never be reported as foreign")

    def test_a_foreign_interpreter_does_not_drift_the_status_on_its_own(self):
        """A wrong interpreter is not a wrong number: it is a reason to
        distrust the numbers, and one status cannot say which a reader is
        looking at. Held explicitly, because folding it in is the tempting
        move and it would destroy the distinction the key exists to draw."""
        box = self._target("nodrift", venv_version="3.12.13")
        notebook = self._notebook(box, "one.ipynb", version="3.9.6")
        stamped = json.loads(notebook.read_text(encoding="utf-8"))
        stamped["cells"][0]["outputs"] = [{
            "output_type": "stream", "name": "stdout",
            "text": [f"{impl.DIGEST_MARKER} {impl.source_digest(box, 'Method')}\n"]}]
        notebook.write_text(json.dumps(stamped), encoding="utf-8")

        state = impl.notebooks_state(box, "Method", "Method")
        self.assertEqual(state["status"], "ok")
        self.assertEqual(state["reports"][0]["status"], "executed")
        self.assertIs(state["reports"][0]["sourcesMatch"], True)
        self.assertIs(state["reports"][0]["interpreterMatch"], False)
        self.assertEqual(state["foreignInterpreter"], ["Method/Notebooks/one.ipynb"])

    def test_verify_carries_the_fact_all_the_way_to_the_reader(self):
        """A key computed and never surfaced is a key nobody reads."""
        box = self._target("verify", venv_version="3.12.13")
        self._notebook(box, "one.ipynb", version="3.9.6")
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        proc = subprocess.run(
            [sys.executable, str(CLI), "verify", "--target", str(box),
             "--name", "Method"], capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        notebooks = json.loads(proc.stdout)["validation"]["notebooks"]
        self.assertEqual(notebooks["foreignInterpreter"],
                         ["Method/Notebooks/one.ipynb"])
        self.assertEqual(notebooks["interpreterVersion"], "3.12.13")

    # --- the doctrine, where a reader meets it -----------------------------

    def test_the_doctrine_gives_the_safe_invocation_and_says_why(self):
        """Prose nobody executes is the defect class this whole change is
        about, so the mechanism above is the real repair -- but a reader about
        to type the command still has to be told, in the section that states
        the rule the command breaks."""
        text = SKILL_MD.read_text(encoding="utf-8")
        section = text[text.index("## Non-negotiable isolation"):]
        section = section[:section.index("\n## ", 1)]
        self.assertIn('PATH="$PWD/.venv/bin:$PATH"', section,
                      "the safe invocation is not written down")
        self.assertIn("kernelspec", section,
                      "nothing says WHY the obvious invocation is wrong")
        self.assertIn("interpreterMatch", section,
                      "the doctrine never names the fact `verify` reports")

    def test_the_toy_targets_left_nothing_behind(self):
        self._target("cleanup")
        self.doCleanups()
        leftover = list((FORGE / "implementations").glob("_nbinterp_*"))
        self.assertEqual(leftover, [], leftover)

    def test_the_shipped_scaffold_obeys_the_doctrine_it_ships_with(self):
        """The doctrine is checked one file away from the file that breaks it.

        `test_the_isolation_section_carries_the_safe_invocation` above reads
        `SKILL.md` and passes when the rule is written down. It stayed green
        while the shipped scaffold told a reader to run a notebook the way that
        same section calls "reads as isolated and is not". Doctrine only its own
        page is held to is doctrine the forge ships past.

        Two spellings, because the first version of this test caught one and
        walked past the other. `nbconvert` is the command form. "run the
        notebook" is the prose form -- `benchmark.py`'s refusal named an
        interpreter without the prefix and never said `nbconvert` at all, so a
        check keyed on the command alone reported the scaffold clean while the
        message a reader sees AT the isolation failure prescribed the remedy
        that does not fix it.

        Every shipped asset, `.py` and `.ipynb` alike, not the one file that
        was wrong on the day this was written.
        """
        kit = Path(impl.SKILL_ROOT) / "assets" / "kit"
        assets = sorted(path for path in kit.rglob("*")
                        if path.suffix in (".py", ".ipynb")
                        and "__pycache__" not in path.parts)
        self.assertTrue(assets, f"no shipped assets under {kit}")
        prefix = '.venv/bin:$PATH'
        seen, offenders = 0, []
        for path in assets:
            if path.suffix == ".ipynb":
                text = "".join(
                    "".join(cell["source"])
                    for cell in json.loads(
                        path.read_text(encoding="utf-8"))["cells"])
            else:
                text = path.read_text(encoding="utf-8")
            lines = text.splitlines()
            for n, line in enumerate(lines):
                if "nbconvert" not in line and "run the notebook" not in line:
                    continue
                seen += 1
                # The prefix may sit on a neighbouring line: a shell command
                # wrapped for width, or a refusal built from several f-strings.
                window = "\n".join(lines[max(0, n - 2):n + 6])
                if prefix not in window:
                    offenders.append(f"{path.name}:{n + 1}: {line.strip()}")
        self.assertEqual(
            offenders, [],
            "shipped assets tell a reader to run a notebook without the PATH "
            "prefix the isolation doctrine requires")
        self.assertTrue(
            seen, "no shipped asset mentions running a notebook at all, so "
                  "this test proves nothing about the ones that do")


class StepSequenceOrderTests(unittest.TestCase):
    """A step that says which rung it advances cannot run ahead of that rung.

    An ordering that lives only in prose is an ordering nobody is stopped from
    skipping, and this repository skipped one: a pilot search ran through a
    hand-rolled invocation while the step it belonged to sat behind an unticked
    predecessor, and nothing in `step` had anything to say about it.

    `advances` is the TARGET's word. The forge compares ordinals and knows
    nothing about what any rung means -- the same division `gate` already
    keeps when it refuses `SEQUENCE_NOT_REACHED` for a launch.
    """

    _box = StepCommandTests._box
    _commit = StepCommandTests._commit
    run_cli = StepCommandTests.run_cli

    def _position(self, box, marks):
        """An AGREED.md whose position block carries `marks`, in order.

        Rendered by `impl_position.render` rather than hand-written: a
        fixture that spells the grammar a second time is a fixture that can
        drift away from the parser it is meant to feed, and the first version
        of this one did exactly that -- it produced `POSITION_BLOCK_MALFORMED`
        and proved nothing about ordering.
        """
        # A real 64-hex digest: `_BLOCK_OPEN_RE` requires exactly that width,
        # and a short stand-in is refused as a malformed opener -- which is
        # what the first version of this fixture produced.
        header = {"revision": "r01.md", "revisionSha256": "a" * 64,
                  "derivedAt": "2026-01-01T00:00:00Z", "session": "t",
                  "target": "pilot"}
        items = [{"mark": mark, "ordinal": n, "text": f"rung {n}",
                  "witness": {"kind": "record", "operand": None,
                              "twostate": True}}
                 for n, mark in enumerate(marks, start=1)]
        (box / "Method").mkdir(parents=True, exist_ok=True)
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")

    def _declare(self, box, advances):
        (box / "src" / "Method_Benchmark").mkdir(parents=True, exist_ok=True)
        (box / "src" / "Method_Benchmark" / "work.py").write_text(
            "def run():\n    return 'ran'\n", encoding="utf-8")
        entry = {"module": "Method_Benchmark.work", "function": "run"}
        if advances is not None:
            entry["advances"] = advances
        (box / "src" / "Method_Benchmark" / "__init__.py").write_text(
            f"__steps__ = {{'later': {entry!r}}}\n", encoding="utf-8")

    def _run(self, box):
        return self.run_cli("step", "--target", str(box), "--name", "Method",
                            "--session", "t", "--step", "later")

    def test_an_earlier_open_rung_refuses_the_step(self):
        box = self._box("behind")
        self._declare(box, advances=3)
        self._position(box, ["x", " ", " "])
        self._commit(box)
        result = self._run(box)
        body = json.loads(result.stdout)
        self.assertEqual(body["code"], "STEP_SEQUENCE_NOT_REACHED", result.stdout)
        self.assertIn("item 2", body["detail"])

    def test_every_earlier_rung_ticked_lets_the_step_run(self):
        box = self._box("ahead")
        self._declare(box, advances=3)
        self._position(box, ["x", "x", " "])
        self._commit(box)
        body = json.loads(self._run(box).stdout)
        self.assertEqual(body.get("outcome"), "returned", body)

    def test_a_step_declaring_no_rung_runs_exactly_as_before(self):
        """A target that never opted into ordering must not change behaviour."""
        box = self._box("unbound")
        self._declare(box, advances=None)
        self._position(box, [" ", " ", " "])
        self._commit(box)
        body = json.loads(self._run(box).stdout)
        self.assertEqual(body.get("outcome"), "returned", body)

    def test_a_non_integer_rung_is_refused_rather_than_coerced(self):
        box = self._box("bogus")
        self._declare(box, advances="third")
        self._position(box, ["x", "x", " "])
        self._commit(box)
        body = json.loads(self._run(box).stdout)
        self.assertEqual(body["code"], "STEP_MALFORMED", body)


class LedgerIsARequiredIgnoreTests(unittest.TestCase):
    """`.implementation/` must be ignored, and the check must say so.

    The ledger this skill writes carries `gate` events, and a `gate` event is a
    launch authorization. Committed, it travels into a clone -- it authorizes no
    different work, being bound to `(commit, entrypoint, units, worker)`, but an
    approval arriving in a clone is an approval nobody there gave.

    The cost is stated rather than hidden: the same file now also carries the
    deliberation (`discuss`, `settle`), which IS history a clone would want, and
    `SKILL.md`'s "What this skill has not written down" says so. This test only
    holds the mechanism: a target without the entry is told.
    """

    def _target(self, ignore_text):
        box = FORGE / "implementations" / f"_ign_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        box.mkdir(parents=True)
        (box / ".gitignore").write_text(ignore_text, encoding="utf-8")
        return box

    def test_a_target_without_the_entry_is_reported(self):
        box = self._target(".venv/\n__pycache__/\n.ipynb_checkpoints/\n")
        self.assertIn(".implementation/", impl.ignore_gaps(box))

    def test_a_target_carrying_every_entry_reports_nothing(self):
        box = self._target("".join(f"{e}\n" for e in impl.IGNORE_ENTRIES))
        self.assertEqual(impl.ignore_gaps(box), [])


#: The counts doctrine spells out in words. Only the two the roster can produce
#: are needed; anything else fails loudly rather than silently skipping the
#: assertion that reads it.
_ENGLISH_COUNTS = {
    # `Seven` and `Seventeen`/`Eighteen` join for the two counts outside the
    # refusal roster this table now holds: `usage.md`'s tally of the
    # non-finding statuses `verify` reports, and `SKILL.md`'s count of the
    # Output Contract's own rows. Both were prose nothing was reading, and
    # both were one short by the time anybody looked; `Eighteen` is the
    # Output Contract row count after `undeclaredRecords` joined it
    # (the-pilot-proves-the-science, slice B).
    7: "Seven", 8: "Eight",
    9: "Nine", 10: "Ten", 17: "Seventeen", 18: "Eighteen", 19: "Nineteen",
    20: "Twenty",
    26: "Twenty-six", 27: "Twenty-seven", 28: "Twenty-eight",
    29: "Twenty-nine", 30: "Thirty", 31: "Thirty-one", 32: "Thirty-two",
    33: "Thirty-three", 34: "Thirty-four", 35: "Thirty-five",
    36: "Thirty-six",
    54: "Fifty-four", 55: "Fifty-five", 56: "Fifty-six", 57: "Fifty-seven",
    63: "Sixty-three", 64: "Sixty-four", 65: "Sixty-five", 66: "Sixty-six",
    67: "Sixty-seven", 68: "Sixty-eight", 69: "Sixty-nine",
}


def _english_count(value: int) -> str:
    if value not in _ENGLISH_COUNTS:
        raise AssertionError(
            f"{value} has no spelled form here; the roster's split moved far "
            "enough that the doctrine's own wording needs rewriting, not a "
            "wider lookup table")
    return _ENGLISH_COUNTS[value]


def raised_refusal_codes(source: Path, function: str) -> set[str]:
    """Every `Refused("<CODE>", ...)` literal raised inside one function's body.

    The second half of the `returned_keys` discipline, applied to the other end
    of a command: what it returns is doctrine's subject, and so is what it
    refuses. A roster of refusals restated beside the code is a roster that
    drifts, so the roster is held to a second read of the source rather than to
    a reviewer's memory -- add a `Refused` to a gating command and the classes
    below go red until the code has been classified.

    `ast` rather than calling the command: a refusal needs a repository on disk
    to reach, and this has to be answerable about a command nobody invoked.

    Nested definitions ARE descended into here, unlike `returned_keys`: a guard
    written as a closure inside a command still refuses for that command, and
    skipping it would let a code escape the roster by moving one indent level.

    A `Refused` whose first argument is not a string literal is invisible here.
    None exists today (the classes below assert the total), and the limitation
    is stated rather than guessed at.
    """
    tree = ast.parse(source.read_text(encoding="utf-8"))
    definition = next(
        (node for node in ast.walk(tree)
         if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
         and node.name == function), None)
    if definition is None:
        raise AssertionError(f"{source.name} defines no {function}")
    codes = set()
    for node in ast.walk(definition):
        if (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id == "Refused" and node.args
                and isinstance(node.args[0], ast.Constant)
                and isinstance(node.args[0].value, str)):
            codes.add(node.args[0].value)
    return codes


class GatingRefusalRosterTests(unittest.TestCase):
    """Lock A: every refusal a gating command raises declares how it is cleared.

    The incident. `gate` refused `POSITION_DISAGREES` in a live session, the
    payload carried a code and a sentence, and the agent driving the CLI
    composed the next question itself -- "Do you want me to do that now?".
    Fifty-six distinct codes are raised inside the gating commands and exactly
    two publication points existed in the whole engine, so fifty-four of them
    reached the user as a bare code with nothing runnable attached. A harness
    that has to sit above the agent driving it cannot leave the next act to
    that agent's prose.

    The rule the roster encodes, and the one derivable test that separates the
    two kinds: **can the caller clear this by changing the invocation alone,
    without touching the repository?** Yes is an *invocation* defect -- the
    detail already names the flag, and there is nothing to publish. No is a
    *work state* -- somebody must act on the repository, and the engine says
    what, as a runnable command or as the question a human answers.

    Why the roster and not one hundred and sixty-five tagged call sites: the
    same reason `VerifyStatusRosterTests` reads a table rather than proof-reads
    a sentence. One chokepoint, one roster, and a derivation that goes red the
    moment a new code is raised without a decision attached.
    """

    def gating_codes(self):
        codes = set()
        for command in impl.GATING_COMMANDS:
            codes |= raised_refusal_codes(CLI, f"cmd_{command}")
        return codes

    def test_the_derivation_finds_the_measured_sixty_nine(self):
        """Sanity check on the scraper itself, not on the roster: a change to a
        gating command that adds, removes or renames a refusal should move this
        number, never a typo in the walk above.

        Fifty-six until `position` joined `GATING_COMMANDS`, which brought its
        own eight previously-unclassified codes with it (`REVISION_UNREADABLE`
        it already shared with `admit`) plus `POSITION_RUNG_SKIPPED`, for
        sixty-five. Sixty-six once `POSITION_STEP_UNKNOWN` joined `cmd_position`
        -- `STEPS_UNDECLARED` is reused verbatim from `cmd_step` and adds no
        new member to this union. Sixty-seven once `POSITION_RECORD_UNKNOWN`
        joined `cmd_position` beside it (the-pilot-proves-the-science, slice
        B). Sixty-eight once `RUNG_NOT_ATTAINED` joined `cmd_gate` (same
        change, slice A). Sixty-nine once `POSITION_RECORD_MALFORMED` joined
        `cmd_position` beside `POSITION_RECORD_UNKNOWN` -- the shape half of
        the same declaration, which `__steps__` had and `__records__` did
        not."""
        self.assertEqual(len(self.gating_codes()), 69)

    def test_every_gating_refusal_is_classified(self):
        roster = set(impl.GATING_REFUSALS)
        raised = self.gating_codes()
        self.assertEqual(
            sorted(raised - roster), [],
            "these codes are raised in a gating command and the roster "
            "classifies none of them; a refusal nobody decided about is the "
            "defect this roster exists to make impossible")
        self.assertEqual(
            sorted(roster - raised), [],
            "the roster classifies these and no gating command raises them")

    def test_the_roster_names_only_the_two_kinds(self):
        self.assertEqual(
            sorted({kind for kind in impl.GATING_REFUSALS.values()}),
            [impl.INVOCATION_DEFECT, impl.WORK_STATE])

    def _args(self, **overrides):
        base = {"command": "gate", "target": "implementations/box",
                "name": "Method", "session": "s1", "revision": "r1.md",
                "about": None, "text": None}
        base.update(overrides)
        return argparse.Namespace(**base)

    def test_every_work_state_publishes_something_runnable(self):
        """The point of the whole lock. A work state with nothing published is
        a misclassification, never an empty field -- so this asserts the
        content, not the presence of a key."""
        for code, kind in sorted(impl.GATING_REFUSALS.items()):
            if kind != impl.WORK_STATE:
                continue
            with self.subTest(code=code):
                resolution = impl.refusal_resolution(code, self._args())
                self.assertIsInstance(resolution, dict)
                self.assertIn(resolution["kind"], ("command", "question"))
                self.assertTrue(resolution["command"].strip(),
                                "a work state must publish a runnable command")
                if resolution["kind"] == "question":
                    self.assertTrue(resolution["question"].strip())
                    self.assertIn("discuss", resolution["command"])

    def test_no_invocation_defect_publishes_a_resolution(self):
        """The other pole. An invocation defect's detail already names the flag,
        and a published `resolve` beside it would be ceremony -- the shape a
        reader learns to skip, which is how a real one stops being read."""
        for code, kind in sorted(impl.GATING_REFUSALS.items()):
            if kind != impl.INVOCATION_DEFECT:
                continue
            with self.subTest(code=code):
                self.assertIsNone(impl.refusal_resolution(code, self._args()))

    def test_the_doctrine_states_the_split_the_roster_actually_holds(self):
        """A count written into prose is a count that drifts. Both documents
        state the split, so both are read against the roster rather than
        proof-read: re-classifying one code moves this test, not a reviewer's
        memory.

        **Trap 3, fixed (design "strengthen the degenerating split
        assertion").** Both kinds now count 34 apiece, so a loop over
        `set(counts.values())` collapses to the single element `{34}` and
        checks `usage.md` for "Thirty-four codes" only once -- a stale
        work-state sentence left reading a DIFFERENT, wrong number would
        still pass as long as ONE of the two sentences (invocation's, which
        never moved) still says "Thirty-four codes" somewhere in the file.
        Two explicit per-kind assertions, each checked against its own
        sentence, is what a collapsed set could no longer catch. Required
        mutation: reverting only `usage.md`'s work-state sentence to
        "Thirty-two codes" (its pre-slice-A value, while invocation's stays
        "Thirty-four") must fail this test -- and does, because the
        work-state assertion below reads the sentence usage.md actually
        carries beside `POSITION_RUNG_SKIPPED`/`NOT_READY`, not merely
        `usage.md`'s presence of ANY correct-looking count."""
        counts = {kind: sum(1 for value in impl.GATING_REFUSALS.values()
                            if value == kind)
                  for kind in (impl.INVOCATION_DEFECT, impl.WORK_STATE)}
        skill = " ".join(SKILL_MD.read_text(encoding="utf-8").split())
        self.assertIn(
            f"{_english_count(len(impl.GATING_REFUSALS))} distinct codes are "
            "raised inside the nine gating commands", skill)
        self.assertIn(
            f"an *invocation* defect** ({counts[impl.INVOCATION_DEFECT]} "
            "codes)", skill)
        self.assertIn(
            f"a *work state*** ({counts[impl.WORK_STATE]} codes)", skill)
        usage = " ".join(USAGE_MD.read_text(encoding="utf-8").split())
        self.assertIn(
            f"{_english_count(counts[impl.INVOCATION_DEFECT])} codes, and "
            "nothing is published beside them", usage,
            "the invocation-defect sentence must name the roster's own "
            "invocation count, not merely some count that happens to match")
        self.assertIn(
            f"{_english_count(counts[impl.WORK_STATE])} codes, including", usage,
            "the work-state sentence must name the roster's own work-state "
            "count -- a stale number here would have passed the old "
            "`set(counts.values())` loop the moment both kinds tied")

    def test_a_code_outside_the_roster_publishes_nothing(self):
        """The roster is the gating commands' own. A refusal raised anywhere
        else is not silently handed a resolution it was never classified for."""
        self.assertIsNone(
            impl.refusal_resolution("NOT_A_GIT_REPO", self._args()))

    def test_position_disagrees_publishes_the_notebook_re_execution(self):
        """The code from the incident, and the one resolution named in the
        brief rather than derived: re-execute the verification notebook under
        the target's own venv with that venv's `bin` on PATH, then re-run
        `position` to rebind the mark to what was measured.

        Every part is built from what the engine already holds -- the target
        path it was given and `PROBE_NOTEBOOK` -- so no target-specific string
        can enter this file through it.
        """
        resolution = impl.refusal_resolution(
            "POSITION_DISAGREES", self._args(target="implementations/box"))
        self.assertEqual(resolution["kind"], "command")
        command = resolution["command"]
        self.assertIn("PATH=", command)
        self.assertIn("implementations/box/.venv/bin", command)
        self.assertIn("nbconvert", command)
        self.assertIn(impl.PROBE_NOTEBOOK, command)
        self.assertIn("position", command.split("&&")[-1])
        self.assertIn("--session", command.split("&&")[-1])

    def test_the_published_position_command_is_the_one_the_caller_can_run(self):
        """`position` takes `--session`, so a published `position` command that
        omitted it would refuse on its own advice. Every gating command that
        raises a position code carries `--session`; this holds the join."""
        for code in ("POSITION_STALE", "POSITION_UNBACKED"):
            with self.subTest(code=code):
                command = impl.refusal_resolution(code, self._args())["command"]
                self.assertIn("position", command)
                self.assertIn("--session s1", command)
                self.assertIn("--target implementations/box", command)


class RefusalPayloadPublishesItsExitTests(unittest.TestCase):
    """The chokepoint, end to end: the refused JSON carries the resolution.

    `implementation_cli.py`'s one `except Refused` is where every refusal in
    the engine reaches a reader, so it is where the roster is read. These run
    the real CLI against a real repository rather than calling the builder, so
    a resolution that exists in a dict and never reaches stdout still fails.
    """

    # Borrowed whole, for the reason the probe fixture next door states: a
    # second copy of a fixture's own constants is a second thing to keep in
    # step with a repository this class only reads.
    PROPOSAL_REVISION = CloseCommandTests.PROPOSAL_REVISION
    PROPOSAL_TEXT = CloseCommandTests.PROPOSAL_TEXT
    PROPOSAL_SHA256 = CloseCommandTests.PROPOSAL_SHA256

    def _proposals(self):
        return CloseCommandTests._proposals(self)

    def _box(self, packages=("Method",)):
        return CloseCommandTests._box(self, packages)

    def _write_job_folder(self, box, commit, **kwargs):
        return CloseCommandTests._write_job_folder(self, box, commit, **kwargs)

    def run_cli(self, *args, proposals=None):
        return CloseCommandTests.run_cli(self, *args, proposals=proposals)

    def test_a_work_state_refusal_carries_its_resolution(self):
        box, _ = self._box()
        proc = self.run_cli("close", "--target", str(box), "--name", "Method",
                            "--revision", CloseCommandTests.PROPOSAL_REVISION,
                            "--session", "s1", proposals=self._proposals())
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["code"], "POSITION_ABSENT")
        # A question, not a command, and the reason is measured: running the
        # published `position --reconcile` refuses
        # `POSITION_TARGET_LEVEL_REQUIRED` until a rung is named, and only the
        # target declares its rungs. The engine publishes that open decision
        # rather than a command that would refuse on its own advice.
        self.assertEqual(payload["resolve"]["kind"], "question")
        self.assertIn("--target-level", payload["resolve"]["question"])
        self.assertIn("implementation_cli.py discuss",
                      payload["resolve"]["command"])

    def test_the_disagreement_refusal_carries_the_notebook_re_execution(self):
        """The incident itself, reproduced through the real command."""
        proposals = self._proposals()
        box, commit = self._box()
        self._write_job_folder(box, commit)
        header = {"revision": CloseCommandTests.PROPOSAL_REVISION,
                  "revisionSha256": CloseCommandTests.PROPOSAL_SHA256,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1",
                  "target": "final"}
        items = [{"ordinal": 1, "mark": "x", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")
        proc = self.run_cli("close", "--target", str(box), "--name", "Method",
                            "--revision", CloseCommandTests.PROPOSAL_REVISION,
                            "--session", "s1", proposals=proposals)
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["code"], "POSITION_DISAGREES")
        self.assertIn("nbconvert", payload["resolve"]["command"])
        self.assertIn(impl.PROBE_NOTEBOOK, payload["resolve"]["command"])

    def test_an_invocation_defect_refusal_carries_no_resolve_key(self):
        box, _ = self._box()
        proc = self.run_cli("materialize", "--target", str(box), "--name", "Method")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["code"], "MATERIALIZE_MODE_REQUIRED")
        self.assertNotIn("resolve", payload)

    def test_the_published_command_is_directly_runnable(self):
        """A published command that does not parse is prose with a monospace
        font. This runs the one the engine published, unedited."""
        box, _ = self._box()
        proposals = self._proposals()
        # A block bound to a revision whose bytes moved: `POSITION_STALE`,
        # whose exit is a refresh of the block that is already there.
        header = {"revision": CloseCommandTests.PROPOSAL_REVISION,
                  "revisionSha256": "a" * 64,
                  "derivedAt": "2026-08-27T00:00:00Z", "session": "s1",
                  "target": "final"}
        items = [{"ordinal": 1, "mark": " ", "text": "Rehearse the job.",
                  "witness": {"kind": "rehearsal", "operand": "job1"}}]
        (box / "Method" / "AGREED.md").write_text(
            impl_position.render(header, items), encoding="utf-8")
        proc = self.run_cli("close", "--target", str(box), "--name", "Method",
                            "--revision", "r2.md",
                            "--session", "s1", proposals=proposals)
        published = json.loads(proc.stdout)["resolve"]["command"]
        # Run in the caller's own environment, which is the only one the
        # published command claims to run in: the revision it carries is the
        # revision the refused call was made against.
        tokens = shlex.split(published)
        rerun = self.run_cli(*tokens[1:], proposals=proposals)
        self.assertEqual(rerun.returncode, 0, rerun.stdout + rerun.stderr)
        self.assertEqual(json.loads(rerun.stdout)["command"], "position")


class NextStepPublicationRosterTests(unittest.TestCase):
    """Lock B: every `nextStep` that names work publishes that work.

    The measured defect was one literal. `probe`'s only publication fired on
    `next_step == "piloted"` and on nothing else, so `search-first` -- which
    launches a search, and is exactly the point the standing rule says the
    flow question belongs at -- reported a word and published nothing. Adding
    `"search-first"` beside `"piloted"` would have reproduced the defect one
    value later, so the condition is a roster over every value the ladder can
    assign, and the derivation below goes red when a new one is added without
    a decision.

    Terminal is a decision too. `nothing-to-compare` and `already-benchmarked`
    name no work, so they publish nothing -- but they say so in the roster, the
    same way an *invocation* refusal says so in Lock A's.
    """

    @classmethod
    def all_next_steps(cls):
        return NextStepSectionCoverageTests.all_next_steps()

    def test_every_value_the_ladder_can_assign_is_in_the_roster(self):
        roster = set(impl.PROBE_NEXT_STEPS)
        assigned = self.all_next_steps()
        self.assertEqual(
            sorted(assigned - roster), [],
            "the ladder can answer these and the roster classifies none of "
            "them; a step nobody decided about publishes nothing by accident")
        self.assertEqual(
            sorted(roster - assigned), [],
            "the roster classifies these and the ladder can never answer them")

    def test_the_roster_names_only_the_three_kinds(self):
        self.assertEqual(
            sorted({entry["kind"] for entry in impl.PROBE_NEXT_STEPS.values()}),
            sorted({impl.NEXT_STEP_EXPERIMENT, impl.NEXT_STEP_REPAIR,
                    impl.NEXT_STEP_TERMINAL}))

    def test_exactly_the_two_terminal_steps_are_declared_terminal(self):
        """Read rather than assumed: `piloted` looks terminal (a pilot ran) and
        is not -- its own rule keeps the question open, which is work. These
        two are the only answers that prescribe none."""
        terminal = sorted(step for step, entry in impl.PROBE_NEXT_STEPS.items()
                          if entry["kind"] == impl.NEXT_STEP_TERMINAL)
        self.assertEqual(terminal, ["already-benchmarked", "nothing-to-compare"])

    def test_the_experiment_steps_are_the_ones_that_spend_machine_time(self):
        """The predicate the standing rule needs: whenever the flow reaches the
        point of running experiments it must ask whether to continue the flow
        or complement them. Three answers reach that point -- the offer to run
        (`benchmark`), the pilot already run below its declared scale
        (`piloted`), and the declared search that has chosen nothing yet
        (`search-first`), which launches a run of its own."""
        experiments = sorted(step for step, entry in impl.PROBE_NEXT_STEPS.items()
                             if entry["kind"] == impl.NEXT_STEP_EXPERIMENT)
        self.assertEqual(experiments, ["benchmark", "piloted", "search-first"])

    def test_every_non_terminal_step_publishes_something(self):
        for step, entry in sorted(impl.PROBE_NEXT_STEPS.items()):
            with self.subTest(step=step):
                if entry["kind"] == impl.NEXT_STEP_TERMINAL:
                    self.assertIsNone(entry["publish"])
                    continue
                self.assertIsNotNone(entry["publish"])

    def test_the_wiring_draft_belongs_to_the_two_steps_the_wiring_blocks(self):
        """The withheld payload. `wiring_proposal` had one call site, guarded
        by `next_step == "benchmark"`, and `wiring-first` is set by an override
        that runs BEFORE it -- so at the one answer that names missing wiring,
        the draft of how to wire it came back `None` and the agent composed the
        plan in prose. Both steps get it, and the roster is what says so."""
        carrying = sorted(step for step, entry in impl.PROBE_NEXT_STEPS.items()
                          if entry["wiring"])
        self.assertEqual(carrying, ["benchmark", "wiring-first"])

    def test_the_experiment_question_names_the_open_choice(self):
        for step, entry in sorted(impl.PROBE_NEXT_STEPS.items()):
            if entry["kind"] != impl.NEXT_STEP_EXPERIMENT:
                continue
            with self.subTest(step=step):
                published = entry["publish"](
                    Path("implementations/box"), "Method", {"declared": {}})
                self.assertIn("question", published)
                self.assertIn("implementation_cli.py discuss",
                              published["command"])


class ProbePublishesEveryStepsWorkTests(unittest.TestCase):
    """Lock B end to end: `probe`'s JSON carries the publication.

    Composed from `ProbeReportedFactsRosterTests`'s fixture rather than a new
    one: that repository is already proved to reach `benchmark` with every
    downgrade rung non-firing, which is the only way an assertion about one
    rung can mean anything.
    """

    # Borrowed whole rather than rebuilt: the fixture's own class attributes
    # are what `build_target` writes, and a second copy of them here is a
    # second thing to keep in step with a repository this class only reads.
    DECLARATION = ProbeReportedFactsRosterTests.DECLARATION
    WIRING = ProbeReportedFactsRosterTests.WIRING
    TABLES = ProbeReportedFactsRosterTests.TABLES

    def build_target(self, suffix):
        return ProbeReportedFactsRosterTests.build_target(self, suffix)

    def build_piloted_target(self, suffix, ran=1, declared=5):
        return ProbeReportedFactsRosterTests.build_piloted_target(
            self, suffix, ran=ran, declared=declared)

    def write_job_folder(self, box, head):
        return ProbeReportedFactsRosterTests.write_job_folder(self, box, head)

    def probe(self, box):
        return ProbeReportedFactsRosterTests.probe(self, box)

    def test_the_benchmark_offer_publishes_its_own_question(self):
        """The old pole asserted `toDiscuss == []` here. It is the defect: the
        offer to run is the point the standing rule names, and it published
        nothing."""
        box, head = self.build_target("pub-benchmark")
        self.write_job_folder(box, head)
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "benchmark")
        self.assertEqual(probe["resolve"]["kind"], "question")
        self.assertEqual(len(probe["toDiscuss"]), 1)
        self.assertIn("implementation_cli.py discuss",
                      probe["toDiscuss"][0]["command"])

    def test_the_benchmark_offer_still_carries_the_wiring_draft(self):
        box, head = self.build_target("pub-benchmark-wiring")
        self.write_job_folder(box, head)
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "benchmark")
        self.assertEqual((probe["wiring"] or {}).get("status"), "draft")

    def test_wiring_first_carries_the_draft_it_used_to_withhold(self):
        """The sharp instance. `unreachedModules` is non-empty, the answer is
        `wiring-first`, and the draft of how each module becomes trainable must
        be in the payload rather than in the agent's prose."""
        box, head = self.build_target("pub-wiring-first")
        self.write_job_folder(box, head)
        # The fixture's arm reaches both modules through `wiring.py`; emptying
        # it is what leaves declared mathematics uncalled, which is the state
        # this rung names.
        (box / "src" / "Method_Benchmark" / "wiring.py").write_text(
            "", encoding="utf-8")
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "wiring-first")
        self.assertTrue(probe["unreachedModules"])
        self.assertEqual((probe["wiring"] or {}).get("status"), "draft")
        self.assertEqual(probe["resolve"]["kind"], "question")

    def test_the_piloted_payload_is_unchanged(self):
        """The one shape this change may not move: `piloted` published a
        working entry before it, and its question text is pinned by the
        stability proof next door."""
        box, _ = self.build_piloted_target("pub-piloted")
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "piloted")
        entry = probe["toDiscuss"][0]
        self.assertIn("Method", entry["question"])
        self.assertIn("5", entry["question"])
        self.assertEqual(entry["about"], {"kind": "record", "operand": None})
        self.assertEqual(probe["resolve"]["question"], entry["question"])

    def test_a_terminal_step_publishes_nothing(self):
        """The pole that replaces the old one. A repository with nothing to
        compare against names no work, so it publishes none -- and that is a
        roster entry, not an omission."""
        box, _ = self.build_target("pub-terminal")
        # Every package under `src/` that is not ours is a baseline
        # (`previous_implementations`), the benchmark package included, so
        # both have to go for there to be nothing to compare against.
        shutil.rmtree(box / "src" / "Prior")
        shutil.rmtree(box / "src" / "Method_Benchmark")
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "nothing-to-compare")
        self.assertIsNone(probe["resolve"])
        self.assertEqual(probe["toDiscuss"], [])
        self.assertIsNone(probe["wiring"])

    def test_the_published_probe_command_is_directly_runnable(self):
        box, head = self.build_target("pub-runnable")
        self.write_job_folder(box, head)
        probe = self.probe(box)
        tokens = shlex.split(probe["resolve"]["command"])
        proc = subprocess.run([sys.executable, str(CLI), *tokens[1:]],
                              capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        self.assertEqual(json.loads(proc.stdout)["asked"],
                         probe["resolve"]["question"])


class PilotCompletenessTests(unittest.TestCase):
    """`pilot_completeness_state(steps, sequence, evidence)` -- the derived
    notion of "the declared flow has actually run at pilot".

    The measured defect: a reference target had run ONE of six ordered steps,
    six of its seven notebooks carried zero executed cells, and `probe` still
    answered the rung that offers the declared scale. That rung fires on "the
    record is missing", which is a different fact from "the pilot was
    validated", and the flow was reading the wrong one.

    Nothing here is hardcoded and nothing is read out of the target's Python.
    The flow is `__steps__`'s own entries that carry an `advances` ordinal;
    the order is that ordinal; a step has run when the ledger's `@step`
    verdict says `returned` under a current suite digest; and the notebook a
    step owes, when it owes one, is the operand of the sequence item that
    step's own `advances` names -- a link the target already writes, so no
    second declaration is invented beside it.
    """

    def evidence(self, *, step_verdicts=None, reports=None, levels=None):
        return {"stepVerdicts": dict(step_verdicts or {}),
                "notebooks": {"reports": list(reports or [])},
                "levels": list(levels or [])}

    def report(self, notebook, *, status="executed", sources_match=True):
        return {"notebook": notebook, "status": status,
                "sourcesMatch": sources_match}

    def item(self, ordinal, kind, operand, *, twostate=True):
        return {"ordinal": ordinal, "mark": " ",
                "witness": {"kind": kind, "operand": operand,
                            "twostate": twostate}}

    def test_a_target_that_declares_no_ordered_flow_is_undeclared(self):
        """A repository whose `__steps__` is empty, or whose entries carry no
        ordinal at all, declared no flow -- and a flow nobody declared is not
        an incomplete one. Anything else would withhold the declared scale
        from every target that never opted into an ordering."""
        for steps in ({}, {"a": {"module": "m", "function": "f"}}):
            with self.subTest(steps=steps):
                state = impl.pilot_completeness_state(
                    steps, [], self.evidence())
                self.assertEqual(state["status"], "undeclared")
                self.assertEqual(state["steps"], [])
                self.assertEqual(state["incomplete"], [])

    def test_a_step_without_an_ordinal_is_outside_the_flow(self):
        """The mutation this survives: folding the ordinal-less entries in.
        They are the ones `cmd_step` itself runs ungated, so an ordering that
        never claimed them cannot be waiting on them -- and a rule that
        counted them would report a complete flow incomplete forever."""
        steps = {"one": {"module": "m", "function": "f", "advances": 1},
                 "aside": {"module": "m", "function": "g"}}
        state = impl.pilot_completeness_state(
            steps, [self.item(1, "record", None)],
            self.evidence(step_verdicts={"one": True}))
        self.assertEqual(state["status"], "complete")
        self.assertEqual([row["step"] for row in state["steps"]], ["one"])

    def test_the_flow_is_reported_in_the_ordinal_order_the_target_declared(self):
        """`__steps__` is a mapping, so its own insertion order is whatever
        the file happened to spell. The ordinal is the ordering, and this
        fixture spells them out of order on purpose."""
        steps = {"third": {"module": "m", "function": "c", "advances": 3},
                 "first": {"module": "m", "function": "a", "advances": 1},
                 "second": {"module": "m", "function": "b", "advances": 2}}
        state = impl.pilot_completeness_state(steps, [], self.evidence())
        self.assertEqual([row["step"] for row in state["steps"]],
                         ["first", "second", "third"])
        self.assertEqual([row["advances"] for row in state["steps"]], [1, 2, 3])

    def test_a_step_the_ledger_never_recorded_is_not_complete(self):
        steps = {"one": {"module": "m", "function": "f", "advances": 1}}
        state = impl.pilot_completeness_state(
            steps, [self.item(1, "record", None)], self.evidence())
        self.assertEqual(state["status"], "incomplete")
        self.assertEqual(state["incomplete"], ["one"])
        self.assertIsNone(state["steps"][0]["ran"])

    def test_a_step_whose_verdict_is_stale_is_not_complete(self):
        """`unmeasured` is not attainment. `_step_verdicts` folds a ledger
        event whose recorded suite digest no longer matches to `None`, and
        `None` here must read as "not shown" rather than as a pass -- the
        same distinction `_skipped_rung_detail` keeps one rung over."""
        steps = {"one": {"module": "m", "function": "f", "advances": 1}}
        state = impl.pilot_completeness_state(
            steps, [self.item(1, "record", None)],
            self.evidence(step_verdicts={"one": None}))
        self.assertEqual(state["incomplete"], ["one"])

    def test_a_step_that_raised_is_not_complete(self):
        steps = {"one": {"module": "m", "function": "f", "advances": 1}}
        state = impl.pilot_completeness_state(
            steps, [self.item(1, "record", None)],
            self.evidence(step_verdicts={"one": False}))
        self.assertEqual(state["incomplete"], ["one"])
        self.assertIs(state["steps"][0]["ran"], False)

    def test_a_step_whose_item_names_a_notebook_owes_that_notebook_executed(self):
        """The half a lock reading only the ledger would lose. The step ran
        and returned; its own sequence item names a notebook; that notebook
        carries no executed cell. A rule that stopped at the ledger reads this
        repository as a validated pilot with nothing on disk to read."""
        steps = {"one": {"module": "m", "function": "f", "advances": 1}}
        state = impl.pilot_completeness_state(
            steps, [self.item(1, "notebook", "Notebooks/one.ipynb")],
            self.evidence(step_verdicts={"one": True},
                          reports=[self.report("Method/Notebooks/one.ipynb",
                                               status="stale")]))
        self.assertEqual(state["incomplete"], ["one"])
        self.assertIs(state["steps"][0]["ran"], True)
        self.assertIs(state["steps"][0]["notebookCurrent"], False)
        self.assertEqual(state["steps"][0]["notebook"], "Notebooks/one.ipynb")

    def test_a_notebook_executed_against_other_sources_is_not_complete(self):
        """`executed` alone says a cell ran once, never that it ran against
        this code. `sourcesMatch` is the other half and both are demanded."""
        steps = {"one": {"module": "m", "function": "f", "advances": 1}}
        state = impl.pilot_completeness_state(
            steps, [self.item(1, "notebook", "Notebooks/one.ipynb")],
            self.evidence(step_verdicts={"one": True},
                          reports=[self.report("Method/Notebooks/one.ipynb",
                                               sources_match=False)]))
        self.assertEqual(state["incomplete"], ["one"])

    def test_a_leveled_notebook_item_is_read_at_the_pilot_and_never_at_a_rung(self):
        """The trap that would have made this predicate unreachable. A
        sequence item may declare itself leveled, and a leveled notebook
        witness grades a RUNG -- evidence only a full-scale run can produce.
        Read that way, a pilot could never complete, so this reads the same
        executed-and-current fact for a leveled item as for a two-state one,
        with no ladder consulted at all."""
        steps = {"one": {"module": "m", "function": "f", "advances": 1}}
        state = impl.pilot_completeness_state(
            steps,
            [self.item(1, "notebook", "Notebooks/one.ipynb", twostate=False)],
            self.evidence(step_verdicts={"one": True},
                          reports=[self.report("Method/Notebooks/one.ipynb")],
                          levels=["floor", "pilot", "full"]))
        self.assertEqual(state["status"], "complete")
        self.assertIs(state["steps"][0]["notebookCurrent"], True)

    def test_an_item_whose_witness_is_not_a_notebook_owes_only_its_verdict(self):
        """The deadlock this refuses. A step's item may witness a record or a
        shard, and both of those are full-scale evidence: demanding them here
        would mean the pilot could never complete, and the rung that waits on
        completeness would never lift. Only the notebook half -- which a pilot
        run genuinely produces -- is added to the step's own verdict."""
        steps = {"one": {"module": "m", "function": "f", "advances": 1},
                 "two": {"module": "m", "function": "g", "advances": 2}}
        state = impl.pilot_completeness_state(
            steps,
            [self.item(1, "record", None),
             self.item(2, "shard", "s00", twostate=False)],
            self.evidence(step_verdicts={"one": True, "two": True},
                          levels=["floor", "full"]))
        self.assertEqual(state["status"], "complete")
        self.assertEqual([row["notebook"] for row in state["steps"]],
                         [None, None])
        self.assertEqual([row["notebookCurrent"] for row in state["steps"]],
                         [None, None])

    def test_a_step_whose_ordinal_names_no_item_owes_only_its_verdict(self):
        """A sequence that has not been derived yet, or one shorter than the
        ordinals `__steps__` names, leaves the notebook unknown -- and unknown
        is not a demand. The step's own verdict still decides."""
        steps = {"one": {"module": "m", "function": "f", "advances": 9}}
        state = impl.pilot_completeness_state(
            steps, [], self.evidence(step_verdicts={"one": True}))
        self.assertEqual(state["status"], "complete")
        self.assertIsNone(state["steps"][0]["notebook"])

    def test_every_step_run_and_every_notebook_current_reads_complete(self):
        steps = {"one": {"module": "m", "function": "f", "advances": 1},
                 "two": {"module": "m", "function": "g", "advances": 2}}
        state = impl.pilot_completeness_state(
            steps,
            [self.item(1, "notebook", "Notebooks/one.ipynb"),
             self.item(2, "notebook", "Notebooks/two.ipynb")],
            self.evidence(step_verdicts={"one": True, "two": True},
                          reports=[self.report("Method/Notebooks/one.ipynb"),
                                   self.report("Method/Notebooks/two.ipynb")]))
        self.assertEqual(state["status"], "complete")
        self.assertEqual(state["incomplete"], [])
        self.assertTrue(all(row["complete"] for row in state["steps"]))

    def test_the_incomplete_list_names_only_the_steps_still_short(self):
        """Not "how many": which. The published question names them, and a
        count would send a reader looking for the difference themselves."""
        steps = {"one": {"module": "m", "function": "f", "advances": 1},
                 "two": {"module": "m", "function": "g", "advances": 2},
                 "three": {"module": "m", "function": "h", "advances": 3}}
        state = impl.pilot_completeness_state(
            steps,
            [self.item(1, "record", None), self.item(2, "record", None),
             self.item(3, "record", None)],
            self.evidence(step_verdicts={"one": True, "three": True}))
        self.assertEqual(state["incomplete"], ["two"])

    def test_a_non_integer_ordinal_is_not_an_ordering(self):
        """`cmd_step` already refuses `STEP_MALFORMED` for one; this reader
        never raises, so it treats the entry as declaring no position in the
        flow rather than sorting a string against an int and crashing."""
        steps = {"one": {"module": "m", "function": "f", "advances": "1"},
                 "two": {"module": "m", "function": "g", "advances": True}}
        state = impl.pilot_completeness_state(steps, [], self.evidence())
        self.assertEqual(state["status"], "undeclared")


class UnfinishableFlowTests(unittest.TestCase):
    """`unfinishable_flow_state(steps, sequence, required_scale)` -- an ordered
    flow whose own declarations contradict each other, said before the first
    step runs instead of ten minutes into it.

    The measured defect. A target declared six ordered steps and six sequence
    items. Its first two steps ran and returned; the third was refused
    `STEP_SEQUENCE_NOT_REACHED`, because item 2 was unticked and item 3 cannot
    run ahead of it. Item 2 carries a bare, two-state `@record` witness, and
    `impl_position._derive_record` grades one of those against
    `search.scaleSatisfied` whenever the search declares a `requiredScale` --
    so below that scale the item derives `false` by construction, and a
    two-state item admits no rung for a smaller run to earn partial credit at.
    Every step above it is therefore refused for as long as the run stays
    below scale, while `pilotCompleteness` asks for exactly that flow to
    finish at pilot. Two declarations, each legible on its own, that cannot
    both be satisfied.

    **Two-state alone is not the rule, and a report that said so would be
    wrong.** The same target's item 1 is two-state as well -- a `@notebook`
    witness -- and it was satisfied at pilot, because `_derive_notebook` asks
    only that the notebook be executed against these sources. What makes an
    item unsatisfiable below scale is the pair: two-state AND graded against a
    declared scale. `test_the_kind_this_names_is_the_one_derive_grades_
    against_scale` is that claim held to `impl_position.derive` itself rather
    than restated here, because a kind list copied beside the derivers is a
    list that drifts -- and a drifted one would report an unfinishable flow
    for a target whose every item ticks perfectly well at pilot.

    **Reported, never repaired, and nothing is weakened.**
    `STEP_SEQUENCE_NOT_REACHED` stays exactly as it is: the operator learns
    earlier, and nobody is let through. `unreachable_ladder_state`'s own
    shape, placement and restraint, one composition over.
    """

    SCALE = {"runs": 30}

    def item(self, ordinal, kind, operand, *, twostate=True, mark=" "):
        return {"ordinal": ordinal, "mark": mark, "text": "t",
                "witness": {"kind": kind, "operand": operand,
                            "twostate": twostate}}

    def step(self, advances=None):
        entry = {"module": "m", "function": "f"}
        if advances is not None:
            entry["advances"] = advances
        return entry

    def flow(self, *ordinals):
        return {f"s{ordinal}": self.step(ordinal) for ordinal in ordinals}

    # --- the predicate, held to the derivation it claims to describe -------

    def test_the_kind_this_names_is_the_one_derive_grades_against_scale(self):
        """The whole report rests on one claim: that among the two-state
        witness kinds, `@record` is the only one `impl_position.derive`
        grades against a DECLARED scale, so it is the only one a run below
        that scale can never satisfy. Written as a join against `derive`
        rather than as a second list, and measured on the best evidence a
        below-scale run can leave behind: every other kind grades `True`
        there, and a rule naming any of them would report a flow that
        finishes fine as one that cannot.
        """
        best = {
            "notebook": ("n.ipynb", {"notebooks": {"reports": [
                {"notebook": "n.ipynb", "status": "executed",
                 "sourcesMatch": True}]}}),
            "rehearsal": ("job", {"smokeReady": {"job": True}}),
            "shard": ("s1", {"shardsArrived": ["s1"], "shardsCurrent": None}),
            "step": ("one", {"stepVerdicts": {"one": True}}),
            # A record left by a run below the declared scale: it is on disk
            # and it reports on this code, and it is still short.
            "record": (None, {"search": {"recordFound": True,
                                         "recordCurrent": True,
                                         "scaleSatisfied": False}}),
        }
        graded = {}
        for kind, (operand, evidence) in best.items():
            item = self.item(1, kind, operand)
            graded[kind] = impl_position.derive(
                [item], {**evidence, "requiredScale": dict(self.SCALE),
                         "levels": []})[0]["satisfied"]
        self.assertEqual(
            sorted(kind for kind, satisfied in graded.items()
                   if satisfied is not True),
            ["record"],
            "the kinds a below-scale run cannot satisfy moved; the predicate "
            "below names a fixed one and would now be reporting the wrong "
            "items")
        # And the predicate agrees with that join, kind by kind.
        for kind, (operand, _) in best.items():
            with self.subTest(kind=kind):
                state = impl.unfinishable_flow_state(
                    self.flow(1, 2), [self.item(1, kind, operand)],
                    dict(self.SCALE))
                self.assertEqual(state is not None, kind == "record")

    def test_a_two_state_record_item_is_satisfiable_when_no_scale_is_declared(self):
        """The other half of the same join, and the guard against the false
        alarm that would matter most: with no `requiredScale` declared,
        `_derive_record` answers `recordFound` alone, so a record a smaller
        run leaves behind ticks the item and the flow finishes. A rule that
        fired on the witness kind alone would refuse every such target's
        whole flow in prose.
        """
        item = self.item(2, "record", None)
        satisfied = impl_position.derive(
            [item], {"search": {"recordFound": True, "recordCurrent": True,
                                "scaleSatisfied": False},
                     "requiredScale": {}, "levels": []})[0]["satisfied"]
        self.assertIs(satisfied, True)
        self.assertIsNone(impl.unfinishable_flow_state(
            self.flow(1, 2, 3), [item], {}))

    # --- what it reports ---------------------------------------------------

    def test_the_flow_waiting_behind_the_item_is_named(self):
        """The shape the defect actually arrived in: six items, six ordered
        steps, and a bare two-state `@record` at ordinal 2."""
        sequence = [self.item(1, "notebook", "one.ipynb", mark="x"),
                    self.item(2, "record", None),
                    self.item(3, "notebook", "three.ipynb", twostate=False),
                    self.item(4, "shard", "s0", twostate=False),
                    self.item(5, "notebook", "five.ipynb", twostate=False),
                    self.item(6, "notebook", "six.ipynb", twostate=False)]
        state = impl.unfinishable_flow_state(
            self.flow(1, 2, 3, 4, 5, 6), sequence, dict(self.SCALE))
        self.assertIsNotNone(state)
        self.assertEqual([row["ordinal"] for row in state["blockedBy"]], [2])
        self.assertEqual([row["step"] for row in state["blockedSteps"]],
                         ["s3", "s4", "s5", "s6"])
        self.assertEqual([row["advances"] for row in state["blockedSteps"]],
                         [3, 4, 5, 6])
        self.assertEqual(state["requiredScale"], self.SCALE)

    def test_the_step_that_advances_the_item_is_not_waiting_behind_it(self):
        """`cmd_step` refuses on items STRICTLY BELOW the ordinal a step
        advances, so the step whose own item is the unsatisfiable one runs
        perfectly well -- and the measured run proves it: the step advancing
        item 2 returned. Reporting it as blocked would name a step the
        operator has already watched succeed, which is how a report stops
        being read.
        """
        state = impl.unfinishable_flow_state(
            self.flow(1, 2, 3), [self.item(2, "record", None)],
            dict(self.SCALE))
        self.assertEqual([row["step"] for row in state["blockedSteps"]], ["s3"])

    def test_an_item_no_step_waits_behind_is_silent(self):
        """An unsatisfiable item at or above the furthest ordinal any step
        advances blocks nothing: the flow runs to its end and stops one tick
        short of a full sequence, which is an unfinished POSITION and not an
        unfinishable flow. `pilotCompleteness` already speaks to the first.
        """
        for ordinal in (3, 4):
            with self.subTest(ordinal=ordinal):
                self.assertIsNone(impl.unfinishable_flow_state(
                    self.flow(1, 2, 3), [self.item(ordinal, "record", None)],
                    dict(self.SCALE)))

    def test_a_leveled_record_item_is_silent(self):
        """The exit itself, proven to close the report rather than asserted
        to. A `:level`-marked record item admits a rung, so a smaller run
        earns one and the item ticks below the declared scale.
        """
        self.assertIsNone(impl.unfinishable_flow_state(
            self.flow(1, 2, 3), [self.item(2, "record", "pilot", twostate=False)],
            dict(self.SCALE)))

    def test_a_flow_nobody_declared_is_not_an_unfinishable_one(self):
        """`_flow_steps`'s own rule, reused rather than restated: an entry
        with no ordinal is outside the flow, and `cmd_step` runs one ungated
        -- so it can never be refused for waiting on anything.
        """
        for steps in ({}, {"aside": self.step()}):
            with self.subTest(steps=steps):
                self.assertIsNone(impl.unfinishable_flow_state(
                    steps, [self.item(1, "record", None)], dict(self.SCALE)))

    def test_an_ordinal_less_step_is_never_reported_blocked(self):
        """The mutation this survives: folding the ordinal-less entries into
        the flow. They run ungated, so naming one here would publish a step
        that is not blocked at all.
        """
        steps = {**self.flow(1, 3), "aside": self.step()}
        state = impl.unfinishable_flow_state(
            steps, [self.item(1, "record", None)], dict(self.SCALE))
        self.assertEqual([row["step"] for row in state["blockedSteps"]], ["s3"])

    def test_an_empty_sequence_says_nothing(self):
        """A target that never derived a position has no item to be waiting
        on -- `position_state` answers `sequence: []` there, and reading that
        as an unfinishable flow would fire on every target before its first
        `position` call.
        """
        self.assertIsNone(impl.unfinishable_flow_state(
            self.flow(1, 2), [], dict(self.SCALE)))

    def test_the_earliest_blocking_item_decides_and_every_one_is_named(self):
        """`cmd_step` refuses on the FIRST unticked item below the ordinal,
        so the earliest such item is what bounds the flow -- but a reader
        given only that one would fix it and meet the next. Both are named.
        """
        state = impl.unfinishable_flow_state(
            self.flow(1, 2, 3, 4),
            [self.item(1, "record", None), self.item(3, "record", None)],
            dict(self.SCALE))
        self.assertEqual([row["ordinal"] for row in state["blockedBy"]], [1, 3])
        self.assertEqual([row["step"] for row in state["blockedSteps"]],
                         ["s2", "s3", "s4"])

    # --- the consequence ---------------------------------------------------

    def test_the_consequence_names_what_is_lost_and_the_exit(self):
        """`undeclaredLadder`'s and `unreachableLadder`'s own bar: a reader
        handed the key's name learns nothing. The consequence has to name
        what the target gives up and what it can do instead, in enough
        detail that the exit is a decision somebody can take rather than
        advice.
        """
        state = impl.unfinishable_flow_state(
            self.flow(1, 2, 3), [self.item(2, "record", None)],
            dict(self.SCALE))
        consequence = state["consequence"]
        for named in ("STEP_SEQUENCE_NOT_REACHED", "pilotCompleteness",
                      "`@record:level", impl.RECORDS_DECLARATION,
                      "requiredScale", "s3"):
            self.assertIn(named, consequence)
        self.assertIn("2", consequence)

    def test_the_consequence_names_no_target_of_its_own(self):
        """The forge reports the shape of the exit; the repository decides
        its own words. Held to the same floor every shipped surface is."""
        state = impl.unfinishable_flow_state(
            self.flow(1, 2), [self.item(1, "record", None)], dict(self.SCALE))
        self.assertEqual(leaks_in(state["consequence"]), [])

    # --- the gate is not weakened -----------------------------------------

    def test_the_refusal_this_reports_ahead_of_is_still_raised(self):
        """The one thing this change must not do. The report exists so the
        operator learns earlier, never so anybody is let through, and the
        proof is that `cmd_step` still raises the identical code.
        """
        self.assertIn("STEP_SEQUENCE_NOT_REACHED",
                      raised_refusal_codes(CLI, "cmd_step"))

    # --- end to end, through `verify` itself --------------------------------

    LADDER = ["floor", "smoke", "pilot", "campaign"]

    BODY = (
        "- [x] 1. Invariants. `@notebook Notebooks/verification.ipynb`\n"
        "- [ ] 2. A record at the declared scale. `@record`\n"
        "- [ ] 3. The report is current. `@notebook:level Notebooks/r.ipynb`\n")

    def _box(self, suffix, *, scale):
        box = FORGE / "implementations" / f"_unfinishable_{suffix}_{os.getpid()}_{id(self)}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        for directory in ("src/Method", "src/Method_Benchmark", "Method", "tests"):
            (box / directory).mkdir(parents=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        search = {"what": "one free scalar", "role": "valid",
                  "tieRule": "the smaller value wins"}
        if scale:
            search["requiredScale"] = dict(scale)
        steps = {"one": {"module": "Method_Benchmark.steps", "function": "a",
                         "advances": 1},
                 "two": {"module": "Method_Benchmark.steps", "function": "b",
                         "advances": 2},
                 "three": {"module": "Method_Benchmark.steps", "function": "c",
                           "advances": 3}}
        (box / "src/Method_Benchmark/__init__.py").write_text(
            "__benchmark__ = " + repr({"revision": "r1.md", "search": search})
            + f"\n__levels__ = {self.LADDER!r}\n__steps__ = {steps!r}\n",
            encoding="utf-8")
        (box / "Method/AGREED.md").write_text(
            "<!-- position revision=r1.md sha256=" + "a" * 64 + " "
            "derivedAt=2026-08-30T00:00:00Z session=s0 target=pilot -->\n"
            + self.BODY + "<!-- /position -->\n", encoding="utf-8")
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        return box

    def verify(self, box):
        proc = subprocess.run(
            [sys.executable, str(CLI), "verify", "--target", str(box),
             "--name", "Method"],
            capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        return json.loads(proc.stdout)

    def test_verify_reports_the_contradiction_on_a_real_target(self):
        """The wiring, end to end: a declared scale, a two-state `@record` at
        ordinal 2, and a step at ordinal 3 that can never run below it."""
        report = self.verify(self._box("blocked", scale=self.SCALE))
        state = report["unfinishableFlow"]
        self.assertIsNotNone(state)
        self.assertEqual([row["ordinal"] for row in state["blockedBy"]], [2])
        self.assertEqual([row["step"] for row in state["blockedSteps"]],
                         ["three"])
        self.assertEqual(state["requiredScale"], self.SCALE)

    def test_verify_says_nothing_about_a_flow_that_can_finish(self):
        """The direction that matters more. The identical target, with the
        one declaration that decides removed: no `requiredScale`, so
        `_derive_record` grades the same item on `recordFound` alone and a
        record a smaller run leaves behind ticks it.
        """
        report = self.verify(self._box("clear", scale=None))
        self.assertIsNone(report["unfinishableFlow"])


class DiscussionBucketFoldTests(unittest.TestCase):
    """`_answered_discussions(target, name)` -- the other half of the fold
    `_open_discussions` already performs, and the same one: bucket by exact
    trimmed question text, last event in ledger order wins.

    A per-step decision pass needs to know which questions were ANSWERED, and
    `_open_discussions` only ever reports the ones still open -- a question
    nobody has asked yet is in neither list, and reading "not open" as
    "decided" would treat every never-asked step as settled.
    """

    def _target(self, events):
        root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, root, ignore_errors=True)
        path = root / "Method" / ".implementation" / "position.jsonl"
        path.parent.mkdir(parents=True)
        with path.open("w", encoding="utf-8") as handle:
            for event in events:
                handle.write(json.dumps(event) + "\n")
        return root

    def _event(self, asked, answered=None):
        return {"kind": "discuss", "about": {"kind": "record", "operand": None},
                "asked": asked, "answered": answered,
                "status": "answered" if answered else "open"}

    def test_a_ledger_with_no_discussion_answers_nothing(self):
        root = self._target([])
        self.assertEqual(impl._answered_discussions(root, "Method"), set())

    def test_an_answered_question_is_named_by_its_exact_text(self):
        root = self._target([self._event("how is this one carried out?", "locally")])
        self.assertEqual(impl._answered_discussions(root, "Method"),
                         {"how is this one carried out?"})

    def test_an_open_question_is_not_answered(self):
        root = self._target([self._event("how is this one carried out?")])
        self.assertEqual(impl._answered_discussions(root, "Method"), set())

    def test_a_re_ask_after_an_answer_reopens_the_bucket(self):
        """Last event in ledger order wins, never answered-once: a question
        re-asked after it was answered is open again, and a pass that read
        "some event answered it" would walk straight past the re-ask."""
        root = self._target([self._event("q", "yes"), self._event("q")])
        self.assertEqual(impl._answered_discussions(root, "Method"), set())

    def test_an_answer_after_a_re_ask_closes_it_again(self):
        root = self._target([self._event("q"), self._event("q", "no")])
        self.assertEqual(impl._answered_discussions(root, "Method"), {"q"})

    def test_a_blank_answer_is_no_answer(self):
        root = self._target([self._event("q", "   ")])
        self.assertEqual(impl._answered_discussions(root, "Method"), set())

    def test_distinct_texts_are_distinct_buckets(self):
        """The property the per-step pass rests on: one answer retires one
        step's question and no other. Grouping by witness identity instead
        would retire all of them at once -- every entry this pass writes
        shares the identical operand-less `record` identity."""
        root = self._target([self._event("first?", "remote"),
                             self._event("second?")])
        self.assertEqual(impl._answered_discussions(root, "Method"), {"first?"})

    def test_the_two_folds_answer_one_ledger_consistently(self):
        """`_open_discussions` and this one are two readings of one fold, so
        no text may ever be reported open and answered at once."""
        root = self._target([self._event("open?"), self._event("closed?", "yes")])
        opened = {entry["asked"] for entry in impl._open_discussions(root, "Method")}
        answered = impl._answered_discussions(root, "Method")
        self.assertEqual(opened, {"open?"})
        self.assertEqual(answered, {"closed?"})
        self.assertEqual(opened & answered, set())


class PilotGatesTheDeclaredScaleTests(unittest.TestCase):
    """The pair that decides this change, end to end: with the declared flow
    unfinished at pilot the declared scale is NOT offered, and once every step
    has run and every notebook its sequence names is executed against these
    sources it IS -- after each step's own decision has been answered.

    The measured defect, on a reference target: one of six ordered steps had
    run, six of seven notebooks carried zero executed cells, and `probe`
    answered the rung whose published question offers the declared scale. The
    rung was right about its own condition (the search record is absent) and
    wrong about the flow, because "the record is missing" and "the pilot was
    validated" are different facts.

    A lock that only checked the published text changed would be worthless.
    These fixtures differ ONLY in what actually ran -- the same declaration,
    the same search, the same absent record -- so the rung has to move on the
    evidence or not at all.
    """

    SEARCH = SearchDeclaredBeforeTheRunTests.SEARCH
    WIRING = SearchDeclaredBeforeTheRunTests.WITH

    STEPS = ("__steps__ = {\n"
             "    'second': {'module': 'Method_Benchmark.steps',\n"
             "               'function': 'b', 'advances': 2},\n"
             "    'first': {'module': 'Method_Benchmark.steps',\n"
             "              'function': 'a', 'advances': 1},\n"
             "    'aside': {'module': 'Method_Benchmark.steps',\n"
             "              'function': 'c'},\n"
             "}\n")

    SEQUENCE = ("- [ ] 1. The first step's evidence. `@notebook Notebooks/one.ipynb`\n"
                "- [ ] 2. The second step's evidence. `@record`\n")

    def _declaration(self):
        return ("__benchmark__ = {\n"
                "    'revision': 'r01.md',\n"
                "    'arms': {'floor': {'sections': ['3']}, "
                "'full': {'sections': ['3']}},\n"
                f"    'search': {self.SEARCH!r},\n"
                "}\n" + self.STEPS)

    def build(self, suffix, *, ran=(), notebook_executed=False,
              notebook_current=True):
        box = FORGE / "implementations" / f"_pilotgate_{suffix}_{os.getpid()}"
        self.addCleanup(shutil.rmtree, box, ignore_errors=True)
        for directory in ("src/Method", "src/Method_Benchmark", "src/Prior",
                          "Method/Notebooks"):
            (box / directory).mkdir(parents=True)
        subprocess.run(["git", "init", "-q", str(box)], check=True,
                       capture_output=True)
        (box / "src/Method/__init__.py").write_text("", encoding="utf-8")
        (box / "src/Method/called.py").write_text(
            _module("r01.md", ["3"], ["11"], imports="import torch\n"),
            encoding="utf-8")
        (box / "src/Method/never_called.py").write_text(
            _module("r01.md", ["3"], ["12"], imports="import torch\n"),
            encoding="utf-8")
        (box / "src/Prior/model.py").write_text("import torch\n", encoding="utf-8")
        (box / "src/Method_Benchmark/__init__.py").write_text(
            self._declaration(), encoding="utf-8")
        (box / "src/Method_Benchmark/wiring.py").write_text(
            self.WIRING, encoding="utf-8")

        # Written after every file under `src/` and before the notebook, so
        # the stamp is the digest of the sources as they finally stand.
        digest = impl.source_digest(box, impl.package_name("Method"))
        stamped = digest if notebook_current else "0" * 64
        (box / "Method/Notebooks/one.ipynb").write_text(json.dumps({
            "cells": [{"cell_type": "code",
                       "execution_count": 1 if notebook_executed else None,
                       "metadata": {},
                       "outputs": ([{"output_type": "stream", "name": "stdout",
                                     "text": [f"{impl.DIGEST_MARKER} {stamped}\n"]}]
                                   if notebook_executed else []),
                       "source": ["print('measured')\n"]}],
            "metadata": {}, "nbformat": 4, "nbformat_minor": 5,
        }), encoding="utf-8")

        (box / "Method/AGREED.md").write_text(
            "<!-- position revision=r01.md sha256=" + "a" * 64
            + " derivedAt=2026-08-27T00:00:00Z session=s0 target=pilot -->\n"
            + self.SEQUENCE + "<!-- /position -->\n", encoding="utf-8")

        ledger = box / "Method" / ".implementation" / "position.jsonl"
        ledger.parent.mkdir(parents=True)
        live = impl.suite_digest(box)
        with ledger.open("w", encoding="utf-8") as handle:
            for step in ran:
                handle.write(json.dumps({
                    "kind": "step", "step": step, "outcome": "returned",
                    "suiteDigest": live, "at": "2026-08-27T00:00:00Z"}) + "\n")
        return box

    def probe(self, box):
        proc = subprocess.run(
            [sys.executable, str(CLI), "probe", "--target", str(box),
             "--name", "Method", "--revision", "r01.md"],
            capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        return json.loads(proc.stdout)

    def answer(self, box, entry):
        """Run the entry's own published `discuss` command, with an answer
        appended -- the operator's act, not a hand-written ledger line."""
        tokens = shlex.split(entry["command"])[1:]
        proc = subprocess.run(
            [sys.executable, str(CLI), *tokens, "--answer", "a decision"],
            capture_output=True, text=True, cwd=FORGE)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        return json.loads(proc.stdout)

    # --- the flow has not finished at pilot -------------------------------

    def test_nothing_run_withholds_the_declared_scale(self):
        box = self.build("none")
        probe = self.probe(box)
        self.assertIs(probe["search"]["recordFound"], False)
        self.assertEqual(probe["nextStep"], "pilot-first")
        self.assertEqual(probe["pilotCompleteness"]["status"], "incomplete")
        self.assertEqual(probe["pilotCompleteness"]["incomplete"],
                         ["first", "second"])

    def test_the_withheld_question_names_the_steps_still_short(self):
        """Not "the pilot is incomplete": which steps. The shape
        `POSITION_RUNG_SKIPPED`'s own detail already uses when it names the
        items that came up short."""
        box = self.build("named", ran=("first",), notebook_executed=True)
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "pilot-first")
        question = probe["resolve"]["question"]
        self.assertIn("'second'", question)
        self.assertNotIn("'first'", question)

    def test_the_withheld_question_does_not_offer_the_declared_scale(self):
        """The whole point. `search-first`'s published sentence offers to
        continue toward the declared scale and names its axes; at this state
        neither may appear, because nothing has been produced for anybody to
        read and a question that offers the expensive run is an invitation to
        say yes."""
        box = self.build("noscale")
        probe = self.probe(box)
        question = probe["resolve"]["question"]
        self.assertNotIn(impl.NEXT_STEP_EXPERIMENT_CHOICE, question)
        for axis in self.SEARCH["requiredScale"]:
            self.assertNotIn(axis, question)
        self.assertEqual(len(probe["toDiscuss"]), 1)

    def test_a_step_that_ran_but_left_an_unexecuted_notebook_is_still_short(self):
        """The half a lock reading only the ledger would lose: the step
        returned, and the notebook its own sequence item names has no
        executed cell. Nothing was produced, so nothing was validated."""
        box = self.build("stale", ran=("first", "second"),
                         notebook_executed=False)
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "pilot-first")
        self.assertEqual(probe["pilotCompleteness"]["incomplete"], ["first"])

    def test_a_notebook_executed_against_other_sources_is_still_short(self):
        box = self.build("drifted", ran=("first", "second"),
                         notebook_executed=True, notebook_current=False)
        probe = self.probe(box)
        self.assertEqual(probe["nextStep"], "pilot-first")
        self.assertEqual(probe["pilotCompleteness"]["incomplete"], ["first"])

    # --- the flow has finished at pilot -----------------------------------

    def test_a_finished_pilot_starts_the_per_step_decision_pass(self):
        """What completeness unlocks is not permission to launch: the flow
        returns to its first step, and each one owes its own decision about
        how it is carried out in the full run."""
        box = self.build("complete", ran=("first", "second"),
                         notebook_executed=True)
        probe = self.probe(box)
        self.assertEqual(probe["pilotCompleteness"]["status"], "complete")
        self.assertEqual(probe["nextStep"], "pilot-decisions")
        asked = [entry["question"] for entry in probe["toDiscuss"]]
        self.assertEqual(len(asked), 3, asked)
        self.assertIn("'first'", asked[1])
        self.assertIn("'second'", asked[2])

    def test_the_decision_pass_still_withholds_the_declared_scale(self):
        box = self.build("undecided", ran=("first", "second"),
                         notebook_executed=True)
        probe = self.probe(box)
        for entry in probe["toDiscuss"]:
            self.assertNotIn(impl.NEXT_STEP_EXPERIMENT_CHOICE,
                             entry["question"])

    def test_the_pass_asks_one_question_per_step_in_declared_order(self):
        """One bucket per step, and the ordinal is the order -- the fixture
        spells the entries out of ordinal order on purpose."""
        box = self.build("order", ran=("first", "second"),
                         notebook_executed=True)
        probe = self.probe(box)
        steps = [row["step"] for row in probe["pilotCompleteness"]["steps"]]
        self.assertEqual(steps, ["first", "second"])

    def test_answering_one_step_leaves_the_other_still_asked(self):
        """The property the pass rests on: one answer retires one step. All
        of these entries share the identical operand-less `record` witness
        identity, so a fold that grouped by identity would retire every one
        of them at once."""
        box = self.build("partial", ran=("first", "second"),
                         notebook_executed=True)
        first = self.probe(box)
        self.answer(box, first["toDiscuss"][1])
        second = self.probe(box)
        self.assertEqual(second["nextStep"], "pilot-decisions")
        asked = [entry["question"] for entry in second["toDiscuss"]]
        self.assertEqual(len(asked), 2, asked)
        self.assertIn("'second'", asked[1])

    def test_every_step_decided_finally_offers_the_declared_scale(self):
        """The other pole, and the one that proves the rung is a gate rather
        than a wall: the same repository, the same absent record, and once
        the flow has run and every step's decision is on the record, the
        question that offers the declared scale is published at last."""
        box = self.build("decided", ran=("first", "second"),
                         notebook_executed=True)
        probe = self.probe(box)
        for entry in probe["toDiscuss"][1:]:
            self.answer(box, entry)
        final = self.probe(box)
        self.assertEqual(final["pilotCompleteness"]["status"], "complete")
        self.assertEqual(final["nextStep"], "search-first")
        question = final["resolve"]["question"]
        self.assertIn(impl.NEXT_STEP_EXPERIMENT_CHOICE, question)
        for axis in self.SEARCH["requiredScale"]:
            self.assertIn(axis, question)

    # --- a target that declared no flow is untouched -----------------------

    def test_a_target_that_declares_no_flow_reaches_the_same_rung_it_always_did(self):
        """No regression on every repository that never opted into an
        ordering: `undeclared` means this rule does not apply, and the ladder
        answers exactly what it answered before it existed."""
        box = self.build("noflow")
        (box / "src/Method_Benchmark/__init__.py").write_text(
            self._declaration().replace(self.STEPS, ""), encoding="utf-8")
        probe = self.probe(box)
        self.assertEqual(probe["pilotCompleteness"]["status"], "undeclared")
        self.assertEqual(probe["nextStep"], "search-first")

    def test_the_toy_targets_left_nothing_behind(self):
        box = self.build("cleanup")
        self.assertTrue(box.is_dir())
        shutil.rmtree(box, ignore_errors=True)
        self.assertEqual(
            list((FORGE / "implementations").glob("_pilotgate_cleanup_*")), [])


class PilotPublicationProseTests(unittest.TestCase):
    """The two published sentences, read as a reader meets them.

    A published question is the whole of what this rung hands somebody, so its
    prose is the deliverable rather than decoration -- and neither the roster
    lock nor the end-to-end pair reads it as one sentence.
    """

    TARGET = Path("implementations/box")

    def decisions(self, **facts):
        return impl._pilot_decisions_publication(
            self.TARGET, "Method", facts)["question"]

    def first(self, **facts):
        return impl._pilot_first_publication(
            self.TARGET, "Method", facts)["question"]

    def test_the_decision_pass_says_where_the_outputs_are(self):
        """The owner's second act is reading them, so where they are is named
        rather than left to be looked for."""
        question = self.decisions(notebooks=["Notebooks/a.ipynb",
                                             "Notebooks/b.ipynb"])
        self.assertIn("Notebooks/a.ipynb", question)
        self.assertIn("Notebooks/b.ipynb", question)

    def test_the_decision_pass_reads_as_one_sentence_either_way(self):
        """The clause naming the outputs is optional -- a flow whose steps
        witness no notebook has none to name -- and an optional clause spliced
        in is exactly where two fragments run together."""
        for facts in ({}, {"notebooks": ["Notebooks/a.ipynb"]}):
            with self.subTest(facts=facts):
                question = self.decisions(**facts)
                # `[;,]` only: a path operand legitimately carries `.` and
                # the sentence's own `:` is followed by a space, so a wider
                # class would fail on `.ipynb` rather than on the splice.
                self.assertNotRegex(question, r"[;,]\S",
                                    "punctuation runs into the next word")
                self.assertNotIn("  ", question)

    def test_one_step_short_is_said_in_the_singular(self):
        question = self.first(incomplete=["one"])
        self.assertIn("whose step 'one' has not finished", question)

    def test_several_steps_short_are_said_in_the_plural(self):
        question = self.first(incomplete=["one", "two"])
        self.assertIn("whose steps 'one', 'two' have not finished", question)

    def test_neither_sentence_offers_the_declared_scale(self):
        for question in (self.first(incomplete=["one"]),
                         self.decisions(notebooks=["Notebooks/a.ipynb"])):
            with self.subTest(question=question[:40]):
                self.assertIn(impl.NEXT_STEP_REPAIR_CHOICE, question)
                self.assertNotIn(impl.NEXT_STEP_EXPERIMENT_CHOICE, question)
